package main

// This file is the CANDIDATE SLOT for evolved routing algorithms. During
// optimization, the entire file is replaced (via go build -overlay) with a
// generated implementation. The contract is a single constructor:
//
//	newCandidateRouter(view, source, localBalances, spec)
//
// returning a routing.SimRouter. The router sees only the public gossip
// graph, its own channel balances and per-attempt feedback — the same
// information a real Lightning sender has. The in-tree implementation below
// is the seed algorithm: a deliberately simple fee-optimizing Dijkstra with
// failure blacklisting and halving-based MPP splitting.

import (
	"container/heap"
	"context"
	"errors"
	"fmt"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

// candidateEdge is one directed edge of the public graph: a channel from
// one node to another, with the policy the sending node announced.
type candidateEdge struct {
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

// fee returns the fee the sending node charges to forward amt over this
// edge.
func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

// usable reports whether the edge can carry the given amount per its
// announced policy.
func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC {
		return false
	}
	if e.maxHTLC != 0 && amt > e.maxHTLC {
		return false
	}
	// The public capacity is a hard upper bound on what can flow.
	return amt <= e.capacity
}

// candidateRouter is the seed algorithm: cheapest-path routing with a
// failure blacklist and amount halving when no route is found.
type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	// incomingEdges maps a node to the directed edges arriving at it,
	// the natural shape for backward Dijkstra.
	incomingEdges map[route.Vertex][]*candidateEdge

	// localBalances is the exact outbound liquidity of our own channels.
	localBalances map[uint64]lnwire.MilliSatoshi

	// failedAmt records, per directed channel, the lowest amount that
	// failed with a liquidity error; routes are built to stay below it.
	failedAmt map[uint64]lnwire.MilliSatoshi

	// shardAmt is the current shard size for MPP splitting.
	shardAmt lnwire.MilliSatoshi

	// partsUsed counts the successful shards so far.
	partsUsed uint32

	// pending maps in-flight attempt ids to their routes.
	pending map[uint64]*route.Route
}

// newCandidateRouter builds the router for one payment. This signature is
// the stable contract between the harness and generated candidates.
func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	router := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		localBalances: localBalances,
		failedAmt:     make(map[uint64]lnwire.MilliSatoshi),
		shardAmt:      spec.Amount,
		pending:       make(map[uint64]*route.Route),
	}

	// Build the adjacency list from gossip. Iterating a node's channels
	// yields, per channel, the policy the OTHER node announced toward us
	// (InPolicy). That is exactly the policy governing the directed edge
	// other -> node, so we record the reversed edge at each visit.
	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(ctx, node,
			func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat: pol.FeeBaseMSat,
					feeRatePPM: pol.
						FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				router.incomingEdges[edge.to] = append(
					router.incomingEdges[edge.to], edge,
				)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return router, nil
}

// dijkstraItem is a priority queue entry.
type dijkstraItem struct {
	node route.Vertex
	cost lnwire.MilliSatoshi
	idx  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int           { return len(q) }
func (q dijkstraQueue) Less(i, j int) bool { return q[i].cost < q[j].cost }
func (q dijkstraQueue) Swap(i, j int)      { q[i], q[j] = q[j], q[i]; q[i].idx = i; q[j].idx = j }
func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}
func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

// findRoute computes the cheapest usable path delivering amt to the target,
// walking backward from the target so fees accumulate correctly.
func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (*route.Route,
	error) {

	// dist[node] = amount that must arrive at node to deliver amt.
	dist := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = amt
	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{node: r.spec.Target, cost: amt})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		node, arriving := item.node, item.cost

		if arriving > dist[node] {
			continue
		}
		if node == r.source {
			break
		}

		// Consider all edges INTO node: for edge u->node, u must
		// send arriving plus u's fee.
		for _, edge := range r.incomingEdges[node] {
			amtOver := arriving

			if !edge.usable(amtOver) {
				continue
			}

			// Skip channels whose liquidity failure bound says
			// this amount cannot pass.
			if bound, ok := r.failedAmt[edge.chanID]; ok &&
				amtOver >= bound {

				continue
			}

			// Our own channels: check exact local balance.
			if edge.from == r.source {
				if r.localBalances[edge.chanID] < amtOver {
					continue
				}
			}

			var sending lnwire.MilliSatoshi
			if edge.from == r.source {
				// We pay no fee to ourselves.
				sending = amtOver
			} else {
				sending = amtOver + edge.fee(amtOver)
			}

			best, ok := dist[edge.from]
			if !ok || sending < best {
				dist[edge.from] = sending
				next[edge.from] = edge
				heap.Push(pq, &dijkstraItem{
					node: edge.from,
					cost: sending,
				})
			}
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

// buildRoute walks the next-pointers from source to target and constructs a
// route with correctly accumulated fees and cltv deltas.
func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	const finalCltvDelta = 40

	// Collect the path edges source -> target.
	var path []*candidateEdge
	for node := r.source; node != r.spec.Target; {
		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.to
	}

	// Amounts and expiries per channel, computed backward.
	numHops := len(path)
	amtOver := make([]lnwire.MilliSatoshi, numHops)
	expiryOver := make([]uint32, numHops)

	amtOver[numHops-1] = amt
	expiryOver[numHops-1] = finalCltvDelta

	for i := numHops - 2; i >= 0; i-- {
		fwd := path[i+1]
		amtOver[i] = amtOver[i+1] + fwd.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(fwd.timeLockDelta)
	}

	hops := make([]*route.Hop, numHops)
	for i, edge := range path {
		amtToFwd := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < numHops-1 {
			amtToFwd = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToFwd,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

// RequestRoute returns the next route to try: the cheapest path for the
// current shard size, halving the shard when no route exists.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.shardAmt > amt {
		r.shardAmt = amt
	}

	for {
		rt, err := r.findRoute(r.shardAmt)
		if err == nil {
			return rt, nil
		}

		// No route at this shard size: split if we're allowed more
		// parts and the shard is still meaningfully large.
		partsLeft := r.spec.MaxParts - inFlightHtlcs
		if partsLeft <= 1 || r.shardAmt < 10_000_000 {
			return nil, err
		}
		r.shardAmt /= 2
	}
}

// ReportAttempt learns from an attempt: liquidity failures set an upper
// bound on the failing channel.
//
// NOTE: Part of the routing.SimRouter interface.
func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		return nil
	}

	// Locate the failing hop and record the amount bound on its
	// outgoing channel.
	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == result.FailureSource {
			failIdx = i + 1
		}
	}

	// The failing node could not forward over its outgoing channel,
	// which is rt.Hops[failIdx].
	if failIdx >= 0 && failIdx < len(rt.Hops) {
		hop := rt.Hops[failIdx]
		amtOver := rt.TotalAmount
		if failIdx > 0 {
			amtOver = rt.Hops[failIdx-1].AmtToForward
		}

		bound, ok := r.failedAmt[hop.ChannelID]
		if !ok || amtOver < bound {
			r.failedAmt[hop.ChannelID] = amtOver
		}
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	point     lnwire.MilliSatoshi
	conf      float64
}

type candidateNetworkMemory struct {
	view    routing.SimNetworkView
	beliefs map[candidateEdgeKey]candidateBelief
}

var (
	candidateMemoryMu sync.Mutex
	candidateMemories = make(map[string]*candidateNetworkMemory)
)

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	memory        *candidateNetworkMemory

	// Liquidity already consumed or held by successful/in-flight shards.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi

	// Per-payment soft penalties prevent uninformative failures from
	// repeatedly selecting the same corridor.
	failPenalty map[candidateEdgeKey]float64

	plan     []candidatePlannedRoute
	attempts int
	failures int
	maxTries int
}

type candidatePlannedRoute struct {
	path []*candidateEdge
	amt  lnwire.MilliSatoshi
	rt   *route.Route
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	networkID := fmt.Sprintf("%p", view)

	candidateMemoryMu.Lock()
	memory := candidateMemories[networkID]
	if memory == nil {
		memory = &candidateNetworkMemory{
			view:    view,
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemories[networkID] = memory
	}
	candidateMemoryMu.Unlock()

	maxTries := 18 + int(spec.MaxParts)*4
	if maxTries < 28 {
		maxTries = 28
	}
	if maxTries > 64 {
		maxTries = 64
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edgeByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances: localBalances,
		memory:        memory,
		reserved:      make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		failPenalty:   make(map[candidateEdgeKey]float64),
		maxTries:      maxTries,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := candidateEdgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
				}
				edge := &candidateEdge{
					key:      key,
					from:     ch.OtherNode,
					to:       node,
					capacity: lnwire.NewMSatFromSatoshis(ch.Capacity),

					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[edge.to] = append(
					r.incomingEdges[edge.to], edge,
				)
				r.edgeByKey[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func candidateClampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// candidatePrior models a channel as a mixture of an almost-empty mode and
// an almost-full mode. Tiny HTLCs can pass either mode, while large HTLCs
// increasingly require the full mode.
func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.90)*24))
	return candidateClampProbability(0.005 + lowMode + highMode)
}

func (r *candidateRouter) belief(
	key candidateEdgeKey) candidateBelief {

	candidateMemoryMu.Lock()
	b := r.memory.beliefs[key]
	candidateMemoryMu.Unlock()
	return b
}

func (r *candidateRouter) probability(edge *candidateEdge,
	totalAmt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		if totalAmt <= r.localBalances[edge.key.chanID] {
			return 0.999
		}
		return 0.001
	}

	prior := candidatePrior(totalAmt, edge.capacity)
	b := r.belief(edge.key)

	if b.lowerOK != 0 && totalAmt <= b.lowerOK {
		return 0.995
	}
	if b.upperFail != 0 && totalAmt >= b.upperFail {
		return 0.005
	}
	if b.conf == 0 || b.point == 0 {
		return prior
	}

	scale := float64(edge.capacity) * 0.07
	if scale < 1 {
		scale = 1
	}
	dataProbability := 1 / (1 + math.Exp(
		(float64(totalAmt)-float64(b.point))/scale,
	))
	weight := b.conf / (b.conf + 1.5)

	return candidateClampProbability(
		(1-weight)*prior + weight*dataProbability,
	)
}

func (r *candidateRouter) recordSuccess(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	candidateMemoryMu.Lock()
	defer candidateMemoryMu.Unlock()

	b := r.memory.beliefs[edge.key]

	// A success above an old failure bound is direct evidence that the
	// network moved; retain hard bounds, but discard contradicted ones.
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}
	if amt > b.lowerOK {
		b.lowerOK = amt
	}

	target := amt
	highPoint := edge.capacity * 9 / 10
	if target < highPoint {
		target = highPoint
	}

	if b.conf == 0 {
		b.point = target
	} else {
		b.point = lnwire.MilliSatoshi(
			(float64(b.point)*b.conf + float64(target)*2) /
				(b.conf + 2),
		)
	}
	b.conf += 2
	if b.conf > 10 {
		b.conf = 10
	}
	r.memory.beliefs[edge.key] = b
}

func (r *candidateRouter) recordFailure(edge *candidateEdge,
	amt lnwire.MilliSatoshi) {

	candidateMemoryMu.Lock()
	defer candidateMemoryMu.Unlock()

	b := r.memory.beliefs[edge.key]

	if b.lowerOK != 0 && amt <= b.lowerOK {
		b.lowerOK = 0
	}
	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}

	target := amt / 4
	if target < 1 {
		target = 1
	}
	if b.conf == 0 {
		b.point = target
	} else {
		b.point = lnwire.MilliSatoshi(
			(float64(b.point)*b.conf + float64(target)*2) /
				(b.conf + 2),
		)
	}
	b.conf += 2
	if b.conf > 10 {
		b.conf = 10
	}
	r.memory.beliefs[edge.key] = b
}

type candidateQueueItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
	index  int
}

type candidateQueue []*candidateQueueItem

func (q candidateQueue) Len() int { return len(q) }
func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}
func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}
func (q *candidateQueue) Push(x any) {
	item := x.(*candidateQueueItem)
	item.index = len(*q)
	*q = append(*q, item)
}
func (q *candidateQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) edgeUsable(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	checkMin bool) bool {

	if checkMin && amt < edge.minHTLC {
		return false
	}
	if edge.maxHTLC != 0 && amt > edge.maxHTLC {
		return false
	}

	total := amt + r.reserved[edge.key] + extra[edge.key]
	if total > edge.capacity {
		return false
	}
	if edge.from == r.source &&
		total > r.localBalances[edge.key.chanID] {

		return false
	}

	b := r.belief(edge.key)
	if b.upperFail != 0 && total >= b.upperFail {
		return false
	}
	return true
}

// findPath performs a probability-weighted backward Dijkstra. Fees remain
// part of the objective, but a likely liquidity miss is much more expensive
// than a modest forwarding fee.
func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]int,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi) (
	[]*candidateEdge, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	dist := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	dist[r.spec.Target] = float64(amt)
	pq := &candidateQueue{}
	heap.Push(pq, &candidateQueueItem{
		node:   r.spec.Target,
		amount: amt,
		score:  float64(amt),
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*candidateQueueItem)
		best, ok := dist[item.node]
		if !ok || item.score > best {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			over := item.amount
			if !r.edgeUsable(edge, over, extra, true) {
				continue
			}

			total := over + r.reserved[edge.key] + extra[edge.key]
			p := r.probability(edge, total)

			sending := over
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(over)
				sending += fee
			}

			riskScale := math.Max(float64(amt)*0.16, 50_000)
			riskCost := -math.Log(p) * riskScale
			softCost := r.failPenalty[edge.key] *
				float64(amt) * 0.18
			diversityCost := float64(diversity[edge.key]) *
				float64(amt) * 0.40

			score := item.score + float64(fee) + riskCost +
				softCost + diversityCost + 2_000

			old, exists := dist[edge.from]
			if !exists || score < old {
				dist[edge.from] = score
				next[edge.from] = edge
				heap.Push(pq, &candidateQueueItem{
					node:   edge.from,
					amount: sending,
					score:  score,
				})
			}
		}
	}

	if _, ok := dist[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, 8)
	seen := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("cyclic route")
		}
		seen[node] = true

		edge := next[node]
		if edge == nil {
			return nil, errors.New("broken route")
		}
		path = append(path, edge)
		node = edge.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}
	return path, nil
}

func candidatePathAmounts(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	amounts := make([]lnwire.MilliSatoshi, len(path))
	if len(path) == 0 {
		return amounts
	}

	amounts[len(path)-1] = deliver
	for i := len(path) - 2; i >= 0; i-- {
		amounts[i] = amounts[i+1] +
			path[i+1].fee(amounts[i+1])
	}
	return amounts
}

func (r *candidateRouter) pathFeasible(path []*candidateEdge,
	deliver lnwire.MilliSatoshi,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	checkMin bool) bool {

	if deliver <= 0 || len(path) == 0 {
		return false
	}

	amounts := candidatePathAmounts(path, deliver)
	for i, edge := range path {
		if !r.edgeUsable(edge, amounts[i], extra, checkMin) {
			return false
		}
	}
	return true
}

func (r *candidateRouter) maxPathAmount(path []*candidateEdge,
	extra map[candidateEdgeKey]lnwire.MilliSatoshi,
	limit lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	lo := lnwire.MilliSatoshi(0)
	hi := limit

	for lo < hi {
		mid := lo + (hi-lo+1)/2
		if r.pathFeasible(path, mid, extra, false) {
			lo = mid
		} else {
			hi = mid - 1
		}
	}

	if lo == 0 || !r.pathFeasible(path, lo, extra, true) {
		return 0
	}
	return lo
}

func candidatePathHash(path []*candidateEdge) uint64 {
	h := uint64(1469598103934665603)
	for _, edge := range path {
		h ^= edge.key.chanID
		h *= 1099511628211
		for _, b := range edge.from {
			h ^= uint64(b)
			h *= 1099511628211
		}
	}
	return h
}

func candidateAddPathLoad(loads map[candidateEdgeKey]lnwire.MilliSatoshi,
	path []*candidateEdge, amt lnwire.MilliSatoshi, add bool) {

	amounts := candidatePathAmounts(path, amt)
	for i, edge := range path {
		if add {
			loads[edge.key] += amounts[i]
		} else {
			loads[edge.key] -= amounts[i]
			if loads[edge.key] <= 0 {
				delete(loads, edge.key)
			}
		}
	}
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (*route.Route, error) {

	const finalCltvDelta = uint32(40)

	if len(path) == 0 {
		return nil, errors.New("empty path")
	}

	amounts := candidatePathAmounts(path, deliver)
	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = finalCltvDelta

	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := deliver
		outgoingExpiry := finalCltvDelta
		if i+1 < len(path) {
			forward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func (r *candidateRouter) allocatePlan(paths [][]*candidateEdge,
	total lnwire.MilliSatoshi) ([]candidatePlannedRoute,
	map[candidateEdgeKey]lnwire.MilliSatoshi, bool) {

	n := len(paths)
	if n == 0 {
		return nil, nil, false
	}

	caps := make([]lnwire.MilliSatoshi, n)
	var capSum lnwire.MilliSatoshi
	emptyLoads := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	for i := range paths {
		caps[i] = r.maxPathAmount(paths[i], emptyLoads, total)
		capSum += caps[i]
	}
	if capSum < total {
		return nil, nil, false
	}

	alloc := make([]lnwire.MilliSatoshi, n)
	loads := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	var assigned lnwire.MilliSatoshi

	// Start with a capacity-proportional split. Parallel corridors of
	// unequal size therefore receive unequal shards.
	for i := range paths {
		if caps[i] == 0 {
			continue
		}

		desired := lnwire.MilliSatoshi(
			float64(total) * float64(caps[i]) /
				float64(capSum),
		)
		if i == n-1 {
			desired = total - assigned
		}
		if desired > total-assigned {
			desired = total - assigned
		}
		if desired <= 0 {
			continue
		}

		maximum := r.maxPathAmount(paths[i], loads, desired)
		if maximum < desired {
			desired = maximum
		}
		if desired == 0 {
			continue
		}

		alloc[i] = desired
		assigned += desired
		candidateAddPathLoad(loads, paths[i], desired, true)
	}

	// Fill any rounding or shared-corridor shortfall using residual
	// capacities, recalculating aggregate liquidity after every change.
	for round := 0; round < 3 && assigned < total; round++ {
		progress := false
		for i := range paths {
			old := alloc[i]
			if old != 0 {
				candidateAddPathLoad(loads, paths[i], old, false)
			}

			maximum := r.maxPathAmount(paths[i], loads, total)
			want := old + (total - assigned)
			if want > maximum {
				want = maximum
			}
			if want < old {
				want = old
			}

			if want != 0 {
				candidateAddPathLoad(loads, paths[i], want, true)
			}
			if want > old {
				assigned += want - old
				alloc[i] = want
				progress = true
			}

			if assigned == total {
				break
			}
		}
		if !progress {
			break
		}
	}

	if assigned != total {
		return nil, nil, false
	}

	plan := make([]candidatePlannedRoute, 0, n)
	for i, amt := range alloc {
		if amt == 0 {
			continue
		}
		if !r.pathFeasible(paths[i], amt,
			planLoadsExcept(loads, paths[i], amt), true) {

			return nil, nil, false
		}

		rt, err := r.buildRoute(paths[i], amt)
		if err != nil {
			return nil, nil, false
		}
		plan = append(plan, candidatePlannedRoute{
			path: paths[i],
			amt:  amt,
			rt:   rt,
		})
	}

	// Commit the largest shards first, reducing exposure to drift between
	// the beginning and end of an atomic-MPP attempt set.
	for i := 0; i < len(plan); i++ {
		best := i
		for j := i + 1; j < len(plan); j++ {
			if plan[j].amt > plan[best].amt {
				best = j
			}
		}
		plan[i], plan[best] = plan[best], plan[i]
	}

	return plan, loads, true
}

func planLoadsExcept(all map[candidateEdgeKey]lnwire.MilliSatoshi,
	path []*candidateEdge,
	amt lnwire.MilliSatoshi) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(all))
	for key, value := range all {
		result[key] = value
	}
	candidateAddPathLoad(result, path, amt, false)
	return result
}

func (r *candidateRouter) planScore(plan []candidatePlannedRoute,
	loads map[candidateEdgeKey]lnwire.MilliSatoshi,
	total lnwire.MilliSatoshi) float64 {

	score := 0.0
	for key, load := range loads {
		edge := r.edgeByKey[key]
		if edge == nil {
			continue
		}
		aggregate := load + r.reserved[key]
		score -= math.Log(r.probability(edge, aggregate))
	}

	var fees lnwire.MilliSatoshi
	for _, part := range plan {
		fees += part.rt.TotalAmount - part.amt
	}
	if total > 0 {
		score += 20 * float64(fees) / float64(total)
	}

	// Each extra shard is another chance for the moving network to
	// invalidate the plan before atomic settlement.
	score += 0.06 * float64(len(plan)-1)
	return score
}

func (r *candidateRouter) buildJointPlan(amt lnwire.MilliSatoshi,
	partsLeft uint32) []candidatePlannedRoute {

	if partsLeft == 0 || amt <= 0 {
		return nil
	}

	maxParts := int(partsLeft)
	if maxParts > 12 {
		maxParts = 12
	}

	paths := make([][]*candidateEdge, 0, maxParts)
	seenPaths := make(map[uint64]bool)
	diversity := make(map[candidateEdgeKey]int)
	noExtra := make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	// Always consider a single full-payment path first.
	if path, err := r.findPath(amt, diversity, noExtra); err == nil {
		hash := candidatePathHash(path)
		seenPaths[hash] = true
		paths = append(paths, path)
		for _, edge := range path {
			diversity[edge.key]++
		}
	}

	probe := (amt + lnwire.MilliSatoshi(maxParts) - 1) /
		lnwire.MilliSatoshi(maxParts)
	if probe < 1 {
		probe = 1
	}

	tries := 0
	halves := 0
	for len(paths) < maxParts && tries < maxParts*6 {
		tries++
		path, err := r.findPath(probe, diversity, noExtra)
		if err != nil {
			if halves < 4 && probe > 1 {
				probe /= 2
				halves++
				continue
			}
			break
		}

		hash := candidatePathHash(path)
		if seenPaths[hash] {
			for _, edge := range path {
				diversity[edge.key] += 2
			}
			continue
		}

		seenPaths[hash] = true
		paths = append(paths, path)
		for _, edge := range path {
			diversity[edge.key]++
		}
	}

	if len(paths) == 0 {
		return nil
	}

	var best []candidatePlannedRoute
	bestScore := math.Inf(1)
	limit := len(paths)
	if limit > maxParts {
		limit = maxParts
	}

	for count := 1; count <= limit; count++ {
		plan, loads, ok := r.allocatePlan(paths[:count], amt)
		if !ok {
			continue
		}

		score := r.planScore(plan, loads, amt)
		if score < bestScore {
			bestScore = score
			best = plan
		}
	}

	return best
}

func (r *candidateRouter) fallbackRoute(amt lnwire.MilliSatoshi,
	partsLeft uint32) (*candidatePlannedRoute, error) {

	if partsLeft == 0 {
		return nil, errors.New("maximum parts reached")
	}

	want := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	if want < 1 {
		want = 1
	}

	diversity := make(map[candidateEdgeKey]int)
	extra := make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	for reductions := 0; reductions < 7 && want > 0; reductions++ {
		path, err := r.findPath(want, diversity, extra)
		if err == nil {
			maximum := r.maxPathAmount(path, extra, amt)
			if maximum >= want {
				// A known upper bound is retried below the failed
				// amount instead of blacklisting the channel forever.
				shard := want
				if maximum < amt && maximum > shard {
					shard = maximum
				}

				rt, buildErr := r.buildRoute(path, shard)
				if buildErr == nil {
					return &candidatePlannedRoute{
						path: path,
						amt:  shard,
						rt:   rt,
					}, nil
				}
			}
		}

		if want == 1 {
			break
		}
		want = want * 2 / 3
		if want < 1 {
			want = 1
		}
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) reserve(path []*candidateEdge,
	amt lnwire.MilliSatoshi) {

	amounts := candidatePathAmounts(path, amt)
	for i, edge := range path {
		r.reserved[edge.key] += amounts[i]
	}
}

func (r *candidateRouter) releaseRoute(rt *route.Route) {
	from := rt.SourcePubKey
	for i, hop := range rt.Hops {
		key := candidateEdgeKey{chanID: hop.ChannelID, from: from}
		amt := rt.TotalAmount
		if i > 0 {
			amt = rt.Hops[i-1].AmtToForward
		}

		if r.reserved[key] <= amt {
			delete(r.reserved, key)
		} else {
			r.reserved[key] -= amt
		}
		from = hop.PubKeyBytes
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}
	if r.failures >= r.maxTries || r.attempts >= r.maxTries {
		return nil, errors.New("routing attempt budget exhausted")
	}
	if inFlightHtlcs >= r.spec.MaxParts {
		return nil, errors.New("maximum parts reached")
	}

	partsLeft := r.spec.MaxParts - inFlightHtlcs

	for len(r.plan) != 0 {
		part := r.plan[0]
		r.plan = r.plan[1:]

		if part.amt > amt {
			r.plan = nil
			break
		}

		if !r.pathFeasible(
			part.path, part.amt,
			map[candidateEdgeKey]lnwire.MilliSatoshi{}, true,
		) {
			r.plan = nil
			break
		}

		r.reserve(part.path, part.amt)
		r.attempts++
		return part.rt, nil
	}

	r.plan = r.buildJointPlan(amt, partsLeft)
	if len(r.plan) != 0 {
		part := r.plan[0]
		r.plan = r.plan[1:]
		r.reserve(part.path, part.amt)
		r.attempts++
		return part.rt, nil
	}

	part, err := r.fallbackRoute(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	r.reserve(part.path, part.amt)
	r.attempts++
	return part.rt, nil
}

func (r *candidateRouter) routeEdge(rt *route.Route,
	index int) (*candidateEdge, candidateEdgeKey,
	lnwire.MilliSatoshi, bool) {

	if index < 0 || index >= len(rt.Hops) {
		return nil, candidateEdgeKey{}, 0, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	hop := rt.Hops[index]
	key := candidateEdgeKey{chanID: hop.ChannelID, from: from}
	edge := r.edgeByKey[key]
	if edge == nil {
		return nil, key, 0, false
	}

	amt := rt.TotalAmount
	if index > 0 {
		amt = rt.Hops[index-1].AmtToForward
	}
	return edge, key, amt, true
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if result.Failure == nil {
		for i := range rt.Hops {
			edge, key, amt, ok := r.routeEdge(rt, i)
			if !ok {
				continue
			}

			// At the instant this HTLC passed, all same-direction
			// sibling reservations also occupied liquidity.
			total := r.reserved[key]
			if total < amt {
				total = amt
			}
			r.recordSuccess(edge, total)
			r.failPenalty[key] *= 0.25
		}
		return nil
	}

	r.failures++

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	isLiquidity := false
	isPolicy := false
	switch result.Failure.(type) {
	case *lnwire.FailTemporaryChannelFailure:
		isLiquidity = true

	case *lnwire.FailFeeInsufficient,
		*lnwire.FailIncorrectCltvExpiry:

		isPolicy = true
	}

	if failIndex >= 0 && failIndex < len(rt.Hops) {
		edge, key, amt, ok := r.routeEdge(rt, failIndex)
		if ok {
			r.failPenalty[key] += 1
			if isPolicy {
				r.failPenalty[key] += 2
			}

			if isLiquidity {
				total := r.reserved[key]
				if total < amt {
					total = amt
				}
				r.recordFailure(edge, total)
			}
		}
	} else {
		// Unknown/final failures still provide route-level information.
		// Softly penalize every edge without inventing a hard liquidity
		// bound for any particular channel.
		for i := range rt.Hops {
			_, key, _, ok := r.routeEdge(rt, i)
			if ok {
				r.failPenalty[key] += 0.65
			}
		}
	}

	r.releaseRoute(rt)
	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      edgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate lnwire.MilliSatoshi
	evidence uint32
}

type liquidityWorld struct {
	mu      sync.RWMutex
	beliefs map[edgeKey]liquidityBelief
}

var candidateWorlds = struct {
	sync.Mutex
	byView map[string]*liquidityWorld
}{
	byView: make(map[string]*liquidityWorld),
}

func worldForView(view routing.SimNetworkView) *liquidityWorld {
	key := fmt.Sprintf("%T:%p", view, view)

	candidateWorlds.Lock()
	defer candidateWorlds.Unlock()

	world := candidateWorlds.byView[key]
	if world == nil {
		world = &liquidityWorld{
			beliefs: make(map[edgeKey]liquidityBelief),
		}
		candidateWorlds.byView[key] = world
	}

	return world
}

func (w *liquidityWorld) belief(key edgeKey) liquidityBelief {
	w.mu.RLock()
	b := w.beliefs[key]
	w.mu.RUnlock()
	return b
}

func (w *liquidityWorld) reportSuccess(e *candidateEdge,
	amt lnwire.MilliSatoshi) {

	w.mu.Lock()
	defer w.mu.Unlock()

	b := w.beliefs[e.key]

	// A success contradicting an old failure bound refreshes that bound.
	if b.upperFail != 0 && amt >= b.upperFail {
		b.upperFail = 0
	}
	if amt > b.lowerOK {
		b.lowerOK = amt
	}

	// In a bimodal channel, passing a meaningful amount is evidence that
	// this direction is in its high-liquidity mode.
	highEstimate := amt + (e.capacity-amt)*3/4
	if highEstimate < amt {
		highEstimate = amt
	}
	if b.evidence == 0 || highEstimate > b.estimate {
		b.estimate = highEstimate
	} else {
		b.estimate = (3*b.estimate + highEstimate) / 4
	}
	b.evidence++
	w.beliefs[e.key] = b

	// A liquid direction makes the reverse direction less attractive,
	// without creating a hard bound that was not directly observed.
	reverseKey := edgeKey{
		chanID: e.key.chanID,
		from:   e.key.to,
		to:     e.key.from,
	}
	reverse := w.beliefs[reverseKey]
	reverseEstimate := e.capacity - amt
	if reverseEstimate < 0 {
		reverseEstimate = 0
	}
	if reverse.evidence == 0 {
		reverse.estimate = reverseEstimate
	} else if reverse.estimate > reverseEstimate {
		reverse.estimate = (reverse.estimate + reverseEstimate) / 2
	}
	w.beliefs[reverseKey] = reverse
}

func (w *liquidityWorld) reportFailure(e *candidateEdge,
	amt lnwire.MilliSatoshi) {

	w.mu.Lock()
	defer w.mu.Unlock()

	b := w.beliefs[e.key]

	// A new failure below a stale success bound refreshes the stale bound.
	if b.lowerOK >= amt {
		b.lowerOK = 0
	}
	if b.upperFail == 0 || amt < b.upperFail {
		b.upperFail = amt
	}

	lowEstimate := amt / 3
	if b.evidence == 0 || b.estimate == 0 {
		b.estimate = lowEstimate
	} else if lowEstimate < b.estimate {
		b.estimate = (b.estimate + 2*lowEstimate) / 3
	}
	b.evidence++
	w.beliefs[e.key] = b

	// A depleted direction is soft evidence that the reverse direction is
	// in its high mode.
	reverseKey := edgeKey{
		chanID: e.key.chanID,
		from:   e.key.to,
		to:     e.key.from,
	}
	reverse := w.beliefs[reverseKey]
	reverseEstimate := e.capacity * 9 / 10
	if reverseEstimate > reverse.estimate {
		reverse.estimate = reverseEstimate
	}
	if reverse.evidence < 2 {
		reverse.evidence++
	}
	w.beliefs[reverseKey] = reverse
}

type plannedRoute struct {
	path []*candidateEdge
	amt  lnwire.MilliSatoshi
}

type attemptMeta struct {
	path      []*candidateEdge
	shard     lnwire.MilliSatoshi
	remaining lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	world         *liquidityWorld

	badPolicy map[edgeKey]bool
	penalty   map[edgeKey]float64
	reserved  map[edgeKey]lnwire.MilliSatoshi

	plans       []plannedRoute
	pending     map[*route.Route]attemptMeta
	reported    map[uint64]bool
	failures    uint32
	fullFailures uint32
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: localBalances,
		world:         worldForView(view),
		badPolicy:     make(map[edgeKey]bool),
		penalty:       make(map[edgeKey]float64),
		reserved:      make(map[edgeKey]lnwire.MilliSatoshi),
		pending:       make(map[*route.Route]attemptMeta),
		reported:      make(map[uint64]bool),
	}

	ctx := context.Background()
	seen := make(map[route.Vertex]bool)
	queue := []route.Vertex{source}
	seen[source] = true

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				if _, ok := r.edges[key]; ok {
					return nil
				}

				e := &candidateEdge{
					key: key,
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					e.maxHTLC = pol.MaxHTLC
				}

				r.edges[key] = e
				r.incomingEdges[key.to] = append(
					r.incomingEdges[key.to], e,
				)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

type searchItem struct {
	node   route.Vertex
	amount lnwire.MilliSatoshi
	score  float64
}

type searchQueue []*searchItem

func (q searchQueue) Len() int {
	return len(q)
}

func (q searchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q searchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *searchQueue) Push(x any) {
	*q = append(*q, x.(*searchItem))
}

func (q *searchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func clampProbability(p float64) float64 {
	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

// bimodalPrior models a channel as a mixture of a narrow depleted mode and
// a broad high-liquidity mode.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.018)
	highMode := 1 / (1 + math.Exp((x-0.91)/0.035))

	return clampProbability(0.48*lowMode + 0.52*highMode)
}

func (r *candidateRouter) edgeLimit(e *candidateEdge,
	extra map[edgeKey]lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	limit := e.capacity
	if e.maxHTLC != 0 && e.maxHTLC < limit {
		limit = e.maxHTLC
	}

	if e.key.from == r.source {
		balance, ok := r.localBalances[e.key.chanID]
		if !ok {
			return 0
		}
		if balance < limit {
			limit = balance
		}
	} else {
		b := r.world.belief(e.key)
		if b.upperFail != 0 && b.upperFail-1 < limit {
			limit = b.upperFail - 1
		}
	}

	used := r.reserved[e.key]
	if extra != nil {
		used += extra[e.key]
	}
	if used >= limit {
		return 0
	}

	return limit - used
}

func (r *candidateRouter) edgeProbability(e *candidateEdge,
	amt lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi) float64 {

	if e.key.from == r.source {
		return 0.995
	}

	total := amt + r.reserved[e.key]
	if extra != nil {
		total += extra[e.key]
	}

	b := r.world.belief(e.key)
	if b.lowerOK != 0 && total <= b.lowerOK {
		return 0.995
	}
	if b.upperFail != 0 && total >= b.upperFail {
		return 0.005
	}

	prior := bimodalPrior(total, e.capacity)
	if b.evidence == 0 || b.estimate == 0 {
		return prior
	}

	width := math.Max(float64(e.capacity)*0.07, 1)
	point := 1 / (1 + math.Exp(
		(float64(total)-float64(b.estimate))/width,
	))
	confidence := math.Min(0.78, float64(b.evidence)*0.18)
	return clampProbability(
		prior*(1-confidence) + point*confidence,
	)
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	searchPenalty map[edgeKey]float64,
	extraReserved map[edgeKey]lnwire.MilliSatoshi) ([]*candidateEdge,
	error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}

	best := make(map[route.Vertex]float64)
	arrival := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	best[r.spec.Target] = 0
	arrival[r.spec.Target] = amt

	pq := &searchQueue{}
	heap.Push(pq, &searchItem{
		node:   r.spec.Target,
		amount: amt,
		score:  0,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*searchItem)
		if known, ok := best[item.node]; !ok ||
			item.score > known+1e-12 {

			continue
		}
		if item.node == r.source {
			break
		}

		for _, e := range r.incomingEdges[item.node] {
			if r.badPolicy[e.key] {
				continue
			}

			amtOver := item.amount
			if amtOver < e.minHTLC ||
				amtOver > r.edgeLimit(e, extraReserved) {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if e.key.from != r.source {
				fee = e.fee(amtOver)
				sending += fee
			}
			if sending < amtOver {
				continue
			}

			p := r.edgeProbability(e, amtOver, extraReserved)
			edgeScore := -math.Log(p) + 0.018
			edgeScore += 18 * float64(fee) /
				math.Max(float64(amt), 1)
			edgeScore += 0.12 * float64(amtOver) /
				math.Max(float64(e.capacity), 1)
			edgeScore += r.penalty[e.key]
			if searchPenalty != nil {
				edgeScore += searchPenalty[e.key]
			}

			score := item.score + edgeScore
			old, ok := best[e.key.from]
			if !ok || score < old {
				best[e.key.from] = score
				arrival[e.key.from] = sending
				next[e.key.from] = e
				heap.Push(pq, &searchItem{
					node:   e.key.from,
					amount: sending,
					score:  score,
				})
			}
		}
	}

	if _, ok := best[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, 8)
	node := r.source
	for node != r.spec.Target {
		e, ok := next[node]
		if !ok {
			return nil, errors.New("broken route")
		}
		path = append(path, e)
		node = e.key.to
		if len(path) > len(r.edges)+1 {
			return nil, errors.New("route cycle")
		}
	}

	return path, nil
}

func pathSignature(path []*candidateEdge) string {
	result := ""
	for _, e := range path {
		result += fmt.Sprintf("%d/%x;", e.key.chanID, e.key.to[:4])
	}
	return result
}

func pathAmounts(path []*candidateEdge, deliver lnwire.MilliSatoshi,
	enforceMin bool) ([]lnwire.MilliSatoshi, bool) {

	if len(path) == 0 || deliver <= 0 {
		return nil, false
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	amounts[len(path)-1] = deliver

	for i := len(path) - 2; i >= 0; i-- {
		fee := path[i+1].fee(amounts[i+1])
		amounts[i] = amounts[i+1] + fee
		if amounts[i] < amounts[i+1] {
			return nil, false
		}
	}

	if enforceMin {
		for i, e := range path {
			if amounts[i] < e.minHTLC {
				return nil, false
			}
		}
	}

	return amounts, true
}

func (r *candidateRouter) pathFits(path []*candidateEdge,
	deliver lnwire.MilliSatoshi,
	extra map[edgeKey]lnwire.MilliSatoshi, soft bool) bool {

	amounts, ok := pathAmounts(path, deliver, false)
	if !ok {
		return false
	}

	for i, e := range path {
		limit := r.edgeLimit(e, extra)
		if soft && e.key.from != r.source {
			b := r.world.belief(e.key)
			switch {
			case b.lowerOK != 0:
				softLimit := b.lowerOK -
					r.reserved[e.key] - extra[e.key]
				if softLimit > limit {
					softLimit = limit
				}
				if softLimit > 0 {
					limit = softLimit
				}

			case b.estimate != 0:
				softLimit := b.estimate -
					r.reserved[e.key] - extra[e.key]
				if softLimit > 0 && softLimit < limit {
					limit = softLimit
				}

			default:
				softLimit := limit * 7 / 8
				if softLimit > 0 {
					limit = softLimit
				}
			}
		}

		if amounts[i] > limit {
			return false
		}
	}

	return true
}

func (r *candidateRouter) pathLimit(path []*candidateEdge,
	extra map[edgeKey]lnwire.MilliSatoshi, soft bool,
	max lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if max <= 0 {
		return 0
	}

	lo := lnwire.MilliSatoshi(0)
	hi := max
	for lo < hi {
		mid := lo + (hi-lo+1)/2
		if r.pathFits(path, mid, extra, soft) {
			lo = mid
		} else {
			hi = mid - 1
		}
	}

	return lo
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (*route.Route, error) {

	amounts, ok := pathAmounts(path, deliver, true)
	if !ok {
		return nil, errors.New("invalid path amount")
	}

	n := len(path)
	expiries := make([]uint32, n)
	expiries[n-1] = finalCltvDelta
	for i := n - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, n)
	for i, e := range path {
		amtToForward := deliver
		outgoingExpiry := uint32(finalCltvDelta)
		if i < n-1 {
			amtToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      e.key.to,
			ChannelID:        e.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

type pathCandidate struct {
	path []*candidateEdge
	soft lnwire.MilliSatoshi
	hard lnwire.MilliSatoshi
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots int) error {

	r.plans = nil
	if total <= 0 || slots <= 0 {
		return errors.New("no payment parts available")
	}

	// A full-value attempt is best when one corridor can carry it. Limit
	// these probes so a large payment quickly switches to a joint MPP plan.
	if r.fullFailures < 2 {
		path, err := r.findPath(total, nil, nil)
		if err == nil {
			r.plans = []plannedRoute{{path: path, amt: total}}
			return nil
		}
	}

	if slots == 1 {
		return errors.New("no route for remaining amount")
	}

	average := total / lnwire.MilliSatoshi(slots)
	if average <= 0 {
		average = total
	}
	small := average / 4
	if small < 1_000 {
		small = 1_000
	}

	maxCandidates := slots * 3
	if maxCandidates < 6 {
		maxCandidates = 6
	}
	if maxCandidates > 18 {
		maxCandidates = 18
	}

	diversity := make(map[edgeKey]float64)
	seen := make(map[string]bool)
	candidates := make([]pathCandidate, 0, maxCandidates)

	for i := 0; i < maxCandidates*2 &&
		len(candidates) < maxCandidates; i++ {

		searchAmt := average
		if i%2 == 1 {
			searchAmt = small
		}
		if searchAmt > total {
			searchAmt = total
		}

		path, err := r.findPath(searchAmt, diversity, nil)
		if err != nil {
			if searchAmt != small {
				path, err = r.findPath(small, diversity, nil)
			}
			if err != nil {
				break
			}
		}

		sig := pathSignature(path)
		for _, e := range path {
			diversity[e.key] += 1.8
		}
		if seen[sig] {
			continue
		}
		seen[sig] = true

		hard := r.pathLimit(path, nil, false, total)
		if hard <= 0 {
			continue
		}
		softLimit := r.pathLimit(path, nil, true, hard)
		if softLimit <= 0 {
			softLimit = hard / 2
		}

		candidates = append(candidates, pathCandidate{
			path: path,
			soft: softLimit,
			hard: hard,
		})
	}

	if len(candidates) == 0 {
		return errors.New("no route found")
	}

	// Allocate smaller corridors first, leaving the largest corridor to
	// absorb the unequal remainder.
	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].soft == candidates[j].soft {
			return candidates[i].hard < candidates[j].hard
		}
		return candidates[i].soft < candidates[j].soft
	})

	if len(candidates) > slots {
		candidates = candidates[:slots]
	}

	virtual := make(map[edgeKey]lnwire.MilliSatoshi)
	remaining := total
	selected := make([]plannedRoute, 0, slots)

	for i := 0; i < len(candidates) && remaining > 0; i++ {
		c := candidates[i]
		left := len(candidates) - i

		hard := r.pathLimit(c.path, virtual, false, remaining)
		if hard <= 0 {
			continue
		}
		softLimit := r.pathLimit(c.path, virtual, true, hard)
		if softLimit <= 0 {
			softLimit = hard
		}

		laterHard := lnwire.MilliSatoshi(0)
		for j := i + 1; j < len(candidates); j++ {
			laterHard += r.pathLimit(
				candidates[j].path, virtual, false, remaining,
			)
			if laterHard >= remaining {
				laterHard = remaining
				break
			}
		}

		minNeeded := remaining - laterHard
		if minNeeded < 0 {
			minNeeded = 0
		}
		want := remaining / lnwire.MilliSatoshi(left)
		if want < minNeeded {
			want = minNeeded
		}
		if want > softLimit {
			want = softLimit
		}
		if want < minNeeded {
			want = minNeeded
		}
		if want > hard {
			want = hard
		}
		if want <= 0 {
			continue
		}

		amounts, ok := pathAmounts(c.path, want, true)
		if !ok {
			continue
		}
		for j, e := range c.path {
			virtual[e.key] += amounts[j]
		}

		selected = append(selected, plannedRoute{
			path: c.path,
			amt:  want,
		})
		remaining -= want
	}

	if remaining > 0 {
		// Use any spare hard capacity in the selected route set.
		for i := len(selected) - 1; i >= 0 && remaining > 0; i-- {
			current := selected[i]
			amounts, _ := pathAmounts(
				current.path, current.amt, false,
			)
			for j, e := range current.path {
				virtual[e.key] -= amounts[j]
			}

			maxAmt := current.amt + remaining
			hard := r.pathLimit(
				current.path, virtual, false, maxAmt,
			)
			add := hard - current.amt
			if add > remaining {
				add = remaining
			}
			if add > 0 {
				selected[i].amt += add
				remaining -= add
			}

			amounts, _ = pathAmounts(
				current.path, selected[i].amt, false,
			)
			for j, e := range current.path {
				virtual[e.key] += amounts[j]
			}
		}
	}

	if len(selected) == 0 {
		return errors.New("no usable MPP route set")
	}

	// Commit the largest shards first so the most important liquidity is
	// secured before background traffic gets additional opportunities.
	sort.Slice(selected, func(i, j int) bool {
		return selected[i].amt > selected[j].amt
	})
	r.plans = selected
	return nil
}

func (r *candidateRouter) maxFailures() uint32 {
	parts := r.spec.MaxParts
	if parts == 0 {
		parts = 1
	}
	limit := uint32(12) + 4*parts
	if limit < 20 {
		limit = 20
	}
	if limit > 48 {
		limit = 48
	}
	return limit
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if r.failures >= r.maxFailures() {
		return nil, errors.New("routing attempt budget exhausted")
	}
	if amt <= 0 {
		return nil, errors.New("invalid remaining amount")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum payment parts in flight")
	}
	slots := int(maxParts - inFlightHtlcs)

	if len(r.plans) == 0 {
		if err := r.makePlan(amt, slots); err != nil {
			return nil, err
		}
	}

	plan := r.plans[0]
	r.plans = r.plans[1:]

	if plan.amt > amt {
		plan.amt = amt
	}
	if plan.amt <= 0 {
		return nil, errors.New("empty payment shard")
	}

	rt, err := r.buildRoute(plan.path, plan.amt)
	if err != nil {
		r.plans = nil
		return nil, err
	}

	r.pending[rt] = attemptMeta{
		path:      plan.path,
		shard:     plan.amt,
		remaining: amt,
	}
	return rt, nil
}

func (r *candidateRouter) pathFromRoute(rt *route.Route) []*candidateEdge {
	path := make([]*candidateEdge, 0, len(rt.Hops))
	from := rt.SourcePubKey

	for _, hop := range rt.Hops {
		key := edgeKey{
			chanID: hop.ChannelID,
			from:   from,
			to:     hop.PubKeyBytes,
		}
		e := r.edges[key]
		if e == nil {
			return nil
		}
		path = append(path, e)
		from = hop.PubKeyBytes
	}

	return path
}

func routeEdgeAmounts(rt *route.Route) []lnwire.MilliSatoshi {
	amounts := make([]lnwire.MilliSatoshi, len(rt.Hops))
	for i := range rt.Hops {
		if i == 0 {
			amounts[i] = rt.TotalAmount
		} else {
			amounts[i] = rt.Hops[i-1].AmtToForward
		}
	}
	return amounts
}

func failureEdgeIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if r.reported[attemptID] {
		return nil
	}
	r.reported[attemptID] = true

	meta, ok := r.pending[rt]
	if !ok {
		meta.path = r.pathFromRoute(rt)
		meta.shard = rt.Hops[len(rt.Hops)-1].AmtToForward
		meta.remaining = meta.shard
	}
	delete(r.pending, rt)

	path := meta.path
	if len(path) != len(rt.Hops) {
		path = r.pathFromRoute(rt)
	}
	amounts := routeEdgeAmounts(rt)

	if result.Failure == nil {
		for i, e := range path {
			if i >= len(amounts) {
				break
			}
			r.world.reportSuccess(e, amounts[i])
			r.reserved[e.key] += amounts[i]
			r.penalty[e.key] *= 0.4
		}
		return nil
	}

	r.failures++
	r.plans = nil

	for _, e := range path {
		r.penalty[e.key] += 0.08
	}

	if meta.remaining > 0 &&
		meta.shard >= meta.remaining-meta.remaining/10 {

		r.fullFailures++
	}

	failIdx := failureEdgeIndex(rt, result.FailureSource)
	if failIdx < 0 || failIdx >= len(path) ||
		failIdx >= len(amounts) {

		// Unattributed failures must still move the search away from the
		// exact route instead of repeating it until the runner's limit.
		for _, e := range path {
			r.penalty[e.key] += 0.9
		}
		return nil
	}

	failedEdge := path[failIdx]
	failedAmt := amounts[failIdx]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.world.reportFailure(failedEdge, failedAmt)
		r.penalty[failedEdge.key] += 2.4

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// This snapshot's policy cannot produce a valid route over the
		// offending direction, so avoid it for the rest of the payment.
		r.badPolicy[failedEdge.key] = true
		r.penalty[failedEdge.key] += 5

	default:
		r.penalty[failedEdge.key] += 1.5
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type edgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type liquidityBelief struct {
	lowerOK  lnwire.MilliSatoshi
	upperBad lnwire.MilliSatoshi
}

var sharedBeliefs = struct {
	sync.Mutex
	m map[edgeKey]liquidityBelief
}{
	m: make(map[edgeKey]liquidityBelief),
}

type candidateEdge struct {
	key      edgeKey
	chanID   uint64
	from, to route.Vertex
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) usable(amt lnwire.MilliSatoshi) bool {
	if amt <= 0 || amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type plannedRoute struct {
	path    []*candidateEdge
	route   *route.Route
	deliver lnwire.MilliSatoshi
	quality float64
}

type pathCandidate struct {
	path    []*candidateEdge
	probe   lnwire.MilliSatoshi
	cap     lnwire.MilliSatoshi
	quality float64
	sig     uint64
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[edgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	// These are deliberately payment-local. A failure is a hard bound for
	// the current payment, while the shared bound remains a very unlikely,
	// but still explorable, state on later payments.
	currentFail map[edgeKey]lnwire.MilliSatoshi
	policyBad   map[edgeKey]bool
	penalty     map[edgeKey]float64
	routeFails  map[uint64]int

	plan         []plannedRoute
	attempts     int
	maxAttempts  int
	unknownFails int
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	balances := make(map[uint64]lnwire.MilliSatoshi, len(localBalances))
	for chanID, balance := range localBalances {
		balances[chanID] = balance
	}

	maxParts := int(spec.MaxParts)
	if maxParts < 1 {
		maxParts = 1
	}
	maxAttempts := 24 + 4*maxParts
	if maxAttempts > 72 {
		maxAttempts = 72
	}

	r := &candidateRouter{
		source:        source,
		spec:          spec,
		incomingEdges: make(map[route.Vertex][]*candidateEdge),
		edges:         make(map[edgeKey]*candidateEdge),
		localBalances: balances,
		currentFail:   make(map[edgeKey]lnwire.MilliSatoshi),
		policyBad:     make(map[edgeKey]bool),
		penalty:       make(map[edgeKey]float64),
		routeFails:    make(map[uint64]int),
		maxAttempts:   maxAttempts,
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}

	for len(queue) != 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				key := edgeKey{
					chanID: ch.ChannelID,
					from:   ch.OtherNode,
					to:     node,
				}
				edge := &candidateEdge{
					key:           key,
					chanID:        ch.ChannelID,
					from:          ch.OtherNode,
					to:            node,
					capacity:      lnwire.NewMSatFromSatoshis(ch.Capacity),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[key] = edge
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	return r, nil
}

func clampProbability(p float64) float64 {
	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

// The prior represents a roughly even mixture of a nearly empty mode and a
// nearly full mode. Tiny HTLCs can pass in either mode, while large HTLCs
// depend almost entirely on the full mode.
func bimodalPrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0.005
	}

	x := float64(amt) / float64(capacity)
	lowMode := 0.48 * math.Exp(-x/0.025)
	highMode := 0.50 / (1 + math.Exp((x-0.88)/0.045))

	return clampProbability(0.005 + lowMode + highMode)
}

func getBelief(key edgeKey) liquidityBelief {
	sharedBeliefs.Lock()
	b := sharedBeliefs.m[key]
	sharedBeliefs.Unlock()
	return b
}

func recordSuccess(key edgeKey, amt lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	b := sharedBeliefs.m[key]

	if amt > b.lowerOK {
		b.lowerOK = amt
	}
	if b.upperBad != 0 && amt >= b.upperBad {
		b.upperBad = 0
	}
	sharedBeliefs.m[key] = b
	sharedBeliefs.Unlock()
}

func recordFailure(key edgeKey, amt lnwire.MilliSatoshi) {
	sharedBeliefs.Lock()
	b := sharedBeliefs.m[key]

	// Contradictory evidence means the network moved. Retain the fresh
	// failure rather than attempting gradual time decay.
	if b.lowerOK != 0 && amt <= b.lowerOK {
		b.lowerOK = 0
	}
	if b.upperBad == 0 || amt < b.upperBad {
		b.upperBad = amt
	}
	sharedBeliefs.m[key] = b
	sharedBeliefs.Unlock()
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if edge.from == r.source {
		if r.localBalances[edge.chanID] >= amt {
			return 0.999
		}
		return 0.001
	}

	prior := bimodalPrior(amt, edge.capacity)
	b := getBelief(edge.key)

	if b.lowerOK == 0 && b.upperBad == 0 {
		return prior
	}
	if b.lowerOK != 0 && amt <= b.lowerOK {
		return 0.995
	}

	if b.upperBad != 0 {
		if amt >= b.upperBad {
			// Shared failures are intentionally soft. This lets a later
			// payment cheaply discover that background traffic replenished
			// the direction, while current-payment failures remain hard.
			return 0.006
		}

		if b.lowerOK != 0 && b.upperBad > b.lowerOK {
			span := float64(b.upperBad - b.lowerOK)
			pos := float64(amt-b.lowerOK) / span
			evidence := 0.01 + 0.975*(1-pos)
			return clampProbability(0.80*evidence + 0.20*prior)
		}

		// A failed large HTLC still leaves a meaningful chance that a
		// substantially smaller retry fits in the depleted-side tail.
		ratio := float64(amt) / float64(b.upperBad)
		evidence := 0.01 + 0.65*math.Exp(-ratio/0.28)
		return clampProbability(0.75*evidence + 0.25*prior)
	}

	// A successful HTLC is strong evidence for the full side of the
	// bimodal distribution. Extrapolate toward capacity, but retain the
	// public prior near the final capacity cliff.
	remaining := edge.capacity - b.lowerOK
	if remaining <= 0 {
		return 0.995
	}
	pos := float64(amt-b.lowerOK) / float64(remaining)
	evidence := 0.01 + 0.96/(1+math.Exp((pos-0.82)/0.08))

	return clampProbability(0.75*evidence + 0.25*prior)
}

type dijkstraItem struct {
	node   route.Vertex
	score  float64
	amount lnwire.MilliSatoshi
	index  int
}

type dijkstraQueue []*dijkstraItem

func (q dijkstraQueue) Len() int {
	return len(q)
}

func (q dijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q dijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *dijkstraQueue) Push(x any) {
	item := x.(*dijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *dijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func copyPenalties(src map[edgeKey]float64) map[edgeKey]float64 {
	dst := make(map[edgeKey]float64, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func (r *candidateRouter) findPath(deliver lnwire.MilliSatoshi,
	extra map[edgeKey]float64) ([]*candidateEdge, error) {

	if deliver <= 0 {
		return nil, errors.New("invalid payment amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source is target")
	}

	bestScore := make(map[route.Vertex]float64)
	bestAmount := make(map[route.Vertex]lnwire.MilliSatoshi)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	bestAmount[r.spec.Target] = deliver

	pq := &dijkstraQueue{}
	heap.Push(pq, &dijkstraItem{
		node:   r.spec.Target,
		score:  0,
		amount: deliver,
	})

	for pq.Len() != 0 {
		item := heap.Pop(pq).(*dijkstraItem)
		score, ok := bestScore[item.node]
		if !ok || item.score > score+0.000001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.amount
			if !edge.usable(amtOver) || r.policyBad[edge.key] {
				continue
			}
			if bound := r.currentFail[edge.key]; bound != 0 &&
				amtOver >= bound {

				continue
			}
			if edge.from == r.source &&
				r.localBalances[edge.chanID] < amtOver {

				continue
			}

			sending := amtOver
			fee := lnwire.MilliSatoshi(0)
			if edge.from != r.source {
				fee = edge.fee(amtOver)
				sending += fee
			}

			p := r.probability(edge, amtOver)
			riskUnit := 100000.0 + float64(amtOver)/1500.0
			edgeScore := float64(fee) +
				(-math.Log(clampProbability(p)))*riskUnit +
				15000.0

			edgeScore += r.penalty[edge.key] * riskUnit
			if extra != nil {
				edgeScore += extra[edge.key] * riskUnit
			}

			newScore := item.score + edgeScore
			oldScore, exists := bestScore[edge.from]
			if !exists || newScore < oldScore {
				bestScore[edge.from] = newScore
				bestAmount[edge.from] = sending
				next[edge.from] = edge
				heap.Push(pq, &dijkstraItem{
					node:   edge.from,
					score:  newScore,
					amount: sending,
				})
			}
		}
	}

	if _, ok := next[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	path := make([]*candidateEdge, 0, 8)
	seen := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if seen[node] {
			return nil, errors.New("cyclic route")
		}
		seen[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		if len(path) > 20 {
			return nil, errors.New("route exceeds hop limit")
		}
		node = edge.to
	}

	return path, nil
}

func pathAmounts(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) ([]lnwire.MilliSatoshi, bool) {

	if len(path) == 0 || deliver <= 0 {
		return nil, false
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	amounts[len(path)-1] = deliver

	for i := len(path) - 2; i >= 0; i-- {
		fee := path[i+1].fee(amounts[i+1])
		if fee < 0 || amounts[i+1] > lnwire.MilliSatoshi(math.MaxInt64)-fee {
			return nil, false
		}
		amounts[i] = amounts[i+1] + fee
	}

	return amounts, true
}

func (r *candidateRouter) pathAllowed(path []*candidateEdge,
	deliver lnwire.MilliSatoshi, probabilityFloor float64) bool {

	amounts, ok := pathAmounts(path, deliver)
	if !ok {
		return false
	}

	for i, edge := range path {
		amt := amounts[i]
		if !edge.usable(amt) || r.policyBad[edge.key] {
			return false
		}
		if bound := r.currentFail[edge.key]; bound != 0 && amt >= bound {
			return false
		}
		if edge.from == r.source &&
			r.localBalances[edge.chanID] < amt {

			return false
		}
		if r.probability(edge, amt) < probabilityFloor {
			return false
		}
	}

	return true
}

func (r *candidateRouter) maxDeliver(path []*candidateEdge,
	probe, limit lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if probe <= 0 || limit < probe ||
		!r.pathAllowed(path, probe, 0.08) {

		return 0
	}

	lo, hi := probe, limit
	for lo < hi {
		mid := lo + (hi-lo+1)/2
		if r.pathAllowed(path, mid, 0.08) {
			lo = mid
		} else {
			hi = mid - 1
		}
	}

	return lo
}

func (r *candidateRouter) pathStats(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (float64, lnwire.MilliSatoshi, bool) {

	amounts, ok := pathAmounts(path, deliver)
	if !ok {
		return 0, 0, false
	}

	probability := 1.0
	for i, edge := range path {
		if !edge.usable(amounts[i]) {
			return 0, 0, false
		}
		probability *= r.probability(edge, amounts[i])
	}

	fee := amounts[0] - deliver
	return clampProbability(probability), fee, true
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	deliver lnwire.MilliSatoshi) (*route.Route, error) {

	amounts, ok := pathAmounts(path, deliver)
	if !ok {
		return nil, errors.New("invalid path amount")
	}

	expiries := make([]uint32, len(path))
	expiries[len(path)-1] = finalCltvDelta
	for i := len(path) - 2; i >= 0; i-- {
		expiries[i] = expiries[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := deliver
		outgoingExpiry := uint32(finalCltvDelta)
		if i < len(path)-1 {
			amtToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.to,
			ChannelID:        edge.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func pathSignature(path []*candidateEdge) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	for _, edge := range path {
		hash ^= edge.chanID
		hash *= prime
		for _, b := range edge.from {
			hash ^= uint64(b)
			hash *= prime
		}
	}
	return hash
}

func routeSignature(rt *route.Route) uint64 {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)

	hash := offset
	for _, hop := range rt.Hops {
		hash ^= hop.ChannelID
		hash *= prime
	}
	// Group close lower-amount retries together without conflating large
	// changes in shard size.
	bucket := uint64(rt.TotalAmount / 1_000_000)
	hash ^= bucket
	hash *= prime
	return hash
}

func pathsConflict(a, b []*candidateEdge) bool {
	used := make(map[uint64]bool, len(a))
	for _, edge := range a {
		used[edge.chanID] = true
	}
	for _, edge := range b {
		if used[edge.chanID] {
			return true
		}
	}
	return false
}

func compatibleWithSet(candidate *pathCandidate,
	set []*pathCandidate) bool {

	for _, existing := range set {
		if pathsConflict(candidate.path, existing.path) {
			return false
		}
	}
	return true
}

func allocateCandidates(set []*pathCandidate,
	total lnwire.MilliSatoshi) ([]lnwire.MilliSatoshi,
	lnwire.MilliSatoshi, bool) {

	if len(set) == 0 {
		return nil, 0, false
	}

	var capSum, floorSum lnwire.MilliSatoshi
	for _, candidate := range set {
		if candidate.cap < candidate.probe {
			return nil, 0, false
		}
		capSum += candidate.cap
		floorSum += candidate.probe
	}

	goal := total
	if capSum < goal {
		goal = capSum
	}
	if floorSum > goal {
		return nil, 0, false
	}

	allocations := make([]lnwire.MilliSatoshi, len(set))
	var spareSum lnwire.MilliSatoshi
	for i, candidate := range set {
		allocations[i] = candidate.probe
		spareSum += candidate.cap - candidate.probe
	}

	left := goal - floorSum
	if left == 0 {
		return allocations, goal, true
	}
	if spareSum <= 0 {
		return nil, 0, false
	}

	var assigned lnwire.MilliSatoshi
	for i, candidate := range set {
		spare := candidate.cap - candidate.probe
		add := lnwire.MilliSatoshi(
			float64(left) * float64(spare) / float64(spareSum),
		)
		if add > spare {
			add = spare
		}
		allocations[i] += add
		assigned += add
	}

	remainder := left - assigned
	for i := 0; remainder > 0 && i < len(set); i++ {
		room := set[i].cap - allocations[i]
		if room <= 0 {
			continue
		}
		add := room
		if add > remainder {
			add = remainder
		}
		allocations[i] += add
		remainder -= add
	}

	return allocations, goal - remainder, remainder == 0
}

func (r *candidateRouter) evaluateSet(set []*pathCandidate,
	total lnwire.MilliSatoshi) ([]lnwire.MilliSatoshi,
	lnwire.MilliSatoshi, float64, bool) {

	allocations, delivered, ok := allocateCandidates(set, total)
	if !ok {
		return nil, 0, 0, false
	}

	objective := 0.0
	feeScale := 100000.0 + float64(total)/2000.0

	for i, candidate := range set {
		if !r.pathAllowed(candidate.path, allocations[i], 0.005) {
			return nil, 0, 0, false
		}
		p, fee, ok := r.pathStats(candidate.path, allocations[i])
		if !ok {
			return nil, 0, 0, false
		}
		objective += math.Log(clampProbability(p))
		objective -= float64(fee) / feeScale
	}

	// Slightly prefer fewer simultaneous failure points when estimates tie.
	objective -= 0.015 * float64(len(set))
	return allocations, delivered, objective, true
}

func (r *candidateRouter) discoverCandidates(total lnwire.MilliSatoshi,
	slots int) []*pathCandidate {

	base := total / lnwire.MilliSatoshi(slots)
	if base <= 0 {
		base = 1
	}

	extra := copyPenalties(r.penalty)
	seen := make(map[uint64]bool)
	candidates := make([]*pathCandidate, 0, slots*2)

	triesPerLevel := slots * 2
	if triesPerLevel < 4 {
		triesPerLevel = 4
	}
	if triesPerLevel > 10 {
		triesPerLevel = 10
	}

	for level := 0; level < 4 && len(candidates) < 32; level++ {
		probe := base
		for i := 0; i < level; i++ {
			probe = (probe + 1) / 2
		}
		if probe <= 0 {
			probe = 1
		}

		for try := 0; try < triesPerLevel; try++ {
			path, err := r.findPath(probe, extra)
			if err != nil {
				break
			}

			sig := pathSignature(path)
			for _, edge := range path {
				extra[edge.key] += 7.0
			}

			if seen[sig] {
				for _, edge := range path {
					extra[edge.key] += 6.0
				}
				continue
			}
			seen[sig] = true

			capacity := r.maxDeliver(path, probe, total)
			if capacity < probe {
				continue
			}

			p, fee, ok := r.pathStats(path, probe)
			if !ok {
				continue
			}
			scale := 100000.0 + float64(probe)/2000.0
			quality := math.Log(clampProbability(p)) +
				0.55*math.Log1p(float64(capacity)/float64(probe)) -
				float64(fee)/scale

			candidates = append(candidates, &pathCandidate{
				path:    path,
				probe:   probe,
				cap:     capacity,
				quality: quality,
				sig:     sig,
			})
		}
	}

	sort.Slice(candidates, func(i, j int) bool {
		if candidates[i].quality == candidates[j].quality {
			return candidates[i].cap > candidates[j].cap
		}
		return candidates[i].quality > candidates[j].quality
	})

	return candidates
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	slots int) []plannedRoute {

	if total <= 0 || slots <= 0 {
		return nil
	}

	candidates := r.discoverCandidates(total, slots)
	if len(candidates) == 0 {
		return nil
	}

	var bestSet []*pathCandidate
	var bestAlloc []lnwire.MilliSatoshi
	var bestDelivered lnwire.MilliSatoshi
	bestObjective := math.Inf(-1)

	consider := func(set []*pathCandidate) {
		alloc, delivered, objective, ok := r.evaluateSet(set, total)
		if !ok {
			return
		}

		better := delivered > bestDelivered
		if delivered == bestDelivered && objective > bestObjective {
			better = true
		}
		if better {
			bestSet = append([]*pathCandidate(nil), set...)
			bestAlloc = append([]lnwire.MilliSatoshi(nil), alloc...)
			bestDelivered = delivered
			bestObjective = objective
		}
	}

	for seed := 0; seed < len(candidates); seed++ {
		set := []*pathCandidate{candidates[seed]}
		consider(set)

		for _, candidate := range candidates {
			if len(set) >= slots {
				break
			}
			if candidate == candidates[seed] ||
				!compatibleWithSet(candidate, set) {

				continue
			}

			set = append(set, candidate)
			consider(set)
		}
	}

	if len(bestSet) == 0 {
		return nil
	}

	plan := make([]plannedRoute, 0, len(bestSet))
	for i, candidate := range bestSet {
		rt, err := r.buildRoute(candidate.path, bestAlloc[i])
		if err != nil {
			continue
		}

		p, fee, _ := r.pathStats(candidate.path, bestAlloc[i])
		quality := math.Log(clampProbability(p)) -
			float64(fee)/(100000.0+float64(bestAlloc[i])/2000.0)

		plan = append(plan, plannedRoute{
			path:    candidate.path,
			route:   rt,
			deliver: bestAlloc[i],
			quality: quality,
		})
	}

	// Commit the strongest shards first. If one fails, ReportAttempt drops
	// the remainder of this plan and replans around the fresh bound.
	sort.Slice(plan, func(i, j int) bool {
		return plan[i].quality > plan[j].quality
	})

	return plan
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment complete")
	}
	if r.attempts >= r.maxAttempts {
		return nil, errors.New("attempt budget exhausted")
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum parts in flight")
	}
	slots := int(maxParts - inFlightHtlcs)

	if len(r.plan) != 0 && r.plan[0].deliver > amt {
		r.plan = nil
	}
	if len(r.plan) == 0 {
		r.plan = r.makePlan(amt, slots)
	}
	if len(r.plan) != 0 {
		next := r.plan[0]
		r.plan = r.plan[1:]
		return next.route, nil
	}

	// Last-resort lower retry ladder. This is intentionally short: joint
	// planning is preferred in atomic arenas, but a depleted channel can
	// still be useful at a substantially smaller amount.
	shard := amt
	if slots > 1 {
		shard = (amt + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)
	}

	for tries := 0; tries < 7 && shard > 0; tries++ {
		path, err := r.findPath(shard, nil)
		if err == nil {
			return r.buildRoute(path, shard)
		}
		if slots <= 1 || shard == 1 {
			return nil, err
		}
		next := shard * 55 / 100
		if next >= shard {
			next = shard - 1
		}
		shard = next
	}

	return nil, errors.New("no route found")
}

func routeEdgeKey(rt *route.Route, index int) edgeKey {
	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}
	return edgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}
}

func routeChannelAmount(rt *route.Route,
	index int) lnwire.MilliSatoshi {

	if index == 0 {
		return rt.TotalAmount
	}
	return rt.Hops[index-1].AmtToForward
}

func failureOutgoingIndex(rt *route.Route,
	source route.Vertex) int {

	if source == rt.SourcePubKey {
		return 0
	}
	for i, hop := range rt.Hops {
		if hop.PubKeyBytes == source {
			return i + 1
		}
	}
	return -1
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID
	r.attempts++

	if rt == nil || len(rt.Hops) == 0 {
		r.plan = nil
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key := routeEdgeKey(rt, i)
			amt := routeChannelAmount(rt, i)
			recordSuccess(key, amt)
		}

		// A settled or held shard consumes our exact outbound balance.
		firstAmt := routeChannelAmount(rt, 0)
		firstChan := rt.Hops[0].ChannelID
		if r.localBalances[firstChan] >= firstAmt {
			r.localBalances[firstChan] -= firstAmt
		} else {
			r.localBalances[firstChan] = 0
		}
		return nil
	}

	r.plan = nil
	failIndex := failureOutgoingIndex(rt, result.FailureSource)

	// Every channel before the failing node demonstrably carried this HTLC.
	if failIndex >= 0 {
		passed := failIndex
		if passed > len(rt.Hops) {
			passed = len(rt.Hops)
		}
		for i := 0; i < passed; i++ {
			recordSuccess(
				routeEdgeKey(rt, i),
				routeChannelAmount(rt, i),
			)
		}
	}

	code := result.Failure.Code()
	switch code {
	case lnwire.CodeTemporaryChannelFailure:
		if failIndex >= 0 && failIndex < len(rt.Hops) {
			key := routeEdgeKey(rt, failIndex)
			amt := routeChannelAmount(rt, failIndex)

			bound := r.currentFail[key]
			if bound == 0 || amt < bound {
				r.currentFail[key] = amt
			}
			recordFailure(key, amt)
			r.penalty[key] += 1.0
			return nil
		}

	case lnwire.CodeFeeInsufficient, lnwire.CodeIncorrectCltvExpiry:
		if failIndex >= 0 && failIndex < len(rt.Hops) {
			key := routeEdgeKey(rt, failIndex)
			r.policyBad[key] = true
			r.penalty[key] += 12.0
			return nil
		}
	}

	// Unknown-source and terminal failures otherwise cause an identical
	// route to repeat forever. Spread a moderate penalty across the path,
	// escalating if the same amount/path combination recurs.
	r.unknownFails++
	sig := routeSignature(rt)
	r.routeFails[sig]++
	multiplier := 1.5 + float64(r.routeFails[sig])

	for i := range rt.Hops {
		key := routeEdgeKey(rt, i)
		r.penalty[key] += multiplier
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	// currentFails are hard bounds learned during this payment. Historical
	// bounds are deliberately soft so a changed channel gets one chance to
	// refresh, while a failure in the current payment is not repeated at
	// the same amount.
	currentFails map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked map[candidateEdgeKey]bool

	// reserved is reconstructed from successful in-flight shards. It makes
	// route selection account for liquidity already held by atomic MPP.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*5 + 12
	if r.attemptLimit < 32 {
		r.attemptLimit = 32
	}
	if r.attemptLimit > 96 {
		r.attemptLimit = 96
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	total := amt + reserved

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		balance := r.localBalances[edge.key.chanID]
		if total > balance {
			return 0
		}
		return 0.999
	}

	if r.policyBlocked[edge.key] {
		return 0
	}

	if bound := r.currentFails[edge.key]; bound != 0 &&
		total >= bound {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	// Historical failure bounds are soft. Liquidity may have moved since
	// the observation, but their large penalty ensures they are retried
	// only when fresher-looking alternatives are exhausted.
	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*pos
		p = 0.2*p + 0.8*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.55 {
			scale := 1 - 0.92*(ratio-0.55)/0.45
			if scale < 0.08 {
				scale = 0.08
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		ratio := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.45 * math.Exp(-ratio/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.12 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.7*p + 0.3*q
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node    route.Vertex
	score   float64
	required lnwire.MilliSatoshi
	logProb float64
	idx     int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int { return len(q) }
func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}
func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}
func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}
func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 350_000.0
		hopPenalty = 250.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			// In atomic MPP, prefer another corridor once a channel is
			// already occupied. This is only a penalty: shared endpoint
			// bottlenecks remain usable when unavoidable.
			if r.reserved[edge.key] > 0 {
				edgeScore += 80_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.reserved[key] += amt
			}
		}
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if partsLeft == 1 {
		rt, _, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}
		r.attempts++
		return rt, nil
	}

	base := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base, amt)
	candidateAddAmount(&sizes, seen, base*5/4, amt)
	candidateAddAmount(&sizes, seen, base*3/2, amt)
	candidateAddAmount(&sizes, seen, base*2, amt)
	candidateAddAmount(&sizes, seen, base*3, amt)
	candidateAddAmount(&sizes, seen, amt, amt)

	// Lower retry sizes are considered only if no allocation capable of
	// completing within the remaining part budget can be found.
	var lowerSizes []lnwire.MilliSatoshi
	lowerSeen := make(map[lnwire.MilliSatoshi]bool)
	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&lowerSizes, lowerSeen, r.lastFailedShard*5/8, amt,
		)
	}
	candidateAddAmount(&lowerSizes, lowerSeen, base*3/4, amt)
	candidateAddAmount(&lowerSizes, lowerSeen, base/2, amt)

	choose := func(candidates []lnwire.MilliSatoshi,
		reference lnwire.MilliSatoshi) (*route.Route, error) {

		var bestRoute *route.Route
		bestUtility := math.Inf(-1)

		for _, size := range candidates {
			rt, logProb, err := r.findRoute(size)
			if err != nil {
				continue
			}

			fees := rt.TotalAmount - size
			sizeReward := math.Log(
				float64(size) / float64(reference),
			)

			// Payment completion dominates. The modest size reward
			// avoids gratuitous tiny shards while allowing a large,
			// reliable corridor to take an unequal share.
			utility := logProb + 0.38*sizeReward -
				float64(fees)/5_000_000

			if bestRoute == nil || utility > bestUtility {
				bestRoute = rt
				bestUtility = utility
			}
		}

		if bestRoute == nil {
			return nil, errors.New("no route found")
		}
		return bestRoute, nil
	}

	rt, err := choose(sizes, base)
	if err != nil {
		rt, err = choose(lowerSizes, base)
	}
	if err != nil {
		return nil, err
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}
		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	// Every channel before the failing outgoing channel demonstrably
	// forwarded this attempt, so retain that positive information.
	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.lastFailedShard =
			rt.Hops[len(rt.Hops)-1].AmtToForward

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// Policy failures say nothing about liquidity. Avoid the stale or
		// incompatible directed policy for the rest of this payment.
		r.policyBlocked[key] = true

	default:
		// Unknown failures at a forwarding node are safer to route around
		// locally, without poisoning persistent liquidity knowledge.
		r.policyBlocked[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked map[candidateEdgeKey]bool
	edgePenalty   map[candidateEdgeKey]float64

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgePenalty:    make(map[candidateEdgeKey]float64),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*3 + 12
	if r.attemptLimit < 24 {
		r.attemptLimit = 24
	}
	if r.attemptLimit > 48 {
		r.attemptLimit = 48
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	held := reserved[edge.key]
	total := amt + held

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}
	if bound := r.currentFails[edge.key]; bound != 0 &&
		total >= bound {

		return 0
	}

	if edge.key.from == r.source {
		if total > r.localBalances[edge.key.chanID] {
			return 0
		}
		return 0.999
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	// Historical failure evidence remains strong but not absolute. This
	// gives a channel whose balance moved one expensive refresh attempt
	// only after genuinely better alternatives have been exhausted.
	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.010 {
			p = 0.010
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.99 - 0.98*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.50 {
			scale := 1 - 0.94*(ratio-0.50)/0.50
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.50 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	switch {
	case p < 0.005:
		return 0.005
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 500_000.0
		hopPenalty = 350.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver, reserved)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty +
				r.edgePenalty[edge.key]

			// A planned or held sibling shard should normally use a new
			// corridor. Sharing remains possible for endpoint bottlenecks
			// and when the combined amount is well supported by evidence.
			if held := reserved[edge.key]; held > 0 {
				fraction := float64(held) /
					math.Max(1, float64(edge.capacity))
				edgeScore += 140_000 + 300_000*fraction
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReserved(
	src map[candidateEdgeKey]lnwire.MilliSatoshi) map[
	candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveRoute(
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		candidateReserveRoute(r.reserved, rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planAmounts(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var amounts []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&amounts, seen, base, remaining)
	candidateAddAmount(&amounts, seen, base*3/4, remaining)
	candidateAddAmount(&amounts, seen, base*5/4, remaining)
	candidateAddAmount(&amounts, seen, base*3/2, remaining)
	candidateAddAmount(&amounts, seen, base*9/5, remaining)
	candidateAddAmount(&amounts, seen, base/2, remaining)
	candidateAddAmount(&amounts, seen, base*5/2, remaining)
	candidateAddAmount(&amounts, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&amounts, seen, r.lastFailedShard*5/8, remaining,
		)
		candidateAddAmount(
			&amounts, seen, r.lastFailedShard*3/4, remaining,
		)
	}

	// The target-side channel carries exactly the shard amount, making
	// its capacity and learned bounds especially useful split points.
	for _, edge := range r.incomingEdges[r.spec.Target] {
		if len(amounts) >= 24 {
			break
		}

		candidateAddAmount(
			&amounts, seen, edge.capacity*8/100, remaining,
		)
		candidateAddAmount(
			&amounts, seen, edge.capacity*45/100, remaining,
		)
		candidateAddAmount(
			&amounts, seen, edge.capacity*82/100, remaining,
		)

		belief := r.beliefs[edge.key]
		if belief.lowerOK > 0 {
			candidateAddAmount(
				&amounts, seen, belief.lowerOK, remaining,
			)
		}
		if belief.upperFail > 0 {
			candidateAddAmount(
				&amounts, seen,
				belief.upperFail*5/8, remaining,
			)
		}
	}

	sort.Slice(amounts, func(i, j int) bool {
		di := math.Abs(math.Log(
			float64(amounts[i]) / float64(base),
		))
		dj := math.Abs(math.Log(
			float64(amounts[j]) / float64(base),
		))
		return di < dj
	})

	if len(amounts) > 24 {
		amounts = amounts[:24]
	}

	return amounts
}

type candidatePlanState struct {
	remaining lnwire.MilliSatoshi
	routes    []*route.Route
	reserved  map[candidateEdgeKey]lnwire.MilliSatoshi
	score     float64
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	partsLeft uint32) ([]*route.Route, error) {

	if partsLeft <= 1 {
		rt, _, err := r.findRoute(amt, r.reserved)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	initial := amt
	beam := []*candidatePlanState{{
		remaining: amt,
		reserved:  candidateCopyReserved(r.reserved),
	}}
	var complete []*candidatePlanState

	const beamWidth = 10

	for depth := uint32(0); depth < partsLeft && len(beam) > 0; depth++ {
		var nextBeam []*candidatePlanState

		for _, state := range beam {
			slots := partsLeft - uint32(len(state.routes))
			for _, shard := range r.planAmounts(
				state.remaining, slots,
			) {
				if shard <= 0 || shard > state.remaining {
					continue
				}

				rt, logProb, err := r.findRoute(
					shard, state.reserved,
				)
				if err != nil {
					continue
				}

				nextReserved := candidateCopyReserved(
					state.reserved,
				)
				candidateReserveRoute(nextReserved, rt)

				fees := rt.TotalAmount - shard
				nextState := &candidatePlanState{
					remaining: state.remaining - shard,
					routes: append(
						append([]*route.Route(nil),
							state.routes...),
						rt,
					),
					reserved: nextReserved,
					score: state.score + logProb -
						float64(fees)/4_000_000 -
						0.025,
				}

				if nextState.remaining == 0 {
					complete = append(complete, nextState)
				} else if slots > 1 {
					nextBeam = append(nextBeam, nextState)
				}
			}
		}

		sort.Slice(nextBeam, func(i, j int) bool {
			progressI := float64(initial-nextBeam[i].remaining) /
				float64(initial)
			progressJ := float64(initial-nextBeam[j].remaining) /
				float64(initial)

			rankI := nextBeam[i].score + 0.16*progressI
			rankJ := nextBeam[j].score + 0.16*progressJ
			return rankI > rankJ
		})

		if len(nextBeam) > beamWidth {
			nextBeam = nextBeam[:beamWidth]
		}
		beam = nextBeam
	}

	if len(complete) == 0 {
		return nil, errors.New("no complete route set found")
	}

	sort.Slice(complete, func(i, j int) bool {
		return complete[i].score > complete[j].score
	})
	return complete[0].routes, nil
}

func (r *candidateRouter) plannedAmount() lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, rt := range r.planned {
		total += candidateFinalAmount(rt)
	}
	return total
}

func (r *candidateRouter) routeStillUsable(rt *route.Route) bool {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil {
			return false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok || r.probability(edge, amt, r.reserved) <= 0 {
			return false
		}
	}
	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	// A precomputed route set represents an atomic commitment plan. Keep
	// using it only while the observed remaining amount and reservations
	// match the plan.
	if len(r.planned) > 0 {
		if r.plannedAmount() != amt ||
			!r.routeStillUsable(r.planned[0]) {

			r.planned = nil
		}
	}

	if len(r.planned) == 0 {
		plan, err := r.makePlan(amt, partsLeft)
		if err != nil {
			// If a complete joint allocation cannot be constructed,
			// retain the best reactive lower-amount behavior.
			base := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
				lnwire.MilliSatoshi(partsLeft)

			var fallback []lnwire.MilliSatoshi
			seen := make(map[lnwire.MilliSatoshi]bool)
			candidateAddAmount(&fallback, seen, base, amt)
			if r.lastFailedShard > 0 {
				candidateAddAmount(
					&fallback, seen,
					r.lastFailedShard*5/8, amt,
				)
			}
			candidateAddAmount(
				&fallback, seen, base*3/4, amt,
			)
			candidateAddAmount(
				&fallback, seen, base/2, amt,
			)
			candidateAddAmount(&fallback, seen, amt, amt)

			var best *route.Route
			bestUtility := math.Inf(-1)
			for _, shard := range fallback {
				rt, logProb, routeErr := r.findRoute(
					shard, r.reserved,
				)
				if routeErr != nil {
					continue
				}

				fees := rt.TotalAmount - shard
				utility := logProb +
					0.25*math.Log(
						float64(shard)/float64(base),
					) -
					float64(fees)/4_000_000

				if best == nil || utility > bestUtility {
					best = rt
					bestUtility = utility
				}
			}
			if best == nil {
				return nil, err
			}
			r.planned = []*route.Route{best}
		} else {
			r.planned = plan
		}
	}

	rt := r.planned[0]
	r.planned = r.planned[1:]
	r.attempts++

	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if bound := r.currentFails[key]; bound != 0 && amt >= bound {
		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) penalizeRoute(rt *route.Route, penalty float64) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgePenalty[key] += penalty
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.learnSuccess(key, amt+r.reserved[key])
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	// Any failed member invalidates the uncommitted remainder of the
	// route-set plan. Replan around its new evidence immediately.
	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	// Failures without an identifiable outgoing channel must not cause
	// an exact-route retry loop. Apply a soft whole-path penalty while
	// avoiding unsupported persistent liquidity conclusions.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		r.penalizeRoute(rt, 180_000)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.penalizeRoute(rt, 180_000)
		return nil
	}

	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.penalizeRoute(rt, 180_000)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)

		// Permit a materially smaller retry on the same channel, but
		// prefer another corridor when one has comparable reliability.
		r.edgePenalty[key] += 45_000

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true

	default:
		r.policyBlocked[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked map[candidateEdgeKey]bool
	failureCost   map[candidateEdgeKey]float64
	unknownFails  map[candidateEdgeKey]uint32

	// reserved represents liquidity held by successful atomic-MPP shards.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route

	// planned is the remainder of a route set selected jointly. It is kept
	// after a successful shard and discarded whenever an attempt fails.
	planned []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		failureCost:    make(map[candidateEdgeKey]float64),
		unknownFails:   make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*4 + 12
	if r.attemptLimit < 32 {
		r.attemptLimit = 32
	}
	if r.attemptLimit > 72 {
		r.attemptLimit = 72
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)

	// The first mode models an almost empty directed channel. The second
	// models a channel whose balance is almost entirely in this direction.
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	total := amt + reserved

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		if total > r.localBalances[edge.key.chanID] {
			return 0
		}
		return 0.999
	}

	if r.policyBlocked[edge.key] {
		return 0
	}

	if bound := r.currentFails[edge.key]; bound != 0 &&
		total >= bound {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	// Historical bounds remain strong. A tiny non-zero probability lets a
	// changed channel be refreshed only after better alternatives run out.
	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.008 {
			p = 0.008
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.99 - 0.98*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.94*(ratio-0.45)/0.55
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.5 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight       = 350_000.0
		hopPenalty       = 250.0
		reservedPenalty  = 220_000.0
		failureWeight    = 190_000.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty +
				failureWeight*r.failureCost[edge.key]

			// Prefer a distinct corridor for another atomic shard. Sharing
			// remains possible when the combined liquidity is credible.
			if r.reserved[edge.key] > 0 {
				edgeScore += reservedPenalty
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}

	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateShardAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCloneReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateEqualAllocation(total lnwire.MilliSatoshi,
	parts int) []lnwire.MilliSatoshi {

	if parts <= 0 || total < lnwire.MilliSatoshi(parts) {
		return nil
	}

	result := make([]lnwire.MilliSatoshi, 0, parts)
	remaining := total

	for left := parts; left > 0; left-- {
		amt := (remaining + lnwire.MilliSatoshi(left) - 1) /
			lnwire.MilliSatoshi(left)
		result = append(result, amt)
		remaining -= amt
	}

	return result
}

func candidateFirstBiasedAllocation(total lnwire.MilliSatoshi,
	parts int, numerator, denominator int64) []lnwire.MilliSatoshi {

	if parts <= 1 {
		return candidateEqualAllocation(total, parts)
	}
	if total < lnwire.MilliSatoshi(parts) {
		return nil
	}

	base := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)
	first := base * lnwire.MilliSatoshi(numerator) /
		lnwire.MilliSatoshi(denominator)

	maxFirst := total - lnwire.MilliSatoshi(parts-1)
	if first < 1 {
		first = 1
	}
	if first > maxFirst {
		first = maxFirst
	}

	tail := candidateEqualAllocation(total-first, parts-1)
	if tail == nil {
		return nil
	}

	result := make([]lnwire.MilliSatoshi, 0, parts)
	result = append(result, first)
	result = append(result, tail...)
	return result
}

func candidateAllocationEqual(a, b []lnwire.MilliSatoshi) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func candidateAppendAllocation(dst *[][]lnwire.MilliSatoshi,
	allocation []lnwire.MilliSatoshi) {

	if len(allocation) == 0 {
		return
	}
	for _, old := range *dst {
		if candidateAllocationEqual(old, allocation) {
			return
		}
	}
	*dst = append(*dst, allocation)
}

func (r *candidateRouter) hintedAllocation(total lnwire.MilliSatoshi,
	parts int) []lnwire.MilliSatoshi {

	if parts <= 1 {
		return nil
	}

	base := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)
	maxFirst := total - lnwire.MilliSatoshi(parts-1)
	var hint lnwire.MilliSatoshi

	for _, edge := range r.incomingEdges[r.spec.Target] {
		reserved := r.reserved[edge.key]
		if reserved >= edge.capacity {
			continue
		}

		available := edge.capacity - reserved
		belief := r.beliefs[edge.key]

		value := available * 3 / 4
		if belief.estimate > reserved {
			value = belief.estimate - reserved
		}
		if belief.lowerOK > reserved {
			proven := belief.lowerOK - reserved
			if proven > value {
				value = proven
			}
		}

		if value > maxFirst {
			value = maxFirst
		}
		if value >= base/2 && value > hint {
			hint = value
		}
	}

	if hint <= 0 {
		return nil
	}

	tail := candidateEqualAllocation(total-hint, parts-1)
	if tail == nil {
		return nil
	}

	result := make([]lnwire.MilliSatoshi, 0, parts)
	result = append(result, hint)
	result = append(result, tail...)
	return result
}

func (r *candidateRouter) buildPlan(
	allocation []lnwire.MilliSatoshi) ([]*route.Route, float64, bool) {

	original := candidateCloneReservations(r.reserved)
	defer func() {
		r.reserved = original
	}()

	r.reserved = candidateCloneReservations(original)

	routes := make([]*route.Route, 0, len(allocation))
	var logProb float64
	var fees lnwire.MilliSatoshi

	for _, shard := range allocation {
		rt, lp, err := r.findRoute(shard)
		if err != nil {
			return nil, 0, false
		}

		routes = append(routes, rt)
		logProb += lp
		fees += rt.TotalAmount - shard
		r.reserveRoute(rt)
	}

	// Completion probability dominates. Fees and the number of held shards
	// are only tie-breakers between plans with comparable reliability.
	score := logProb -
		float64(fees)/3_500_000 -
		0.035*float64(len(routes)-1)

	return routes, score, true
}

func (r *candidateRouter) chooseJointPlan(total lnwire.MilliSatoshi,
	maxParts uint32) ([]*route.Route, error) {

	limit := int(maxParts)
	if limit < 1 {
		limit = 1
	}
	if total < lnwire.MilliSatoshi(limit) {
		limit = int(total)
	}
	if limit < 1 {
		return nil, errors.New("invalid payment amount")
	}

	var best []*route.Route
	bestScore := math.Inf(-1)

	for parts := 1; parts <= limit; parts++ {
		var allocations [][]lnwire.MilliSatoshi

		candidateAppendAllocation(
			&allocations,
			candidateEqualAllocation(total, parts),
		)
		if parts > 1 {
			candidateAppendAllocation(
				&allocations,
				candidateFirstBiasedAllocation(
					total, parts, 3, 2,
				),
			)
			candidateAppendAllocation(
				&allocations,
				candidateFirstBiasedAllocation(
					total, parts, 3, 4,
				),
			)
			candidateAppendAllocation(
				&allocations,
				r.hintedAllocation(total, parts),
			)
		}

		for _, allocation := range allocations {
			plan, score, ok := r.buildPlan(allocation)
			if !ok {
				continue
			}
			if best == nil || score > bestScore {
				best = plan
				bestScore = score
			}
		}
	}

	if best == nil {
		return nil, errors.New("no complete route set found")
	}
	return best, nil
}

func (r *candidateRouter) routeUsable(rt *route.Route) bool {
	if rt == nil || len(rt.Hops) == 0 {
		return false
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil {
			return false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok || r.probability(edge, amt) <= 0 {
			return false
		}
	}

	return true
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) fallbackRoute(amt lnwire.MilliSatoshi,
	partsLeft uint32) (*route.Route, error) {

	if partsLeft <= 1 {
		rt, _, err := r.findRoute(amt)
		return rt, err
	}

	base := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base, amt)
	candidateAddAmount(&sizes, seen, base*5/4, amt)
	candidateAddAmount(&sizes, seen, base*3/2, amt)
	candidateAddAmount(&sizes, seen, base*2, amt)
	candidateAddAmount(&sizes, seen, base*3/4, amt)
	candidateAddAmount(&sizes, seen, base/2, amt)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, amt,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/8, amt,
		)
	}

	var best *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range sizes {
		rt, logProb, err := r.findRoute(size)
		if err != nil {
			continue
		}

		fees := rt.TotalAmount - size
		progress := math.Log(float64(size) / float64(base))
		utility := logProb + 0.30*progress -
			float64(fees)/4_000_000

		if best == nil || utility > bestUtility {
			best = rt
			bestUtility = utility
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		shard := candidateShardAmount(rt)

		if shard > 0 && shard <= amt &&
			uint32(len(r.planned)) <= partsLeft &&
			r.routeUsable(rt) {

			r.planned = r.planned[1:]
			r.attempts++
			return rt, nil
		}

		r.planned = nil
	}

	plan, err := r.chooseJointPlan(amt, partsLeft)
	if err == nil && len(plan) > 0 {
		rt := plan[0]
		r.planned = plan[1:]
		r.attempts++
		return rt, nil
	}

	rt, err := r.fallbackRoute(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) penalizeRoute(rt *route.Route, amount float64) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.failureCost[key] += amount
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}

			r.learnSuccess(key, amt+r.reserved[key])
			if r.failureCost[key] > 0.15 {
				r.failureCost[key] -= 0.15
			} else {
				r.failureCost[key] = 0
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	// A failed member invalidates the precomputed route set. The next call
	// plans again using the new bound and the still-held successful shards.
	r.planned = nil
	r.penalizeRoute(rt, 0.10)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	r.lastFailedShard = candidateShardAmount(rt)

	// Some simulator failures do not identify a source. Repeatedly retrying
	// the identical terminal corridor caused the longest failure ladders.
	// Strongly diversify once, then block that corridor after a recurrence.
	if failIdx < 0 || failIdx >= len(rt.Hops) {
		last := len(rt.Hops) - 1
		key, ok := candidateRouteEdgeKey(rt, last)
		if ok {
			r.failureCost[key] += 2.5
			r.unknownFails[key]++
			if r.unknownFails[key] >= 2 {
				r.policyBlocked[key] = true
			}
		}
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		// Keep lower retries available, but prefer a fresh corridor first.
		r.learnFailure(key, totalRequired)
		r.failureCost[key] += 0.35

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		// Policy errors are not liquidity observations.
		r.policyBlocked[key] = true
		r.failureCost[key] += 2

	default:
		// Unknown forwarding errors are local to this directed channel and
		// must not poison persistent liquidity beliefs.
		r.policyBlocked[key] = true
		r.failureCost[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgeByKey     map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked map[candidateEdgeKey]bool
	edgePenalty  map[candidateEdgeKey]float64
	failedRoutes map[uint64]uint8

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat))
	x ^= candidateMix64(uint64(e.feeRatePPM))
	x ^= candidateMix64(uint64(e.timeLockDelta))
	x ^= candidateMix64(uint64(e.minHTLC))
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgeByKey:      make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgePenalty:    make(map[candidateEdgeKey]float64),
		failedRoutes:   make(map[uint64]uint8),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*3 + 12
	if r.attemptLimit < 28 {
		r.attemptLimit = 28
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgeByKey[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	held := reserved[edge.key]
	total := amt + held

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		balance := r.localBalances[edge.key.chanID]
		if total > balance {
			return 0
		}
		if bound := r.currentFails[edge.key]; bound != 0 &&
			total >= bound {

			return 0
		}
		return 0.999
	}

	if r.policyBlocked[edge.key] {
		return 0
	}

	if bound := r.currentFails[edge.key]; bound != 0 &&
		total >= bound {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*position
		p = 0.18*p + 0.82*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.5 {
			scale := 1 - 0.94*(ratio-0.5)/0.5
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.5 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.1 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.68*p + 0.32*q
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type candidateRouteOption struct {
	rt      *route.Route
	logProb float64
	score   float64
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	banned map[candidateEdgeKey]bool) (*route.Route, float64, float64,
	error) {

	if amt <= 0 {
		return nil, 0, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 280_000.0
		hopPenalty = 300.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64
	var sourceScore float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			sourceScore = item.score
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned != nil && banned[edge.key] {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver, reserved)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty +
				r.edgePenalty[edge.key]

			actualHeld := r.reserved[edge.key]
			plannedHeld := reserved[edge.key]
			if actualHeld > 0 {
				edgeScore += 180_000
			}
			if plannedHeld > actualHeld {
				edgeScore += 300_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, 0, err
	}

	return rt, sourceLogProb, sourceScore, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidatePathHash(rt *route.Route) uint64 {
	h := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		x := candidateMix64(key.chanID)
		x ^= candidateMix64(candidateVertexHash(key.from))
		x ^= candidateMix64(candidateVertexHash(key.to))
		h = candidateMix64(h ^ x)
	}
	return h
}

func candidateAttemptHash(rt *route.Route) uint64 {
	return candidateMix64(
		candidatePathHash(rt) ^
			candidateMix64(uint64(candidateFinalAmount(rt))),
	)
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func candidateReserveRoute(
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		candidateReserveRoute(r.reserved, rt)
	}
}

func (r *candidateRouter) routeOptions(amt lnwire.MilliSatoshi,
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	limit int) []candidateRouteOption {

	rt, logProb, score, err := r.findRoute(amt, reserved, nil)
	if err != nil {
		return nil
	}

	options := []candidateRouteOption{{
		rt:      rt,
		logProb: logProb,
		score:   score,
	}}
	seen := map[uint64]bool{
		candidatePathHash(rt): true,
	}

	for optionIndex := 0; optionIndex < len(options) &&
		optionIndex < 4 && len(options) < limit; optionIndex++ {

		path := options[optionIndex].rt
		for i := range path.Hops {
			key, ok := candidateRouteEdgeKey(path, i)
			if !ok {
				continue
			}

			banned := map[candidateEdgeKey]bool{key: true}
			alt, altLogProb, altScore, findErr := r.findRoute(
				amt, reserved, banned,
			)
			if findErr != nil {
				continue
			}

			hash := candidatePathHash(alt)
			if seen[hash] {
				continue
			}
			seen[hash] = true

			options = append(options, candidateRouteOption{
				rt:      alt,
				logProb: altLogProb,
				score:   altScore,
			})
			if len(options) >= limit {
				break
			}
		}
	}

	return options
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) selectShard(remaining lnwire.MilliSatoshi,
	partsLeft uint32,
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi) (
	*route.Route, error) {

	if remaining <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if partsLeft == 0 {
		return nil, errors.New("maximum number of parts in flight")
	}

	if partsLeft == 1 {
		options := r.routeOptions(remaining, reserved, 10)
		var best *route.Route
		bestUtility := math.Inf(-1)

		for _, option := range options {
			if r.failedRoutes[candidateAttemptHash(option.rt)] > 0 {
				continue
			}
			fees := option.rt.TotalAmount - remaining
			utility := option.logProb -
				float64(fees)/3_000_000 -
				option.score/2_000_000_000
			if best == nil || utility > bestUtility {
				best = option.rt
				bestUtility = utility
			}
		}
		if best == nil {
			return nil, errors.New("no route found")
		}
		return best, nil
	}

	base := (remaining + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, base*5/2, remaining)
	candidateAddAmount(&sizes, seen, base*3, remaining)
	candidateAddAmount(&sizes, seen, base*4, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/4, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
	}
	candidateAddAmount(&sizes, seen, base*3/4, remaining)
	candidateAddAmount(&sizes, seen, base/2, remaining)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range sizes {
		options := r.routeOptions(size, reserved, 9)
		for _, option := range options {
			if r.failedRoutes[candidateAttemptHash(option.rt)] > 0 {
				continue
			}

			fees := option.rt.TotalAmount - size
			sizeReward := math.Log(
				float64(size) / float64(base),
			)

			utility := option.logProb + 0.62*sizeReward -
				float64(fees)/3_000_000 -
				option.score/2_500_000_000

			if size < base {
				utility -= 0.25 *
					math.Log(float64(base)/float64(size))
			}

			if bestRoute == nil || utility > bestUtility {
				bestRoute = option.rt
				bestUtility = utility
			}
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}
	return bestRoute, nil
}

func (r *candidateRouter) planRoutes(amt lnwire.MilliSatoshi,
	partsLeft uint32) {

	r.planned = nil
	if amt <= 0 || partsLeft == 0 {
		return
	}

	virtualReserved := candidateCopyReservations(r.reserved)
	remaining := amt

	for slot := uint32(0); slot < partsLeft && remaining > 0; slot++ {
		slotsLeft := partsLeft - slot
		rt, err := r.selectShard(
			remaining, slotsLeft, virtualReserved,
		)
		if err != nil {
			break
		}

		shard := candidateFinalAmount(rt)
		if shard <= 0 || shard > remaining {
			break
		}

		r.planned = append(r.planned, rt)
		candidateReserveRoute(virtualReserved, rt)
		remaining -= shard
	}
}

func (r *candidateRouter) routeUsable(rt *route.Route,
	remaining lnwire.MilliSatoshi) bool {

	if rt == nil || candidateFinalAmount(rt) <= 0 ||
		candidateFinalAmount(rt) > remaining {

		return false
	}
	if r.failedRoutes[candidateAttemptHash(rt)] > 0 {
		return false
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edgeByKey[key]
		if edge == nil {
			return false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok || r.probability(edge, amt, r.reserved) <= 0 {
			return false
		}
	}

	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	for len(r.planned) > 0 {
		rt := r.planned[0]
		r.planned = r.planned[1:]
		if !r.routeUsable(rt, amt) {
			continue
		}

		r.attempts++
		return rt, nil
	}

	r.planRoutes(amt, partsLeft)
	for len(r.planned) > 0 {
		rt := r.planned[0]
		r.planned = r.planned[1:]
		if !r.routeUsable(rt, amt) {
			continue
		}

		r.attempts++
		return rt, nil
	}

	return nil, errors.New("no route found")
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) penalizeUnknownRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgePenalty[key] += 35_000
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	attemptHash := candidateAttemptHash(rt)
	if r.failedRoutes[attemptHash] < 255 {
		r.failedRoutes[attemptHash]++
	}

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		r.penalizeUnknownRoute(rt)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.penalizeUnknownRoute(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.penalizeUnknownRoute(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.edgePenalty[key] += 20_000
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.lastFailedShard = candidateFinalAmount(rt)

	default:
		r.edgePenalty[key] += 100_000
		r.penalizeUnknownRoute(rt)
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked map[candidateEdgeKey]bool
	edgePenalty   map[candidateEdgeKey]float64
	routeFailures map[uint64]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route

	plan []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgePenalty:    make(map[candidateEdgeKey]float64),
		routeFailures:  make(map[uint64]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*3 + 12
	if r.attemptLimit < 28 {
		r.attemptLimit = 28
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	reserved := reservations[edge.key]
	total := amt + reserved

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}
	if bound := r.currentFails[edge.key]; bound != 0 &&
		total >= bound {

		return 0
	}

	if edge.key.from == r.source {
		if total > r.localBalances[edge.key.chanID] {
			return 0
		}
		return 0.999
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.002 {
			p = 0.002
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		evidence := 0.99 - 0.985*position
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.97*(ratio-0.45)/0.55
			if scale < 0.03 {
				scale = 0.03
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.5 * math.Exp(-distance/0.17)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.1 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateProb := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*estimateProb
	}

	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	bias map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight       = 400_000.0
		hopPenalty       = 220.0
		heldEdgePenalty  = 120_000.0
		plannedReuseCost = 330_000.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver, reservations)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += bias[edge.key]
			edgeScore += r.edgePenalty[edge.key] * 180_000

			if r.reserved[edge.key] > 0 {
				edgeScore += heldEdgePenalty
			}
			if reservations[edge.key] > r.reserved[edge.key] {
				edgeScore += plannedReuseCost
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateRouteDelivery(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteSignature(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	hash := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i, hop := range rt.Hops {
		x := candidateMix64(hop.ChannelID + uint64(i+1))
		x ^= candidateMix64(candidateVertexHash(hop.PubKeyBytes))
		hash = candidateMix64(hash ^ x)
	}
	return hash
}

func candidateCloneReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	clone := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(source))
	for key, amount := range source {
		clone[key] = amount
	}
	return clone
}

func candidateReserveRoute(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		candidateReserveRoute(r.reserved, rt)
	}
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeAlternatives(
	amt lnwire.MilliSatoshi,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
) []candidateRouteChoice {

	first, firstLogProb, err := r.findRoute(amt, reservations, nil)
	if err != nil {
		return nil
	}

	firstSignature := candidateRouteSignature(first)
	firstLogProb -= 1.4 * float64(r.routeFailures[firstSignature])

	choices := []candidateRouteChoice{{
		route:   first,
		logProb: firstLogProb,
	}}

	bias := make(map[candidateEdgeKey]float64)
	for i := range first.Hops {
		key, ok := candidateRouteEdgeKey(first, i)
		if ok {
			bias[key] += 700_000
		}
	}

	second, secondLogProb, err := r.findRoute(
		amt, reservations, bias,
	)
	if err != nil {
		return choices
	}

	secondSignature := candidateRouteSignature(second)
	if secondSignature == firstSignature {
		return choices
	}

	secondLogProb -= 1.4 * float64(r.routeFailures[secondSignature])
	choices = append(choices, candidateRouteChoice{
		route:   second,
		logProb: secondLogProb,
	})

	return choices
}

func candidateAddSize(sizes *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, size,
	maxSize lnwire.MilliSatoshi) {

	if size < 1 {
		size = 1
	}
	if size > maxSize {
		size = maxSize
	}
	if size > 0 && !seen[size] {
		seen[size] = true
		*sizes = append(*sizes, size)
	}
}

func (r *candidateRouter) allocationSizes(
	remaining lnwire.MilliSatoshi, partsLeft int,
) []lnwire.MilliSatoshi {

	if partsLeft <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	maxSize := remaining - lnwire.MilliSatoshi(partsLeft-1)
	if maxSize <= 0 {
		return nil
	}

	base := remaining / lnwire.MilliSatoshi(partsLeft)
	if base <= 0 {
		base = 1
	}

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddSize(&sizes, seen, base*3/5, maxSize)
	candidateAddSize(&sizes, seen, base*17/20, maxSize)
	candidateAddSize(&sizes, seen, base, maxSize)
	candidateAddSize(&sizes, seen, base*13/10, maxSize)
	candidateAddSize(&sizes, seen, base*9/5, maxSize)
	candidateAddSize(&sizes, seen, base*13/5, maxSize)

	if r.lastFailedShard > 0 {
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*9/20, maxSize,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*5/8, maxSize,
		)
	}

	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	routes       []*route.Route
	score        float64
}

func (r *candidateRouter) planForPartCount(total lnwire.MilliSatoshi,
	partCount int) (*candidatePlanState, bool) {

	if partCount <= 0 {
		return nil, false
	}

	beam := []*candidatePlanState{{
		remaining:    total,
		reservations: candidateCloneReservations(r.reserved),
	}}

	const beamWidth = 5

	for partIndex := 0; partIndex < partCount; partIndex++ {
		partsLeft := partCount - partIndex
		var expanded []*candidatePlanState

		for _, state := range beam {
			sizes := r.allocationSizes(
				state.remaining, partsLeft,
			)
			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				alternatives := r.routeAlternatives(
					size, state.reservations,
				)
				for _, choice := range alternatives {
					nextReservations := candidateCloneReservations(
						state.reservations,
					)
					candidateReserveRoute(
						nextReservations, choice.route,
					)

					nextRoutes := make(
						[]*route.Route, len(state.routes)+1,
					)
					copy(nextRoutes, state.routes)
					nextRoutes[len(state.routes)] = choice.route

					fees := choice.route.TotalAmount - size
					score := state.score + choice.logProb -
						float64(fees)/8_000_000 - 0.08

					expanded = append(expanded, &candidatePlanState{
						remaining: state.remaining - size,
						reservations: nextReservations,
						routes:       nextRoutes,
						score:        score,
					})
				}
			}
		}

		if len(expanded) == 0 {
			return nil, false
		}

		sort.Slice(expanded, func(i, j int) bool {
			return expanded[i].score > expanded[j].score
		})
		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		beam = expanded
	}

	var best *candidatePlanState
	for _, state := range beam {
		if state.remaining != 0 {
			continue
		}
		if best == nil || state.score > best.score {
			best = state
		}
	}

	return best, best != nil
}

func candidatePartCounts(maxParts int) []int {
	if maxParts < 1 {
		return nil
	}

	seen := make(map[int]bool)
	var counts []int

	add := func(value int) {
		if value < 1 || value > maxParts || seen[value] {
			return
		}
		seen[value] = true
		counts = append(counts, value)
	}

	add(1)
	add(2)
	add(3)
	add(4)
	add(6)
	add(8)
	add(12)
	add(maxParts)

	sort.Ints(counts)
	return counts
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	maxParts int) ([]*route.Route, error) {

	var best *candidatePlanState
	for _, partCount := range candidatePartCounts(maxParts) {
		state, ok := r.planForPartCount(total, partCount)
		if !ok {
			continue
		}
		if best == nil || state.score > best.score {
			best = state
		}
	}

	if best == nil || len(best.routes) == 0 {
		return nil, errors.New("no route found")
	}
	return best.routes, nil
}

func candidatePlanAmount(plan []*route.Route) lnwire.MilliSatoshi {
	var total lnwire.MilliSatoshi
	for _, rt := range plan {
		total += candidateRouteDelivery(rt)
	}
	return total
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}

	partsLeft := int(maxParts - inFlightHtlcs)
	if len(r.plan) > 0 && candidatePlanAmount(r.plan) != amt {
		r.plan = nil
	}

	if len(r.plan) == 0 {
		plan, err := r.makePlan(amt, partsLeft)
		if err != nil {
			return nil, err
		}
		r.plan = plan
	}

	rt := r.plan[0]
	r.plan = r.plan[1:]
	r.attempts++

	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}
	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 9 / 20
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) penalizeUnknownRoute(rt *route.Route) {
	signature := candidateRouteSignature(rt)
	r.routeFailures[signature]++

	increment := 0.7
	if len(rt.Hops) > 0 {
		increment /= float64(len(rt.Hops))
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgePenalty[key] += increment
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.plan = nil

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	passed := failIndex
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIndex < 0 || failIndex >= len(rt.Hops) {
		r.penalizeUnknownRoute(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIndex)
	if !ok {
		r.penalizeUnknownRoute(rt)
		return nil
	}

	amtOver, ok := candidateRouteAmount(rt, failIndex)
	if !ok {
		r.penalizeUnknownRoute(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.edgePenalty[key] += 0.2
		r.lastFailedShard = candidateRouteDelivery(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.routeFailures[candidateRouteSignature(rt)]++

	default:
		r.policyBlocked[key] = true
		r.penalizeUnknownRoute(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) +
		0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat) +
		uint64(e.feeRatePPM)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) +
		uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 8
	if r.attemptLimit < 24 {
		r.attemptLimit = 24
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	total := amt + reserved

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.count >= 2 {
			return 0
		}
		if failure.upper > 0 {
			if total >= failure.upper {
				return 0
			}

			retryCeiling := failure.upper * 2 / 3
			if retryCeiling == 0 {
				retryCeiling = 1
			}
			if total > retryCeiling {
				return 0
			}
			retryScale = 0.35
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*pos
		p = 0.2*p + 0.8*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.55 {
			scale := 1 - 0.92*(ratio-0.55)/0.45
			if scale < 0.08 {
				scale = 0.08
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.45 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.12 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.7*p + 0.3*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 420_000.0
		hopPenalty = 220.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 22_000
			edgeScore += float64(r.suspect[edge.key]) * 260_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 260_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planOnce(total lnwire.MilliSatoshi,
	parts uint32, sizeBias float64) ([]*route.Route, float64, bool) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	remaining := total
	slots := parts
	var plan []*route.Route
	jointScore := 0.0

	for remaining > 0 && slots > 0 {
		if slots == 1 {
			rt, logProb, err := r.findRoute(remaining)
			if err != nil {
				return nil, 0, false
			}

			fees := rt.TotalAmount - remaining
			jointScore += logProb -
				float64(fees)/4_000_000 - 0.025
			plan = append(plan, rt)
			r.reserveRoute(rt)
			remaining = 0
			break
		}

		base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		var sizes []lnwire.MilliSatoshi
		seen := make(map[lnwire.MilliSatoshi]bool)

		candidateAddAmount(&sizes, seen, base, remaining)
		candidateAddAmount(&sizes, seen, base*5/4, remaining)
		candidateAddAmount(&sizes, seen, base*3/2, remaining)
		candidateAddAmount(&sizes, seen, base*2, remaining)
		candidateAddAmount(&sizes, seen, base*3, remaining)
		candidateAddAmount(&sizes, seen, remaining, remaining)

		if r.lastFailedShard > 0 {
			candidateAddAmount(
				&sizes, seen, r.lastFailedShard*5/8,
				remaining,
			)
		}

		var bestRoute *route.Route
		bestSize := lnwire.MilliSatoshi(0)
		bestLogProb := 0.0
		bestUtility := math.Inf(-1)

		for _, size := range sizes {
			rt, logProb, err := r.findRoute(size)
			if err != nil {
				continue
			}

			fees := rt.TotalAmount - size
			sizeReward := math.Log(
				float64(size) / float64(base),
			)
			utility := logProb + sizeBias*sizeReward -
				float64(fees)/4_000_000

			if bestRoute == nil || utility > bestUtility {
				bestRoute = rt
				bestSize = size
				bestLogProb = logProb
				bestUtility = utility
			}
		}

		if bestRoute == nil {
			return nil, 0, false
		}

		fees := bestRoute.TotalAmount - bestSize
		jointScore += bestLogProb -
			float64(fees)/4_000_000 - 0.025

		plan = append(plan, bestRoute)
		r.reserveRoute(bestRoute)
		remaining -= bestSize
		slots--
	}

	if remaining != 0 || len(plan) == 0 {
		return nil, 0, false
	}
	return plan, jointScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32, inFlight uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	if inFlight == 0 && r.lastFailedShard == 0 {
		full, logProb, err := r.findRoute(total)
		if err == nil && logProb >= math.Log(0.22) {
			return []*route.Route{full}, nil
		}
	}

	biases := []float64{0.28, 0.48, 0.72}
	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	for _, bias := range biases {
		plan, score, ok := r.planOnce(total, parts, bias)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		if candidateFinalAmount(rt) > 0 &&
			candidateFinalAmount(rt) <= amt {

			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft, inFlightHtlcs)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32
	searchPenalty map[candidateEdgeKey]float64

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		searchPenalty:  make(map[candidateEdgeKey]float64),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 6
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 52 {
		r.attemptLimit = 52
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.94)/0.032))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.987 {
		return 0.987
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		if ratio > 0.82 {
			return 0
		}

		retryScale = 0.78 - 0.42*ratio
		if retryScale < 0.32 {
			retryScale = 0.32
		}
		if failure.count > 2 {
			retryScale *= 0.85
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.996 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.006)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.992 - 0.982*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.42 {
			scale := 1 - 0.90*(ratio-0.42)/0.58
			if scale < 0.07 {
				scale = 0.07
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.52 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.09 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		weight := 0.32
		if belief.successes+belief.failures > 2 {
			weight = 0.42
		}
		p = (1-weight)*p + weight*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.996 {
		return 0.996
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 470_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 15_000
			edgeScore += float64(r.suspect[edge.key]) * 210_000
			edgeScore += r.searchPenalty[edge.key]

			if r.reserved[edge.key] > 0 {
				fraction := float64(r.reserved[edge.key]) /
					math.Max(1, float64(edge.capacity))
				edgeScore += 55_000 + fraction*190_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

type candidateRouteOption struct {
	route   *route.Route
	logProb float64
}

func candidateSameRoute(a, b *route.Route) bool {
	if a == nil || b == nil || len(a.Hops) != len(b.Hops) {
		return false
	}
	for i := range a.Hops {
		if a.Hops[i].ChannelID != b.Hops[i].ChannelID ||
			a.Hops[i].PubKeyBytes != b.Hops[i].PubKeyBytes {

			return false
		}
	}
	return true
}

func (r *candidateRouter) routeOptions(
	size lnwire.MilliSatoshi) []candidateRouteOption {

	first, firstProb, err := r.findRoute(size)
	if err != nil {
		return nil
	}

	options := []candidateRouteOption{{
		route:   first,
		logProb: firstProb,
	}}

	oldPenalty := r.searchPenalty
	penalty := make(map[candidateEdgeKey]float64)
	for i := range first.Hops {
		key, ok := candidateRouteEdgeKey(first, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(first.Hops) > 1 {
			continue
		}
		penalty[key] = 620_000
	}
	r.searchPenalty = penalty
	alternate, alternateProb, alternateErr := r.findRoute(size)
	r.searchPenalty = oldPenalty

	if alternateErr == nil && !candidateSameRoute(first, alternate) {
		options = append(options, candidateRouteOption{
			route:   alternate,
			logProb: alternateProb,
		})
	}

	return options
}

type candidatePlanState struct {
	routes    []*route.Route
	reserved  map[candidateEdgeKey]lnwire.MilliSatoshi
	remaining lnwire.MilliSatoshi
	score     float64
}

func (r *candidateRouter) planningSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base*3/4, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*1/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*2/3, remaining,
		)
	}

	sort.Slice(sizes, func(i, j int) bool {
		di := math.Abs(float64(sizes[i] - base))
		dj := math.Abs(float64(sizes[j] - base))
		return di < dj
	})

	if len(sizes) > 8 {
		sizes = sizes[:8]
	}
	return sizes
}

func candidatePlanRank(state candidatePlanState,
	total lnwire.MilliSatoshi) float64 {

	delivered := total - state.remaining
	progress := float64(delivered) / math.Max(1, float64(total))
	return state.score + 0.9*progress
}

func (r *candidateRouter) makeJointPlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		reserved:  candidateCopyReservations(r.reserved),
		remaining: total,
	}}

	var bestComplete *candidatePlanState
	const beamWidth = 14

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slotsLeft := parts - depth
		var next []candidatePlanState

		for _, state := range states {
			sizes := r.planningSizes(state.remaining, slotsLeft)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reserved,
				)
				options := r.routeOptions(size)

				for _, option := range options {
					fees := option.route.TotalAmount - size
					score := state.score + option.logProb -
						float64(fees)/4_500_000 - 0.03

					newReserved := candidateCopyReservations(
						state.reserved,
					)
					r.reserved = newReserved
					r.reserveRoute(option.route)

					routes := append(
						[]*route.Route(nil), state.routes...,
					)
					routes = append(routes, option.route)

					child := candidatePlanState{
						routes:    routes,
						reserved:  newReserved,
						remaining: state.remaining - size,
						score:     score,
					}

					if child.remaining == 0 {
						if bestComplete == nil ||
							child.score > bestComplete.score {

							copyChild := child
							bestComplete = &copyChild
						}
						continue
					}

					if slotsLeft > 1 {
						next = append(next, child)
					}
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return candidatePlanRank(next[i], total) >
				candidatePlanRank(next[j], total)
		})
		if len(next) > beamWidth {
			next = next[:beamWidth]
		}
		states = next
	}

	if bestComplete == nil {
		return nil, errors.New("no complete route set found")
	}
	return bestComplete.routes, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32, inFlight uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	if inFlight == 0 && r.lastFailedShard == 0 {
		full, logProb, err := r.findRoute(total)
		if err == nil && logProb >= math.Log(0.62) {
			return []*route.Route{full}, nil
		}
	}

	plan, err := r.makeJointPlan(total, parts)
	if err == nil && len(plan) > 0 {
		return plan, nil
	}

	rt, _, routeErr := r.findRoute(total)
	if routeErr != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft, inFlightHtlcs)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	var capacity lnwire.MilliSatoshi
	for _, edges := range r.incomingEdges {
		for _, edge := range edges {
			if edge.key == key {
				capacity = edge.capacity
				break
			}
		}
		if capacity > 0 {
			break
		}
	}

	highEstimate := capacity * 9 / 10
	if highEstimate < amt {
		highEstimate = amt
	}
	if highEstimate > belief.estimate {
		belief.estimate = highEstimate
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 9 / 20
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else {
		belief.estimate = (
			belief.estimate*2 + estimate
		) / 3
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) +
		0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat) +
		uint64(e.feeRatePPM)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) +
		uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 44 {
		r.attemptLimit = 44
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}

	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if ok {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.995

		case belief.upperFail > 0 && total >= belief.upperFail:
			if p > 0.010 {
				p = 0.010
			}

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK:

			width := float64(
				belief.upperFail - belief.lowerOK,
			)
			pos := float64(total-belief.lowerOK) / width
			if pos < 0 {
				pos = 0
			}
			if pos > 1 {
				pos = 1
			}
			evidence := 0.99 - 0.98*pos
			p = 0.16*p + 0.84*evidence

		case belief.upperFail > 0:
			ratio := float64(total) /
				float64(belief.upperFail)
			if ratio > 0.45 {
				scale := 1 - 0.88*(ratio-0.45)/0.55
				if scale < 0.12 {
					scale = 0.12
				}
				p *= scale
			}

		case belief.lowerOK > 0 && total > belief.lowerOK:
			distance := float64(total-belief.lowerOK) /
				float64(edge.capacity)
			boost := 0.48 * math.Exp(-distance/0.20)
			p += boost * (1 - p)
		}

		if belief.estimate > 0 {
			scale := 0.10 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			q := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate)) /
					scale,
			))
			p = 0.72*p + 0.28*q
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		count := failure.count
		if count > 3 {
			count = 3
		}
		p *= math.Pow(0.74, float64(count))
	}

	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	shard lnwire.MilliSatoshi) float64 {

	if r.policyBlocked[edge.key] || !edge.policyAllows(shard) {
		return 0
	}

	reserved := r.reserved[edge.key]
	total := reserved + shard
	if total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	totalProb := r.liquidityProbability(edge, total)
	if totalProb <= 0 {
		return 0
	}

	if reserved == 0 {
		return totalProb
	}

	baseProb := r.liquidityProbability(edge, reserved)
	if baseProb <= 0 {
		baseProb = 0.002
	}

	conditional := totalProb / baseProb
	if conditional < 0.001 {
		return 0.001
	}
	if conditional > 0.999 {
		return 0.999
	}
	return conditional
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 340_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 8_000
			edgeScore += float64(r.suspect[edge.key]) * 180_000

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if max <= 0 {
		return
	}
	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

type candidateSizeHint struct {
	amt      lnwire.MilliSatoshi
	distance float64
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	maxFirst := remaining - lnwire.MilliSatoshi(slots-1)
	if maxFirst <= 0 {
		return nil
	}

	base := remaining / lnwire.MilliSatoshi(slots)
	if base <= 0 {
		base = 1
	}

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base/2, maxFirst)
	candidateAddAmount(&sizes, seen, base*2/3, maxFirst)
	candidateAddAmount(&sizes, seen, base*4/5, maxFirst)
	candidateAddAmount(&sizes, seen, base, maxFirst)
	candidateAddAmount(&sizes, seen, base*5/4, maxFirst)
	candidateAddAmount(&sizes, seen, base*3/2, maxFirst)
	candidateAddAmount(&sizes, seen, base*2, maxFirst)
	candidateAddAmount(&sizes, seen, maxFirst, maxFirst)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, maxFirst,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, maxFirst,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/4, maxFirst,
		)
	}

	hints := make([]candidateSizeHint, 0, len(r.beliefs)*3)
	for _, belief := range r.beliefs {
		values := []lnwire.MilliSatoshi{
			belief.lowerOK,
			belief.estimate,
			belief.upperFail * 5 / 8,
		}
		for _, value := range values {
			if value <= 0 || value > maxFirst {
				continue
			}
			distance := math.Abs(math.Log(
				float64(value) / float64(base),
			))
			hints = append(hints, candidateSizeHint{
				amt:      value,
				distance: distance,
			})
		}
	}

	sort.Slice(hints, func(i, j int) bool {
		return hints[i].distance < hints[j].distance
	})
	if len(hints) > 4 {
		hints = hints[:4]
	}
	for _, hint := range hints {
		candidateAddAmount(
			&sizes, seen, hint.amt, maxFirst,
		)
	}

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] < sizes[j]
	})
	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planForParts(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, float64, bool) {

	if parts == 0 || total < lnwire.MilliSatoshi(parts) {
		return nil, 0, false
	}

	originalReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = originalReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(originalReservations),
	}}

	const beamWidth = 4

	for step := uint32(0); step < parts; step++ {
		var nextStates []candidatePlanState

		for _, state := range states {
			sizes := r.planSizes(state.remaining, state.slots)
			for _, size := range sizes {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				rt, logProb, err := r.findRoute(size)
				if err != nil {
					continue
				}

				fees := rt.TotalAmount - size
				score := state.score + logProb -
					float64(fees)/4_000_000 - 0.022

				reservations := candidateCopyReservations(
					r.reserved,
				)
				r.reserved = reservations
				r.reserveRoute(rt)

				routes := make([]*route.Route, len(state.routes)+1)
				copy(routes, state.routes)
				routes[len(state.routes)] = rt

				remaining := state.remaining - size
				slots := state.slots - 1
				if slots == 0 && remaining != 0 {
					continue
				}
				if slots > 0 &&
					remaining < lnwire.MilliSatoshi(slots) {

					continue
				}

				progress := 1 - float64(remaining)/float64(total)
				nextStates = append(
					nextStates, candidatePlanState{
						remaining:    remaining,
						slots:        slots,
						routes:       routes,
						reservations: reservations,
						score:        score,
						rank:         score + 0.08*progress,
					},
				)
			}
		}

		if len(nextStates) == 0 {
			return nil, 0, false
		}

		sort.Slice(nextStates, func(i, j int) bool {
			return nextStates[i].rank > nextStates[j].rank
		})
		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	var best *candidatePlanState
	for i := range states {
		state := &states[i]
		if state.remaining != 0 {
			continue
		}
		if best == nil || state.score > best.score {
			best = state
		}
	}

	if best == nil {
		return nil, 0, false
	}
	return best.routes, best.score, true
}

func candidatePartCounts(maxParts uint32) []uint32 {
	candidates := []uint32{1, 2, 3, 4, 6, 8, maxParts}
	seen := make(map[uint32]bool)
	counts := make([]uint32, 0, len(candidates))

	for _, count := range candidates {
		if count == 0 || count > maxParts || seen[count] {
			continue
		}
		seen[count] = true
		counts = append(counts, count)
	}
	sort.Slice(counts, func(i, j int) bool {
		return counts[i] < counts[j]
	})
	return counts
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	for _, count := range candidatePartCounts(parts) {
		plan, score, ok := r.planForParts(total, count)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		return nil, errors.New("no route found")
	}
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	if belief.upperFail > belief.lowerOK {
		belief.estimate = belief.lowerOK +
			(belief.upperFail-belief.lowerOK)/2
	} else if amt > belief.estimate {
		belief.estimate = amt
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		belief.estimate = belief.lowerOK +
			(belief.upperFail-belief.lowerOK)/2
	} else {
		estimate := amt * 5 / 8
		if belief.estimate == 0 || belief.estimate >= amt {
			belief.estimate = estimate
		}
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails    map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked   map[candidateEdgeKey]bool
	transientPenalty map[candidateEdgeKey]float64

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route

	planned   []*route.Route
	queuedAmt lnwire.MilliSatoshi

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:           source,
		spec:             spec,
		incomingEdges:    make(map[route.Vertex][]*candidateEdge),
		localBalances:    localBalances,
		beliefs:          make(map[candidateEdgeKey]candidateBelief),
		currentFails:     make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:    make(map[candidateEdgeKey]bool),
		transientPenalty: make(map[candidateEdgeKey]float64),
		reserved:         make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*3 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if total > r.localBalances[edge.key.chanID] {
			return 0
		}
		return 0.999
	}

	if bound := r.currentFails[edge.key]; bound > 0 && total >= bound {
		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*pos
		p = 0.2*p + 0.8*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.5 {
			scale := 1 - 0.93*(ratio-0.5)/0.5
			if scale < 0.07 {
				scale = 0.07
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.45 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.12 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	path     []*candidateEdge
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight       = 390_000.0
		hopPenalty       = 300.0
		reservedPenalty  = 850_000.0
	)

	bestScore := make(map[route.Vertex]float64)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(amt, item.path)
			if err != nil {
				return nil, 0, err
			}
			return rt, item.logProb, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty +
				r.transientPenalty[edge.key]

			if r.reserved[edge.key] > 0 {
				edgeScore += reservedPenalty
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			bestScore[edge.key.from] = score
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				path:     path,
			})
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}
	if path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("broken route")
	}

	for i := 1; i < len(path); i++ {
		if path[i-1].key.to != path[i].key.from {
			return nil, errors.New("disconnected route")
		}
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateDeliveryAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateCloneReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func candidateReserveRoute(
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		candidateReserveRoute(r.reserved, rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/4, remaining,
		)
		candidateAddAmount(
			&sizes, seen, base/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, base*3/4, remaining,
		)
	}

	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, base*5/2, remaining)
	candidateAddAmount(&sizes, seen, base*3, remaining)

	candidateAddAmount(&sizes, seen, remaining/4, remaining)
	candidateAddAmount(&sizes, seen, remaining/3, remaining)
	candidateAddAmount(&sizes, seen, remaining/2, remaining)
	candidateAddAmount(&sizes, seen, remaining*2/3, remaining)
	candidateAddAmount(&sizes, seen, remaining*3/4, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] < sizes[j]
	})
	return sizes
}

type candidatePlanState struct {
	remaining lnwire.MilliSatoshi
	routes    []*route.Route
	reserved  map[candidateEdgeKey]lnwire.MilliSatoshi
	score     float64
}

func (r *candidateRouter) buildPlan(amt lnwire.MilliSatoshi,
	partsLeft uint32) ([]*route.Route, error) {

	if partsLeft == 0 {
		return nil, errors.New("no payment parts available")
	}

	actualReservations := r.reserved
	defer func() {
		r.reserved = actualReservations
	}()

	initial := &candidatePlanState{
		remaining: amt,
		reserved:  candidateCloneReservations(actualReservations),
	}
	states := []*candidatePlanState{initial}

	var bestComplete *candidatePlanState
	const beamWidth = 6

	for depth := uint32(0); depth < partsLeft && len(states) > 0; depth++ {
		var nextStates []*candidatePlanState

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					bestComplete = state
				}
				continue
			}

			slots := partsLeft - depth
			for _, size := range r.planSizes(state.remaining, slots) {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = state.reserved
				rt, logProb, err := r.findRoute(size)
				if err != nil {
					continue
				}

				fees := rt.TotalAmount - size
				nextReserved := candidateCloneReservations(
					state.reserved,
				)
				candidateReserveRoute(nextReserved, rt)

				nextRoutes := make(
					[]*route.Route, len(state.routes)+1,
				)
				copy(nextRoutes, state.routes)
				nextRoutes[len(state.routes)] = rt

				next := &candidatePlanState{
					remaining: state.remaining - size,
					routes:    nextRoutes,
					reserved:  nextReserved,
					score: state.score + logProb -
						float64(fees)/10_000_000,
				}

				if next.remaining == 0 {
					if bestComplete == nil ||
						next.score > bestComplete.score {

						bestComplete = next
					}
				} else if slots > 1 {
					nextStates = append(nextStates, next)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			progressI := float64(amt-nextStates[i].remaining) /
				float64(amt)
			progressJ := float64(amt-nextStates[j].remaining) /
				float64(amt)

			rankI := nextStates[i].score + 0.3*progressI
			rankJ := nextStates[j].score + 0.3*progressJ
			return rankI > rankJ
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if bestComplete == nil {
		r.reserved = actualReservations
		rt, _, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	return bestComplete.routes, nil
}

func (r *candidateRouter) clearPlan() {
	r.planned = nil
	r.queuedAmt = 0
}

func (r *candidateRouter) popPlannedRoute() (*route.Route, error) {
	if len(r.planned) == 0 {
		return nil, errors.New("empty route plan")
	}

	rt := r.planned[0]
	r.planned = r.planned[1:]

	delivered := candidateDeliveryAmount(rt)
	if delivered <= 0 || delivered > r.queuedAmt {
		r.clearPlan()
		return nil, errors.New("invalid planned shard")
	}
	r.queuedAmt -= delivered
	return rt, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 &&
		r.queuedAmt == amt &&
		uint32(len(r.planned)) <= partsLeft {

		rt, err := r.popPlannedRoute()
		if err != nil {
			return nil, err
		}
		r.attempts++
		return rt, nil
	}

	r.clearPlan()

	plan, err := r.buildPlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}
	if len(plan) == 0 || uint32(len(plan)) > partsLeft {
		return nil, errors.New("no feasible shard plan")
	}

	var total lnwire.MilliSatoshi
	for _, rt := range plan {
		total += candidateDeliveryAmount(rt)
	}
	if total != amt {
		return nil, errors.New("incomplete shard plan")
	}

	r.planned = plan
	r.queuedAmt = total

	rt, err := r.popPlannedRoute()
	if err != nil {
		return nil, err
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) penalizeUnknownRoute(rt *route.Route) {
	if rt == nil || len(rt.Hops) == 0 {
		return
	}

	penalty := 260_000.0
	if len(rt.Hops) > 1 {
		penalty /= math.Sqrt(float64(len(rt.Hops)))
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok || key.from == r.source {
			continue
		}
		r.transientPenalty[key] += penalty
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
			r.transientPenalty[key] *= 0.25
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.clearPlan()

	delivered := candidateDeliveryAmount(rt)
	if delivered > 0 {
		r.lastFailedShard = delivered
	}

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		r.penalizeUnknownRoute(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.penalizeUnknownRoute(rt)
		return nil
	}

	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.penalizeUnknownRoute(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.transientPenalty[key] += 120_000

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true

	default:
		r.policyBlocked[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails    map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked   map[candidateEdgeKey]bool
	transientPenalty map[candidateEdgeKey]uint8

	// Successful shards either remain held by atomic MPP or have already
	// consumed directional liquidity. In both cases later shards must
	// account for them.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route

	// plan contains a jointly selected route set for the remaining amount.
	// It is discarded immediately when any member fails.
	plan []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:           source,
		spec:             spec,
		incomingEdges:    make(map[route.Vertex][]*candidateEdge),
		edges:            make(map[candidateEdgeKey]*candidateEdge),
		localBalances:    localBalances,
		beliefs:          make(map[candidateEdgeKey]candidateBelief),
		currentFails:     make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:    make(map[candidateEdgeKey]bool),
		transientPenalty: make(map[candidateEdgeKey]uint8),
		reserved:         make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*3 + 8
	if r.attemptLimit < 28 {
		r.attemptLimit = 28
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	scale := 1.0
	if bound := r.currentFails[edge.key]; bound != 0 {
		if total >= bound {
			return 0
		}

		// A bimodal liquidity miss is evidence that the direction is
		// depleted, not merely that it was short by a few millisatoshis.
		// Very small retries remain possible, but near-bound retries are
		// strongly discouraged.
		ratio := float64(total) / float64(bound)
		scale *= 0.025 + 0.75*math.Exp(-ratio/0.13)
	}

	if n := r.transientPenalty[edge.key]; n > 0 {
		scale *= math.Pow(0.30, float64(n))
	}

	finish := func(p float64) float64 {
		p *= scale
		if p < 0.0001 {
			return 0.0001
		}
		if p > 0.995 {
			return 0.995
		}
		return p
	}

	if edge.key.from == r.source {
		if total > r.localBalances[edge.key.chanID] {
			return 0
		}
		return finish(0.999)
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return finish(p)
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return finish(0.995)
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return finish(p)
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*pos
		p = 0.2*p + 0.8*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.35 {
			penalty := 0.04 + 0.72*math.Exp(
				-(ratio-0.35)/0.16,
			)
			p *= penalty
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.48 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		width := 0.14 * float64(edge.capacity)
		if width < 1 {
			width = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/width,
		))
		p = 0.75*p + 0.25*q
	}

	return finish(p)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 390_000.0
		hopPenalty = 300.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			// For a joint plan this makes independent corridors win over
			// repeatedly leaning on a single bottleneck, while still
			// permitting shared channels when their aggregate belief is
			// strong enough.
			if r.reserved[edge.key] > 0 {
				share := float64(r.reserved[edge.key]) /
					float64(edge.capacity)
				edgeScore += 110_000 + 180_000*share
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	logProb := 0.0
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return nil, 0, errors.New("invalid route edge")
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, 0, errors.New("route edge not found")
		}
		amtOver, ok := candidateRouteAmount(rt, i)
		if !ok {
			return nil, 0, errors.New("invalid route amount")
		}
		p := r.probability(edge, amtOver)
		if p <= 0 {
			return nil, 0, errors.New("route became infeasible")
		}
		logProb += math.Log(p)
	}

	return rt, logProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateDeliveredAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCloneReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveRoute(
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations() {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	for _, rt := range r.held {
		candidateReserveRoute(r.reserved, rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

// buildPlan jointly chooses shard sizes and corridors. Several allocation
// biases are evaluated without sending probes; only complete plans that
// deliver the full remaining amount are eligible.
func (r *candidateRouter) buildPlan(total lnwire.MilliSatoshi,
	slots int) ([]*route.Route, error) {

	if total <= 0 || slots <= 0 {
		return nil, errors.New("invalid plan request")
	}

	actual := candidateCloneReservations(r.reserved)
	defer func() {
		r.reserved = actual
	}()

	biases := []float64{0.04, 0.28, 0.62, 1.00}
	bestScore := math.Inf(-1)
	var bestPlan []*route.Route

	for _, sizeBias := range biases {
		r.reserved = candidateCloneReservations(actual)

		remaining := total
		left := slots
		var routes []*route.Route
		planScore := 0.0
		complete := true

		for remaining > 0 && left > 0 {
			base := (remaining + lnwire.MilliSatoshi(left) - 1) /
				lnwire.MilliSatoshi(left)

			var sizes []lnwire.MilliSatoshi
			seen := make(map[lnwire.MilliSatoshi]bool)

			if left == 1 {
				candidateAddAmount(
					&sizes, seen, remaining, remaining,
				)
			} else {
				candidateAddAmount(
					&sizes, seen, base*3/4, remaining,
				)
				candidateAddAmount(
					&sizes, seen, base, remaining,
				)
				candidateAddAmount(
					&sizes, seen, base*5/4, remaining,
				)
				candidateAddAmount(
					&sizes, seen, base*3/2, remaining,
				)
				candidateAddAmount(
					&sizes, seen, base*2, remaining,
				)
				candidateAddAmount(
					&sizes, seen, remaining, remaining,
				)
			}

			var chosen *route.Route
			var chosenSize lnwire.MilliSatoshi
			chosenLogProb := 0.0
			chosenUtility := math.Inf(-1)

			for _, size := range sizes {
				rt, logProb, err := r.findRoute(size)
				if err != nil {
					continue
				}

				fees := rt.TotalAmount - size
				sizeTerm := math.Log(
					float64(size) / float64(base),
				)
				utility := logProb + sizeBias*sizeTerm -
					float64(fees)/4_000_000

				if chosen == nil || utility > chosenUtility {
					chosen = rt
					chosenSize = size
					chosenLogProb = logProb
					chosenUtility = utility
				}
			}

			if chosen == nil {
				complete = false
				break
			}

			routes = append(routes, chosen)
			candidateReserveRoute(r.reserved, chosen)

			fees := chosen.TotalAmount - chosenSize
			planScore += chosenLogProb -
				float64(fees)/4_000_000 - 0.035

			remaining -= chosenSize
			left--
		}

		if !complete || remaining != 0 {
			continue
		}
		if bestPlan == nil || planScore > bestScore {
			bestScore = planScore
			bestPlan = append([]*route.Route(nil), routes...)
		}
	}

	if bestPlan == nil {
		return nil, errors.New("no complete route set found")
	}
	return bestPlan, nil
}

func (r *candidateRouter) planMatches(amt lnwire.MilliSatoshi,
	slots int) bool {

	if len(r.plan) == 0 || len(r.plan) > slots {
		return false
	}

	var sum lnwire.MilliSatoshi
	for _, rt := range r.plan {
		part := candidateDeliveredAmount(rt)
		if part <= 0 {
			return false
		}
		sum += part
	}
	return sum == amt
}

func (r *candidateRouter) fallbackRoute(
	amt lnwire.MilliSatoshi, partsLeft uint32) (*route.Route, error) {

	base := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base, amt)
	candidateAddAmount(&sizes, seen, base*3/4, amt)
	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/8, amt,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/4, amt,
		)
	}
	candidateAddAmount(&sizes, seen, base/2, amt)
	candidateAddAmount(&sizes, seen, amt, amt)

	var best *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range sizes {
		rt, logProb, err := r.findRoute(size)
		if err != nil {
			continue
		}

		fees := rt.TotalAmount - size
		progress := math.Log(float64(size) / float64(base))
		utility := logProb + 0.30*progress -
			float64(fees)/4_000_000

		if best == nil || utility > bestUtility {
			best = rt
			bestUtility = utility
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations()

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if !r.planMatches(amt, int(partsLeft)) {
		r.plan = nil
		plan, err := r.buildPlan(amt, int(partsLeft))
		if err == nil {
			r.plan = plan
		}
	}

	var rt *route.Route
	if len(r.plan) > 0 {
		rt = r.plan[0]
		r.plan = r.plan[1:]
	} else {
		var err error
		rt, err = r.fallbackRoute(amt, partsLeft)
		if err != nil {
			return nil, err
		}
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if bound := r.currentFails[key]; bound != 0 && amt >= bound {
		delete(r.currentFails, key)
	}
	delete(r.transientPenalty, key)

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 3 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) penalizeUnknownRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok || key.from == r.source {
			continue
		}
		if r.transientPenalty[key] < 4 {
			r.transientPenalty[key]++
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	// Any failure invalidates the remaining joint allocation because its
	// virtual reservations and shard sizes assumed every prior member
	// would succeed.
	r.plan = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		r.penalizeUnknownRoute(rt)
		r.lastFailedShard = candidateDeliveredAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.penalizeUnknownRoute(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.penalizeUnknownRoute(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.lastFailedShard = candidateDeliveredAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true

	default:
		r.policyBlocked[key] = true
		r.penalizeUnknownRoute(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) +
		0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat) +
		uint64(e.feeRatePPM)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) +
		uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 72 {
		r.attemptLimit = 72
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64
	var edgeCount uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				edgeCount++
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	fingerprint ^= candidateMix64(edgeCount + 0x517cc1b727220a95)
	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.032))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		retryScale = 0.88 - 0.68*ratio
		if retryScale < 0.20 {
			retryScale = 0.20
		}
		if retryScale > 0.78 {
			retryScale = 0.78
		}

		if failure.count > 1 {
			retryScale /= 1 + 0.18*float64(failure.count-1)
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = 0.005
		if belief.failures > 1 {
			p /= math.Min(3, float64(belief.failures))
		}
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.99 - 0.98*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.94*(ratio-0.45)/0.55
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.50 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}
	return r.liquidityProbability(edge, amt+r.reserved[edge.key])
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]uint32, diversityWeight float64,
	avoid map[candidateEdgeKey]bool) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 500_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if avoid != nil && avoid[edge.key] {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.suspect[edge.key]) * 145_000
			edgeScore += float64(r.edgeUses[edge.key]) * 8_000

			if uses := diversity[edge.key]; uses > 0 {
				edgeScore += diversityWeight * float64(uses)
			}
			if r.reserved[edge.key] > 0 {
				edgeScore += 90_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateMergeReservations(a, b map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := candidateCopyReservations(a)
	for key, amt := range b {
		dst[key] += amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateRouteSignature(rt *route.Route) uint64 {
	h := candidateMix64(uint64(candidateFinalAmount(rt)))
	for i, hop := range rt.Hops {
		h ^= candidateMix64(hop.ChannelID +
			uint64(i+1)*0x9e3779b97f4a7c15)
		h = candidateMix64(h)
	}
	return h
}

type candidateRouteOption struct {
	rt      *route.Route
	quality float64
}

func (r *candidateRouter) routeOptions(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]uint32,
	diversityWeight float64) []candidateRouteOption {

	primary, logProb, err := r.findRoute(
		amt, diversity, diversityWeight, nil,
	)
	if err != nil {
		return nil
	}

	fee := primary.TotalAmount - amt
	options := []candidateRouteOption{{
		rt: primary,
		quality: logProb -
			float64(fee)/3_000_000,
	}}
	seen := map[uint64]bool{
		candidateRouteSignature(primary): true,
	}

	for i := range primary.Hops {
		key, ok := candidateRouteEdgeKey(primary, i)
		if !ok {
			continue
		}

		avoid := map[candidateEdgeKey]bool{key: true}
		alt, altLogProb, altErr := r.findRoute(
			amt, diversity, diversityWeight, avoid,
		)
		if altErr != nil {
			continue
		}

		sig := candidateRouteSignature(alt)
		if seen[sig] {
			continue
		}
		seen[sig] = true

		altFee := alt.TotalAmount - amt
		options = append(options, candidateRouteOption{
			rt: alt,
			quality: altLogProb -
				float64(altFee)/3_000_000,
		})
	}

	sort.Slice(options, func(i, j int) bool {
		return options[i].quality > options[j].quality
	})
	if len(options) > 3 {
		options = options[:3]
	}
	return options
}

func candidateAddSize(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value, remaining,
	slotsAfter lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	maxValue := remaining - slotsAfter
	if maxValue <= 0 {
		return
	}
	if value > maxValue {
		value = maxValue
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidateSizes(remaining lnwire.MilliSatoshi,
	slots int, failed lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	avg := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)
	leave := lnwire.MilliSatoshi(slots - 1)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddSize(&sizes, seen, avg/2, remaining, leave)
	candidateAddSize(&sizes, seen, avg*2/3, remaining, leave)
	candidateAddSize(&sizes, seen, avg*4/5, remaining, leave)
	candidateAddSize(&sizes, seen, avg, remaining, leave)
	candidateAddSize(&sizes, seen, avg*6/5, remaining, leave)
	candidateAddSize(&sizes, seen, avg*3/2, remaining, leave)
	candidateAddSize(&sizes, seen, avg*2, remaining, leave)
	candidateAddSize(&sizes, seen, remaining/2, remaining, leave)

	if failed > 0 {
		candidateAddSize(
			&sizes, seen, failed/2, remaining, leave,
		)
		candidateAddSize(
			&sizes, seen, failed*5/8, remaining, leave,
		)
	}

	return sizes
}

type candidatePlanState struct {
	routes    []*route.Route
	remaining lnwire.MilliSatoshi
	added     map[candidateEdgeKey]lnwire.MilliSatoshi
	used      map[candidateEdgeKey]uint32
	score     float64
	signature uint64
}

func candidateCloneAmounts(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func candidateCloneUses(
	src map[candidateEdgeKey]uint32,
) map[candidateEdgeKey]uint32 {

	dst := make(map[candidateEdgeKey]uint32, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func candidateAddRouteToState(state *candidatePlanState,
	rt *route.Route) *candidatePlanState {

	next := &candidatePlanState{
		routes: append(
			append([]*route.Route(nil), state.routes...), rt,
		),
		remaining: state.remaining - candidateFinalAmount(rt),
		added:     candidateCloneAmounts(state.added),
		used:      candidateCloneUses(state.used),
		signature: candidateMix64(
			state.signature ^ candidateRouteSignature(rt),
		),
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			continue
		}
		next.added[key] += amt
		next.used[key]++
	}

	return next
}

func (r *candidateRouter) scorePlan(routes []*route.Route,
	base map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	if len(routes) == 0 {
		return math.Inf(-1)
	}

	added := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	uses := make(map[candidateEdgeKey]uint32)
	var fees lnwire.MilliSatoshi

	for _, rt := range routes {
		finalAmt := candidateFinalAmount(rt)
		if finalAmt <= 0 {
			return math.Inf(-1)
		}
		fees += rt.TotalAmount - finalAmt

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				return math.Inf(-1)
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				return math.Inf(-1)
			}

			edge := r.edges[key]
			if edge == nil || !edge.policyAllows(amt) {
				return math.Inf(-1)
			}
			added[key] += amt
			uses[key]++
		}
	}

	score := -float64(fees)/3_000_000 -
		0.025*float64(len(routes))

	for key, amount := range added {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		total := base[key] + amount
		p := r.liquidityProbability(edge, total)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)

		if uses[key] > 1 && key.from != r.source {
			score -= 0.075 * float64(uses[key]-1)
		}
	}

	return score
}

func (r *candidateRouter) planExact(total lnwire.MilliSatoshi,
	parts int) ([]*route.Route, float64, bool) {

	if parts <= 0 {
		return nil, 0, false
	}

	base := candidateCopyReservations(r.reserved)
	saved := r.reserved
	defer func() {
		r.reserved = saved
	}()

	states := []*candidatePlanState{{
		remaining: total,
		added:     make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		used:      make(map[candidateEdgeKey]uint32),
		score:     0,
	}}

	const beamWidth = 24

	for depth := 0; depth < parts; depth++ {
		slots := parts - depth
		var expanded []*candidatePlanState
		bestBySignature := make(map[uint64]*candidatePlanState)

		for _, state := range states {
			if state.remaining <= 0 {
				continue
			}

			r.reserved = candidateMergeReservations(
				base, state.added,
			)
			sizes := candidateSizes(
				state.remaining, slots, r.lastFailedShard,
			)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				weights := []float64{260_000, 820_000}
				for _, weight := range weights {
					options := r.routeOptions(
						size, state.used, weight,
					)
					for _, option := range options {
						next := candidateAddRouteToState(
							state, option.rt,
						)
						if next.remaining < 0 {
							continue
						}
						if slots == 1 &&
							next.remaining != 0 {

							continue
						}

						next.score = r.scorePlan(
							next.routes, base,
						)
						if math.IsInf(next.score, -1) {
							continue
						}

						old := bestBySignature[
							next.signature
						]
						if old == nil ||
							next.score > old.score {

							bestBySignature[
								next.signature
							] = next
						}
					}
				}
			}
		}

		for _, state := range bestBySignature {
			expanded = append(expanded, state)
		}
		if len(expanded) == 0 {
			return nil, 0, false
		}

		sort.Slice(expanded, func(i, j int) bool {
			deliveredI := total - expanded[i].remaining
			deliveredJ := total - expanded[j].remaining
			rankI := expanded[i].score +
				2.25*float64(deliveredI)/float64(total)
			rankJ := expanded[j].score +
				2.25*float64(deliveredJ)/float64(total)
			return rankI > rankJ
		})

		if len(expanded) > beamWidth {
			expanded = expanded[:beamWidth]
		}
		states = expanded
	}

	var best *candidatePlanState
	for _, state := range states {
		if state.remaining != 0 {
			continue
		}
		if best == nil || state.score > best.score {
			best = state
		}
	}
	if best == nil {
		return nil, 0, false
	}

	return best.routes, best.score, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no part slots available")
	}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	if direct, _, err := r.findRoute(total, nil, 0, nil); err == nil {
		score := r.scorePlan(
			[]*route.Route{direct}, r.reserved,
		)
		if !math.IsInf(score, -1) {
			bestPlan = []*route.Route{direct}
			bestScore = score
		}
	}

	maxRegular := int(parts)
	if maxRegular > 6 {
		maxRegular = 6
	}

	counts := make([]int, 0, maxRegular)
	for count := 2; count <= maxRegular; count++ {
		counts = append(counts, count)
	}
	if int(parts) > maxRegular {
		counts = append(counts, int(parts))
	}

	for _, count := range counts {
		plan, score, ok := r.planExact(total, count)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		return nil, errors.New("no route set found")
	}
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			valid := true
			for i := range rt.Hops {
				key, ok := candidateRouteEdgeKey(rt, i)
				if !ok {
					valid = false
					break
				}
				edge := r.edges[key]
				partAmt, amountOK := candidateRouteAmount(rt, i)
				if edge == nil || !amountOK ||
					r.probability(edge, partAmt) <= 0 {

					valid = false
					break
				}
			}

			if valid {
				r.planned = r.planned[1:]
				r.recordRouteUse(rt)
				r.attempts++
				return rt, nil
			}
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 9 / 16
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else {
		belief.estimate = (
			3*belief.estimate + estimate
		) / 4
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid reported route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
			if r.suspect[key] > 0 {
				r.suspect[key]--
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked map[candidateEdgeKey]bool
	unknownPenalty map[candidateEdgeKey]uint32
	routeFails     map[uint64]lnwire.MilliSatoshi

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	return candidateMix64(x)
}

func candidateRouteHash(rt *route.Route) uint64 {
	h := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i, hop := range rt.Hops {
		x := candidateMix64(hop.ChannelID + uint64(i+1))
		x ^= candidateMix64(candidateVertexHash(hop.PubKeyBytes))
		h = candidateMix64(h ^ x)
	}
	return h
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:          source,
		spec:            spec,
		incomingEdges:   make(map[route.Vertex][]*candidateEdge),
		localBalances:   localBalances,
		beliefs:         make(map[candidateEdgeKey]candidateBelief),
		currentFails:    make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:   make(map[candidateEdgeKey]bool),
		unknownPenalty:  make(map[candidateEdgeKey]uint32),
		routeFails:      make(map[uint64]lnwire.MilliSatoshi),
		reserved:        make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := int(spec.MaxParts)
	if maxParts < 1 {
		maxParts = 1
	}
	r.attemptLimit = maxParts*4 + 8
	if r.attemptLimit < 24 {
		r.attemptLimit = 24
	}
	if r.attemptLimit > 72 {
		r.attemptLimit = 72
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		if total > r.localBalances[edge.key.chanID] {
			return 0
		}
		return 0.999
	}

	if r.policyBlocked[edge.key] {
		return 0
	}

	if bound := r.currentFails[edge.key]; bound != 0 &&
		total >= bound {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.006 {
			p = 0.006
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.99 - 0.98*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.94*(ratio-0.45)/0.55
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		if distance > 0 {
			boost := 0.5 * math.Exp(-distance/0.16)
			p += boost * (1 - p)
		}
	}

	if belief.estimate > 0 {
		scale := 0.1 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
}

func (q *candidateDijkstraQueue) Push(x any) {
	*q = append(*q, x.(*candidateDijkstraItem))
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) ([]*candidateEdge,
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 700_000.0
		hopPenalty = 300.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty +
				extraPenalty[edge.key]

			if r.reserved[edge.key] > 0 {
				edgeScore += 350_000
			}
			edgeScore += float64(
				r.unknownPenalty[edge.key],
			) * 300_000

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, nil, 0, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, nil, 0, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	rt, err := r.buildPathRoute(amt, path)
	if err != nil {
		return nil, nil, 0, err
	}
	return path, rt, sourceLogProb, nil
}

func (r *candidateRouter) buildPathRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.reserved[key] += amt
			}
		}
	}
}

func (r *candidateRouter) planningTotal(
	edge *candidateEdge) lnwire.MilliSatoshi {

	if edge.key.from == r.source {
		return r.localBalances[edge.key.chanID]
	}

	capacity := edge.capacity
	limit := capacity * 86 / 100
	belief, known := r.beliefs[edge.key]

	if known {
		switch {
		case belief.lowerOK > 0 && belief.upperFail > belief.lowerOK:
			gap := belief.upperFail - belief.lowerOK
			limit = belief.lowerOK + gap*18/100

		case belief.lowerOK > 0:
			gap := capacity - belief.lowerOK
			limit = belief.lowerOK + gap*12/100

		case belief.upperFail > 0:
			limit = belief.upperFail * 55 / 100
		}

		if belief.estimate > limit && belief.upperFail == 0 {
			limit = (limit*3 + belief.estimate) / 4
		}
	}

	if fail := r.currentFails[edge.key]; fail > 0 {
		if belief.lowerOK > 0 && belief.lowerOK < fail {
			gap := fail - belief.lowerOK
			limit = belief.lowerOK + gap/10
		} else {
			limit = fail * 52 / 100
		}
		if limit >= fail {
			limit = fail - 1
		}
	}

	if limit > capacity {
		limit = capacity
	}
	if limit < 0 {
		return 0
	}
	return limit
}

func (r *candidateRouter) pathAllowsPlan(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, bool) {

	rt, err := r.buildPathRoute(amt, path)
	if err != nil {
		return nil, false
	}

	for i, edge := range path {
		amtOver, ok := candidateRouteAmount(rt, i)
		if !ok || !edge.policyAllows(amtOver) {
			return nil, false
		}

		total := amtOver + r.reserved[edge.key]
		if total > r.planningTotal(edge) {
			return nil, false
		}
	}

	return rt, true
}

func (r *candidateRouter) routeLimit(path []*candidateEdge,
	seed, maximum lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if seed <= 0 || seed > maximum {
		return 0
	}
	if _, ok := r.pathAllowsPlan(path, seed); !ok {
		return 0
	}

	low, high := seed, maximum
	for low < high {
		mid := low + (high-low+1)/2
		if _, ok := r.pathAllowsPlan(path, mid); ok {
			low = mid
		} else {
			high = mid - 1
		}
	}
	return low
}

func (r *candidateRouter) pathLogProbability(path []*candidateEdge,
	rt *route.Route) float64 {

	logProb := 0.0
	for i, edge := range path {
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return math.Inf(-1)
		}
		p := r.probability(edge, amt)
		if p <= 0 {
			return math.Inf(-1)
		}
		logProb += math.Log(p)
	}
	return logProb
}

type candidateRouteOption struct {
	path    []*candidateEdge
	hash    uint64
	lastKey candidateEdgeKey
	minAmt  lnwire.MilliSatoshi
	limit   lnwire.MilliSatoshi
	quality float64
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	maximum lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > maximum {
		value = maximum
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) enumerateOptions(amt lnwire.MilliSatoshi,
	partsLeft uint32) []candidateRouteOption {

	base := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)
	scout := (base + 2) / 3

	var searchSizes []lnwire.MilliSatoshi
	sizeSeen := make(map[lnwire.MilliSatoshi]bool)
	candidateAddAmount(&searchSizes, sizeSeen, scout, amt)
	candidateAddAmount(&searchSizes, sizeSeen, base/2, amt)
	candidateAddAmount(&searchSizes, sizeSeen, base*2/3, amt)
	candidateAddAmount(&searchSizes, sizeSeen, base, amt)
	candidateAddAmount(&searchSizes, sizeSeen, base*3/2, amt)
	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&searchSizes, sizeSeen,
			r.lastFailedShard*52/100, amt,
		)
	}

	want := int(partsLeft)*2 + 4
	if want > 24 {
		want = 24
	}
	if want < 6 {
		want = 6
	}

	penalty := make(map[candidateEdgeKey]float64)
	seenRoutes := make(map[uint64]bool)
	var options []candidateRouteOption

	rounds := want * 3
	for round := 0; round < rounds && len(options) < want; round++ {
		size := searchSizes[round%len(searchSizes)]
		path, rt, logProb, err := r.findPath(size, penalty)
		if err != nil {
			continue
		}

		hash := candidateRouteHash(rt)
		for i, edge := range path {
			add := 1_700_000.0
			if i == len(path)-1 {
				add = 3_800_000
			} else if i == 0 {
				add = 2_200_000
			}
			penalty[edge.key] += add
		}

		if seenRoutes[hash] {
			continue
		}
		if failedAt := r.routeFails[hash]; failedAt > 0 &&
			size >= failedAt {

			continue
		}

		limit := r.routeLimit(path, size, amt)
		if limit == 0 {
			continue
		}

		seenRoutes[hash] = true
		quality := math.Log(float64(limit)+1) + 0.22*logProb
		fees := rt.TotalAmount - size
		quality -= float64(fees) / 4_000_000

		options = append(options, candidateRouteOption{
			path:    path,
			hash:    hash,
			lastKey: path[len(path)-1].key,
			minAmt:  size,
			limit:   limit,
			quality: quality,
		})
	}

	// A target-side channel is an aggregate bottleneck. Retain only the
	// strongest offer per directed target channel so the joint allocation
	// does not count the same liquidity multiple times.
	bestByLast := make(map[candidateEdgeKey]candidateRouteOption)
	for _, option := range options {
		old, found := bestByLast[option.lastKey]
		if !found || option.quality > old.quality {
			bestByLast[option.lastKey] = option
		}
	}

	options = options[:0]
	for _, option := range bestByLast {
		options = append(options, option)
	}
	sort.Slice(options, func(i, j int) bool {
		if options[i].quality == options[j].quality {
			return options[i].limit > options[j].limit
		}
		return options[i].quality > options[j].quality
	})

	if len(options) > int(partsLeft) {
		options = options[:partsLeft]
	}
	return options
}

func (r *candidateRouter) exactRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	penalty := make(map[candidateEdgeKey]float64)
	for tries := 0; tries < 16; tries++ {
		path, rt, _, err := r.findPath(amt, penalty)
		if err != nil {
			return nil, err
		}

		hash := candidateRouteHash(rt)
		if failedAt := r.routeFails[hash]; failedAt == 0 ||
			amt < failedAt {

			return rt, nil
		}

		for _, edge := range path {
			penalty[edge.key] += 3_000_000
		}
	}
	return nil, errors.New("no untried route found")
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if partsLeft == 1 {
		rt, err := r.exactRoute(amt)
		if err != nil {
			return nil, err
		}
		r.attempts++
		return rt, nil
	}

	options := r.enumerateOptions(amt, partsLeft)
	if len(options) == 0 {
		return nil, errors.New("no route found")
	}

	var totalLimit float64
	for _, option := range options {
		totalLimit += float64(option.limit)
	}

	base := float64(amt) / float64(partsLeft)
	var bestRoute *route.Route
	bestScore := math.Inf(-1)

	for _, option := range options {
		var allocation lnwire.MilliSatoshi
		if totalLimit >= float64(amt) {
			allocation = lnwire.MilliSatoshi(math.Ceil(
				float64(amt) * float64(option.limit) /
					totalLimit,
			))
		} else {
			allocation = option.limit
		}

		if allocation < option.minAmt {
			allocation = option.minAmt
		}
		if allocation > option.limit {
			allocation = option.limit
		}
		if allocation > amt {
			allocation = amt
		}
		if allocation <= 0 {
			continue
		}

		rt, ok := r.pathAllowsPlan(option.path, allocation)
		if !ok {
			continue
		}
		if failedAt := r.routeFails[option.hash]; failedAt > 0 &&
			allocation >= failedAt {

			continue
		}

		logProb := r.pathLogProbability(option.path, rt)
		if math.IsInf(logProb, -1) {
			continue
		}

		fees := rt.TotalAmount - allocation
		progress := math.Log(float64(allocation) / base)
		score := logProb + 0.28*progress -
			float64(fees)/4_000_000

		if bestRoute == nil || score > bestScore {
			bestRoute = rt
			bestScore = score
		}
	}

	if bestRoute == nil {
		// The confidence allocation may be deliberately conservative.
		// Fall back to the most reliable route at the average shard size.
		fallback := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
			lnwire.MilliSatoshi(partsLeft)
		rt, err := r.exactRoute(fallback)
		if err != nil {
			return nil, err
		}
		bestRoute = rt
	}

	r.attempts++
	return bestRoute, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}
	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 52 / 100
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markUnknownRouteFailure(rt *route.Route) {
	if len(rt.Hops) == 0 {
		return
	}

	finalAmt := rt.Hops[len(rt.Hops)-1].AmtToForward
	hash := candidateRouteHash(rt)
	if old := r.routeFails[hash]; old == 0 || finalAmt < old {
		r.routeFails[hash] = finalAmt
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok || key.from == r.source {
			continue
		}
		r.unknownPenalty[key]++
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.learnSuccess(key, amt+r.reserved[key])
			}
		}
		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	if len(rt.Hops) > 0 {
		r.lastFailedShard =
			rt.Hops[len(rt.Hops)-1].AmtToForward
	}

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		r.markUnknownRouteFailure(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markUnknownRouteFailure(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markUnknownRouteFailure(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true

	default:
		r.markUnknownRouteFailure(rt)
		r.unknownPenalty[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int

	paymentActive bool
	lastRequest   lnwire.MilliSatoshi
	expectedNext  lnwire.MilliSatoshi
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) +
		0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat) +
		uint64(e.feeRatePPM)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) +
		uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*5 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 56 {
		r.attemptLimit = 56
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.05)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.032))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	p := candidatePrior(total, edge.capacity)
	belief, known := r.beliefs[edge.key]

	if known {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.995

		case belief.upperFail > 0 && total >= belief.upperFail:
			p = 0.004

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK:

			width := float64(
				belief.upperFail - belief.lowerOK,
			)
			pos := float64(total-belief.lowerOK) / width
			if pos < 0 {
				pos = 0
			}
			if pos > 1 {
				pos = 1
			}

			evidence := 0.99 - 0.985*pos
			p = 0.15*p + 0.85*evidence

		case belief.upperFail > 0:
			ratio := float64(total) /
				float64(belief.upperFail)
			if ratio > 0.45 {
				scale := 1 - 0.9*(ratio-0.45)/0.55
				if scale < 0.08 {
					scale = 0.08
				}
				p *= scale
			}

		case belief.lowerOK > 0 && total > belief.lowerOK:
			distance := float64(total-belief.lowerOK) /
				float64(edge.capacity)
			boost := 0.5 * math.Exp(-distance/0.16)
			p += boost * (1 - p)
		}

		if belief.estimate > 0 &&
			!(belief.lowerOK > 0 && total <= belief.lowerOK) {

			scale := 0.1 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			q := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate)) /
					scale,
			))
			p = 0.72*p + 0.28*q
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		scale := 0.62
		if failure.count > 1 {
			scale = 0.45
		}
		if ratio < 0.35 {
			scale += 0.25
		}
		p *= scale
	}

	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	total := amt + r.reserved[edge.key]
	if total < amt {
		return 0
	}

	return r.liquidityProbability(edge, total)
}

type candidateLabel struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	edge     *candidateEdge
	next     *candidateLabel
	active   bool
	index    int
}

type candidateQueue []*candidateLabel

func (q candidateQueue) Len() int {
	return len(q)
}

func (q candidateQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateQueue) Push(x any) {
	item := x.(*candidateLabel)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidateLabelContains(label *candidateLabel,
	node route.Vertex) bool {

	for current := label; current != nil; current = current.next {
		if current.node == node {
			return true
		}
	}
	return false
}

func candidateDominates(a *candidateLabel, score float64,
	required lnwire.MilliSatoshi) bool {

	return a.active && a.score <= score+0.0001 &&
		a.required <= required
}

func candidateInsertLabel(labels map[route.Vertex][]*candidateLabel,
	label *candidateLabel) bool {

	current := labels[label.node]
	for _, old := range current {
		if candidateDominates(old, label.score, label.required) {
			return false
		}
	}

	for _, old := range current {
		if old.active &&
			label.score <= old.score+0.0001 &&
			label.required <= old.required {

			old.active = false
		}
	}

	label.active = true
	current = append(current, label)
	labels[label.node] = current

	active := 0
	for _, old := range current {
		if old.active {
			active++
		}
	}
	if active <= 12 {
		return true
	}

	var worst *candidateLabel
	for _, old := range current {
		if !old.active {
			continue
		}
		if worst == nil || old.score > worst.score {
			worst = old
		}
	}
	if worst != nil {
		worst.active = false
	}
	return label.active
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 600_000.0
		hopPenalty = 500.0
	)

	target := &candidateLabel{
		node:     r.spec.Target,
		required: amt,
		active:   true,
	}

	labels := map[route.Vertex][]*candidateLabel{
		r.spec.Target: {target},
	}
	pq := &candidateQueue{}
	heap.Push(pq, target)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateLabel)
		if !item.active {
			continue
		}
		if item.node == r.source {
			rt, err := r.buildRoute(item)
			if err != nil {
				return nil, 0, err
			}
			return rt, item.logProb, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidateLabelContains(item, edge.key.from) {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee
			if sending < amtOver {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.edgeUses[edge.key]) * 12_000
			edgeScore += float64(r.suspect[edge.key]) * 180_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 190_000
			}

			label := &candidateLabel{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				edge:     edge,
				next:     item,
			}
			if !candidateInsertLabel(labels, label) {
				continue
			}
			heap.Push(pq, label)
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(label *candidateLabel) (
	*route.Route, error) {

	var path []*candidateEdge
	for current := label; current != nil &&
		current.node != r.spec.Target; current = current.next {

		if current.edge == nil || current.next == nil {
			return nil, errors.New("broken route label")
		}
		path = append(path, current.edge)
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = labelAmountAtTarget(label)
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwarding := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwarding.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwarding.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amtOver[last]
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func labelAmountAtTarget(label *candidateLabel) lnwire.MilliSatoshi {
	current := label
	for current.next != nil {
		current = current.next
	}
	return current.required
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) suggestedShard(rt *route.Route,
	max lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 {
		return 0
	}

	suggested := float64(max)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		edge := r.edges[key]
		if edge == nil {
			continue
		}
		amtOver, ok := candidateRouteAmount(rt, i)
		if !ok || amtOver <= 0 {
			continue
		}

		reserved := r.reserved[key]
		limit := edge.capacity * 4 / 5

		if key.from == r.source {
			if balance, ok := r.localBalances[key.chanID]; ok {
				limit = balance
			} else {
				return 0
			}
		} else {
			belief := r.beliefs[key]
			if belief.lowerOK > reserved {
				limit = belief.lowerOK
			} else if belief.estimate > reserved {
				limit = belief.estimate
			}
			if belief.upperFail > 0 {
				failLimit := belief.upperFail * 5 / 8
				if failLimit < limit {
					limit = failLimit
				}
			}
		}

		if failure, ok := r.currentFails[key]; ok &&
			failure.upper > 0 {

			failLimit := failure.upper * 5 / 8
			if failLimit < limit {
				limit = failLimit
			}
		}

		if limit <= reserved {
			return 0
		}

		available := limit - reserved
		candidate := float64(finalAmt) *
			float64(available) / float64(amtOver)

		if edge.maxHTLC > 0 {
			policyCandidate := float64(finalAmt) *
				float64(edge.maxHTLC) /
				float64(amtOver)
			if policyCandidate < candidate {
				candidate = policyCandidate
			}
		}

		if candidate < suggested {
			suggested = candidate
		}
	}

	if suggested < 1 {
		return 1
	}
	if suggested > float64(max) {
		return max
	}
	return lnwire.MilliSatoshi(suggested)
}

func (r *candidateRouter) planOnce(total lnwire.MilliSatoshi,
	parts uint32, sizeBias float64) ([]*route.Route, bool) {

	saved := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = saved
	}()

	remaining := total
	slots := parts
	var plan []*route.Route

	for remaining > 0 && slots > 0 {
		if slots == 1 {
			rt, _, err := r.findRoute(remaining)
			if err != nil {
				return nil, false
			}
			plan = append(plan, rt)
			r.reserveRoute(rt)
			remaining = 0
			break
		}

		base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)

		var sizes []lnwire.MilliSatoshi
		seen := make(map[lnwire.MilliSatoshi]bool)

		candidateAddAmount(&sizes, seen, base*3/4, remaining)
		candidateAddAmount(&sizes, seen, base, remaining)
		candidateAddAmount(&sizes, seen, base*5/4, remaining)
		candidateAddAmount(&sizes, seen, base*3/2, remaining)
		candidateAddAmount(&sizes, seen, base*2, remaining)
		candidateAddAmount(&sizes, seen, remaining, remaining)

		seed, _, seedErr := r.findRoute(base)
		if seedErr == nil {
			hint := r.suggestedShard(seed, remaining)
			candidateAddAmount(&sizes, seen, hint*4/5, remaining)
			candidateAddAmount(&sizes, seen, hint, remaining)
		}

		if r.lastFailedShard > 0 {
			candidateAddAmount(
				&sizes, seen, r.lastFailedShard/2, remaining,
			)
			candidateAddAmount(
				&sizes, seen, r.lastFailedShard*5/8,
				remaining,
			)
		}

		var bestRoute *route.Route
		var bestSize lnwire.MilliSatoshi
		bestUtility := math.Inf(-1)

		for _, size := range sizes {
			rt, logProb, err := r.findRoute(size)
			if err != nil {
				continue
			}

			fees := rt.TotalAmount - size
			sizeReward := math.Log(
				float64(size) / float64(base),
			)
			utility := logProb + sizeBias*sizeReward -
				float64(fees)/5_000_000

			if bestRoute == nil || utility > bestUtility {
				bestRoute = rt
				bestSize = size
				bestUtility = utility
			}
		}

		if bestRoute == nil {
			return nil, false
		}

		plan = append(plan, bestRoute)
		r.reserveRoute(bestRoute)
		remaining -= bestSize
		slots--
	}

	return plan, remaining == 0 && len(plan) > 0
}

func (r *candidateRouter) scorePlan(plan []*route.Route,
	initial map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	totals := candidateCopyReservations(initial)
	used := make(map[candidateEdgeKey]bool)
	fees := lnwire.MilliSatoshi(0)

	for _, rt := range plan {
		finalAmt := candidateFinalAmount(rt)
		fees += rt.TotalAmount - finalAmt

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				return math.Inf(-1)
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				return math.Inf(-1)
			}
			totals[key] += amt
			used[key] = true
		}
	}

	score := -float64(fees)/5_000_000 -
		0.035*float64(len(plan))

	for key := range used {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}
		p := r.liquidityProbability(edge, totals[key])
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	return score
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	initial := candidateCopyReservations(r.reserved)
	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	full, _, err := r.findRoute(total)
	if err == nil {
		plan := []*route.Route{full}
		bestPlan = plan
		bestScore = r.scorePlan(plan, initial)
	}

	if parts > 1 {
		biases := []float64{0.2, 0.5, 0.85}
		for count := uint32(2); count <= parts; count++ {
			for _, bias := range biases {
				plan, ok := r.planOnce(total, count, bias)
				if !ok {
					continue
				}

				score := r.scorePlan(plan, initial)
				if bestPlan == nil || score > bestScore {
					bestPlan = plan
					bestScore = score
				}
			}
		}
	}

	if bestPlan == nil {
		return nil, errors.New("no route found")
	}
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) resetPayment() {
	r.currentFails = make(map[candidateEdgeKey]candidateCurrentFailure)
	r.policyBlocked = make(map[candidateEdgeKey]bool)
	r.edgeUses = make(map[candidateEdgeKey]uint32)
	r.suspect = make(map[candidateEdgeKey]uint32)
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	r.held = nil
	r.planned = nil
	r.lastFailedShard = 0
	r.attempts = 0
	r.lastRequest = 0
	r.expectedNext = 0
}

func (r *candidateRouter) preparePayment(amt lnwire.MilliSatoshi) {
	newPayment := !r.paymentActive || r.expectedNext == 0 ||
		amt != r.expectedNext

	if newPayment {
		r.resetPayment()
		r.paymentActive = true
	}

	r.lastRequest = amt
	r.expectedNext = amt
}

func (r *candidateRouter) terminal(err error) (*route.Route, error) {
	r.paymentActive = false
	r.planned = nil
	return nil, err
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return r.terminal(errors.New("payment amount exhausted"))
	}

	r.preparePayment(amt)
	r.syncReservations(inFlightHtlcs)

	if r.attempts >= r.attemptLimit {
		return r.terminal(
			errors.New("routing attempt budget exhausted"),
		)
	}

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return r.terminal(
			errors.New("maximum number of parts in flight"),
		)
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return r.terminal(err)
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		r.paymentActive = false
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0

		settled := candidateFinalAmount(rt)
		if settled >= r.lastRequest {
			r.expectedNext = 0
		} else {
			r.expectedNext = r.lastRequest - settled
		}
		return nil
	}

	r.expectedNext = r.lastRequest
	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 6
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.032))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if amt <= 0 || !edge.policyAllows(amt) ||
		r.policyBlocked[edge.key] {

		return 0
	}

	reserved := r.reserved[edge.key]
	total := amt + reserved
	if total < amt || total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		// A liquidity failure is evidence against the failed amount,
		// not against the channel at every smaller amount. Retrying well
		// below the failure point is especially valuable for MPP.
		retryCeiling := failure.upper * 7 / 10
		if retryCeiling == 0 {
			retryCeiling = 1
		}
		if total > retryCeiling {
			return 0
		}

		retryScale = 0.42
		if total <= failure.upper/2 {
			retryScale = 0.68
		}
		if failure.count > 2 {
			retryScale *= 0.8
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.008)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.99 - 0.98*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.5 {
			scale := 1 - 0.9*(ratio-0.5)/0.5
			if scale < 0.1 {
				scale = 0.1
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.5 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.1 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 390_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee
			if sending < amtOver {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 12_000
			edgeScore += float64(r.suspect[edge.key]) * 210_000
			edgeScore += extraPenalty[edge.key]

			// Held shards make a corridor less attractive even when its
			// remaining capacity appears sufficient. This encourages
			// atomic MPP plans to commit across distinct bottlenecks.
			if r.reserved[edge.key] > 0 {
				edgeScore += 420_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(uint64(len(rt.Hops)) + 1)
	for i, hop := range rt.Hops {
		h ^= candidateMix64(
			hop.ChannelID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		h ^= candidateMix64(candidateVertexHash(hop.PubKeyBytes))
	}
	return h
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeChoices(amt lnwire.MilliSatoshi,
	limit int) []candidateRouteChoice {

	if limit < 1 {
		limit = 1
	}

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	choices := make([]candidateRouteChoice, 0, limit)
	scans := limit*4 + 2

	for scan := 0; scan < scans && len(choices) < limit; scan++ {
		rt, logProb, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				logProb: logProb,
			})
		}

		// Repeated searches receive progressively larger path penalties,
		// yielding alternate corridors without hard-banning the only
		// feasible path.
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			if key.from == r.source {
				penalties[key] += 120_000
			} else {
				penalties[key] += 520_000
			}
		}
	}

	return choices
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	values := make([]lnwire.MilliSatoshi, 0, 11)
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&values, seen, base*2/3, remaining)
	candidateAddAmount(&values, seen, base*4/5, remaining)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(&values, seen, base*5/4, remaining)
	candidateAddAmount(&values, seen, base*3/2, remaining)
	candidateAddAmount(&values, seen, base*2, remaining)
	candidateAddAmount(&values, seen, base*3, remaining)
	candidateAddAmount(&values, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*11/20, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*2/3, remaining,
		)
	}

	return values
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func candidateInsertPlanState(states *[]candidatePlanState,
	state candidatePlanState, limit int) {

	insert := len(*states)
	for i := range *states {
		if state.score > (*states)[i].score {
			insert = i
			break
		}
	}

	if insert == len(*states) {
		if len(*states) < limit {
			*states = append(*states, state)
		}
		return
	}

	*states = append(*states, candidatePlanState{})
	copy((*states)[insert+1:], (*states)[insert:])
	(*states)[insert] = state
	if len(*states) > limit {
		*states = (*states)[:limit]
	}
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	const beamWidth = 18

	beam := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState

	for depth := uint32(0); depth < parts && len(beam) > 0; depth++ {
		nextBeam := make([]candidatePlanState, 0, beamWidth)

		for _, state := range beam {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}
			if state.slots == 0 {
				continue
			}

			sizes := r.planSizes(state.remaining, state.slots)
			for _, size := range sizes {
				r.reserved = state.reservations
				choices := r.routeChoices(size, 3)

				for _, choice := range choices {
					newReservations := candidateCopyReservations(
						state.reservations,
					)
					r.reserved = newReservations
					r.reserveRoute(choice.route)

					fees := choice.route.TotalAmount - size
					if fees < 0 {
						continue
					}

					// The progress term is constant for every completed
					// plan, but prevents low-value tiny shards from
					// crowding feasible plans out of the beam early.
					progress := 0.75 * float64(size) /
						float64(total)
					score := state.score + choice.logProb +
						progress -
						float64(fees)/4_500_000 - 0.03

					routes := make(
						[]*route.Route, len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes[len(state.routes)] = choice.route

					nextState := candidatePlanState{
						remaining: state.remaining - size,
						slots:     state.slots - 1,
						routes:    routes,
						reservations: newReservations,
						score: score,
					}

					if nextState.remaining == 0 {
						if bestComplete == nil ||
							nextState.score >
								bestComplete.score {

							copyState := nextState
							bestComplete = &copyState
						}
						continue
					}

					candidateInsertPlanState(
						&nextBeam, nextState, beamWidth,
					)
				}
			}
		}

		beam = nextBeam
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		r.reserved = savedReservations
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	return bestComplete.routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 3 / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	if rt == nil {
		return
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 3)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 3
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateRetryFactor(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.58
	case count == 2:
		return 0.42
	default:
		return 0.30
	}
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var numerator int64
	switch {
	case f.count <= 1:
		numerator = 72
	case f.count == 2:
		numerator = 56
	default:
		numerator = 44
	}

	ceiling := f.upper * lnwire.MilliSatoshi(numerator) / 100
	if ceiling <= 0 {
		ceiling = 1
	}
	return ceiling, true
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	reserved := r.reserved[edge.key]
	total := amt + reserved
	if total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, ok := candidateRetryCeiling(failure); ok &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryFactor(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.006)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence := 0.993 - 0.985*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.94*(ratio-0.45)/0.55
			if scale < 0.04 {
				scale = 0.04
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.55 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 500_000.0
		hopPenalty = 160.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 8_000
			edgeScore += float64(r.suspect[edge.key]) * 150_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 190_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidateScaledAmount(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func (r *candidateRouter) routeLimit(rt *route.Route) lnwire.MilliSatoshi {
	limit := lnwire.MilliSatoshi(math.MaxInt64)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}
		edge := r.edges[key]
		if edge == nil {
			return 0
		}

		reserved := r.reserved[key]
		available := edge.capacity - reserved
		if available < limit {
			limit = available
		}
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok {
				return 0
			}
			localAvailable := balance - reserved
			if localAvailable < limit {
				limit = localAvailable
			}
			continue
		}

		if failure, ok := r.currentFails[key]; ok {
			ceiling, ok := candidateRetryCeiling(failure)
			if ok {
				available = ceiling - reserved
				if available < limit {
					limit = available
				}
			}
		}

		belief, ok := r.beliefs[key]
		if !ok {
			likely := candidateScaledAmount(
				edge.capacity, 88, 100,
			) - reserved
			if likely < limit {
				limit = likely
			}
			continue
		}

		if belief.upperFail > 0 {
			likelyTotal := candidateScaledAmount(
				belief.upperFail, 62, 100,
			)
			if belief.lowerOK > likelyTotal {
				likelyTotal = belief.lowerOK
			}
			if likelyTotal >= belief.upperFail {
				likelyTotal = belief.upperFail - 1
			}

			likely := likelyTotal - reserved
			if likely < limit {
				limit = likely
			}
		} else if belief.lowerOK > 0 {
			likelyTotal := belief.lowerOK +
				candidateScaledAmount(
					edge.capacity-belief.lowerOK,
					45, 100,
				)
			likely := likelyTotal - reserved
			if likely < limit {
				limit = likely
			}
		}
	}

	if limit < 1 {
		return 0
	}
	return limit
}

func candidatePlanSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 1, 2),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 2, 3),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 4),
		remaining,
	)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 5, 4),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 2),
		remaining,
	)
	candidateAddAmount(&values, seen, base*2, remaining)
	candidateAddAmount(&values, seen, base*3, remaining)
	candidateAddAmount(&values, seen, remaining, remaining)

	return values
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState
	const beamWidth = 18

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make([]candidatePlanState, 0, beamWidth*8)

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}

			r.reserved = candidateCopyReservations(
				state.reservations,
			)

			sizes := candidatePlanSizes(state.remaining, slots)
			seen := make(map[lnwire.MilliSatoshi]bool)
			for _, size := range sizes {
				seen[size] = true
			}

			for i := 0; i < len(sizes) && i < 18; i++ {
				size := sizes[i]
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				rt, logProb, err := r.findRoute(size)
				if err != nil {
					continue
				}

				limit := r.routeLimit(rt)
				if limit > 0 {
					candidateAddAmount(
						&sizes, seen,
						candidateScaledAmount(limit, 4, 5),
						state.remaining,
					)
					candidateAddAmount(
						&sizes, seen, limit,
						state.remaining,
					)
				}

				newReservations := candidateCopyReservations(
					state.reservations,
				)
				r.reserved = newReservations
				r.reserveRoute(rt)

				fees := rt.TotalAmount - size
				score := state.score + logProb -
					float64(fees)/4_000_000 - 0.018

				remaining := state.remaining - size
				progress := float64(total-remaining) /
					float64(total)
				rank := score + 2.6*progress

				routes := make(
					[]*route.Route, len(state.routes), len(state.routes)+1,
				)
				copy(routes, state.routes)
				routes = append(routes, rt)

				nextStates = append(nextStates, candidatePlanState{
					remaining:    remaining,
					routes:       routes,
					reservations: newReservations,
					score:        score,
					rank:         rank,
				})
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			if nextStates[i].remaining == 0 &&
				nextStates[j].remaining != 0 {

				return true
			}
			if nextStates[j].remaining == 0 &&
				nextStates[i].remaining != 0 {

				return false
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	for _, state := range states {
		if state.remaining != 0 {
			continue
		}
		if bestComplete == nil || state.score > bestComplete.score {
			copyState := state
			bestComplete = &copyState
		}
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no route set found")
	}

	return bestComplete.routes, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	rt, _, singleErr := r.findRoute(total)
	if singleErr != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaledAmount(amt, 11, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key]++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked map[candidateEdgeKey]bool

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	plan     []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*3 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 56 {
		r.attemptLimit = 56
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi,
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	held := reserved[edge.key]
	total := amt + held

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	if r.policyBlocked[edge.key] {
		return 0
	}

	if bound := r.currentFails[edge.key]; bound != 0 &&
		total >= bound {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	// A known liquidity miss is a hard upper bound. Lower amounts remain
	// eligible, which provides the useful retry-at-a-lower-size behavior.
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.99 - 0.98*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.88*(ratio-0.45)/0.55
			if scale < 0.1 {
				scale = 0.1
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.5 * math.Exp(-distance/0.2)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.1 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	used map[candidateEdgeKey]uint8) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 350_000.0
		hopPenalty = 250.0
		reuseCost  = 95_000.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver, reserved)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			if n := used[edge.key]; n > 0 {
				edgeScore += reuseCost * float64(n)
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateCopyUsage(
	src map[candidateEdgeKey]uint8) map[candidateEdgeKey]uint8 {

	dst := make(map[candidateEdgeKey]uint8, len(src))
	for key, count := range src {
		dst[key] = count
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route,
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi,
	used map[candidateEdgeKey]uint8) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			continue
		}
		reserved[key] += amt
		if used[key] < 255 {
			used[key]++
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.reserved[key] += amt
			}
		}
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

type candidatePlanState struct {
	remaining lnwire.MilliSatoshi
	reserved  map[candidateEdgeKey]lnwire.MilliSatoshi
	used      map[candidateEdgeKey]uint8
	routes    []*route.Route
	score     float64
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	average := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, average*3/4, remaining)
	candidateAddAmount(&sizes, seen, average, remaining)
	candidateAddAmount(&sizes, seen, average*5/4, remaining)
	candidateAddAmount(&sizes, seen, average*3/2, remaining)
	candidateAddAmount(&sizes, seen, average*2, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
	}

	return sizes
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if total <= 0 || parts == 0 {
		return nil, errors.New("invalid payment plan")
	}

	const beamWidth = 5

	states := []*candidatePlanState{{
		remaining: total,
		reserved:  candidateCopyReservations(r.reserved),
		used:      make(map[candidateEdgeKey]uint8),
	}}
	var completed []*candidatePlanState

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		var nextStates []*candidatePlanState

		for _, state := range states {
			if state.remaining == 0 {
				completed = append(completed, state)
				continue
			}

			slots := parts - depth
			for _, size := range r.planSizes(state.remaining, slots) {
				rt, logProb, err := r.findRoute(
					size, state.reserved, state.used,
				)
				if err != nil {
					continue
				}

				nextReserved := candidateCopyReservations(
					state.reserved,
				)
				nextUsed := candidateCopyUsage(state.used)
				r.reserveRoute(rt, nextReserved, nextUsed)

				nextRoutes := make(
					[]*route.Route, len(state.routes), len(state.routes)+1,
				)
				copy(nextRoutes, state.routes)
				nextRoutes = append(nextRoutes, rt)

				fees := rt.TotalAmount - size
				next := &candidatePlanState{
					remaining: state.remaining - size,
					reserved:  nextReserved,
					used:      nextUsed,
					routes:    nextRoutes,
					score: state.score + logProb -
						float64(fees)/8_000_000 - 0.035,
				}

				if next.remaining == 0 {
					completed = append(completed, next)
				} else if slots > 1 {
					nextStates = append(nextStates, next)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			if nextStates[i].score == nextStates[j].score {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}
			return nextStates[i].score > nextStates[j].score
		})
		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if len(completed) == 0 {
		return nil, errors.New("no complete route set found")
	}

	sort.Slice(completed, func(i, j int) bool {
		return completed[i].score > completed[j].score
	})
	return completed[0].routes, nil
}

func (r *candidateRouter) routeStillUsable(rt *route.Route,
	remaining lnwire.MilliSatoshi) bool {

	if rt == nil || len(rt.Hops) == 0 {
		return false
	}
	if candidateFinalAmount(rt) <= 0 ||
		candidateFinalAmount(rt) > remaining {

		return false
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil {
			return false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok || r.probability(edge, amt, r.reserved) <= 0 {
			return false
		}
	}

	return true
}

func (r *candidateRouter) reactiveRoute(amt lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	base := amt
	if parts > 1 {
		base = (amt + lnwire.MilliSatoshi(parts) - 1) /
			lnwire.MilliSatoshi(parts)
	}

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)
	candidateAddAmount(&sizes, seen, base, amt)
	candidateAddAmount(&sizes, seen, base*5/4, amt)
	candidateAddAmount(&sizes, seen, base*3/2, amt)
	candidateAddAmount(&sizes, seen, amt, amt)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, amt,
		)
	}
	candidateAddAmount(&sizes, seen, base*3/4, amt)
	candidateAddAmount(&sizes, seen, base/2, amt)

	var best *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range sizes {
		rt, logProb, err := r.findRoute(
			size, r.reserved, nil,
		)
		if err != nil {
			continue
		}

		fees := rt.TotalAmount - size
		sizeReward := math.Log(float64(size) / float64(base))
		utility := logProb + 0.65*sizeReward -
			float64(fees)/8_000_000

		if best == nil || utility > bestUtility {
			best = rt
			bestUtility = utility
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.plan) > 0 {
		rt := r.plan[0]
		if r.routeStillUsable(rt, amt) {
			r.plan = r.plan[1:]
			r.attempts++
			return rt, nil
		}
		r.plan = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err == nil && len(plan) > 0 {
		r.plan = plan[1:]
		r.attempts++
		return plan[0], nil
	}

	rt, err := r.reactiveRoute(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.lowerOK > 0 && estimate < belief.lowerOK {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) weakestRouteEdge(rt *route.Route) (
	candidateEdgeKey, lnwire.MilliSatoshi, bool) {

	var weakest candidateEdgeKey
	var weakestAmt lnwire.MilliSatoshi
	weakestP := math.Inf(1)
	found := false

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok || key.from == r.source {
			continue
		}
		edge := r.edges[key]
		if edge == nil {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			continue
		}
		p := r.probability(edge, amt, r.reserved)
		if !found || p < weakestP {
			found = true
			weakest = key
			weakestAmt = amt + r.reserved[key]
			weakestP = p
		}
	}

	if found {
		return weakest, weakestAmt, true
	}

	if len(rt.Hops) == 0 {
		return candidateEdgeKey{}, 0, false
	}
	i := len(rt.Hops) - 1
	key, ok := candidateRouteEdgeKey(rt, i)
	if !ok {
		return candidateEdgeKey{}, 0, false
	}
	amt, ok := candidateRouteAmount(rt, i)
	if !ok {
		return candidateEdgeKey{}, 0, false
	}
	return key, amt + r.reserved[key], true
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}
		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.plan = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		key, totalRequired, ok := r.weakestRouteEdge(rt)
		if !ok {
			return nil
		}

		switch result.Failure.Code() {
		case lnwire.CodeTemporaryChannelFailure:
			r.learnFailure(key, totalRequired)
			r.lastFailedShard = candidateFinalAmount(rt)

		default:
			r.policyBlocked[key] = true
		}
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true

	default:
		r.policyBlocked[key] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) +
		0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat) +
		uint64(e.feeRatePPM)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) +
		uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 10
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 40 {
		r.attemptLimit = 40
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio <= 0.45:
			retryScale = 0.85
		case ratio <= 0.65:
			retryScale = 0.55
		default:
			retryScale = 0.20
		}
		if failure.count > 2 {
			retryScale *= 0.75
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = 0.006
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.99 - 0.98*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.40 {
			scale := 1 - 0.94*(ratio-0.40)/0.60
			if scale < 0.04 {
				scale = 0.04
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.62 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.09 * float64(edge.capacity)
		if belief.upperFail > belief.lowerOK && belief.lowerOK > 0 {
			scale = 0.20 * float64(
				belief.upperFail - belief.lowerOK,
			)
		}
		if scale < 1 {
			scale = 1
		}

		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.62*p + 0.38*q
	}

	if belief.successes > belief.failures+1 {
		p += 0.05 * (1 - p)
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 450_000.0
		hopPenalty = 240.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 18_000
			edgeScore += float64(r.suspect[edge.key]) * 175_000
			edgeScore += extraPenalty[edge.key]

			if r.reserved[edge.key] > 0 {
				edgeScore += 90_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteSignature(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(uint64(candidateFinalAmount(rt)))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(key.chanID + uint64(i+1)<<48)
		h ^= candidateMix64(candidateVertexHash(key.to))
	}
	return candidateMix64(h)
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserve(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserve(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeAlternatives(
	amt lnwire.MilliSatoshi) []candidateRouteChoice {

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	choices := make([]candidateRouteChoice, 0, 2)

	for tries := 0; tries < 4 && len(choices) < 2; tries++ {
		rt, logProb, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		sig := candidateRouteSignature(rt)
		if !seen[sig] {
			seen[sig] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				logProb: logProb,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				penalties[key] += 720_000
			}
		}
	}

	return choices
}

func candidateAddSize(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	var sizes []lnwire.MilliSatoshi

	candidateAddSize(&sizes, seen, remaining, remaining)
	if slots <= 1 {
		return sizes
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddSize(&sizes, seen, base/2, remaining)
	candidateAddSize(&sizes, seen, base*3/4, remaining)
	candidateAddSize(&sizes, seen, base, remaining)
	candidateAddSize(&sizes, seen, base*5/4, remaining)
	candidateAddSize(&sizes, seen, base*3/2, remaining)
	candidateAddSize(&sizes, seen, base*7/4, remaining)
	candidateAddSize(&sizes, seen, base*2, remaining)

	if r.lastFailedShard > 0 {
		candidateAddSize(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*2/3, remaining,
		)
	}

	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		parts = 1
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	initial := &candidatePlanState{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}

	beam := []*candidatePlanState{initial}
	var best *candidatePlanState

	const beamWidth = 7

	for depth := uint32(0); depth < parts && len(beam) > 0; depth++ {
		var nextBeam []*candidatePlanState

		for _, state := range beam {
			if state.remaining == 0 {
				if best == nil || state.score > best.score {
					best = state
				}
				continue
			}
			if state.slots == 0 {
				continue
			}

			r.reserved = state.reservations
			sizes := r.shardSizes(state.remaining, state.slots)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				for _, choice := range r.routeAlternatives(size) {
					fees := choice.route.TotalAmount - size
					score := state.score + choice.logProb -
						float64(fees)/4_000_000 - 0.018

					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserve(reservations, choice.route)

					routes := append(
						[]*route.Route(nil), state.routes...,
					)
					routes = append(routes, choice.route)

					remaining := state.remaining - size
					progress := 1 - float64(remaining)/
						float64(total)

					ns := &candidatePlanState{
						remaining:    remaining,
						slots:        state.slots - 1,
						routes:       routes,
						reservations: reservations,
						score:        score,
						rank:         score + 0.42*progress,
					}

					if remaining == 0 {
						if best == nil || ns.score > best.score {
							best = ns
						}
					} else if ns.slots > 0 {
						nextBeam = append(nextBeam, ns)
					}
				}
			}
		}

		sort.Slice(nextBeam, func(i, j int) bool {
			return nextBeam[i].rank > nextBeam[j].rank
		})
		if len(nextBeam) > beamWidth {
			nextBeam = nextBeam[:beamWidth]
		}
		beam = nextBeam
	}

	if best == nil || len(best.routes) == 0 {
		r.reserved = savedReservations
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	return best.routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	projected := amt
	if edge := r.edges[key]; edge != nil && edge.capacity > amt {
		if belief.upperFail > amt {
			projected = amt + (belief.upperFail-amt)*2/5
		} else {
			projected = amt + (edge.capacity-amt)*2/3
		}
	}
	if projected > belief.estimate {
		belief.estimate = projected
	}
	if belief.upperFail > 0 && belief.estimate >= belief.upperFail {
		belief.estimate = belief.lowerOK +
			(belief.upperFail-belief.lowerOK)/2
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 7 / 20
	if estimate < belief.lowerOK {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid reported route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi
	settledLocal  map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
	refreshes       int
	relaxCurrent    bool
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		settledLocal:   make(map[uint64]lnwire.MilliSatoshi),
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 10
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 56 {
		r.attemptLimit = 56
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		if _, ok := r.edges[key]; ok {
			r.beliefs[key] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateRetryFactor(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.62
	case count == 2:
		return 0.48
	default:
		return 0.36
	}
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var numerator int64
	switch {
	case f.count <= 1:
		numerator = 70
	case f.count == 2:
		numerator = 54
	default:
		numerator = 42
	}

	ceiling := f.upper * lnwire.MilliSatoshi(numerator) / 100
	if ceiling < 1 {
		ceiling = 1
	}

	return ceiling, true
}

func (r *candidateRouter) localAvailable(
	edge *candidateEdge) lnwire.MilliSatoshi {

	balance, ok := r.localBalances[edge.key.chanID]
	if !ok {
		return 0
	}

	balance -= r.settledLocal[edge.key.chanID]
	if balance < 0 {
		return 0
	}
	return balance
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity ||
		r.policyBlocked[edge.key] {

		return 0
	}

	if edge.key.from == r.source {
		if total > r.localAvailable(edge) {
			return 0
		}
		return 0.999
	}

	retryScale := 1.0
	if !r.relaxCurrent {
		if failure, ok := r.currentFails[edge.key]; ok {
			if failure.upper > 0 && total >= failure.upper {
				return 0
			}
			if ceiling, ok := candidateRetryCeiling(failure); ok &&
				total > ceiling {

				return 0
			}
			retryScale = candidateRetryFactor(failure.count)
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.005)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence := 0.994 - 0.989*pos
		p = 0.12*p + 0.88*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.40 {
			scale := 1 - 0.95*(ratio-0.40)/0.60
			if scale < 0.03 {
				scale = 0.03
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.62 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.09 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.75*p + 0.25*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	shard lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(shard) || r.policyBlocked[edge.key] {
		return 0
	}

	total := shard + r.reserved[edge.key]
	return r.liquidityProbability(edge, total)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 480_000.0
		hopPenalty = 600.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 5_000
			edgeScore += float64(r.suspect[edge.key]) * 170_000
			edgeScore += diversity[edge.key]

			if r.reserved[edge.key] > 0 {
				edgeScore += 120_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) settleRouteLocal(rt *route.Route) {
	if rt == nil || len(rt.Hops) == 0 {
		return
	}

	key, ok := candidateRouteEdgeKey(rt, 0)
	if !ok || key.from != r.source {
		return
	}

	amt, ok := candidateRouteAmount(rt, 0)
	if ok {
		r.settledLocal[key.chanID] += amt
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}

	dropped := len(r.held) - count
	for i := 0; i < dropped; i++ {
		r.settleRouteLocal(r.held[i])
	}

	if count == 0 {
		r.held = nil
		return
	}

	kept := append([]*route.Route(nil), r.held[dropped:]...)
	r.held = kept
	for _, rt := range r.held {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidateScaledAmount(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func (r *candidateRouter) routeLimit(rt *route.Route) lnwire.MilliSatoshi {
	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 {
		return 0
	}

	limit := finalAmt * 4
	if limit < finalAmt {
		limit = finalAmt
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}
		edge := r.edges[key]
		if edge == nil {
			return 0
		}

		over, ok := candidateRouteAmount(rt, i)
		if !ok || over <= 0 {
			return 0
		}

		reserved := r.reserved[key]
		aggregateLimit := edge.capacity

		if key.from == r.source {
			available := r.localAvailable(edge)
			if available < aggregateLimit {
				aggregateLimit = available
			}
		} else {
			belief, known := r.beliefs[key]
			switch {
			case known && belief.upperFail > 0:
				likely := candidateScaledAmount(
					belief.upperFail, 58, 100,
				)
				if belief.lowerOK > likely {
					likely = belief.lowerOK
				}
				if likely >= belief.upperFail {
					likely = belief.upperFail - 1
				}
				if likely < aggregateLimit {
					aggregateLimit = likely
				}

			case known && belief.lowerOK > 0:
				likely := belief.lowerOK +
					candidateScaledAmount(
						edge.capacity-belief.lowerOK,
						40, 100,
					)
				if likely < aggregateLimit {
					aggregateLimit = likely
				}

			default:
				likely := candidateScaledAmount(
					edge.capacity, 88, 100,
				)
				if likely < aggregateLimit {
					aggregateLimit = likely
				}
			}

			if !r.relaxCurrent {
				if failure, ok := r.currentFails[key]; ok {
					if ceiling, ok := candidateRetryCeiling(
						failure,
					); ok && ceiling < aggregateLimit {

						aggregateLimit = ceiling
					}
				}
			}
		}

		available := aggregateLimit - reserved
		if available <= 0 {
			return 0
		}

		shardLimit := available
		if edge.maxHTLC > 0 && edge.maxHTLC < shardLimit {
			shardLimit = edge.maxHTLC
		}

		scaled := lnwire.MilliSatoshi(
			float64(finalAmt) *
				float64(shardLimit) / float64(over),
		)
		if scaled < limit {
			limit = scaled
		}
	}

	if limit < 1 {
		return 0
	}
	return limit
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 5),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 4, 5),
		remaining,
	)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 6, 5),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 2),
		remaining,
	)
	candidateAddAmount(&values, seen, base*2, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(r.lastFailedShard, 7, 10),
			remaining,
		)
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(r.lastFailedShard, 1, 2),
			remaining,
		)
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(r.lastFailedShard, 7, 20),
			remaining,
		)
	}

	candidateAddAmount(&values, seen, remaining, remaining)
	return values
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(uint64(candidateFinalAmount(rt)))
	for _, hop := range rt.Hops {
		h ^= candidateMix64(hop.ChannelID + candidateVertexHash(
			hop.PubKeyBytes,
		))
	}
	return h
}

func (r *candidateRouter) routeRetryPenalty(rt *route.Route) float64 {
	var penalty float64
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if failure, ok := r.currentFails[key]; ok {
			penalty += 0.22 * float64(failure.count)
		}
		penalty += 0.035 * float64(r.suspect[key])
	}
	return penalty
}

func (r *candidateRouter) planScore(
	base, total map[candidateEdgeKey]lnwire.MilliSatoshi,
	fees lnwire.MilliSatoshi, parts int, extraPenalty float64) float64 {

	score := -float64(fees) / 3_500_000
	score -= 0.014 * float64(parts)
	score -= extraPenalty

	for key, totalAmt := range total {
		baseAmt := base[key]
		if totalAmt <= baseAmt {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		pNew := r.liquidityProbability(edge, totalAmt)
		if pNew <= 0 {
			return math.Inf(-1)
		}

		incremental := pNew
		if baseAmt > 0 {
			pBase := r.liquidityProbability(edge, baseAmt)
			if pBase > 0 {
				incremental = pNew / pBase
			}
		}

		if incremental > 0.999 {
			incremental = 0.999
		}
		if incremental < 0.001 {
			incremental = 0.001
		}
		score += math.Log(incremental)
	}

	return score
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	fees         lnwire.MilliSatoshi
	penalty      float64
	score        float64
	rank         float64
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState
	const beamWidth = 28

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make([]candidatePlanState, 0, beamWidth*12)

		for _, state := range states {
			if state.remaining == 0 {
				copyState := state
				if bestComplete == nil ||
					copyState.score > bestComplete.score {

					bestComplete = &copyState
				}
				continue
			}

			r.reserved = candidateCopyReservations(
				state.reservations,
			)

			sizes := r.planSizes(state.remaining, slots)
			seenSizes := make(map[lnwire.MilliSatoshi]bool)
			for _, size := range sizes {
				seenSizes[size] = true
			}

			for si := 0; si < len(sizes) && si < 16; si++ {
				size := sizes[si]
				if size <= 0 || size > state.remaining {
					continue
				}

				diversity := make(
					map[candidateEdgeKey]float64,
				)
				seenRoutes := make(map[uint64]bool)

				for alternative := 0; alternative < 3; alternative++ {
					r.reserved = candidateCopyReservations(
						state.reservations,
					)

					rt, _, err := r.findRoute(
						size, diversity,
					)
					if err != nil {
						break
					}

					for i := range rt.Hops {
						key, ok := candidateRouteEdgeKey(
							rt, i,
						)
						if ok {
							diversity[key] += 520_000
						}
					}

					hash := candidateRouteHash(rt)
					if seenRoutes[hash] {
						continue
					}
					seenRoutes[hash] = true

					limit := r.routeLimit(rt)
					if limit > 0 {
						candidateAddAmount(
							&sizes, seenSizes,
							candidateScaledAmount(
								limit, 4, 5,
							),
							state.remaining,
						)
						candidateAddAmount(
							&sizes, seenSizes, limit,
							state.remaining,
						)
					}

					newReservations :=
						candidateCopyReservations(
							state.reservations,
						)
					r.reserved = newReservations
					r.reserveRoute(rt)

					fees := state.fees +
						rt.TotalAmount - size
					penalty := state.penalty +
						r.routeRetryPenalty(rt)

					routes := make(
						[]*route.Route,
						len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, rt)

					remaining := state.remaining - size
					score := r.planScore(
						savedReservations,
						newReservations,
						fees, len(routes), penalty,
					)
					if math.IsInf(score, -1) {
						continue
					}

					progress := float64(total-remaining) /
						float64(total)
					rank := score + 3.4*progress

					if remaining > 0 && slots == 1 {
						continue
					}

					nextStates = append(
						nextStates, candidatePlanState{
							remaining: remaining,
							routes: routes,
							reservations:
							newReservations,
							fees:    fees,
							penalty: penalty,
							score:   score,
							rank:    rank,
						},
					)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			iComplete := nextStates[i].remaining == 0
			jComplete := nextStates[j].remaining == 0
			if iComplete != jComplete {
				return iComplete
			}
			if nextStates[i].rank == nextStates[j].rank {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	for _, state := range states {
		if state.remaining != 0 {
			continue
		}
		if bestComplete == nil || state.score > bestComplete.score {
			copyState := state
			bestComplete = &copyState
		}
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no route set found")
	}

	return bestComplete.routes, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	sizes := r.planSizes(total, parts)
	for _, size := range sizes {
		if size >= total {
			continue
		}
		rt, _, routeErr := r.findRoute(size, nil)
		if routeErr == nil {
			return []*route.Route{rt}, nil
		}
	}

	rt, _, singleErr := r.findRoute(total, nil)
	if singleErr == nil {
		return []*route.Route{rt}, nil
	}

	return nil, err
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	r.relaxCurrent = false
	plan, err := r.makePlan(amt, partsLeft)
	if err != nil && r.refreshes < 2 {
		r.relaxCurrent = true
		plan, err = r.makePlan(amt, partsLeft)
		r.relaxCurrent = false
		if err == nil {
			r.refreshes++
		}
	}
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaledAmount(amt, 11, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 12
	if r.attemptLimit < 24 {
		r.attemptLimit = 24
	}
	if r.attemptLimit > 48 {
		r.attemptLimit = 48
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateClampProbability(p float64) float64 {
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) absoluteProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if ok {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.995

		case belief.upperFail > 0 && total >= belief.upperFail:
			p = 0.004

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK:

			width := float64(
				belief.upperFail - belief.lowerOK,
			)
			pos := float64(total-belief.lowerOK) / width
			if pos < 0 {
				pos = 0
			}
			if pos > 1 {
				pos = 1
			}

			evidence := 0.992 - 0.984*pos
			p = 0.12*p + 0.88*evidence

		case belief.upperFail > 0:
			ratio := float64(total) /
				float64(belief.upperFail)
			if ratio > 0.45 {
				scale := 1 - 0.94*(ratio-0.45)/0.55
				if scale < 0.06 {
					scale = 0.06
				}
				p *= scale
			}

		case belief.lowerOK > 0 && total > belief.lowerOK:
			distance := float64(total-belief.lowerOK) /
				float64(edge.capacity)
			boost := 0.55 * math.Exp(-distance/0.16)
			p += boost * (1 - p)
		}

		if belief.estimate > 0 {
			scale := 0.09 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			q := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate)) /
					scale,
			))
			p = 0.76*p + 0.24*q
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.85:
			p *= 0.28
		case ratio > 0.65:
			p *= 0.58
		case ratio > 0.45:
			p *= 0.82
		}
	}

	return candidateClampProbability(p)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	total := reserved + amt
	pTotal := r.absoluteProbability(edge, total)
	if pTotal <= 0 {
		return 0
	}
	if reserved == 0 {
		return pTotal
	}

	pReserved := r.absoluteProbability(edge, reserved)
	if pReserved <= 0 {
		return pTotal
	}

	conditional := pTotal / pReserved
	if conditional > 0.999 {
		conditional = 0.999
	}
	if conditional < 0.002 {
		conditional = 0.002
	}
	return conditional
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 600_000.0
		hopPenalty = 300.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee
			if sending < amtOver {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 18_000
			edgeScore += float64(r.suspect[edge.key]) * 310_000

			if reserved := r.reserved[edge.key]; reserved > 0 &&
				edge.key.from != r.source {

				ratio := float64(reserved) /
					float64(edge.capacity)
				edgeScore += 190_000 + 420_000*ratio
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		return
	}
	if value > max {
		value = max
	}
	if value > 0 && !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) shardCandidates(
	remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddAmount(&values, seen, base/2, remaining)
	candidateAddAmount(&values, seen, base*3/4, remaining)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(&values, seen, base*5/4, remaining)
	candidateAddAmount(&values, seen, base*3/2, remaining)
	candidateAddAmount(&values, seen, base*2, remaining)
	candidateAddAmount(&values, seen, base*3, remaining)
	candidateAddAmount(&values, seen, remaining/2, remaining)
	candidateAddAmount(&values, seen, remaining*2/3, remaining)
	candidateAddAmount(&values, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard/3, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*5/8, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*3/4, remaining,
		)
	}

	for _, edge := range r.incomingEdges[r.spec.Target] {
		limit := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}

		reserved := r.reserved[edge.key]
		if reserved >= edge.capacity {
			continue
		}
		cumulativeRoom := edge.capacity - reserved
		if limit > cumulativeRoom {
			limit = cumulativeRoom
		}

		candidateAddAmount(&values, seen, limit/20, remaining)
		candidateAddAmount(&values, seen, limit/10, remaining)
		candidateAddAmount(&values, seen, limit/4, remaining)
		candidateAddAmount(&values, seen, limit/2, remaining)
		candidateAddAmount(&values, seen, limit*4/5, remaining)

		if belief, ok := r.beliefs[edge.key]; ok {
			if belief.lowerOK > reserved {
				safe := belief.lowerOK - reserved
				candidateAddAmount(
					&values, seen, safe, remaining,
				)
				candidateAddAmount(
					&values, seen, safe*4/5, remaining,
				)
			}
			if belief.estimate > reserved {
				estimate := belief.estimate - reserved
				candidateAddAmount(
					&values, seen, estimate*4/5,
					remaining,
				)
			}
			if belief.upperFail > reserved {
				ceiling := belief.upperFail - reserved
				candidateAddAmount(
					&values, seen, ceiling/2, remaining,
				)
				candidateAddAmount(
					&values, seen, ceiling*2/3,
					remaining,
				)
			}
		}

		if failure, ok := r.currentFails[edge.key]; ok &&
			failure.upper > reserved {

			ceiling := failure.upper - reserved
			candidateAddAmount(
				&values, seen, ceiling/3, remaining,
			)
			candidateAddAmount(
				&values, seen, ceiling/2, remaining,
			)
			candidateAddAmount(
				&values, seen, ceiling*2/3, remaining,
			)
		}
	}

	return values
}

func candidatePlanContribution(rt *route.Route,
	finalAmt lnwire.MilliSatoshi, logProb float64) float64 {

	fees := rt.TotalAmount - finalAmt
	return logProb - float64(fees)/2_500_000 - 0.03
}

func (r *candidateRouter) planOnce(total lnwire.MilliSatoshi,
	parts uint32, sizeBias float64) ([]*route.Route, float64, bool) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	remaining := total
	slots := parts
	var plan []*route.Route
	jointScore := 0.0

	for remaining > 0 && slots > 0 {
		if slots == 1 {
			rt, logProb, err := r.findRoute(remaining)
			if err != nil {
				return nil, 0, false
			}

			jointScore += candidatePlanContribution(
				rt, remaining, logProb,
			)
			plan = append(plan, rt)
			r.reserveRoute(rt)
			remaining = 0
			break
		}

		base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)
		sizes := r.shardCandidates(remaining, slots)

		var bestRoute *route.Route
		bestSize := lnwire.MilliSatoshi(0)
		bestLogProb := 0.0
		bestUtility := math.Inf(-1)

		for _, size := range sizes {
			if size <= 0 || size > remaining {
				continue
			}

			rt, logProb, err := r.findRoute(size)
			if err != nil {
				continue
			}

			fees := rt.TotalAmount - size
			sizeReward := math.Log(
				float64(size) / float64(base),
			)
			utility := logProb + sizeBias*sizeReward -
				float64(fees)/2_500_000

			if bestRoute == nil || utility > bestUtility {
				bestRoute = rt
				bestSize = size
				bestLogProb = logProb
				bestUtility = utility
			}
		}

		if bestRoute == nil {
			return nil, 0, false
		}

		jointScore += candidatePlanContribution(
			bestRoute, bestSize, bestLogProb,
		)
		plan = append(plan, bestRoute)
		r.reserveRoute(bestRoute)
		remaining -= bestSize
		slots--
	}

	if remaining != 0 || len(plan) == 0 {
		return nil, 0, false
	}
	return plan, jointScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	full, fullLogProb, fullErr := r.findRoute(total)
	if fullErr == nil {
		bestPlan = []*route.Route{full}
		bestScore = candidatePlanContribution(
			full, total, fullLogProb,
		)
	}

	if parts > 1 {
		biases := []float64{0.0, 0.24, 0.48, 0.78, 1.08}
		for _, bias := range biases {
			plan, score, ok := r.planOnce(total, parts, bias)
			if !ok {
				continue
			}
			if bestPlan == nil || score > bestScore {
				bestPlan = plan
				bestScore = score
			}
		}
	}

	if bestPlan == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return nil, errors.New("no payment plan found")
	}

	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil &&
		amt > edge.capacity/14 {

		highEstimate := edge.capacity * 9 / 10
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 2 / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else if estimate < belief.estimate {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	lastRemaining   lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) +
		0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat) +
		uint64(e.feeRatePPM)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) +
		uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	localCopy := make(map[uint64]lnwire.MilliSatoshi, len(localBalances))
	for chanID, balance := range localBalances {
		localCopy[chanID] = balance
	}

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localCopy,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 56 {
		r.attemptLimit = 56
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.032))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.987 {
		return 0.987
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		var numerator int64
		switch {
		case failure.count <= 1:
			numerator = 55
		case failure.count == 2:
			numerator = 42
		case failure.count == 3:
			numerator = 32
		default:
			numerator = 24
		}

		ceiling := failure.upper *
			lnwire.MilliSatoshi(numerator) / 100
		if ceiling < 1 {
			ceiling = 1
		}
		if total > ceiling {
			return 0
		}

		retryScale = 0.58 *
			math.Pow(0.82, float64(failure.count-1))
		if retryScale < 0.18 {
			retryScale = 0.18
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.996 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.003 * retryScale
	}

	switch {
	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		evidence := 0.994 - 0.989*position
		p = 0.15*p + 0.85*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		exponent := 2.8 + 0.18*float64(belief.failures)
		if exponent > 4.0 {
			exponent = 4.0
		}

		conditional := math.Exp(-exponent * ratio)
		if conditional < 0.004 {
			conditional = 0.004
		}
		p = 0.22*p + 0.78*conditional

	case belief.lowerOK > 0 && total > belief.lowerOK:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.55 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.78*p + 0.22*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.996 {
		return 0.996
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 500_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 9_000
			edgeScore += float64(r.suspect[edge.key]) * 230_000

			if r.reserved[edge.key] > 0 {
				if edge.key.from == r.source {
					edgeScore += 8_000
				} else {
					edgeScore += 850_000
				}
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReservationsWithRoute(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := candidateCopyReservations(src)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			dst[key] += amt
		}
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func candidateSubtractBound(bound, amt lnwire.MilliSatoshi) (
	lnwire.MilliSatoshi, bool) {

	if bound == 0 {
		return 0, false
	}
	if bound > amt {
		return bound - amt, true
	}
	return 1, true
}

func (r *candidateRouter) settleRoutes(routes []*route.Route) {
	for _, rt := range routes {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok || amt <= 0 {
				continue
			}

			if key.from == r.source {
				balance := r.localBalances[key.chanID]
				if balance > amt {
					r.localBalances[key.chanID] = balance - amt
				} else {
					r.localBalances[key.chanID] = 0
				}
			} else {
				belief, exists := r.beliefs[key]
				if exists {
					if belief.lowerOK > amt {
						belief.lowerOK -= amt
					} else {
						belief.lowerOK = 0
					}
					if upper, set := candidateSubtractBound(
						belief.upperFail, amt,
					); set {
						belief.upperFail = upper
					}
					if belief.estimate > amt {
						belief.estimate -= amt
					} else {
						belief.estimate = 0
					}
					r.storeBelief(key, belief)
				}
			}

			if failure, exists := r.currentFails[key]; exists {
				if upper, set := candidateSubtractBound(
					failure.upper, amt,
				); set {
					failure.upper = upper
					r.currentFails[key] = failure
				}
			}
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		if len(r.held) > 0 {
			r.settleRoutes(r.held)
			r.held = nil
		}
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidatePlanSizes(remaining lnwire.MilliSatoshi,
	slots uint32, failed lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base*2/3, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*4/3, remaining)
	candidateAddAmount(&sizes, seen, base*5/3, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	if failed > 0 {
		candidateAddAmount(
			&sizes, seen, failed*2/5, remaining,
		)
		candidateAddAmount(
			&sizes, seen, failed/4, remaining,
		)
	}

	return sizes
}

type candidateRouteChoice struct {
	rt      *route.Route
	logProb float64
}

func candidateSameRoute(a, b *route.Route) bool {
	if a == nil || b == nil || len(a.Hops) != len(b.Hops) {
		return false
	}
	for i := range a.Hops {
		if a.Hops[i].ChannelID != b.Hops[i].ChannelID ||
			a.Hops[i].PubKeyBytes != b.Hops[i].PubKeyBytes {

			return false
		}
	}
	return true
}

func (r *candidateRouter) routeChoices(
	amt lnwire.MilliSatoshi,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	variants int) []candidateRouteChoice {

	r.reserved = candidateCopyReservations(reservations)

	first, firstProb, err := r.findRoute(amt)
	if err != nil {
		return nil
	}

	choices := []candidateRouteChoice{{
		rt:      first,
		logProb: firstProb,
	}}
	if variants < 2 {
		return choices
	}

	saved := make(map[candidateEdgeKey]uint32)
	for i := range first.Hops {
		key, ok := candidateRouteEdgeKey(first, i)
		if !ok || key.from == r.source {
			continue
		}
		if _, exists := saved[key]; exists {
			continue
		}
		saved[key] = r.suspect[key]
		r.suspect[key] += 3
	}

	second, secondProb, secondErr := r.findRoute(amt)

	for key, value := range saved {
		if value == 0 {
			delete(r.suspect, key)
		} else {
			r.suspect[key] = value
		}
	}

	if secondErr == nil && !candidateSameRoute(first, second) {
		choices = append(choices, candidateRouteChoice{
			rt:      second,
			logProb: secondProb,
		})
	}

	return choices
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		parts = 1
	}
	if parts == 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	const beamWidth = 14

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		var next []candidatePlanState

		for _, state := range states {
			slots := parts - uint32(len(state.routes))
			if slots == 0 {
				continue
			}

			sizes := candidatePlanSizes(
				state.remaining, slots, r.lastFailedShard,
			)
			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				variants := 1
				if depth < 2 || size == state.remaining {
					variants = 2
				}

				choices := r.routeChoices(
					size, state.reservations, variants,
				)
				for _, choice := range choices {
					fees := choice.rt.TotalAmount - size
					score := state.score + choice.logProb -
						float64(fees)/5_000_000 - 0.035

					routes := append(
						[]*route.Route(nil), state.routes...,
					)
					routes = append(routes, choice.rt)

					remaining := state.remaining - size
					reservations := candidateReservationsWithRoute(
						state.reservations, choice.rt,
					)

					if remaining == 0 {
						if bestPlan == nil || score > bestScore {
							bestPlan = routes
							bestScore = score
						}
						continue
					}

					progress := 1 -
						float64(remaining)/float64(total)
					next = append(next, candidatePlanState{
						remaining:    remaining,
						routes:       routes,
						reservations: reservations,
						score:        score,
						rank:         score + 0.10*progress,
					})
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return next[i].rank > next[j].rank
		})
		if len(next) > beamWidth {
			next = next[:beamWidth]
		}
		states = next
	}

	if bestPlan != nil {
		return bestPlan, nil
	}

	r.reserved = savedReservations
	rt, _, err := r.findRoute(total)
	if err != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.lastRemaining = amt
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.lastRemaining = amt
	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	var capacity lnwire.MilliSatoshi
	for _, edge := range r.incomingEdges[key.to] {
		if edge.key == key {
			capacity = edge.capacity
			break
		}
	}
	if capacity > 0 && amt*100 >= capacity*6 {
		highEstimate := capacity * 86 / 100
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	var estimate lnwire.MilliSatoshi
	if belief.lowerOK > 0 && belief.lowerOK < amt {
		estimate = belief.lowerOK + (amt-belief.lowerOK)/3
	} else {
		estimate = amt / 3
	}
	if estimate < 1 {
		estimate = 1
	}
	if belief.estimate == 0 || estimate < belief.estimate {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0

		if candidateFinalAmount(rt) == r.lastRemaining {
			r.settleRoutes(r.held)
			r.held = nil
			r.planned = nil
			r.reserved = make(
				map[candidateEdgeKey]lnwire.MilliSatoshi,
			)
		}

		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidatePlannedShard struct {
	path   []*candidateEdge
	amount lnwire.MilliSatoshi
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked map[candidateEdgeKey]bool
	edgePenalty   map[candidateEdgeKey]float64

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	plan     []candidatePlannedShard

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	return candidateMix64(x)
}

func candidatePathHash(path []*candidateEdge) uint64 {
	h := uint64(0x6a09e667f3bcc909)
	for i, edge := range path {
		h ^= candidateMix64(
			candidateEdgeHash(edge) + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		h = candidateMix64(h)
	}
	return h
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgePenalty:    make(map[candidateEdgeKey]float64),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*3 + 12
	if r.attemptLimit < 36 {
		r.attemptLimit = 36
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		if total > r.localBalances[edge.key.chanID] {
			return 0
		}
		return 0.999
	}

	if bound := r.currentFails[edge.key]; bound != 0 &&
		total >= bound {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.988 - 0.976*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.50 {
			scale := 1 - 0.94*(ratio-0.50)/0.50
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.50 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) ([]*candidateEdge,
	float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 360_000.0
		hopPenalty = 300.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty +
				r.edgePenalty[edge.key] +
				extraPenalty[edge.key]

			if r.reserved[edge.key] > 0 {
				edgeScore += 150_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, 0, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, 0, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, 0, errors.New("empty route")
	}
	return path, sourceLogProb, nil
}

func (r *candidateRouter) buildRouteFromPath(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 || len(path) == 0 {
		return nil, errors.New("invalid route")
	}
	if path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("path endpoints do not match payment")
	}

	for i := 1; i < len(path); i++ {
		if path[i-1].key.to != path[i].key.from {
			return nil, errors.New("disconnected route path")
		}
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func (r *candidateRouter) pathLogProbability(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (float64, *route.Route, bool) {

	rt, err := r.buildRouteFromPath(amt, path)
	if err != nil {
		return 0, nil, false
	}

	logProb := 0.0
	for i, edge := range path {
		amtOver, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0, nil, false
		}
		p := r.probability(edge, amtOver)
		if p <= 0 {
			return 0, nil, false
		}
		logProb += math.Log(p)
	}

	return logProb, rt, true
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, []*candidateEdge, float64, error) {

	path, _, err := r.findPath(
		amt, map[candidateEdgeKey]float64{},
	)
	if err != nil {
		return nil, nil, 0, err
	}

	logProb, rt, ok := r.pathLogProbability(path, amt)
	if !ok {
		return nil, nil, 0, errors.New("route became infeasible")
	}
	return rt, path, logProb, nil
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.reserved[key] += amt
			}
		}
	}
}

type candidatePathOption struct {
	path    []*candidateEdge
	seed    lnwire.MilliSatoshi
	rawMax  lnwire.MilliSatoshi
	safeMax lnwire.MilliSatoshi
	quality float64
}

func (r *candidateRouter) maxPathAmount(path []*candidateEdge,
	seed, ceiling lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if ceiling <= 0 {
		return 0
	}
	if seed <= 0 || seed > ceiling {
		seed = ceiling
	}

	if _, _, ok := r.pathLogProbability(path, seed); !ok {
		found := lnwire.MilliSatoshi(0)
		for _, fraction := range []int64{2, 4, 8, 16, 32} {
			probe := seed / lnwire.MilliSatoshi(fraction)
			if probe <= 0 {
				probe = 1
			}
			if _, _, ok := r.pathLogProbability(path, probe); ok {
				found = probe
				break
			}
		}
		if found == 0 {
			return 0
		}
		seed = found
	}

	low, high := seed, ceiling
	for low < high {
		mid := low + (high-low+1)/2
		if _, _, ok := r.pathLogProbability(path, mid); ok {
			low = mid
		} else {
			high = mid - 1
		}
	}
	return low
}

func (r *candidateRouter) enumeratePaths(amt lnwire.MilliSatoshi,
	parts uint32) []candidatePathOption {

	if parts == 0 {
		parts = 1
	}
	base := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	probes := []lnwire.MilliSatoshi{
		base,
		base * 3 / 2,
		base / 2,
		base * 2,
		base / 4,
		amt,
	}
	for i := range probes {
		if probes[i] <= 0 {
			probes[i] = 1
		}
		if probes[i] > amt {
			probes[i] = amt
		}
	}

	rounds := int(parts)*3 + 6
	if rounds > 54 {
		rounds = 54
	}

	diversity := make(map[candidateEdgeKey]float64)
	byHash := make(map[uint64]int)
	var options []candidatePathOption

	for i := 0; i < rounds; i++ {
		probe := probes[i%len(probes)]
		path, _, err := r.findPath(probe, diversity)
		if err != nil {
			continue
		}

		hash := candidatePathHash(path)
		if index, ok := byHash[hash]; ok {
			if probe < options[index].seed {
				options[index].seed = probe
			}
		} else {
			byHash[hash] = len(options)
			options = append(options, candidatePathOption{
				path: path,
				seed: probe,
			})
		}

		for _, edge := range path {
			diversity[edge.key] += 900_000
		}
	}

	for i := range options {
		option := &options[i]
		option.rawMax = r.maxPathAmount(
			option.path, option.seed, amt,
		)
		if option.rawMax == 0 {
			option.quality = math.Inf(-1)
			continue
		}

		option.safeMax = option.rawMax * 9 / 10
		if option.safeMax <= 0 {
			option.safeMax = option.rawMax
		}
		if _, _, ok := r.pathLogProbability(
			option.path, option.safeMax,
		); !ok {
			option.safeMax = option.rawMax
		}

		probe := base
		if probe > option.safeMax {
			probe = option.safeMax
		}
		logProb, rt, ok := r.pathLogProbability(
			option.path, probe,
		)
		if !ok {
			logProb, rt, ok = r.pathLogProbability(
				option.path, option.seed,
			)
		}
		if !ok {
			option.quality = math.Inf(-1)
			continue
		}

		fees := rt.TotalAmount -
			rt.Hops[len(rt.Hops)-1].AmtToForward
		capacityBonus := 0.22 * math.Log1p(
			float64(option.safeMax) / float64(base),
		)
		option.quality = logProb + capacityBonus -
			float64(fees)/8_000_000
	}

	filtered := options[:0]
	for _, option := range options {
		if option.rawMax > 0 && !math.IsInf(option.quality, -1) {
			filtered = append(filtered, option)
		}
	}
	return filtered
}

func candidateOptionCapacity(option candidatePathOption,
	aggressive bool) lnwire.MilliSatoshi {

	if !aggressive {
		return option.safeMax
	}
	capacity := option.rawMax * 98 / 100
	if capacity < option.safeMax {
		capacity = option.safeMax
	}
	return capacity
}

func candidateSelectOptions(options []candidatePathOption,
	amt lnwire.MilliSatoshi, slots int,
	aggressive bool) []candidatePathOption {

	if slots <= 0 {
		return nil
	}

	remaining := append([]candidatePathOption(nil), options...)
	usedEdges := make(map[candidateEdgeKey]bool)
	var selected []candidatePathOption
	var capacity lnwire.MilliSatoshi

	for len(selected) < slots && len(remaining) > 0 {
		best := -1
		bestValue := math.Inf(-1)

		for i, option := range remaining {
			cap := candidateOptionCapacity(option, aggressive)
			if cap <= 0 {
				continue
			}

			overlap := 0
			for _, edge := range option.path {
				if usedEdges[edge.key] {
					overlap++
				}
			}

			value := option.quality -
				1.35*float64(overlap) +
				0.10*math.Log1p(float64(cap))

			if best < 0 || value > bestValue {
				best = i
				bestValue = value
			}
		}

		if best < 0 {
			break
		}

		chosen := remaining[best]
		remaining = append(remaining[:best], remaining[best+1:]...)
		selected = append(selected, chosen)
		capacity += candidateOptionCapacity(chosen, aggressive)

		for _, edge := range chosen.path {
			usedEdges[edge.key] = true
		}

		if capacity >= amt {
			return selected
		}
	}

	if capacity < amt {
		return nil
	}
	return selected
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	parts uint32) []candidatePlannedShard {

	if parts <= 1 || amt <= 0 {
		return nil
	}

	options := r.enumeratePaths(amt, parts)
	if len(options) == 0 {
		return nil
	}

	selected := candidateSelectOptions(
		options, amt, int(parts), false,
	)
	aggressive := false
	if len(selected) == 0 {
		aggressive = true
		selected = candidateSelectOptions(
			options, amt, int(parts), true,
		)
	}
	if len(selected) == 0 {
		return nil
	}

	sort.Slice(selected, func(i, j int) bool {
		return selected[i].quality > selected[j].quality
	})

	caps := make([]lnwire.MilliSatoshi, len(selected))
	var totalCap lnwire.MilliSatoshi
	for i, option := range selected {
		caps[i] = candidateOptionCapacity(option, aggressive)
		totalCap += caps[i]
	}
	if totalCap < amt {
		return nil
	}

	allocations := make([]lnwire.MilliSatoshi, len(selected))
	remainingAmt := amt
	remainingCap := totalCap
	for i := range selected {
		if i == len(selected)-1 {
			allocations[i] = remainingAmt
			break
		}

		allocation := lnwire.MilliSatoshi(
			float64(remainingAmt) * float64(caps[i]) /
				float64(remainingCap),
		)
		if allocation <= 0 {
			allocation = 1
		}
		if allocation > caps[i] {
			allocation = caps[i]
		}

		allocations[i] = allocation
		remainingAmt -= allocation
		remainingCap -= caps[i]
	}

	originalReserved := r.reserved
	virtualReserved := make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	for key, value := range originalReserved {
		virtualReserved[key] = value
	}
	r.reserved = virtualReserved

	var plan []candidatePlannedShard
	var plannedTotal lnwire.MilliSatoshi

	for i, option := range selected {
		allocation := allocations[i]
		if allocation <= 0 {
			continue
		}

		_, rt, ok := r.pathLogProbability(
			option.path, allocation,
		)
		if !ok {
			r.reserved = originalReserved
			return nil
		}

		plan = append(plan, candidatePlannedShard{
			path:   option.path,
			amount: allocation,
		})
		plannedTotal += allocation

		for channelIndex := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, channelIndex)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, channelIndex)
			if ok {
				r.reserved[key] += amount
			}
		}
	}

	r.reserved = originalReserved
	if plannedTotal != amt {
		return nil
	}
	return plan
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	for len(r.plan) > 0 {
		shard := r.plan[0]
		r.plan = r.plan[1:]

		if shard.amount <= 0 || shard.amount > amt {
			r.plan = nil
			break
		}

		_, rt, ok := r.pathLogProbability(
			shard.path, shard.amount,
		)
		if !ok {
			r.plan = nil
			break
		}

		r.attempts++
		return rt, nil
	}

	if partsLeft > 1 {
		r.plan = r.makePlan(amt, partsLeft)
		if len(r.plan) > 0 {
			shard := r.plan[0]
			r.plan = r.plan[1:]

			_, rt, ok := r.pathLogProbability(
				shard.path, shard.amount,
			)
			if ok {
				r.attempts++
				return rt, nil
			}
			r.plan = nil
		}
	}

	if partsLeft == 1 {
		rt, _, _, err := r.findRoute(amt)
		if err != nil {
			return nil, err
		}
		r.attempts++
		return rt, nil
	}

	base := (amt + lnwire.MilliSatoshi(partsLeft) - 1) /
		lnwire.MilliSatoshi(partsLeft)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base, amt)
	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, amt,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/8, amt,
		)
	}
	candidateAddAmount(&sizes, seen, base*3/2, amt)
	candidateAddAmount(&sizes, seen, base*3/4, amt)
	candidateAddAmount(&sizes, seen, base/2, amt)
	candidateAddAmount(&sizes, seen, amt, amt)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range sizes {
		rt, _, logProb, err := r.findRoute(size)
		if err != nil {
			continue
		}

		fees := rt.TotalAmount - size
		sizeReward := math.Log(
			float64(size) / float64(base),
		)
		utility := logProb + 0.30*sizeReward -
			float64(fees)/6_000_000

		if bestRoute == nil || utility > bestUtility {
			bestRoute = rt
			bestUtility = utility
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no route found")
	}

	r.attempts++
	return bestRoute, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) penalizeRoute(rt *route.Route,
	amount float64) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgePenalty[key] += amount
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
			if r.edgePenalty[key] > 20_000 {
				r.edgePenalty[key] -= 20_000
			} else {
				r.edgePenalty[key] = 0
			}
		}
		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.plan = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		r.penalizeRoute(rt, 140_000)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.penalizeRoute(rt, 100_000)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.penalizeRoute(rt, 100_000)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.edgePenalty[key] += 160_000
		r.lastFailedShard =
			rt.Hops[len(rt.Hops)-1].AmtToForward

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.edgePenalty[key] += 500_000

	default:
		r.policyBlocked[key] = true
		r.edgePenalty[key] += 350_000
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	const million = lnwire.MilliSatoshi(1_000_000)

	proportional := (amt/million)*e.feeRatePPM +
		(amt%million)*e.feeRatePPM/million

	return e.baseFeeMsat + proportional
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 10
	if r.attemptLimit < 22 {
		r.attemptLimit = 22
	}
	if r.attemptLimit > 56 {
		r.attemptLimit = 56
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)

	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	total := amt + reserved

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		retryScale = 0.95 - 0.65*ratio
		if retryScale < 0.22 {
			retryScale = 0.22
		}

		if failure.count > 2 {
			retryScale *= 0.75
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*position
		p = 0.18*p + 0.82*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.90*(ratio-0.45)/0.55
			if scale < 0.08 {
				scale = 0.08
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.48 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateProb := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.68*p + 0.32*estimateProb
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 650_000.0
		hopPenalty = 300.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)

		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOverEdge := item.required
			p := r.probability(edge, amountOverEdge)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			sending := amountOverEdge + fee
			if sending < amountOverEdge {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 12_000
			edgeScore += float64(r.suspect[edge.key]) * 180_000

			if reserved := r.reserved[edge.key]; reserved > 0 {
				ratio := float64(reserved) /
					float64(edge.capacity)
				edgeScore += 240_000 + 220_000*ratio
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		fee := forwardingEdge.fee(amounts[i+1])
		amounts[i] = amounts[i+1] + fee
		if amounts[i] < amounts[i+1] {
			return nil, errors.New("route amount overflow")
		}

		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
		if expiries[i] < expiries[i+1] {
			return nil, errors.New("route timelock overflow")
		}
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amount := range src {
		dst[key] = amount
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amount
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAmountsFromWeights(total lnwire.MilliSatoshi,
	weights []uint64) ([]lnwire.MilliSatoshi, bool) {

	if total <= 0 || len(weights) == 0 ||
		total < lnwire.MilliSatoshi(len(weights)) {

		return nil, false
	}

	var weightLeft uint64
	for _, weight := range weights {
		if weight == 0 {
			return nil, false
		}
		weightLeft += weight
	}

	remaining := total
	amounts := make([]lnwire.MilliSatoshi, len(weights))

	for i, weight := range weights {
		if i == len(weights)-1 {
			amounts[i] = remaining
			break
		}

		slotsAfter := len(weights) - i - 1
		base := remaining / lnwire.MilliSatoshi(weightLeft)
		remainder := remaining % lnwire.MilliSatoshi(weightLeft)

		amount := base*lnwire.MilliSatoshi(weight) +
			remainder*lnwire.MilliSatoshi(weight)/
				lnwire.MilliSatoshi(weightLeft)

		maxAmount := remaining -
			lnwire.MilliSatoshi(slotsAfter)
		if amount < 1 {
			amount = 1
		}
		if amount > maxAmount {
			amount = maxAmount
		}

		amounts[i] = amount
		remaining -= amount
		weightLeft -= weight
	}

	return amounts, true
}

func candidateAmountsHash(amounts []lnwire.MilliSatoshi) uint64 {
	h := uint64(1469598103934665603)
	for i, amount := range amounts {
		h ^= candidateMix64(uint64(amount) + uint64(i+1))
		h *= 1099511628211
	}
	return h
}

func (r *candidateRouter) evaluatePlan(plan []*route.Route) float64 {
	saved := candidateCopyReservations(r.reserved)
	edgeProb := make(map[candidateEdgeKey]float64)
	edgeMultiplicity := make(map[candidateEdgeKey]uint32)

	fees := lnwire.MilliSatoshi(0)

	for _, rt := range plan {
		finalAmount := candidateFinalAmount(rt)
		if finalAmount <= 0 || rt.TotalAmount < finalAmount {
			r.reserved = saved
			return math.Inf(-1)
		}
		fees += rt.TotalAmount - finalAmount

		for i := range rt.Hops {
			key, keyOK := candidateRouteEdgeKey(rt, i)
			amount, amountOK := candidateRouteAmount(rt, i)
			if !keyOK || !amountOK {
				r.reserved = saved
				return math.Inf(-1)
			}

			var edge *candidateEdge
			for _, candidate := range r.incomingEdges[key.to] {
				if candidate.key == key {
					edge = candidate
					break
				}
			}
			if edge == nil {
				r.reserved = saved
				return math.Inf(-1)
			}

			p := r.probability(edge, amount)
			if p <= 0 {
				r.reserved = saved
				return math.Inf(-1)
			}

			edgeProb[key] = p
			edgeMultiplicity[key]++
		}

		r.reserveRoute(rt)
	}

	score := -float64(fees) / 5_000_000
	score -= 0.018 * float64(len(plan))

	for key, p := range edgeProb {
		score += math.Log(p)

		if edgeMultiplicity[key] > 1 {
			score -= 0.10 *
				float64(edgeMultiplicity[key]-1)
		}
	}

	r.reserved = saved
	return score
}

func (r *candidateRouter) planAmounts(
	amounts []lnwire.MilliSatoshi) ([]*route.Route, float64, bool) {

	saved := candidateCopyReservations(r.reserved)
	plan := make([]*route.Route, 0, len(amounts))

	for _, amount := range amounts {
		rt, _, err := r.findRoute(amount)
		if err != nil {
			r.reserved = saved
			return nil, 0, false
		}

		plan = append(plan, rt)
		r.reserveRoute(rt)
	}

	r.reserved = saved
	score := r.evaluatePlan(plan)
	if math.IsInf(score, -1) {
		return nil, 0, false
	}

	return plan, score, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32, inFlight uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	full, fullLogProb, fullErr := r.findRoute(total)
	if fullErr == nil && inFlight == 0 &&
		r.lastFailedShard == 0 &&
		fullLogProb >= math.Log(0.42) {

		return []*route.Route{full}, nil
	}

	partLimit := int(parts)
	if partLimit > 16 {
		partLimit = 16
	}
	if total < lnwire.MilliSatoshi(partLimit) {
		partLimit = int(total)
	}
	if partLimit < 1 {
		return nil, errors.New("invalid part limit")
	}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)
	seen := make(map[uint64]bool)

	consider := func(amounts []lnwire.MilliSatoshi) {
		if len(amounts) == 0 {
			return
		}

		hash := candidateAmountsHash(amounts)
		if seen[hash] {
			return
		}
		seen[hash] = true

		plan, score, ok := r.planAmounts(amounts)
		if !ok {
			return
		}

		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if fullErr == nil {
		consider([]lnwire.MilliSatoshi{total})
	}

	for count := 2; count <= partLimit; count++ {
		equal := make([]uint64, count)
		ascending := make([]uint64, count)
		descending := make([]uint64, count)
		frontHeavy := make([]uint64, count)
		backHeavy := make([]uint64, count)

		for i := 0; i < count; i++ {
			equal[i] = 1
			ascending[i] = uint64(i + 1)
			descending[i] = uint64(count - i)
			frontHeavy[i] = 1
			backHeavy[i] = 1
		}
		frontHeavy[0] = uint64(count + 2)
		backHeavy[count-1] = uint64(count + 2)

		templates := [][]uint64{
			equal,
			descending,
			ascending,
			frontHeavy,
			backHeavy,
		}

		for _, weights := range templates {
			amounts, ok := candidateAmountsFromWeights(
				total, weights,
			)
			if ok {
				consider(amounts)
			}
		}

		if r.lastFailedShard > 1 {
			first := r.lastFailedShard * 5 / 8
			if first >= total {
				first = total * 5 / 8
			}

			if first > 0 && first < total &&
				total-first >=
					lnwire.MilliSatoshi(count-1) {

				restWeights := make([]uint64, count-1)
				for i := range restWeights {
					restWeights[i] = 1
				}

				rest, ok := candidateAmountsFromWeights(
					total-first, restWeights,
				)
				if ok {
					amounts := make(
						[]lnwire.MilliSatoshi, 0, count,
					)
					amounts = append(amounts, first)
					amounts = append(amounts, rest...)
					consider(amounts)

					reversed := append(
						[]lnwire.MilliSatoshi(nil),
						rest...,
					)
					reversed = append(reversed, first)
					consider(reversed)
				}
			}
		}
	}

	if bestPlan == nil {
		if fullErr != nil {
			return nil, fullErr
		}
		return []*route.Route{full}, nil
	}

	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)

		if finalAmount > 0 && finalAmount <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}

		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft, inFlightHtlcs)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, keyOK := candidateRouteEdgeKey(rt, i)
			amount, amountOK := candidateRouteAmount(rt, i)
			if !keyOK || !amountOK {
				continue
			}

			r.learnSuccess(key, amount+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, keyOK := candidateRouteEdgeKey(rt, i)
		amount, amountOK := candidateRouteAmount(rt, i)
		if !keyOK || !amountOK {
			continue
		}

		r.learnSuccess(key, amount+r.reserved[key])
	}

	if failIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, keyOK := candidateRouteEdgeKey(rt, failIndex)
	amountOver, amountOK := candidateRouteAmount(rt, failIndex)
	if !keyOK || !amountOK {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amountOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3
		r.lastFailedShard = candidateFinalAmount(rt)

	default:
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	allEdges      []*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 6
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 40 {
		r.attemptLimit = 40
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.allEdges = append(r.allEdges, edge)
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	total := amt + reserved

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	belief, haveBelief := r.beliefs[edge.key]
	retryScale := 1.0

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		retryCeiling := failure.upper * 5 / 8
		if haveBelief && belief.lowerOK > retryCeiling {
			retryCeiling = belief.lowerOK
		}
		if retryCeiling == 0 {
			retryCeiling = 1
		}
		if total > retryCeiling {
			return 0
		}

		if !haveBelief || total > belief.lowerOK {
			retryScale = 0.48 /
				(1 + 0.12*float64(failure.count))
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	if !haveBelief {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		p = 0.995
	} else if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*pos
		p = 0.18*p + 0.82*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.5 {
			scale := 1 - 0.94*(ratio-0.5)/0.5
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.48 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.1 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateSearchLabel struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64

	edge  *candidateEdge
	child *candidateSearchLabel

	active bool
	idx    int
}

type candidateSearchQueue []*candidateSearchLabel

func (q candidateSearchQueue) Len() int {
	return len(q)
}

func (q candidateSearchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateSearchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateSearchQueue) Push(x any) {
	item := x.(*candidateSearchLabel)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateSearchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidateLabelContains(label *candidateSearchLabel,
	node route.Vertex) bool {

	for current := label; current != nil; current = current.child {
		if current.node == node {
			return true
		}
	}
	return false
}

func candidateInsertLabel(
	labels map[route.Vertex][]*candidateSearchLabel,
	label *candidateSearchLabel) bool {

	current := labels[label.node]
	active := current[:0]

	for _, old := range current {
		if !old.active {
			continue
		}

		if old.score <= label.score &&
			old.required <= label.required {

			labels[label.node] = append(active, old)
			return false
		}

		if label.score <= old.score &&
			label.required <= old.required {

			old.active = false
			continue
		}

		active = append(active, old)
	}

	label.active = true
	active = append(active, label)

	const maxLabels = 12
	if len(active) > maxLabels {
		worst := 0
		worstValue := math.Inf(-1)

		for i, item := range active {
			value := item.score +
				float64(item.required)*0.00001
			if value > worstValue {
				worst = i
				worstValue = value
			}
		}

		removed := active[worst]
		removed.active = false
		active = append(active[:worst], active[worst+1:]...)

		if removed == label {
			labels[label.node] = active
			return false
		}
	}

	labels[label.node] = active
	return true
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 420_000.0
		hopPenalty = 220.0
	)

	target := &candidateSearchLabel{
		node:     r.spec.Target,
		required: amt,
		active:   true,
	}

	labels := map[route.Vertex][]*candidateSearchLabel{
		r.spec.Target: {target},
	}
	pq := &candidateSearchQueue{}
	heap.Push(pq, target)

	var sourceLabel *candidateSearchLabel

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateSearchLabel)
		if !item.active {
			continue
		}

		if item.node == r.source {
			sourceLabel = item
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if candidateLabelContains(item, edge.key.from) {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.edgeUses[edge.key]) * 24_000
			edgeScore += float64(r.suspect[edge.key]) * 270_000

			if r.reserved[edge.key] > 0 {
				if edge.key.from == r.source {
					edgeScore += 35_000
				} else {
					edgeScore += 340_000
				}
			}

			label := &candidateSearchLabel{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				edge:     edge,
				child:    item,
			}

			if candidateInsertLabel(labels, label) {
				heap.Push(pq, label)
			}
		}
	}

	if sourceLabel == nil {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	for item := sourceLabel; item.node != r.spec.Target; {
		if item.edge == nil || item.child == nil {
			return nil, 0, errors.New("broken route label")
		}
		path = append(path, item.edge)
		item = item.child
	}

	rt, err := r.buildRoute(amt, path)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLabel.logProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	node := r.source
	for _, edge := range path {
		if edge.key.from != node {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, errors.New("path does not reach target")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveRoute(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveRoute(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

type candidateAmountLandmark struct {
	amount   lnwire.MilliSatoshi
	distance float64
}

func (r *candidateRouter) planningSizes(
	remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, remaining, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base/2, remaining)
	candidateAddAmount(&sizes, seen, base*2/3, remaining)
	candidateAddAmount(&sizes, seen, base*3/4, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
	}

	landmarkSeen := make(map[lnwire.MilliSatoshi]bool)
	var landmarks []candidateAmountLandmark

	addLandmark := func(value lnwire.MilliSatoshi) {
		if value <= 0 || value > remaining || landmarkSeen[value] {
			return
		}
		landmarkSeen[value] = true

		distance := math.Abs(math.Log(
			float64(value) / float64(base),
		))
		landmarks = append(landmarks, candidateAmountLandmark{
			amount:   value,
			distance: distance,
		})
	}

	for _, edge := range r.allEdges {
		belief := r.beliefs[edge.key]

		if belief.lowerOK > 0 {
			addLandmark(belief.lowerOK * 19 / 20)
		}
		if belief.estimate > 0 {
			addLandmark(belief.estimate * 17 / 20)
		}
		if belief.upperFail > 0 {
			addLandmark(belief.upperFail * 9 / 16)
		}
		if failure := r.currentFails[edge.key]; failure.upper > 0 {
			addLandmark(failure.upper * 9 / 16)
		}

		addLandmark(edge.capacity * 7 / 16)
		addLandmark(edge.capacity * 3 / 4)
	}

	for _, balance := range r.localBalances {
		addLandmark(balance * 9 / 10)
	}

	sort.Slice(landmarks, func(i, j int) bool {
		if landmarks[i].distance == landmarks[j].distance {
			return landmarks[i].amount > landmarks[j].amount
		}
		return landmarks[i].distance < landmarks[j].distance
	})

	const maxLandmarks = 7
	for i, landmark := range landmarks {
		if i >= maxLandmarks {
			break
		}
		candidateAddAmount(
			&sizes, seen, landmark.amount, remaining,
		)
	}

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] > sizes[j]
	})
	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	sent         lnwire.MilliSatoshi
}

func candidatePlanOverlap(rt *route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	penalty := 0.0
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok || reservations[key] == 0 {
			continue
		}
		if key.from == rt.SourcePubKey {
			penalty += 0.025
		} else {
			penalty += 0.24
		}
	}
	return penalty
}

func candidatePlanRank(state candidatePlanState,
	total lnwire.MilliSatoshi) float64 {

	progress := float64(state.sent) / float64(total)
	slotPressure := 0.0
	if state.slots > 0 {
		needed := float64(state.remaining) /
			float64(state.slots) / float64(total)
		slotPressure = 0.2 * needed
	}

	return state.score + 1.55*progress - slotPressure
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if total <= 0 {
		return nil, errors.New("invalid plan amount")
	}
	if parts == 0 {
		parts = 1
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	frontier := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	const beamWidth = 8

	for depth := uint32(0); depth < parts && len(frontier) > 0; depth++ {
		var next []candidatePlanState

		for _, state := range frontier {
			if state.remaining <= 0 || state.slots == 0 {
				continue
			}

			r.reserved = state.reservations
			sizes := r.planningSizes(
				state.remaining, state.slots,
			)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = state.reservations
				rt, logProb, err := r.findRoute(size)
				if err != nil {
					continue
				}

				fees := rt.TotalAmount - size
				overlap := candidatePlanOverlap(
					rt, state.reservations,
				)

				newScore := state.score + logProb -
					float64(fees)/4_000_000 -
					overlap - 0.035

				newRoutes := make(
					[]*route.Route, len(state.routes), len(state.routes)+1,
				)
				copy(newRoutes, state.routes)
				newRoutes = append(newRoutes, rt)

				newReservations := candidateCopyReservations(
					state.reservations,
				)
				candidateReserveRoute(newReservations, rt)

				remaining := state.remaining - size
				if remaining == 0 {
					if bestPlan == nil || newScore > bestScore {
						bestPlan = newRoutes
						bestScore = newScore
					}
					continue
				}

				if state.slots <= 1 {
					continue
				}

				next = append(next, candidatePlanState{
					remaining:    remaining,
					slots:        state.slots - 1,
					routes:       newRoutes,
					reservations: newReservations,
					score:        newScore,
					sent:         state.sent + size,
				})
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return candidatePlanRank(next[i], total) >
				candidatePlanRank(next[j], total)
		})
		if len(next) > beamWidth {
			next = next[:beamWidth]
		}
		frontier = next
	}

	if bestPlan == nil {
		return nil, errors.New("no complete route set found")
	}
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)

		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	if belief.estimate == 0 {
		belief.estimate = amt
	} else if amt > belief.estimate {
		belief.estimate = (
			belief.estimate + 2*amt
		) / 3
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		belief.estimate = belief.lowerOK +
			(belief.upperFail-belief.lowerOK)*2/5
	} else {
		estimate := amt * 9 / 16
		if belief.estimate == 0 || belief.estimate >= amt {
			belief.estimate = estimate
		} else {
			belief.estimate = (
				2*belief.estimate + estimate
			) / 3
		}
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 12
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 40 {
		r.attemptLimit = 40
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.034))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateClampProbability(p float64) float64 {
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) absoluteProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 && total >= failure.upper {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if ok {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.995

		case belief.upperFail > 0 && total >= belief.upperFail:
			p = 0.004

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK:

			width := float64(
				belief.upperFail - belief.lowerOK,
			)
			pos := float64(total-belief.lowerOK) / width
			if pos < 0 {
				pos = 0
			}
			if pos > 1 {
				pos = 1
			}

			evidence := 0.992 - 0.984*pos
			p = 0.1*p + 0.9*evidence

		case belief.upperFail > 0:
			ratio := float64(total) /
				float64(belief.upperFail)
			if ratio > 0.35 {
				scale := 1 - 0.95*(ratio-0.35)/0.65
				if scale < 0.05 {
					scale = 0.05
				}
				p *= scale
			}

		case belief.lowerOK > 0 && total > belief.lowerOK:
			distance := float64(total-belief.lowerOK) /
				float64(edge.capacity)
			boost := 0.6 * math.Exp(-distance/0.14)
			p += boost * (1 - p)
		}

		if belief.estimate > 0 {
			scale := 0.075 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			q := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate)) /
					scale,
			))
			p = 0.72*p + 0.28*q
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.8:
			p *= 0.18
		case ratio > 0.6:
			p *= 0.48
		case ratio > 0.4:
			p *= 0.76
		}
	}

	return candidateClampProbability(p)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	total := reserved + amt
	pTotal := r.absoluteProbability(edge, total)
	if pTotal <= 0 {
		return 0
	}
	if reserved == 0 {
		return pTotal
	}

	pReserved := r.absoluteProbability(edge, reserved)
	if pReserved <= 0 {
		return pTotal
	}

	conditional := pTotal / pReserved
	if conditional > 0.999 {
		conditional = 0.999
	}
	if conditional < 0.002 {
		conditional = 0.002
	}
	return conditional
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 900_000.0
		hopPenalty = 1_000.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee
			if sending < amtOver {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 28_000
			edgeScore += float64(r.suspect[edge.key]) * 420_000

			if reserved := r.reserved[edge.key]; reserved > 0 {
				ratio := float64(reserved) /
					float64(edge.capacity)
				edgeScore += 260_000 + 620_000*ratio
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, index int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return 0, false
	}
	if index == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[index-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	index int) (candidateEdgeKey, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	return candidateEdgeKey{
		chanID: rt.Hops[index].ChannelID,
		from:   from,
		to:     rt.Hops[index].PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	copyMap := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amt := range source {
		copyMap[key] = amt
	}
	return copyMap
}

func candidateReserveRoute(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations() {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	for _, rt := range r.held {
		candidateReserveRoute(r.reserved, rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		return
	}
	if value > max {
		value = max
	}
	if value > 0 && !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) shardCandidates(
	remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	values := make([]lnwire.MilliSatoshi, 0, 32)
	seen := make(map[lnwire.MilliSatoshi]bool)

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddAmount(&values, seen, base/2, remaining)
	candidateAddAmount(&values, seen, base*2/3, remaining)
	candidateAddAmount(&values, seen, base*4/5, remaining)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(&values, seen, base*5/4, remaining)
	candidateAddAmount(&values, seen, base*3/2, remaining)
	candidateAddAmount(&values, seen, base*2, remaining)
	candidateAddAmount(&values, seen, remaining/3, remaining)
	candidateAddAmount(&values, seen, remaining/2, remaining)
	candidateAddAmount(&values, seen, remaining*2/3, remaining)
	candidateAddAmount(&values, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard/3, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*2/5, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*3/5, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*3/4, remaining,
		)
	}

	for key, failure := range r.currentFails {
		if failure.upper <= r.reserved[key] {
			continue
		}
		room := failure.upper - r.reserved[key]
		candidateAddAmount(&values, seen, room/3, remaining)
		candidateAddAmount(&values, seen, room*2/5, remaining)
		candidateAddAmount(&values, seen, room/2, remaining)
		candidateAddAmount(&values, seen, room*3/5, remaining)
		candidateAddAmount(&values, seen, room*3/4, remaining)
	}

	for key, belief := range r.beliefs {
		reserved := r.reserved[key]

		if belief.lowerOK > reserved {
			room := belief.lowerOK - reserved
			candidateAddAmount(&values, seen, room, remaining)
			candidateAddAmount(
				&values, seen, room*4/5, remaining,
			)
		}
		if belief.estimate > reserved {
			room := belief.estimate - reserved
			candidateAddAmount(
				&values, seen, room*3/4, remaining,
			)
		}
		if belief.upperFail > reserved {
			room := belief.upperFail - reserved
			candidateAddAmount(
				&values, seen, room*2/5, remaining,
			)
			candidateAddAmount(
				&values, seen, room*3/5, remaining,
			)
		}
	}

	for _, edge := range r.incomingEdges[r.spec.Target] {
		limit := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}

		reserved := r.reserved[edge.key]
		if reserved >= edge.capacity {
			continue
		}
		capacityRoom := edge.capacity - reserved
		if limit > capacityRoom {
			limit = capacityRoom
		}

		candidateAddAmount(&values, seen, limit/3, remaining)
		candidateAddAmount(&values, seen, limit/2, remaining)
		candidateAddAmount(&values, seen, limit*7/10, remaining)
		candidateAddAmount(&values, seen, limit*7/8, remaining)
	}

	if len(values) <= 24 {
		return values
	}

	sort.Slice(values, func(i, j int) bool {
		pi := math.Abs(math.Log(
			float64(values[i]) / float64(base),
		))
		pj := math.Abs(math.Log(
			float64(values[j]) / float64(base),
		))
		if values[i] == remaining {
			pi -= 2
		}
		if values[j] == remaining {
			pj -= 2
		}
		return pi < pj
	})

	return values[:24]
}

func candidatePlanContribution(rt *route.Route,
	finalAmt lnwire.MilliSatoshi, logProb float64) float64 {

	fees := rt.TotalAmount - finalAmt
	return logProb - float64(fees)/3_500_000 - 0.025
}

type candidatePlanState struct {
	routes    []*route.Route
	remaining lnwire.MilliSatoshi
	reserved  map[candidateEdgeKey]lnwire.MilliSatoshi
	score     float64
	rank      float64
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no part slots available")
	}

	originalReservations := r.reserved
	defer func() {
		r.reserved = originalReservations
	}()

	initialReservations := candidateCopyReservations(r.reserved)
	beam := []candidatePlanState{{
		remaining: total,
		reserved:  initialReservations,
	}}

	var completed []candidatePlanState
	const beamWidth = 10

	for depth := uint32(0); depth < parts && len(beam) > 0; depth++ {
		slots := parts - depth
		nextBeam := make([]candidatePlanState, 0, beamWidth*8)

		for _, state := range beam {
			if state.remaining == 0 {
				completed = append(completed, state)
				continue
			}

			r.reserved = state.reserved

			var sizes []lnwire.MilliSatoshi
			if slots == 1 {
				sizes = []lnwire.MilliSatoshi{state.remaining}
			} else {
				sizes = r.shardCandidates(
					state.remaining, slots,
				)
			}

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = state.reserved
				rt, logProb, err := r.findRoute(size)
				if err != nil {
					continue
				}

				newReservations := candidateCopyReservations(
					state.reserved,
				)
				candidateReserveRoute(newReservations, rt)

				routes := make(
					[]*route.Route, len(state.routes)+1,
				)
				copy(routes, state.routes)
				routes[len(state.routes)] = rt

				remaining := state.remaining - size
				score := state.score + candidatePlanContribution(
					rt, size, logProb,
				)
				delivered := total - remaining
				rank := score + 2.0*
					float64(delivered)/float64(total)

				newState := candidatePlanState{
					routes:    routes,
					remaining: remaining,
					reserved:  newReservations,
					score:     score,
					rank:      rank,
				}

				if remaining == 0 {
					completed = append(completed, newState)
				} else if slots > 1 {
					nextBeam = append(nextBeam, newState)
				}
			}
		}

		sort.Slice(nextBeam, func(i, j int) bool {
			return nextBeam[i].rank > nextBeam[j].rank
		})
		if len(nextBeam) > beamWidth {
			nextBeam = nextBeam[:beamWidth]
		}
		beam = nextBeam
	}

	if len(completed) == 0 {
		return nil, errors.New("no payment plan found")
	}

	sort.Slice(completed, func(i, j int) bool {
		return completed[i].score > completed[j].score
	})
	return completed[0].routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations()

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil &&
		amt > edge.capacity/16 {

		highEstimate := edge.capacity * 9 / 10
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt / 3
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else if estimate < belief.estimate {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	passed := failIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIndex >= len(rt.Hops) {
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.suspect[key] += 2
		r.markRouteSuspect(rt, 1)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 10
	if r.attemptLimit < 22 {
		r.attemptLimit = 22
	}
	if r.attemptLimit > 60 {
		r.attemptLimit = 60
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probabilityTotal(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity ||
		r.policyBlocked[edge.key] {

		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		retryCeiling := failure.upper * 3 / 5
		if failure.count > 1 {
			retryCeiling = failure.upper * 11 / 20
		}
		if retryCeiling == 0 {
			retryCeiling = 1
		}
		if total > retryCeiling {
			return 0
		}

		retryScale = 0.28
		if failure.count > 1 {
			retryScale = 0.18
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.008)
		return math.Max(0.002, p*retryScale)
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		evidence := 0.99 - 0.98*position
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.94*(ratio-0.45)/0.55
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.5 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.1 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateP := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*estimateP
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	return r.probabilityTotal(edge, amt+r.reserved[edge.key])
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 380_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 12_000
			edgeScore += float64(r.suspect[edge.key]) * 210_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 190_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveInto(
	dst map[candidateEdgeKey]lnwire.MilliSatoshi, rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			dst[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidateTrimAmounts(values []lnwire.MilliSatoshi,
	base, remaining lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	sort.Slice(values, func(i, j int) bool {
		return values[i] < values[j]
	})
	if len(values) <= 20 {
		return values
	}

	var result []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&result, seen, values[0], remaining)
	candidateAddAmount(&result, seen, base, remaining)
	candidateAddAmount(&result, seen, remaining, remaining)

	for i := 0; i < 17; i++ {
		index := i * (len(values) - 1) / 16
		candidateAddAmount(
			&result, seen, values[index], remaining,
		)
	}

	sort.Slice(result, func(i, j int) bool {
		return result[i] < result[j]
	})
	return result
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots uint32,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&values, seen, base/3, remaining)
	candidateAddAmount(&values, seen, base/2, remaining)
	candidateAddAmount(&values, seen, base*2/3, remaining)
	candidateAddAmount(&values, seen, base*4/5, remaining)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(&values, seen, base*5/4, remaining)
	candidateAddAmount(&values, seen, base*3/2, remaining)
	candidateAddAmount(&values, seen, base*2, remaining)
	candidateAddAmount(&values, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard*9/20, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*3/5, remaining,
		)
	}

	for _, edge := range r.incomingEdges[r.spec.Target] {
		used := reservations[edge.key]
		if edge.capacity > used {
			available := edge.capacity - used
			candidateAddAmount(
				&values, seen, available*9/20, remaining,
			)
			candidateAddAmount(
				&values, seen, available*17/20, remaining,
			)
		}

		belief := r.beliefs[edge.key]
		if belief.lowerOK > used {
			candidateAddAmount(
				&values, seen, belief.lowerOK-used, remaining,
			)
		}
		if belief.upperFail > used {
			available := belief.upperFail - used
			candidateAddAmount(
				&values, seen, available*11/20, remaining,
			)
		}

		if failure, ok := r.currentFails[edge.key]; ok &&
			failure.upper > used {

			available := failure.upper - used
			candidateAddAmount(
				&values, seen, available*11/20, remaining,
			)
		}
	}

	return candidateTrimAmounts(values, base, remaining)
}

type candidatePlanState struct {
	routes      []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	remaining   lnwire.MilliSatoshi
	score       float64
	rank        float64
}

func (r *candidateRouter) jointPlanScore(routes []*route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	touched := make(map[candidateEdgeKey]bool)
	fees := lnwire.MilliSatoshi(0)

	for _, rt := range routes {
		finalAmt := candidateFinalAmount(rt)
		fees += rt.TotalAmount - finalAmt

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				touched[key] = true
			}
		}
	}

	score := -float64(fees) / 4_000_000
	score -= 0.018 * float64(len(routes))

	for key := range touched {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.probabilityTotal(edge, reservations[key])
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	return score
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}
	if parts == 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []*candidatePlanState{{
		reservations: candidateCopyReservations(savedReservations),
		remaining:    total,
	}}
	var completed []*candidatePlanState

	const beamWidth = 18

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		var nextStates []*candidatePlanState

		for _, state := range states {
			sizes := r.shardSizes(
				state.remaining, slots, state.reservations,
			)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = state.reservations
				rt, _, err := r.findRoute(size)
				if err != nil {
					continue
				}

				newReservations := candidateCopyReservations(
					state.reservations,
				)
				candidateReserveInto(newReservations, rt)

				newRoutes := make([]*route.Route, len(state.routes)+1)
				copy(newRoutes, state.routes)
				newRoutes[len(state.routes)] = rt

				remaining := state.remaining - size
				score := r.jointPlanScore(
					newRoutes, newReservations,
				)
				if math.IsInf(score, -1) {
					continue
				}

				progress := float64(total-remaining) / float64(total)
				newState := &candidatePlanState{
					routes:       newRoutes,
					reservations: newReservations,
					remaining:    remaining,
					score:        score,
					rank:         score + 2.4*progress,
				}

				if remaining == 0 {
					completed = append(completed, newState)
				} else if slots > 1 {
					nextStates = append(nextStates, newState)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			if nextStates[i].rank == nextStates[j].rank {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if len(completed) == 0 {
		return nil, errors.New("no route-set plan found")
	}

	sort.Slice(completed, func(i, j int) bool {
		if completed[i].score == completed[j].score {
			return len(completed[i].routes) <
				len(completed[j].routes)
		}
		return completed[i].score > completed[j].score
	})

	return completed[0].routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if edge := r.edges[key]; edge != nil {
		lowEstimate := edge.capacity * 9 / 100
		if amt > edge.capacity/4 && lowEstimate < estimate {
			estimate = lowEstimate
		}
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}

		r.suspect[key] += weight
		if i == len(rt.Hops)-1 {
			r.suspect[key]++
		}
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.suspect[key] += 2
		r.markRouteSuspect(rt, 1)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	attempts     int
	attemptLimit int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateRetryFactor(count uint32) float64 {
	switch count {
	case 0:
		return 1
	case 1:
		return 0.38
	case 2:
		return 0.22
	default:
		return 0.12
	}
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var percent int64
	switch {
	case f.count <= 1:
		percent = 48
	case f.count == 2:
		percent = 30
	default:
		percent = 18
	}

	ceiling := f.upper * lnwire.MilliSatoshi(percent) / 100
	if ceiling <= 0 {
		ceiling = 1
	}
	return ceiling, true
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity ||
		r.policyBlocked[edge.key] {

		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if total >= failure.upper {
			return 0
		}
		if ceiling, ok := candidateRetryCeiling(failure); ok &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryFactor(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.004)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.994 - 0.990*pos
		p = 0.10*p + 0.90*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.25 {
			scale := 1 - 0.97*(ratio-0.25)/0.75
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.70 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.08 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.74*p + 0.26*q
	}

	p *= retryScale
	if p < 0.0005 {
		return 0.0005
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}
	return r.liquidityProbability(edge, amt+r.reserved[edge.key])
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	banned map[candidateEdgeKey]bool) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 600_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned != nil && banned[edge.key] {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.edgeUses[edge.key]) * 9_000
			edgeScore += float64(r.suspect[edge.key]) * 210_000
			if r.reserved[edge.key] > 0 {
				edgeScore += 260_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))
	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, index int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return 0, false
	}
	if index == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[index-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route, index int) (
	candidateEdgeKey, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}
	hop := rt.Hops[index]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateScaledAmount(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidatePlanSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)
	for _, ratio := range [][2]int64{
		{9, 20}, {7, 10}, {1, 1}, {13, 10},
		{17, 10}, {23, 10},
	} {
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(base, ratio[0], ratio[1]),
			remaining,
		)
	}
	candidateAddAmount(&values, seen, remaining, remaining)
	return values
}

func candidateRouteHash(rt *route.Route) uint64 {
	h := uint64(0x9e3779b97f4a7c15)
	if rt == nil {
		return h
	}
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(key.chanID + uint64(i+1))
		h ^= candidateMix64(candidateVertexHash(key.from))
		h ^= candidateMix64(candidateVertexHash(key.to))
		h = candidateMix64(h)
	}
	return h
}

type candidateRouteOption struct {
	rt      *route.Route
	logProb float64
	quality float64
}

func (r *candidateRouter) findRouteOptions(
	amt lnwire.MilliSatoshi, limit int) []candidateRouteOption {

	base, logProb, err := r.findRoute(amt, nil)
	if err != nil {
		return nil
	}

	options := []candidateRouteOption{{
		rt:      base,
		logProb: logProb,
		quality: logProb -
			float64(base.TotalAmount-amt)/3_000_000,
	}}
	seen := map[uint64]bool{candidateRouteHash(base): true}

	for i := range base.Hops {
		key, ok := candidateRouteEdgeKey(base, i)
		if !ok {
			continue
		}
		banned := map[candidateEdgeKey]bool{key: true}
		rt, lp, err := r.findRoute(amt, banned)
		if err != nil {
			continue
		}
		hash := candidateRouteHash(rt)
		if seen[hash] {
			continue
		}
		seen[hash] = true
		options = append(options, candidateRouteOption{
			rt:      rt,
			logProb: lp,
			quality: lp -
				float64(rt.TotalAmount-amt)/3_000_000,
		})
	}

	sort.Slice(options, func(i, j int) bool {
		return options[i].quality > options[j].quality
	})
	if len(options) > limit {
		options = options[:limit]
	}
	return options
}

func (r *candidateRouter) routeLogProbability(
	rt *route.Route) (float64, bool) {

	var result float64
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0, false
		}
		edge := r.edges[key]
		if edge == nil {
			return 0, false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0, false
		}
		p := r.probability(edge, amt)
		if p <= 0 {
			return 0, false
		}
		result += math.Log(p)
	}
	return result, true
}

func (r *candidateRouter) rebuildRoute(amt lnwire.MilliSatoshi,
	template *route.Route) (*route.Route, error) {

	next := make(map[route.Vertex]*candidateEdge)
	for i := range template.Hops {
		key, ok := candidateRouteEdgeKey(template, i)
		if !ok {
			return nil, errors.New("invalid route template")
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, errors.New("route edge disappeared")
		}
		next[key.from] = edge
	}
	return r.buildRoute(amt, next)
}

func (r *candidateRouter) routeLimit(rt *route.Route) lnwire.MilliSatoshi {
	limit := lnwire.MilliSatoshi(math.MaxInt64)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}
		edge := r.edges[key]
		if edge == nil {
			return 0
		}

		reserved := r.reserved[key]
		available := edge.capacity - reserved
		if available < limit {
			limit = available
		}
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok {
				return 0
			}
			localAvailable := balance - reserved
			if localAvailable < limit {
				limit = localAvailable
			}
			continue
		}

		if failure, ok := r.currentFails[key]; ok {
			if ceiling, ok := candidateRetryCeiling(failure); ok {
				retryAvailable := ceiling - reserved
				if retryAvailable < limit {
					limit = retryAvailable
				}
			}
		}

		belief, ok := r.beliefs[key]
		if !ok {
			likely := candidateScaledAmount(
				edge.capacity, 90, 100,
			) - reserved
			if likely < limit {
				limit = likely
			}
			continue
		}

		var likelyTotal lnwire.MilliSatoshi
		switch {
		case belief.upperFail > belief.lowerOK &&
			belief.lowerOK > 0:

			likelyTotal = belief.lowerOK +
				candidateScaledAmount(
					belief.upperFail-belief.lowerOK,
					45, 100,
				)

		case belief.upperFail > 0:
			likelyTotal = candidateScaledAmount(
				belief.upperFail, 52, 100,
			)

		case belief.lowerOK > 0:
			likelyTotal = belief.lowerOK +
				candidateScaledAmount(
					edge.capacity-belief.lowerOK,
					80, 100,
				)

		default:
			likelyTotal = candidateScaledAmount(
				edge.capacity, 90, 100,
			)
		}

		if belief.lowerOK > likelyTotal {
			likelyTotal = belief.lowerOK
		}
		if belief.upperFail > 0 &&
			likelyTotal >= belief.upperFail {

			likelyTotal = belief.upperFail - 1
		}

		likely := likelyTotal - reserved
		if likely < limit {
			limit = likely
		}
	}

	if limit < 1 {
		return 0
	}
	return limit
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState
	const beamWidth = 24

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make([]candidatePlanState, 0, beamWidth*24)

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}

			sizes := candidatePlanSizes(state.remaining, slots)
			base := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			routeSeen := make(map[uint64]bool)

			addRoute := func(rt *route.Route, logProb float64) {
				if rt == nil {
					return
				}
				finalAmt := candidateFinalAmount(rt)
				if finalAmt <= 0 || finalAmt > state.remaining {
					return
				}

				hash := candidateRouteHash(rt) ^
					candidateMix64(uint64(finalAmt))
				if routeSeen[hash] {
					return
				}
				routeSeen[hash] = true

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				if checked, ok := r.routeLogProbability(rt); ok {
					logProb = checked
				} else {
					return
				}

				newReservations := candidateCopyReservations(
					state.reservations,
				)
				r.reserved = newReservations
				r.reserveRoute(rt)

				fees := rt.TotalAmount - finalAmt
				score := state.score + logProb -
					float64(fees)/4_000_000 - 0.024

				remaining := state.remaining - finalAmt
				progress := float64(total-remaining) /
					float64(total)
				rank := score + 3.25*progress

				routes := make(
					[]*route.Route, len(state.routes),
					len(state.routes)+1,
				)
				copy(routes, state.routes)
				routes = append(routes, rt)

				nextStates = append(nextStates, candidatePlanState{
					remaining:    remaining,
					routes:       routes,
					reservations: newReservations,
					score:        score,
					rank:         rank,
				})
			}

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				options := r.findRouteOptions(size, 4)
				for _, option := range options {
					addRoute(option.rt, option.logProb)

					r.reserved = candidateCopyReservations(
						state.reservations,
					)
					limit := r.routeLimit(option.rt)
					if limit <= 0 {
						continue
					}

					capAmt := candidateScaledAmount(
						limit, 9, 10,
					)
					if capAmt > state.remaining {
						capAmt = state.remaining
					}
					if capAmt < candidateScaledAmount(
						base, 7, 20,
					) {
						continue
					}
					if capAmt > size*95/100 &&
						capAmt < size*105/100 {

						continue
					}

					rt, err := r.rebuildRoute(
						capAmt, option.rt,
					)
					if err != nil {
						continue
					}
					lp, ok := r.routeLogProbability(rt)
					if ok {
						addRoute(rt, lp)
					}
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			if nextStates[i].remaining == 0 &&
				nextStates[j].remaining != 0 {

				return true
			}
			if nextStates[j].remaining == 0 &&
				nextStates[i].remaining != 0 {

				return false
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	for _, state := range states {
		if state.remaining != 0 {
			continue
		}
		if bestComplete == nil || state.score > bestComplete.score {
			copyState := state
			bestComplete = &copyState
		}
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no route set found")
	}
	return bestComplete.routes, nil
}

func (r *candidateRouter) orderPlan(routes []*route.Route) {
	type scoredRoute struct {
		rt      *route.Route
		logProb float64
		amount  lnwire.MilliSatoshi
	}

	scored := make([]scoredRoute, 0, len(routes))
	for _, rt := range routes {
		lp, ok := r.routeLogProbability(rt)
		if !ok {
			lp = math.Inf(-1)
		}
		scored = append(scored, scoredRoute{
			rt:      rt,
			logProb: lp,
			amount:  candidateFinalAmount(rt),
		})
	}

	sort.SliceStable(scored, func(i, j int) bool {
		if math.Abs(scored[i].logProb-scored[j].logProb) > 0.001 {
			return scored[i].logProb < scored[j].logProb
		}
		return scored[i].amount > scored[j].amount
	})

	for i := range scored {
		routes[i] = scored[i].rt
	}
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err != nil {
		rt, _, singleErr := r.findRoute(total, nil)
		if singleErr != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	r.orderPlan(plan)
	return plan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	edge := r.edges[key]
	if edge != nil && amt*20 >= edge.capacity {
		estimate = amt + candidateScaledAmount(
			edge.capacity-amt, 7, 10,
		)
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaledAmount(amt, 9, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.learnSuccess(key, amt+r.reserved[key])
			}
		}
		r.held = append(r.held, rt)
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key] += 2

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))

	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 8
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 32 {
		r.attemptLimit = 32
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		if r.edges[key] != nil {
			r.beliefs[key] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateClampProbability(p float64) float64 {
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) absoluteProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 && total >= failure.upper {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if ok {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.995

		case belief.upperFail > 0 && total >= belief.upperFail:
			p = 0.003

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK:

			width := float64(
				belief.upperFail - belief.lowerOK,
			)
			pos := float64(total-belief.lowerOK) / width
			if pos < 0 {
				pos = 0
			}
			if pos > 1 {
				pos = 1
			}

			evidence := 0.993 - 0.987*pos
			p = 0.1*p + 0.9*evidence

		case belief.upperFail > 0:
			ratio := float64(total) /
				float64(belief.upperFail)
			if ratio > 0.4 {
				scale := 1 - 0.96*(ratio-0.4)/0.6
				if scale < 0.04 {
					scale = 0.04
				}
				p *= scale
			}

		case belief.lowerOK > 0 && total > belief.lowerOK:
			distance := float64(total-belief.lowerOK) /
				float64(edge.capacity)
			boost := 0.58 * math.Exp(-distance/0.17)
			p += boost * (1 - p)
		}

		if belief.estimate > 0 {
			scale := 0.08 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			q := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate)) /
					scale,
			))
			p = 0.78*p + 0.22*q
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.8:
			p *= 0.22
		case ratio > 0.6:
			p *= 0.52
		case ratio > 0.4:
			p *= 0.78
		}
	}

	return candidateClampProbability(p)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved >= edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	total := reserved + amt
	pTotal := r.absoluteProbability(edge, total)
	if pTotal <= 0 {
		return 0
	}
	if reserved == 0 {
		return pTotal
	}

	pReserved := r.absoluteProbability(edge, reserved)
	if pReserved <= 0 {
		return pTotal
	}

	conditional := pTotal / pReserved
	if conditional > 0.999 {
		conditional = 0.999
	}
	if conditional < 0.002 {
		conditional = 0.002
	}

	return conditional
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	banned map[candidateEdgeKey]bool) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 650_000.0
		hopPenalty = 450.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned != nil && banned[edge.key] {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee
			if sending < amtOver {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 22_000
			edgeScore += float64(r.suspect[edge.key]) * 360_000

			if reserved := r.reserved[edge.key]; reserved > 0 {
				ratio := float64(reserved) /
					float64(edge.capacity)
				edgeScore += 260_000 + 600_000*ratio
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}

	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteID(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(uint64(candidateFinalAmount(rt)))
	for i, hop := range rt.Hops {
		h ^= candidateMix64(
			hop.ChannelID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
	}
	return candidateMix64(h)
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		return
	}
	if value > max {
		value = max
	}
	if value > 0 && !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) addEdgeLimits(
	values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, edge *candidateEdge,
	remaining lnwire.MilliSatoshi) {

	reserved := r.reserved[edge.key]
	if reserved >= edge.capacity {
		return
	}

	limit := edge.capacity - reserved
	if edge.maxHTLC > 0 && edge.maxHTLC < limit {
		limit = edge.maxHTLC
	}

	candidateAddAmount(values, seen, limit*3/10, remaining)
	candidateAddAmount(values, seen, limit/2, remaining)
	candidateAddAmount(values, seen, limit*7/10, remaining)
	candidateAddAmount(values, seen, limit*9/10, remaining)

	belief, ok := r.beliefs[edge.key]
	if ok {
		if belief.lowerOK > reserved {
			safe := belief.lowerOK - reserved
			candidateAddAmount(values, seen, safe, remaining)
			candidateAddAmount(values, seen, safe*9/10, remaining)
		}
		if belief.estimate > reserved {
			estimate := belief.estimate - reserved
			candidateAddAmount(
				values, seen, estimate*4/5, remaining,
			)
		}
		if belief.upperFail > reserved {
			ceiling := belief.upperFail - reserved
			candidateAddAmount(
				values, seen, ceiling*2/5, remaining,
			)
			candidateAddAmount(
				values, seen, ceiling*3/5, remaining,
			)
			candidateAddAmount(
				values, seen, ceiling*4/5, remaining,
			)
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > reserved {

		ceiling := failure.upper - reserved
		candidateAddAmount(values, seen, ceiling/3, remaining)
		candidateAddAmount(values, seen, ceiling/2, remaining)
		candidateAddAmount(
			values, seen, ceiling*2/3, remaining,
		)
		candidateAddAmount(
			values, seen, ceiling*4/5, remaining,
		)
	}
}

func (r *candidateRouter) shardCandidates(
	remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)
	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddAmount(&values, seen, base*3/5, remaining)
	candidateAddAmount(&values, seen, base*4/5, remaining)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(&values, seen, base*6/5, remaining)
	candidateAddAmount(&values, seen, base*3/2, remaining)
	candidateAddAmount(&values, seen, base*2, remaining)
	candidateAddAmount(&values, seen, remaining/3, remaining)
	candidateAddAmount(&values, seen, remaining/2, remaining)
	candidateAddAmount(&values, seen, remaining*2/3, remaining)
	candidateAddAmount(&values, seen, remaining*3/4, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard/3, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*2/3, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*4/5, remaining,
		)
	}

	for _, edge := range r.incomingEdges[r.spec.Target] {
		r.addEdgeLimits(&values, seen, edge, remaining)
	}

	for _, edge := range r.edges {
		if edge.key.from != r.source {
			continue
		}
		r.addEdgeLimits(&values, seen, edge, remaining)
	}

	sort.Slice(values, func(i, j int) bool {
		di := math.Abs(float64(values[i] - base))
		dj := math.Abs(float64(values[j] - base))
		if di == dj {
			return values[i] > values[j]
		}
		return di < dj
	})

	if len(values) > 18 {
		values = values[:18]
	}
	return values
}

type candidateRouteOption struct {
	rt      *route.Route
	logProb float64
	quality float64
}

func candidatePlanContribution(rt *route.Route,
	finalAmt lnwire.MilliSatoshi, logProb float64) float64 {

	fees := rt.TotalAmount - finalAmt
	return logProb - float64(fees)/2_200_000 - 0.035
}

func (r *candidateRouter) routeOptions(
	amt lnwire.MilliSatoshi) []candidateRouteOption {

	best, bestLogProb, err := r.findRoute(amt, nil)
	if err != nil {
		return nil
	}

	options := []candidateRouteOption{{
		rt:      best,
		logProb: bestLogProb,
		quality: candidatePlanContribution(best, amt, bestLogProb),
	}}
	seen := map[uint64]bool{candidateRouteID(best): true}

	maxBans := len(best.Hops)
	if maxBans > 5 {
		maxBans = 5
	}

	for i := 0; i < maxBans; i++ {
		key, ok := candidateRouteEdgeKey(best, i)
		if !ok {
			continue
		}

		banned := map[candidateEdgeKey]bool{key: true}
		rt, logProb, findErr := r.findRoute(amt, banned)
		if findErr != nil {
			continue
		}

		id := candidateRouteID(rt)
		if seen[id] {
			continue
		}
		seen[id] = true

		options = append(options, candidateRouteOption{
			rt:      rt,
			logProb: logProb,
			quality: candidatePlanContribution(
				rt, amt, logProb,
			),
		})
	}

	sort.Slice(options, func(i, j int) bool {
		return options[i].quality > options[j].quality
	})
	if len(options) > 3 {
		options = options[:3]
	}

	return options
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	quality      float64
	rank         float64
}

func (r *candidateRouter) searchPlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, float64, bool) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(r.reserved),
	}}
	const beamWidth = 9

	for depth := uint32(0); depth < parts; depth++ {
		slots := parts - depth
		var nextStates []candidatePlanState

		for _, state := range states {
			if state.remaining == 0 {
				nextStates = append(nextStates, state)
				continue
			}

			r.reserved = candidateCopyReservations(
				state.reservations,
			)
			sizes := r.shardCandidates(state.remaining, slots)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}
				if slots > 1 && size == state.remaining {
					continue
				}
				if slots == 1 && size != state.remaining {
					continue
				}

				options := r.routeOptions(size)
				for _, option := range options {
					r.reserved = candidateCopyReservations(
						state.reservations,
					)
					r.reserveRoute(option.rt)

					routes := append(
						[]*route.Route(nil),
						state.routes...,
					)
					routes = append(routes, option.rt)

					base := float64(state.remaining) /
						float64(slots)
					sizeRatio := float64(size) / base
					progress := float64(size) /
						float64(total)

					rankBonus := 0.55 * math.Log(sizeRatio)
					rankBonus += 0.85 * progress

					nextStates = append(
						nextStates, candidatePlanState{
							remaining: state.remaining -
								size,
							routes: routes,
							reservations: candidateCopyReservations(
								r.reserved,
							),
							quality: state.quality +
								option.quality,
							rank: state.rank +
								option.quality +
								rankBonus,
						},
					)
				}
			}
		}

		if len(nextStates) == 0 {
			return nil, 0, false
		}

		sort.Slice(nextStates, func(i, j int) bool {
			iDone := nextStates[i].remaining == 0
			jDone := nextStates[j].remaining == 0
			if iDone != jDone {
				return iDone
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	var best *candidatePlanState
	for i := range states {
		if states[i].remaining != 0 {
			continue
		}
		if best == nil || states[i].quality > best.quality {
			best = &states[i]
		}
	}

	if best == nil || len(best.routes) == 0 {
		return nil, 0, false
	}

	return best.routes, best.quality, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)
	var firstErr error

	full, fullLogProb, err := r.findRoute(total, nil)
	if err == nil {
		bestPlan = []*route.Route{full}
		bestScore = candidatePlanContribution(
			full, total, fullLogProb,
		)
	} else {
		firstErr = err
	}

	maxSearchParts := parts
	if maxSearchParts > 8 {
		maxSearchParts = 8
	}

	for count := uint32(2); count <= maxSearchParts; count++ {
		plan, score, ok := r.searchPlan(total, count)
		if !ok {
			continue
		}

		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		if firstErr != nil {
			return nil, firstErr
		}
		return nil, errors.New("no payment plan found")
	}

	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) routeStillFits(rt *route.Route,
	remaining lnwire.MilliSatoshi) bool {

	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 || finalAmt > remaining {
		return false
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok || r.policyBlocked[key] {
			return false
		}
		edge := r.edges[key]
		if edge == nil {
			return false
		}

		amt, ok := candidateRouteAmount(rt, i)
		if !ok || !edge.policyAllows(amt) {
			return false
		}
		reserved := r.reserved[key]
		if reserved >= edge.capacity ||
			amt > edge.capacity-reserved {

			return false
		}
		if failure, ok := r.currentFails[key]; ok &&
			failure.upper > 0 &&
			reserved+amt >= failure.upper {

			return false
		}
	}

	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		if r.routeStillFits(rt, amt) {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++

	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil &&
		amt > edge.capacity/14 {

		highEstimate := edge.capacity * 9 / 10
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 2 / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else if estimate < belief.estimate {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("nil attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
			if r.suspect[key] > 0 {
				r.suspect[key]--
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 3)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.suspect[key] += 3
		r.markRouteSuspect(rt, 1)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"reflect"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}

	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
	instance    uintptr
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb

	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}

	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))

	return candidateMix64(x)
}

func candidateViewIdentity(view routing.SimNetworkView) uintptr {
	value := reflect.ValueOf(view)
	if !value.IsValid() {
		return 0
	}

	switch value.Kind() {
	case reflect.Chan, reflect.Func, reflect.Map, reflect.Ptr,
		reflect.Slice, reflect.UnsafePointer:

		if value.IsNil() {
			return 0
		}
		return value.Pointer()
	default:
		return 0
	}
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}

	r.attemptLimit = int(maxParts)*3 + 10
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 56 {
		r.attemptLimit = 56
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
		instance:    candidateViewIdentity(view),
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	fraction := float64(amt) / float64(capacity)

	lowMode := math.Exp(-fraction / 0.052)
	highMode := 1 / (1 + math.Exp((fraction-0.925)/0.032))
	probability := 0.48*lowMode + 0.52*highMode

	if probability < 0.004 {
		return 0.004
	}
	if probability > 0.986 {
		return 0.986
	}

	return probability
}

func candidateRetryCeiling(failure candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if failure.upper <= 0 {
		return 0, false
	}

	var fraction int64
	switch {
	case failure.count <= 1:
		fraction = 68
	case failure.count == 2:
		fraction = 49
	default:
		fraction = 35
	}

	ceiling := failure.upper * lnwire.MilliSatoshi(fraction) / 100
	if ceiling < 1 {
		ceiling = 1
	}

	return ceiling, true
}

func candidateRetryScale(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.62
	case count == 2:
		return 0.43
	default:
		return 0.29
	}
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	total := amt + r.reserved[edge.key]
	if total <= 0 || total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}

		ceiling, valid := candidateRetryCeiling(failure)
		if valid && total > ceiling {
			return 0
		}

		retryScale = candidateRetryScale(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}

		return 0.999 * retryScale
	}

	prior := candidatePrior(total, edge.capacity)
	belief, known := r.beliefs[edge.key]
	if !known {
		return prior * retryScale
	}

	probability := prior

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		probability = 0.996
	} else if belief.upperFail > 0 && total >= belief.upperFail {
		probability = math.Min(probability, 0.004)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		evidence := 0.994 - 0.990*position
		probability = 0.10*prior + 0.90*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		switch {
		case ratio >= 1:
			probability = math.Min(probability, 0.004)

		case ratio > 0.20:
			falloff := (ratio - 0.20) / 0.80
			scale := 1 - 0.96*falloff
			if scale < 0.035 {
				scale = 0.035
			}
			probability *= scale
		}
	} else if belief.lowerOK > 0 {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		if distance > 0 {
			boost := 0.68 * math.Exp(-distance/0.19)
			probability += boost * (1 - probability)
		}
	}

	if belief.estimate > 0 {
		scale := 0.075 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}

		estimateProbability := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		probability = 0.66*probability + 0.34*estimateProbability
	}

	if belief.failures > belief.successes+1 {
		excess := belief.failures - belief.successes - 1
		if excess > 4 {
			excess = 4
		}
		probability *= 1 - 0.08*float64(excess)
	}

	probability *= retryScale
	if probability < 0.0008 {
		return 0.0008
	}
	if probability > 0.997 {
		return 0.997
	}

	return probability
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]

	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 720_000.0
		hopPenalty = 120.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProbability float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)

		knownScore, ok := bestScore[item.node]
		if !ok || item.score > knownScore+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProbability = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOverEdge := item.required
			probability := r.probability(edge, amountOverEdge)
			if probability <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			required := amountOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(probability)) +
				hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 35_000
			edgeScore += float64(r.suspect[edge.key]) * 480_000

			if r.reserved[edge.key] > 0 {
				reservedFraction := float64(r.reserved[edge.key]) /
					float64(edge.capacity)
				edgeScore += 620_000 + 300_000*reservedFraction
			}

			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}

			score := item.score + edgeScore
			oldScore, found := bestScore[edge.key.from]
			if found && score >= oldScore {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge

			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: required,
				logProb:  item.logProb + math.Log(probability),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}

	if channelIndex == 0 {
		return rt.TotalAmount, true
	}

	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}

	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}

	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	hash := candidateVertexHash(rt.SourcePubKey)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		hash ^= candidateMix64(key.chanID + uint64(i+1))
		hash ^= candidateMix64(candidateVertexHash(key.to))
	}

	return candidateMix64(hash)
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	copyMap := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		copyMap[key] = amount
	}

	return copyMap
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amount
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}

	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateScaledAmount(amount lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if amount <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(
		float64(amount) * float64(numerator) / float64(denominator),
	)
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, amount,
	maximum lnwire.MilliSatoshi) {

	if amount <= 0 {
		amount = 1
	}
	if amount > maximum {
		amount = maximum
	}

	if seen[amount] {
		return
	}

	seen[amount] = true
	*values = append(*values, amount)
}

func (r *candidateRouter) routeLimit(rt *route.Route) lnwire.MilliSatoshi {
	limit := lnwire.MilliSatoshi(math.MaxInt64)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}

		edge := r.edges[key]
		if edge == nil {
			return 0
		}

		reserved := r.reserved[key]
		physical := edge.capacity - reserved
		if physical < limit {
			limit = physical
		}

		if edge.maxHTLC > 0 {
			maximum := edge.maxHTLC - reserved
			if maximum < limit {
				limit = maximum
			}
		}

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok {
				return 0
			}

			localAvailable := balance - reserved
			if localAvailable < limit {
				limit = localAvailable
			}
			continue
		}

		if failure, ok := r.currentFails[key]; ok {
			ceiling, valid := candidateRetryCeiling(failure)
			if valid {
				available := ceiling - reserved
				if available < limit {
					limit = available
				}
			}
		}

		belief, known := r.beliefs[key]
		if !known {
			likely := candidateScaledAmount(
				edge.capacity, 82, 100,
			) - reserved
			if likely < limit {
				limit = likely
			}
			continue
		}

		var likelyTotal lnwire.MilliSatoshi

		switch {
		case belief.upperFail > 0:
			likelyTotal = candidateScaledAmount(
				belief.upperFail, 48, 100,
			)
			if belief.lowerOK > likelyTotal {
				likelyTotal = belief.lowerOK
			}
			if likelyTotal >= belief.upperFail {
				likelyTotal = belief.upperFail - 1
			}

		case belief.lowerOK > 0:
			likelyTotal = candidateScaledAmount(
				edge.capacity, 90, 100,
			)
			if likelyTotal < belief.lowerOK {
				likelyTotal = belief.lowerOK
			}

		case belief.estimate > 0:
			likelyTotal = belief.estimate

		default:
			likelyTotal = candidateScaledAmount(
				edge.capacity, 82, 100,
			)
		}

		likely := likelyTotal - reserved
		if likely < limit {
			limit = likely
		}
	}

	if limit < 1 {
		return 0
	}

	return limit
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	average := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&values, seen,
		candidateScaledAmount(average, 1, 2), remaining,
	)
	candidateAddAmount(
		&values, seen,
		candidateScaledAmount(average, 2, 3), remaining,
	)
	candidateAddAmount(
		&values, seen,
		candidateScaledAmount(average, 4, 5), remaining,
	)
	candidateAddAmount(&values, seen, average, remaining)
	candidateAddAmount(
		&values, seen,
		candidateScaledAmount(average, 6, 5), remaining,
	)
	candidateAddAmount(
		&values, seen,
		candidateScaledAmount(average, 3, 2), remaining,
	)
	candidateAddAmount(&values, seen, average*2, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(r.lastFailedShard, 2, 3),
			remaining,
		)
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(r.lastFailedShard, 1, 2),
			remaining,
		)
	}

	candidateAddAmount(&values, seen, remaining, remaining)

	return values
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func candidatePenalizeRoute(penalties map[candidateEdgeKey]float64,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		penalty := 940_000.0
		if i == 0 || i == len(rt.Hops)-1 {
			penalty = 620_000
		}
		penalties[key] += penalty
	}
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState

	const (
		beamWidth       = 24
		maxSizes        = 16
		alternatives    = 4
		progressWeight  = 4.8
		perPartLogCost  = 0.012
		feeScale        = 5_000_000.0
	)

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make([]candidatePlanState, 0, beamWidth*10)

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}

			r.reserved = candidateCopyReservations(
				state.reservations,
			)

			sizes := r.planSizes(state.remaining, slots)
			seenSizes := make(map[lnwire.MilliSatoshi]bool)
			for _, size := range sizes {
				seenSizes[size] = true
			}

			processed := 0
			for index := 0; index < len(sizes) &&
				processed < maxSizes; index++ {

				size := sizes[index]
				if size <= 0 || size > state.remaining {
					continue
				}
				processed++

				diversityPenalty := make(
					map[candidateEdgeKey]float64,
				)
				seenRoutes := make(map[uint64]bool)

				for alternative := 0; alternative < alternatives;
					alternative++ {

					r.reserved = candidateCopyReservations(
						state.reservations,
					)

					rt, logProbability, err := r.findRoute(
						size, diversityPenalty,
					)
					if err != nil {
						break
					}

					routeHash := candidateRouteHash(rt)
					candidatePenalizeRoute(diversityPenalty, rt)
					if seenRoutes[routeHash] {
						continue
					}
					seenRoutes[routeHash] = true

					limit := r.routeLimit(rt)
					if limit > 0 {
						candidateAddAmount(
							&sizes, seenSizes,
							candidateScaledAmount(
								limit, 2, 3,
							),
							state.remaining,
						)
						candidateAddAmount(
							&sizes, seenSizes,
							candidateScaledAmount(
								limit, 5, 6,
							),
							state.remaining,
						)
						candidateAddAmount(
							&sizes, seenSizes, limit,
							state.remaining,
						)
					}

					newReservations :=
						candidateCopyReservations(
							state.reservations,
						)
					r.reserved = newReservations
					r.reserveRoute(rt)

					fees := rt.TotalAmount - size
					score := state.score + logProbability -
						float64(fees)/feeScale -
						perPartLogCost

					remaining := state.remaining - size
					progress := float64(total-remaining) /
						float64(total)
					rank := score + progressWeight*progress

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, rt)

					nextState := candidatePlanState{
						remaining:    remaining,
						routes:       routes,
						reservations: newReservations,
						score:        score,
						rank:         rank,
					}
					nextStates = append(nextStates, nextState)

					if remaining == 0 &&
						(bestComplete == nil ||
							score > bestComplete.score) {

						copyState := nextState
						bestComplete = &copyState
					}
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			leftComplete := nextStates[i].remaining == 0
			rightComplete := nextStates[j].remaining == 0

			if leftComplete != rightComplete {
				return leftComplete
			}
			if nextStates[i].rank == nextStates[j].rank {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}

			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no route set found")
	}

	return bestComplete.routes, nil
}

func (r *candidateRouter) fallbackRoute(total lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total, nil)
		return rt, err
	}

	sizes := r.planSizes(total, parts)
	seen := make(map[lnwire.MilliSatoshi]bool)
	for _, size := range sizes {
		seen[size] = true
	}

	average := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)
	candidateAddAmount(
		&sizes, seen,
		candidateScaledAmount(average, 7, 10), total,
	)
	candidateAddAmount(
		&sizes, seen,
		candidateScaledAmount(average, 9, 10), total,
	)

	var bestRoute *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range sizes {
		if size <= 0 || size > total {
			continue
		}

		rt, logProbability, err := r.findRoute(size, nil)
		if err != nil {
			continue
		}

		fees := rt.TotalAmount - size
		progress := float64(size) / float64(total)
		utility := logProbability + 2.1*progress -
			float64(fees)/5_000_000

		if utility > bestUtility {
			bestUtility = utility
			bestRoute = rt
		}
	}

	if bestRoute == nil {
		return nil, errors.New("no fallback route found")
	}

	return bestRoute, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}

		return []*route.Route{rt}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	rt, fallbackErr := r.fallbackRoute(total, parts)
	if fallbackErr != nil {
		return nil, err
	}

	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}

	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)

		if finalAmount > 0 && finalAmount <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++

			return rt, nil
		}

		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++

	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil {
		highModeEstimate := candidateScaledAmount(
			edge.capacity, 90, 100,
		)
		if highModeEstimate > estimate {
			estimate = highModeEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaledAmount(amt, 1, 4)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else {
		belief.estimate = (
			2*belief.estimate + estimate
		) / 3
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}

		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}

			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}

			r.learnSuccess(key, amount+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0

		return nil
	}

	r.planned = nil

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passedEdges := failureIndex
	if passedEdges > len(rt.Hops) {
		passedEdges = len(rt.Hops)
	}

	for i := 0; i < passedEdges; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	amountOverEdge, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amountOverEdge + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 6
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 48 {
		r.attemptLimit = 48
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateRetryFactor(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.52
	case count == 2:
		return 0.32
	default:
		return 0.18
	}
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var numerator int64
	switch {
	case f.count <= 1:
		numerator = 55
	case f.count == 2:
		numerator = 36
	default:
		numerator = 22
	}

	ceiling := f.upper * lnwire.MilliSatoshi(numerator) / 100
	if ceiling <= 0 {
		ceiling = 1
	}
	return ceiling, true
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	reserved := r.reserved[edge.key]
	total := amt + reserved
	if total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, ok := candidateRetryCeiling(failure); ok &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryFactor(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.006)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.994 - 0.989*pos
		p = 0.12*p + 0.88*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.25 {
			scale := 1 - 0.97*(ratio-0.25)/0.75
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.68 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.08 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.75*p + 0.25*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	path     []*candidateEdge
	active   bool
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidatePathContains(path []*candidateEdge,
	vertex route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == vertex || edge.key.to == vertex {
			return true
		}
	}
	return false
}

func candidateAcceptLabel(
	labels map[route.Vertex][]*candidateDijkstraItem,
	item *candidateDijkstraItem) bool {

	list := labels[item.node]
	for _, old := range list {
		if old.active && old.score <= item.score &&
			old.required <= item.required {

			return false
		}
	}

	kept := make([]*candidateDijkstraItem, 0, len(list)+1)
	for _, old := range list {
		if !old.active {
			continue
		}
		if item.score <= old.score &&
			item.required <= old.required {

			old.active = false
			continue
		}
		kept = append(kept, old)
	}

	item.active = true
	kept = append(kept, item)

	if len(kept) > 6 {
		sort.Slice(kept, func(i, j int) bool {
			left := kept[i].score +
				float64(kept[i].required)*0.0001
			right := kept[j].score +
				float64(kept[j].required)*0.0001
			return left < right
		})
		for _, old := range kept[6:] {
			old.active = false
		}
		kept = kept[:6]
	}

	labels[item.node] = kept
	return item.active
}

func (r *candidateRouter) findRouteBanned(
	amt lnwire.MilliSatoshi,
	banned map[candidateEdgeKey]bool) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 520_000.0
		hopPenalty = 180.0
	)

	labels := make(map[route.Vertex][]*candidateDijkstraItem)
	pq := &candidateDijkstraQueue{}
	start := &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
		active:   true,
	}
	labels[r.spec.Target] = []*candidateDijkstraItem{start}
	heap.Push(pq, start)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		if !item.active {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(item.path, amt)
			if err != nil {
				return nil, 0, err
			}
			return rt, item.logProb, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned != nil && banned[edge.key] {
				continue
			}
			if candidatePathContains(item.path, edge.key.from) {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.edgeUses[edge.key]) * 35_000
			edgeScore += float64(r.suspect[edge.key]) * 260_000
			if r.reserved[edge.key] > 0 {
				edgeScore += 230_000
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			next := &candidateDijkstraItem{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				path:     path,
			}
			if candidateAcceptLabel(labels, next) {
				heap.Push(pq, next)
			}
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	return r.findRouteBanned(amt, nil)
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}
	if path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("invalid route endpoints")
	}

	for i := 1; i < len(path); i++ {
		if path[i-1].key.to != path[i].key.from {
			return nil, errors.New("disconnected route")
		}
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateVertexHash(rt.SourcePubKey)
	for _, hop := range rt.Hops {
		h ^= candidateMix64(hop.ChannelID + h)
		h ^= candidateMix64(candidateVertexHash(hop.PubKeyBytes))
	}
	return candidateMix64(h)
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidateScaledAmount(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func (r *candidateRouter) routeLimit(rt *route.Route) lnwire.MilliSatoshi {
	limit := lnwire.MilliSatoshi(math.MaxInt64)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}
		edge := r.edges[key]
		if edge == nil {
			return 0
		}

		reserved := r.reserved[key]
		available := edge.capacity - reserved
		if available < limit {
			limit = available
		}
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok {
				return 0
			}
			localAvailable := balance - reserved
			if localAvailable < limit {
				limit = localAvailable
			}
			continue
		}

		if failure, ok := r.currentFails[key]; ok {
			if ceiling, ok := candidateRetryCeiling(failure); ok {
				likely := ceiling - reserved
				if likely < limit {
					limit = likely
				}
			}
		}

		belief, ok := r.beliefs[key]
		if !ok {
			likely := candidateScaledAmount(
				edge.capacity, 90, 100,
			) - reserved
			if likely < limit {
				limit = likely
			}
			continue
		}

		if belief.upperFail > 0 {
			likelyTotal := candidateScaledAmount(
				belief.upperFail, 48, 100,
			)
			if belief.lowerOK > likelyTotal {
				likelyTotal = belief.lowerOK
			}
			if likelyTotal >= belief.upperFail {
				likelyTotal = belief.upperFail - 1
			}
			likely := likelyTotal - reserved
			if likely < limit {
				limit = likely
			}
		} else if belief.lowerOK > 0 {
			likelyTotal := belief.lowerOK +
				candidateScaledAmount(
					edge.capacity-belief.lowerOK,
					60, 100,
				)
			likely := likelyTotal - reserved
			if likely < limit {
				limit = likely
			}
		}
	}

	if limit < 1 {
		return 0
	}
	return limit
}

func (r *candidateRouter) planSizes(
	remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 1, 4),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 2, 5),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 5),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 4, 5),
		remaining,
	)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 5, 4),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 8, 5),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 11, 5),
		remaining,
	)
	candidateAddAmount(&values, seen, base*3, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(r.lastFailedShard, 1, 5),
			remaining,
		)
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(r.lastFailedShard, 1, 3),
			remaining,
		)
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(r.lastFailedShard, 1, 2),
			remaining,
		)
	}

	candidateAddAmount(&values, seen, remaining, remaining)
	return values
}

type candidateRouteOption struct {
	rt      *route.Route
	logProb float64
	utility float64
}

func (r *candidateRouter) routeOptions(
	amt lnwire.MilliSatoshi, maxOptions int) []candidateRouteOption {

	rt, logProb, err := r.findRoute(amt)
	if err != nil {
		return nil
	}

	makeOption := func(routeValue *route.Route,
		lp float64) candidateRouteOption {

		fees := routeValue.TotalAmount - amt
		return candidateRouteOption{
			rt:      routeValue,
			logProb: lp,
			utility: lp - float64(fees)/3_500_000,
		}
	}

	options := []candidateRouteOption{makeOption(rt, logProb)}
	seen := map[uint64]bool{candidateRouteHash(rt): true}

	for i := range rt.Hops {
		if len(options) >= maxOptions {
			break
		}

		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		banned := map[candidateEdgeKey]bool{key: true}
		alt, altLogProb, altErr := r.findRouteBanned(amt, banned)
		if altErr != nil {
			continue
		}

		hash := candidateRouteHash(alt)
		if seen[hash] {
			continue
		}
		seen[hash] = true
		options = append(options, makeOption(alt, altLogProb))
	}

	sort.Slice(options, func(i, j int) bool {
		return options[i].utility > options[j].utility
	})
	return options
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func candidateBetterPartial(a, b *candidatePlanState) bool {
	if b == nil {
		return true
	}
	if a.remaining != b.remaining {
		return a.remaining < b.remaining
	}
	return a.score > b.score
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState
	var bestPartial *candidatePlanState
	const beamWidth = 24

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make([]candidatePlanState, 0, beamWidth*10)

		for _, state := range states {
			r.reserved = candidateCopyReservations(
				state.reservations,
			)
			sizes := r.planSizes(state.remaining, slots)
			seenSizes := make(map[lnwire.MilliSatoshi]bool)
			for _, size := range sizes {
				seenSizes[size] = true
			}

			for i := 0; i < len(sizes) && i < 24; i++ {
				size := sizes[i]
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				options := r.routeOptions(size, 4)
				for _, option := range options {
					r.reserved = candidateCopyReservations(
						state.reservations,
					)

					limit := r.routeLimit(option.rt)
					if limit > size {
						candidateAddAmount(
							&sizes, seenSizes,
							candidateScaledAmount(limit, 3, 4),
							state.remaining,
						)
						candidateAddAmount(
							&sizes, seenSizes, limit,
							state.remaining,
						)
					}

					newReservations := candidateCopyReservations(
						state.reservations,
					)
					r.reserved = newReservations
					r.reserveRoute(option.rt)

					fees := option.rt.TotalAmount - size
					score := state.score + option.logProb -
						float64(fees)/3_500_000 - 0.025

					remaining := state.remaining - size
					progress := float64(total-remaining) /
						float64(total)
					rank := score + 6.0*progress

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, option.rt)

					next := candidatePlanState{
						remaining:    remaining,
						routes:       routes,
						reservations: newReservations,
						score:        score,
						rank:         rank,
					}

					if remaining == 0 {
						if bestComplete == nil ||
							score > bestComplete.score {

							copyState := next
							bestComplete = &copyState
						}
						continue
					}

					if candidateBetterPartial(
						&next, bestPartial,
					) {
						copyState := next
						bestPartial = &copyState
					}

					if depth+1 < parts {
						nextStates = append(
							nextStates, next,
						)
					}
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			return nextStates[i].rank > nextStates[j].rank
		})
		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if bestComplete != nil && len(bestComplete.routes) > 0 {
		return bestComplete.routes, nil
	}
	if bestPartial != nil && len(bestPartial.routes) > 0 {
		return bestPartial.routes, nil
	}
	return nil, errors.New("no route set found")
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err == nil {
			return []*route.Route{rt}, nil
		}

		if r.lastFailedShard > 0 {
			for _, numerator := range []int64{1, 2, 3} {
				smaller := candidateScaledAmount(
					r.lastFailedShard, numerator, 4,
				)
				if smaller <= 0 || smaller >= total {
					continue
				}
				rt, _, retryErr := r.findRoute(smaller)
				if retryErr == nil {
					return []*route.Route{rt}, nil
				}
			}
		}
		return nil, err
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	rt, _, singleErr := r.findRoute(total)
	if singleErr == nil {
		return []*route.Route{rt}, nil
	}

	sizes := r.planSizes(total, parts)
	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] > sizes[j]
	})
	for _, size := range sizes {
		if size >= total {
			continue
		}
		rt, _, routeErr := r.findRoute(size)
		if routeErr == nil {
			return []*route.Route{rt}, nil
		}
	}

	return nil, err
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaledAmount(amt, 2, 5)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key]++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32
	attempted     map[uint64]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		attempted:      make(map[uint64]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 10
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 32 {
		r.attemptLimit = 32
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity ||
		r.policyBlocked[edge.key] {

		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio <= 0.42:
			retryScale = 0.92
		case ratio <= 0.58:
			retryScale = 0.70
		case ratio <= 0.72:
			retryScale = 0.38
		default:
			retryScale = 0.12
		}
		if failure.count > 2 {
			retryScale *= 0.75
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997 * retryScale
	}
	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.003 * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.995 - 0.99*pos
		p = 0.10*p + 0.90*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.34 {
			scale := 1 - 0.96*(ratio-0.34)/0.66
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.72 * math.Exp(-distance/0.22)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.08 * float64(edge.capacity)
		if belief.upperFail > belief.lowerOK && belief.lowerOK > 0 {
			scale = 0.18 * float64(
				belief.upperFail - belief.lowerOK,
			)
		}
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.58*p + 0.42*q
	}

	if belief.successes > belief.failures+1 {
		p += 0.05 * (1 - p)
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}
	return r.liquidityProbability(edge, amt+r.reserved[edge.key])
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 650_000.0
		hopPenalty = 220.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.edgeUses[edge.key]) * 42_000
			edgeScore += float64(r.suspect[edge.key]) * 280_000
			edgeScore += extraPenalty[edge.key]
			if r.reserved[edge.key] > 0 {
				edgeScore += 130_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	return r.buildPath(amt, path)
}

func (r *candidateRouter) buildPath(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))
	last := len(path) - 1

	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.policyAllows(amtOver[i]) {
			return nil, errors.New("path violates channel policy")
		}

		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteTopologySignature(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := uint64(0x6a09e667f3bcc909)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(key.chanID + uint64(i+1)<<48)
		h ^= candidateMix64(candidateVertexHash(key.to))
	}
	return candidateMix64(h)
}

func candidateRouteSignature(rt *route.Route) uint64 {
	return candidateMix64(
		candidateRouteTopologySignature(rt) ^
			candidateMix64(uint64(candidateFinalAmount(rt))),
	)
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserve(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserve(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeAlternatives(
	amt lnwire.MilliSatoshi) []candidateRouteChoice {

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	choices := make([]candidateRouteChoice, 0, 3)

	for tries := 0; tries < 7 && len(choices) < 3; tries++ {
		rt, logProb, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		sig := candidateRouteTopologySignature(rt)
		if !seen[sig] {
			seen[sig] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				logProb: logProb,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				penalties[key] += 1_050_000
			}
		}
	}

	return choices
}

func candidateAddSize(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) edgeLiquidityHint(
	edge *candidateEdge) lnwire.MilliSatoshi {

	limit := edge.capacity * 87 / 100

	if edge.key.from == r.source {
		if balance, ok := r.localBalances[edge.key.chanID]; ok {
			limit = balance
		} else {
			return 0
		}
	}

	belief := r.beliefs[edge.key]
	if belief.lowerOK > limit {
		limit = belief.lowerOK
	}
	if belief.estimate > 0 && belief.estimate < limit {
		limit = belief.estimate
	}
	if belief.upperFail > 0 {
		retry := belief.upperFail * 11 / 20
		if belief.lowerOK > retry {
			retry = belief.lowerOK
		}
		if retry < limit {
			limit = retry
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		retry := failure.upper * 3 / 5
		if belief.lowerOK > retry {
			retry = belief.lowerOK
		}
		if retry < limit {
			limit = retry
		}
	}

	if limit > edge.capacity {
		limit = edge.capacity
	}
	return limit
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	sizes := make([]lnwire.MilliSatoshi, 0, 20)

	candidateAddSize(&sizes, seen, remaining, remaining)
	if slots <= 1 {
		return sizes
	}

	for n := uint32(2); n <= slots; n++ {
		base := (remaining + lnwire.MilliSatoshi(n) - 1) /
			lnwire.MilliSatoshi(n)
		candidateAddSize(&sizes, seen, base, remaining)
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddSize(&sizes, seen, base/2, remaining)
	candidateAddSize(&sizes, seen, base*2/3, remaining)
	candidateAddSize(&sizes, seen, base*4/5, remaining)
	candidateAddSize(&sizes, seen, base*6/5, remaining)
	candidateAddSize(&sizes, seen, base*3/2, remaining)
	candidateAddSize(&sizes, seen, base*2, remaining)

	if r.lastFailedShard > 0 {
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*2/5, remaining,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*11/20, remaining,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*2/3, remaining,
		)
	}

	for _, edge := range r.incomingEdges[r.spec.Target] {
		hint := r.edgeLiquidityHint(edge) - r.reserved[edge.key]
		candidateAddSize(&sizes, seen, hint, remaining)
		if len(sizes) >= 22 {
			break
		}
	}

	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	touched      map[candidateEdgeKey]bool
	fees         lnwire.MilliSatoshi
	repeatCost   float64
	score        float64
	rank         float64
}

func candidateCopyTouched(
	src map[candidateEdgeKey]bool) map[candidateEdgeKey]bool {

	dst := make(map[candidateEdgeKey]bool, len(src))
	for key := range src {
		dst[key] = true
	}
	return dst
}

func (r *candidateRouter) planScore(state *candidatePlanState) float64 {
	score := -float64(state.fees)/5_000_000 - state.repeatCost

	for key := range state.touched {
		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(
			edge, state.reservations[key],
		)
		if p <= 0 {
			return math.Inf(-1)
		}

		score += math.Log(p)
		score -= float64(r.suspect[key]) * 0.42
		score -= float64(r.edgeUses[key]) * 0.025
	}

	score -= float64(len(state.routes)) * 0.012
	return score
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		parts = 1
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	initial := &candidatePlanState{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
		touched:      make(map[candidateEdgeKey]bool),
	}

	beam := []*candidatePlanState{initial}
	var best *candidatePlanState
	var bestPartial *candidatePlanState

	const beamWidth = 18

	for depth := uint32(0); depth < parts && len(beam) > 0; depth++ {
		var nextBeam []*candidatePlanState

		for _, state := range beam {
			if state.remaining == 0 {
				if best == nil || state.score > best.score {
					best = state
				}
				continue
			}
			if state.slots == 0 {
				continue
			}

			r.reserved = state.reservations
			sizes := r.shardSizes(state.remaining, state.slots)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				choices := r.routeAlternatives(size)
				for _, choice := range choices {
					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserve(reservations, choice.route)

					touched := candidateCopyTouched(state.touched)
					for i := range choice.route.Hops {
						key, ok := candidateRouteEdgeKey(
							choice.route, i,
						)
						if ok {
							touched[key] = true
						}
					}

					routes := append(
						[]*route.Route(nil), state.routes...,
					)
					routes = append(routes, choice.route)

					repeatCost := state.repeatCost
					repeats := r.attempted[
						candidateRouteSignature(choice.route)
					]
					if repeats > 0 {
						repeatCost += 1.15 * float64(repeats)
					}

					remaining := state.remaining - size
					ns := &candidatePlanState{
						remaining:    remaining,
						slots:        state.slots - 1,
						routes:       routes,
						reservations: reservations,
						touched:      touched,
						fees: state.fees +
							choice.route.TotalAmount - size,
						repeatCost: repeatCost,
					}
					ns.score = r.planScore(ns)
					if math.IsInf(ns.score, -1) {
						continue
					}

					progress := 1 - float64(remaining)/
						float64(total)
					ns.rank = ns.score + 5.5*progress

					if remaining == 0 {
						if best == nil || ns.score > best.score {
							best = ns
						}
						continue
					}

					if ns.slots > 0 {
						nextBeam = append(nextBeam, ns)
						if bestPartial == nil ||
							ns.remaining < bestPartial.remaining ||
							(ns.remaining == bestPartial.remaining &&
								ns.score > bestPartial.score) {

							bestPartial = ns
						}
					}
				}
			}
		}

		sort.Slice(nextBeam, func(i, j int) bool {
			return nextBeam[i].rank > nextBeam[j].rank
		})
		if len(nextBeam) > beamWidth {
			nextBeam = nextBeam[:beamWidth]
		}
		beam = nextBeam
	}

	if best != nil && len(best.routes) > 0 {
		return best.routes, nil
	}

	r.reserved = savedReservations
	rt, _, err := r.findRoute(total, nil)
	if err == nil {
		return []*route.Route{rt}, nil
	}

	if parts > 1 && bestPartial != nil &&
		len(bestPartial.routes) > 0 {

		return bestPartial.routes, nil
	}

	return nil, err
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	r.attempted[candidateRouteSignature(rt)]++
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	projected := amt
	if edge := r.edges[key]; edge != nil && edge.capacity > amt {
		if belief.upperFail > amt {
			projected = amt + (belief.upperFail-amt)*2/5
		} else {
			projected = amt + (edge.capacity-amt)*7/10
		}
	}
	if projected > belief.estimate {
		belief.estimate = projected
	}
	if belief.upperFail > 0 && belief.estimate >= belief.upperFail {
		belief.estimate = belief.lowerOK +
			(belief.upperFail-belief.lowerOK)/2
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 7 / 20
	if estimate < belief.lowerOK {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid reported route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 4

	default:
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 8
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 48 {
		r.attemptLimit = 48
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.033))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.988 {
		return 0.988
	}
	return p
}

func candidateRetryFactor(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.72
	case count == 2:
		return 0.55
	default:
		return 0.40
	}
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var numerator int64
	switch {
	case f.count <= 1:
		numerator = 58
	case f.count == 2:
		numerator = 42
	default:
		numerator = 30
	}

	ceiling := f.upper * lnwire.MilliSatoshi(numerator) / 100
	if ceiling <= 0 {
		ceiling = 1
	}
	return ceiling, true
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.004)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence := 0.995 - 0.991*pos
		p = 0.12*p + 0.88*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.30 {
			scale := 1 - 0.97*(ratio-0.30)/0.70
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.62 * math.Exp(-distance/0.13)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.075 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.76*p + 0.24*q
	}

	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	reserved := r.reserved[edge.key]
	total := reserved + amt
	if total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, ok := candidateRetryCeiling(failure); ok &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryFactor(failure.count)
	}

	pTotal := r.liquidityProbability(edge, total)
	if pTotal <= 0 {
		return 0
	}

	p := pTotal
	if reserved > 0 {
		pReserved := r.liquidityProbability(edge, reserved)
		if pReserved > 0 {
			p = pTotal / pReserved
		}
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.998 {
		return 0.998
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	banned map[candidateEdgeKey]bool) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 610_000.0
		hopPenalty = 220.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned != nil && banned[edge.key] {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 18_000
			edgeScore += float64(r.suspect[edge.key]) * 180_000
			if r.reserved[edge.key] > 0 {
				edgeScore += 28_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateSameRoute(a, b *route.Route) bool {
	if a == nil || b == nil || len(a.Hops) != len(b.Hops) {
		return false
	}
	for i := range a.Hops {
		ak, aok := candidateRouteEdgeKey(a, i)
		bk, bok := candidateRouteEdgeKey(b, i)
		if !aok || !bok || ak != bk {
			return false
		}
	}
	return true
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeChoices(amt lnwire.MilliSatoshi,
	maxChoices int) []candidateRouteChoice {

	rt, logProb, err := r.findRoute(amt, nil)
	if err != nil {
		return nil
	}

	choices := []candidateRouteChoice{{
		route:   rt,
		logProb: logProb,
	}}
	if maxChoices <= 1 {
		return choices
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		alt, altLogProb, err := r.findRoute(
			amt, map[candidateEdgeKey]bool{key: true},
		)
		if err != nil {
			continue
		}

		duplicate := false
		for _, choice := range choices {
			if candidateSameRoute(choice.route, alt) {
				duplicate = true
				break
			}
		}
		if duplicate {
			continue
		}

		choices = append(choices, candidateRouteChoice{
			route:   alt,
			logProb: altLogProb,
		})
		if len(choices) >= maxChoices {
			break
		}
	}

	return choices
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateScaledAmount(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) routeLimit(rt *route.Route) lnwire.MilliSatoshi {
	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 {
		return 0
	}

	limit := lnwire.MilliSatoshi(math.MaxInt64)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}
		edge := r.edges[key]
		if edge == nil {
			return 0
		}
		edgeAmt, ok := candidateRouteAmount(rt, i)
		if !ok || edgeAmt <= 0 {
			return 0
		}

		reserved := r.reserved[key]
		aggregateLimit := edge.capacity

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok {
				return 0
			}
			if balance < aggregateLimit {
				aggregateLimit = balance
			}
		} else {
			if failure, ok := r.currentFails[key]; ok {
				if ceiling, ok := candidateRetryCeiling(failure); ok &&
					ceiling < aggregateLimit {

					aggregateLimit = ceiling
				}
			}

			belief, ok := r.beliefs[key]
			if !ok {
				likely := candidateScaledAmount(
					edge.capacity, 86, 100,
				)
				if likely < aggregateLimit {
					aggregateLimit = likely
				}
			} else {
				var likely lnwire.MilliSatoshi
				switch {
				case belief.upperFail > 0:
					likely = candidateScaledAmount(
						belief.upperFail, 55, 100,
					)
					if belief.lowerOK > likely {
						likely = belief.lowerOK
					}
					if likely >= belief.upperFail {
						likely = belief.upperFail - 1
					}

				case belief.lowerOK > 0:
					likely = belief.lowerOK +
						candidateScaledAmount(
							edge.capacity-belief.lowerOK,
							38, 100,
						)

				case belief.estimate > 0:
					likely = belief.estimate
				}

				if likely > 0 && likely < aggregateLimit {
					aggregateLimit = likely
				}
			}
		}

		headroom := aggregateLimit - reserved
		if headroom <= 0 {
			return 0
		}

		finalForAggregate := lnwire.MilliSatoshi(
			float64(finalAmt) * float64(headroom) /
				float64(edgeAmt),
		)
		if finalForAggregate < limit {
			limit = finalForAggregate
		}

		if edge.maxHTLC > 0 {
			finalForMax := lnwire.MilliSatoshi(
				float64(finalAmt) * float64(edge.maxHTLC) /
					float64(edgeAmt),
			)
			if finalForMax < limit {
				limit = finalForMax
			}
		}
	}

	if limit < 1 {
		return 0
	}
	return limit
}

func candidatePlanSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 2, 3),
		remaining,
	)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 4, 3),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 5, 3),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(remaining, 1, 3),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(remaining, 1, 2),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(remaining, 2, 3),
		remaining,
	)
	candidateAddAmount(&values, seen, remaining, remaining)

	return values
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState
	const beamWidth = 14

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make([]candidatePlanState, 0, beamWidth*12)

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}

			r.reserved = candidateCopyReservations(
				state.reservations,
			)

			sizes := candidatePlanSizes(state.remaining, slots)
			seenSizes := make(map[lnwire.MilliSatoshi]bool)
			for _, size := range sizes {
				seenSizes[size] = true
			}

			for sizeIndex := 0; sizeIndex < len(sizes) &&
				sizeIndex < 12; sizeIndex++ {

				size := sizes[sizeIndex]
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				maxChoices := 2
				if sizeIndex < 2 {
					maxChoices = 3
				}
				choices := r.routeChoices(size, maxChoices)

				for _, choice := range choices {
					r.reserved = candidateCopyReservations(
						state.reservations,
					)

					limit := r.routeLimit(choice.route)
					if limit > 0 {
						candidateAddAmount(
							&sizes, seenSizes,
							candidateScaledAmount(limit, 3, 4),
							state.remaining,
						)
						candidateAddAmount(
							&sizes, seenSizes, limit,
							state.remaining,
						)
					}

					newReservations := candidateCopyReservations(
						state.reservations,
					)
					r.reserved = newReservations
					r.reserveRoute(choice.route)

					fees := choice.route.TotalAmount - size
					score := state.score + choice.logProb -
						float64(fees)/3_500_000 - 0.014

					remaining := state.remaining - size
					progress := float64(total-remaining) /
						float64(total)
					slotPressure := 0.0
					if slots > 1 && remaining > 0 {
						nextBase := float64(remaining) /
							float64(slots-1)
						slotPressure = -0.08 * nextBase /
							float64(total)
					}
					rank := score + 2.8*progress + slotPressure

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, choice.route)

					nextStates = append(
						nextStates, candidatePlanState{
							remaining:    remaining,
							routes:       routes,
							reservations: newReservations,
							score:        score,
							rank:         rank,
						},
					)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			if nextStates[i].remaining == 0 &&
				nextStates[j].remaining != 0 {

				return true
			}
			if nextStates[j].remaining == 0 &&
				nextStates[i].remaining != 0 {

				return false
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	for _, state := range states {
		if state.remaining != 0 {
			continue
		}
		if bestComplete == nil || state.score > bestComplete.score {
			copyState := state
			bestComplete = &copyState
		}
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no route set found")
	}
	return bestComplete.routes, nil
}

func (r *candidateRouter) fallbackRoute(remaining lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no part slots available")
	}

	base := (remaining + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, remaining, remaining)
	candidateAddAmount(
		&sizes, seen, candidateScaledAmount(remaining, 3, 4),
		remaining,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaledAmount(remaining, 1, 2),
		remaining,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaledAmount(base, 3, 2),
		remaining,
	)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(
		&sizes, seen, candidateScaledAmount(base, 3, 4),
		remaining,
	)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen,
			candidateScaledAmount(r.lastFailedShard, 3, 5),
			remaining,
		)
		candidateAddAmount(
			&sizes, seen,
			candidateScaledAmount(r.lastFailedShard, 2, 5),
			remaining,
		)
	}

	var best *route.Route
	bestUtility := math.Inf(-1)

	for _, size := range sizes {
		rt, logProb, err := r.findRoute(size, nil)
		if err != nil {
			continue
		}

		fees := rt.TotalAmount - size
		progress := float64(size) / float64(remaining)
		utility := logProb + 1.75*progress -
			float64(fees)/3_500_000

		if size >= base {
			utility += 0.12
		}
		if utility > bestUtility {
			bestUtility = utility
			best = rt
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	rt, fallbackErr := r.fallbackRoute(total, parts)
	if fallbackErr != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaledAmount(amt, 9, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key]++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32
	routeFails    map[uint64]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	if spec == nil {
		return nil, errors.New("nil payment specification")
	}

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		routeFails:     make(map[uint64]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 8
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 32 {
		r.attemptLimit = 32
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		if _, ok := r.edges[key]; ok {
			r.beliefs[key] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.032))
	p := 0.5*lowMode + 0.5*highMode

	switch {
	case p < 0.005:
		return 0.005
	case p > 0.985:
		return 0.985
	default:
		return p
	}
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio <= 0.20:
			retryScale = 0.72
		case ratio <= 0.40:
			retryScale = 0.42
		case ratio <= 0.60:
			retryScale = 0.16
		default:
			retryScale = 0.035
		}
		if failure.count > 2 {
			retryScale *= 0.65
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.004 * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence := 0.992 - 0.987*pos
		p = 0.10*p + 0.90*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.25 {
			scale := 1 - 0.975*(ratio-0.25)/0.75
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.70 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.075 * float64(edge.capacity)
		if belief.upperFail > belief.lowerOK && belief.lowerOK > 0 {
			scale = 0.16 * float64(
				belief.upperFail - belief.lowerOK,
			)
		}
		if scale < 1 {
			scale = 1
		}

		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.67*p + 0.33*q
	}

	if belief.successes > belief.failures+1 {
		p += 0.06 * (1 - p)
	}

	p *= retryScale
	switch {
	case p < 0.001:
		return 0.001
	case p > 0.995:
		return 0.995
	default:
		return p
	}
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	path     []*candidateEdge
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	item.index = -1
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 1_350_000.0
		hopPenalty = 750.0
	)

	bestScore := map[route.Vertex]float64{
		r.spec.Target: 0,
	}

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			rt, err := r.buildRoute(item.path, amt)
			if err != nil {
				continue
			}
			return rt, item.logProb, nil
		}

		for _, edge := range r.incomingEdges[item.node] {
			p := r.probability(edge, item.required)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(item.required)
			}
			if fee < 0 ||
				item.required > lnwire.MilliSatoshi(
					math.MaxInt64,
				)-fee {

				continue
			}
			sending := item.required + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 32_000
			edgeScore += float64(r.suspect[edge.key]) * 430_000
			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}
			if r.reserved[edge.key] > 0 {
				edgeScore += 210_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			bestScore[edge.key.from] = score
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				path:     path,
			})
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}
	if path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("invalid route endpoints")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		fee := path[i+1].fee(amtOver[i+1])
		if fee < 0 ||
			amtOver[i+1] > lnwire.MilliSatoshi(math.MaxInt64)-fee {

			return nil, errors.New("route amount overflow")
		}
		amtOver[i] = amtOver[i+1] + fee
		expiryOver[i] = expiryOver[i+1] +
			uint32(path[i+1].timeLockDelta)
	}

	for i, edge := range path {
		if i > 0 && path[i-1].key.to != edge.key.from {
			return nil, errors.New("disconnected route")
		}
		if !edge.policyAllows(amtOver[i]) {
			return nil, errors.New("route violates channel policy")
		}
		if amtOver[i]+r.reserved[edge.key] > edge.capacity {
			return nil, errors.New("route exceeds channel capacity")
		}
		if edge.key.from == r.source {
			balance, ok := r.localBalances[edge.key.chanID]
			if !ok || amtOver[i]+r.reserved[edge.key] > balance {
				return nil, errors.New("route exceeds local balance")
			}
		}
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidatePathSignature(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := uint64(0x243f6a8885a308d3)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(key.chanID + uint64(i+1)<<48)
		h ^= candidateMix64(candidateVertexHash(key.from))
		h ^= candidateMix64(candidateVertexHash(key.to))
	}
	return candidateMix64(h)
}

func candidateRouteSignature(rt *route.Route) uint64 {
	return candidateMix64(
		candidatePathSignature(rt) ^
			candidateMix64(uint64(candidateFinalAmount(rt))),
	)
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserve(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserve(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeAlternatives(
	amt lnwire.MilliSatoshi) []candidateRouteChoice {

	penalties := make(map[candidateEdgeKey]float64)
	seenPaths := make(map[uint64]bool)
	choices := make([]candidateRouteChoice, 0, 4)

	for tries := 0; tries < 10 && len(choices) < 4; tries++ {
		rt, logProb, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		pathSig := candidatePathSignature(rt)
		routeSig := candidateRouteSignature(rt)
		rejected := seenPaths[pathSig] || r.routeFails[routeSig] > 0

		if !rejected {
			seenPaths[pathSig] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				logProb: logProb,
			})
		}

		penalty := 540_000.0
		if rejected {
			penalty = 1_050_000
		}
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				penalties[key] += penalty
			}
		}
	}

	return choices
}

func candidateAddSize(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

type candidateSizedEvidence struct {
	value    lnwire.MilliSatoshi
	distance lnwire.MilliSatoshi
}

func candidateAbsDiff(a, b lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	if a >= b {
		return a - b
	}
	return b - a
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	sizes := make([]lnwire.MilliSatoshi, 0, 24)

	candidateAddSize(&sizes, seen, remaining, remaining)
	if slots <= 1 {
		return sizes
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	for _, numerator := range []int64{
		20, 16, 14, 12, 10, 9, 8, 7, 6, 5, 4,
	} {
		candidateAddSize(
			&sizes, seen,
			remaining*lnwire.MilliSatoshi(numerator)/20,
			remaining,
		)
	}

	for parts := uint32(2); parts <= slots; parts++ {
		size := (remaining + lnwire.MilliSatoshi(parts) - 1) /
			lnwire.MilliSatoshi(parts)
		candidateAddSize(&sizes, seen, size, remaining)
		candidateAddSize(&sizes, seen, size*5/4, remaining)
		candidateAddSize(&sizes, seen, size*3/4, remaining)
	}

	if r.lastFailedShard > 0 {
		for _, numerator := range []int64{3, 4, 5, 6, 7} {
			candidateAddSize(
				&sizes, seen,
				r.lastFailedShard*
					lnwire.MilliSatoshi(numerator)/10,
				remaining,
			)
		}
	}

	var evidence []candidateSizedEvidence
	addEvidence := func(value lnwire.MilliSatoshi) {
		if value <= 0 {
			return
		}
		value = value * 9 / 10
		if value <= 0 || value > remaining {
			return
		}
		evidence = append(evidence, candidateSizedEvidence{
			value:    value,
			distance: candidateAbsDiff(value, base),
		})
	}

	for key, failure := range r.currentFails {
		available := failure.upper - r.reserved[key]
		if available <= 0 {
			continue
		}
		addEvidence(available * 2 / 5)
		addEvidence(available * 3 / 5)
		addEvidence(available * 4 / 5)
	}
	for key, belief := range r.beliefs {
		reserved := r.reserved[key]
		if belief.lowerOK > reserved {
			addEvidence(belief.lowerOK - reserved)
		}
		if belief.estimate > reserved {
			addEvidence(belief.estimate - reserved)
		}
		if belief.upperFail > reserved {
			addEvidence((belief.upperFail - reserved) * 3 / 4)
		}
	}

	sort.Slice(evidence, func(i, j int) bool {
		if evidence[i].distance == evidence[j].distance {
			return evidence[i].value < evidence[j].value
		}
		return evidence[i].distance < evidence[j].distance
	})
	if len(evidence) > 8 {
		evidence = evidence[:8]
	}
	for _, item := range evidence {
		candidateAddSize(
			&sizes, seen, item.value, remaining,
		)
	}

	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func candidateTrimBeam(states []*candidatePlanState,
	total lnwire.MilliSatoshi, width int) []*candidatePlanState {

	sort.Slice(states, func(i, j int) bool {
		return states[i].rank > states[j].rank
	})
	if len(states) <= width {
		return states
	}

	chosen := make([]*candidatePlanState, 0, width)
	used := make(map[int]bool)
	buckets := make(map[int]bool)

	for i, state := range states {
		bucket := 0
		if total > 0 {
			bucket = int(
				uint64(state.remaining) * 8 / uint64(total),
			)
		}
		if buckets[bucket] {
			continue
		}
		buckets[bucket] = true
		used[i] = true
		chosen = append(chosen, state)
		if len(chosen) == width {
			return chosen
		}
	}

	for i, state := range states {
		if used[i] {
			continue
		}
		chosen = append(chosen, state)
		if len(chosen) == width {
			break
		}
	}

	return chosen
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		parts = 1
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	beam := []*candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}}
	var best *candidatePlanState

	const beamWidth = 18

	for depth := uint32(0); depth < parts && len(beam) > 0; depth++ {
		nextBeam := make([]*candidatePlanState, 0, beamWidth*8)

		for _, state := range beam {
			if state.remaining == 0 {
				if best == nil || state.score > best.score {
					best = state
				}
				continue
			}
			if state.slots == 0 {
				continue
			}

			r.reserved = state.reservations
			sizes := r.shardSizes(state.remaining, state.slots)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				choices := r.routeAlternatives(size)
				for _, choice := range choices {
					fees := choice.route.TotalAmount - size
					partPenalty := 0.028
					score := state.score + choice.logProb -
						float64(fees)/8_000_000 -
						partPenalty

					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserve(
						reservations, choice.route,
					)

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, choice.route)

					remaining := state.remaining - size
					progress := 1 - float64(remaining)/
						float64(total)

					ns := &candidatePlanState{
						remaining:    remaining,
						slots:        state.slots - 1,
						routes:       routes,
						reservations: reservations,
						score:        score,
						rank: score + 4.8*progress -
							0.012*float64(len(routes)),
					}

					if remaining == 0 {
						if best == nil || ns.score > best.score {
							best = ns
						}
					} else if ns.slots > 0 {
						nextBeam = append(nextBeam, ns)
					}
				}
			}
		}

		beam = candidateTrimBeam(nextBeam, total, beamWidth)
	}

	if best == nil || len(best.routes) == 0 {
		r.reserved = savedReservations
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	return best.routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	for len(r.planned) > 0 {
		rt := r.planned[0]
		r.planned = r.planned[1:]

		finalAmt := candidateFinalAmount(rt)
		if finalAmt <= 0 || finalAmt > amt {
			continue
		}
		if r.routeFails[candidateRouteSignature(rt)] > 0 {
			continue
		}

		r.recordRouteUse(rt)
		r.attempts++
		return rt, nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	projected := amt
	edge := r.edges[key]
	if edge != nil && edge.capacity > amt {
		if belief.upperFail > amt {
			projected = amt + (belief.upperFail-amt)*2/5
		} else {
			projected = amt + (edge.capacity-amt)*3/5
		}
	}
	if projected > belief.estimate {
		belief.estimate = projected
	}
	if belief.upperFail > belief.lowerOK &&
		belief.estimate >= belief.upperFail {

		belief.estimate = belief.lowerOK +
			(belief.upperFail-belief.lowerOK)/2
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 3 / 10
	if estimate < belief.lowerOK {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid reported route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		return nil
	}

	r.planned = nil
	r.routeFails[candidateRouteSignature(rt)]++

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 3)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 4

	default:
		r.suspect[key] += 3
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.032))
	p := 0.47*lowMode + 0.53*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ceiling := failure.upper * 3 / 5
		if ceiling == 0 {
			ceiling = 1
		}
		if total > ceiling {
			return 0
		}

		retryScale = 0.52 / math.Sqrt(float64(failure.count))
		if retryScale < 0.15 {
			retryScale = 0.15
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.006 * retryScale
	}

	switch {
	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence := 0.99 - 0.98*pos
		confidence := 0.70 + 0.04*math.Min(
			5, float64(belief.successes+belief.failures),
		)
		p = (1-confidence)*p + confidence*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.94*(ratio-0.45)/0.55
			if scale < 0.04 {
				scale = 0.04
			}
			p *= scale
		}

	case belief.lowerOK > 0 && total > belief.lowerOK:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.52 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.68*p + 0.32*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 500_000.0
		hopPenalty = 260.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 30_000
			edgeScore += float64(r.suspect[edge.key]) * 320_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 420_000 +
					0.0008*float64(r.reserved[edge.key])
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	return r.buildPathRoute(amt, path)
}

func (r *candidateRouter) buildPathRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 || len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.policyAllows(amtOver[i]) {
			return nil, errors.New("path policy does not allow amount")
		}

		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func (r *candidateRouter) routePath(rt *route.Route) (
	[]*candidateEdge, bool) {

	path := make([]*candidateEdge, len(rt.Hops))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return nil, false
		}
		edge, ok := r.edges[key]
		if !ok {
			return nil, false
		}
		path[i] = edge
	}
	return path, true
}

func (r *candidateRouter) routeLogProbability(rt *route.Route) (
	float64, bool) {

	logProb := 0.0
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0, false
		}
		edge, ok := r.edges[key]
		if !ok {
			return 0, false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0, false
		}

		p := r.probability(edge, amt)
		if p <= 0 {
			return 0, false
		}
		logProb += math.Log(p)
	}
	return logProb, true
}

func (r *candidateRouter) pathCeiling(seed *route.Route,
	max lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	path, ok := r.routePath(seed)
	if !ok {
		return candidateFinalAmount(seed)
	}

	low := candidateFinalAmount(seed)
	if low > max {
		low = max
	}
	high := max

	for low < high {
		mid := low + (high-low+1)/2
		rt, err := r.buildPathRoute(mid, path)
		if err != nil {
			high = mid - 1
			continue
		}

		logProb, ok := r.routeLogProbability(rt)
		if !ok || logProb < math.Log(0.035) {
			high = mid - 1
			continue
		}

		acceptable := true
		for i := range rt.Hops {
			key, _ := candidateRouteEdgeKey(rt, i)
			edge := r.edges[key]
			amt, _ := candidateRouteAmount(rt, i)
			if r.probability(edge, amt) < 0.10 {
				acceptable = false
				break
			}
		}
		if !acceptable {
			high = mid - 1
			continue
		}

		low = mid
	}

	return low
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planningSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base*3/4, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	seed, _, err := r.findRoute(base)
	if err == nil {
		ceiling := r.pathCeiling(seed, remaining)
		candidateAddAmount(
			&sizes, seen, ceiling*3/5, remaining,
		)
		candidateAddAmount(
			&sizes, seen, ceiling*4/5, remaining,
		)
		candidateAddAmount(&sizes, seen, ceiling, remaining)
	}

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/5, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*2/5, remaining,
		)
	}

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] < sizes[j]
	})
	return sizes
}

func (r *candidateRouter) planOnce(total lnwire.MilliSatoshi,
	parts uint32, sizeBias float64) ([]*route.Route, float64, bool) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	remaining := total
	slots := parts
	var plan []*route.Route
	jointScore := 0.0

	for remaining > 0 && slots > 0 {
		if slots == 1 {
			rt, logProb, err := r.findRoute(remaining)
			if err != nil {
				return nil, 0, false
			}
			fees := rt.TotalAmount - remaining
			jointScore += logProb -
				float64(fees)/4_500_000 - 0.035
			plan = append(plan, rt)
			r.reserveRoute(rt)
			remaining = 0
			break
		}

		base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
			lnwire.MilliSatoshi(slots)
		sizes := r.planningSizes(remaining, slots)

		var bestRoute *route.Route
		bestSize := lnwire.MilliSatoshi(0)
		bestLogProb := 0.0
		bestUtility := math.Inf(-1)

		for _, size := range sizes {
			rt, logProb, err := r.findRoute(size)
			if err != nil {
				continue
			}

			left := remaining - size
			if left > 0 {
				saved := candidateCopyReservations(r.reserved)
				r.reserveRoute(rt)
				_, _, completionErr := r.findRoute(
					(left + lnwire.MilliSatoshi(slots-1) - 1) /
						lnwire.MilliSatoshi(slots-1),
				)
				r.reserved = saved
				if completionErr != nil {
					continue
				}
			}

			fees := rt.TotalAmount - size
			sizeReward := math.Log(
				float64(size) / float64(base),
			)
			utility := logProb + sizeBias*sizeReward -
				float64(fees)/4_500_000

			if bestRoute == nil || utility > bestUtility {
				bestRoute = rt
				bestSize = size
				bestLogProb = logProb
				bestUtility = utility
			}
		}

		if bestRoute == nil {
			return nil, 0, false
		}

		fees := bestRoute.TotalAmount - bestSize
		jointScore += bestLogProb -
			float64(fees)/4_500_000 - 0.035

		plan = append(plan, bestRoute)
		r.reserveRoute(bestRoute)
		remaining -= bestSize
		slots--
	}

	if remaining != 0 || len(plan) == 0 {
		return nil, 0, false
	}
	return plan, jointScore, true
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32, inFlight uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	if inFlight == 0 && r.lastFailedShard == 0 {
		full, logProb, err := r.findRoute(total)
		if err == nil && logProb >= math.Log(0.58) {
			return []*route.Route{full}, nil
		}
	}

	biases := []float64{0.25, 0.42, 0.62, 0.85}
	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	for _, bias := range biases {
		plan, score, ok := r.planOnce(total, parts, bias)
		if !ok {
			continue
		}
		if bestPlan == nil || score > bestScore {
			bestPlan = plan
			bestScore = score
		}
	}

	if bestPlan == nil {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			if _, ok := r.routeLogProbability(rt); ok {
				r.planned = r.planned[1:]
				r.recordRouteUse(rt)
				r.attempts++
				return rt, nil
			}
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft, inFlightHtlcs)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 11 / 20
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else {
		belief.estimate =
			(belief.estimate*3 + estimate) / 4
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 3)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 3
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 12
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 40 {
		r.attemptLimit = 40
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		if _, ok := r.edges[key]; ok {
			r.beliefs[key] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	total := amt + r.reserved[edge.key]
	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio <= 0.38:
			retryScale = 0.92
		case ratio <= 0.52:
			retryScale = 0.74
		case ratio <= 0.68:
			retryScale = 0.42
		default:
			retryScale = 0.12
		}
		if failure.count > 2 {
			retryScale *= 0.7
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.004 * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.992 - 0.988*pos
		p = 0.1*p + 0.9*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.34 {
			scale := 1 - 0.96*(ratio-0.34)/0.66
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.68 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.08 * float64(edge.capacity)
		if belief.upperFail > belief.lowerOK && belief.lowerOK > 0 {
			scale = 0.18 * float64(
				belief.upperFail - belief.lowerOK,
			)
		}
		if scale < 1 {
			scale = 1
		}

		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.58*p + 0.42*q
	}

	if belief.successes > belief.failures+1 {
		p += 0.05 * (1 - p)
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateSearchLabel struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	path     []*candidateEdge
	dead     bool
	idx      int
}

type candidateSearchQueue []*candidateSearchLabel

func (q candidateSearchQueue) Len() int {
	return len(q)
}

func (q candidateSearchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateSearchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateSearchQueue) Push(x any) {
	item := x.(*candidateSearchLabel)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateSearchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidatePathContains(path []*candidateEdge, node route.Vertex) bool {
	for _, edge := range path {
		if edge.key.from == node || edge.key.to == node {
			return true
		}
	}
	return false
}

func candidateAcceptLabel(
	labels map[route.Vertex][]*candidateSearchLabel,
	label *candidateSearchLabel) bool {

	current := labels[label.node]
	for _, old := range current {
		if !old.dead && old.score <= label.score &&
			old.required <= label.required {

			return false
		}
	}

	kept := current[:0]
	for _, old := range current {
		if label.score <= old.score &&
			label.required <= old.required {

			old.dead = true
			continue
		}
		kept = append(kept, old)
	}
	kept = append(kept, label)

	const maxLabels = 10
	if len(kept) > maxLabels {
		sort.Slice(kept, func(i, j int) bool {
			a := kept[i].score +
				float64(kept[i].required)*0.000004
			b := kept[j].score +
				float64(kept[j].required)*0.000004
			return a < b
		})
		for _, dropped := range kept[maxLabels:] {
			dropped.dead = true
		}
		kept = kept[:maxLabels]
	}

	labels[label.node] = kept
	return !label.dead
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 430_000.0
		hopPenalty = 260.0
		maxHops    = 12
		maxExpand  = 30000
	)

	start := &candidateSearchLabel{
		node:     r.spec.Target,
		required: amt,
	}
	labels := map[route.Vertex][]*candidateSearchLabel{
		r.spec.Target: {start},
	}
	pq := &candidateSearchQueue{}
	heap.Push(pq, start)

	expansions := 0
	for pq.Len() > 0 && expansions < maxExpand {
		item := heap.Pop(pq).(*candidateSearchLabel)
		if item.dead {
			continue
		}
		if item.node == r.source {
			rt, err := r.buildRoute(item.path, amt)
			if err != nil {
				return nil, 0, err
			}
			return rt, item.logProb, nil
		}
		if len(item.path) >= maxHops {
			continue
		}

		expansions++
		for _, edge := range r.incomingEdges[item.node] {
			if edge.key.from == item.node ||
				candidatePathContains(item.path, edge.key.from) {

				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.edgeUses[edge.key]) * 24000
			edgeScore += float64(r.suspect[edge.key]) * 190000
			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}
			if r.reserved[edge.key] > 0 {
				edgeScore += 280000
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			label := &candidateSearchLabel{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: sending,
				logProb:  item.logProb + math.Log(p),
				path:     path,
			}
			if candidateAcceptLabel(labels, label) {
				heap.Push(pq, label)
			}
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) buildRoute(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	if len(path) == 0 || path[0].key.from != r.source ||
		path[len(path)-1].key.to != r.spec.Target {

		return nil, errors.New("invalid route path")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	for i, edge := range path {
		if !edge.policyAllows(amtOver[i]) {
			return nil, errors.New("route violates channel policy")
		}
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteSignature(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := uint64(0x9e3779b97f4a7c15)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(key.chanID + uint64(i+1)<<48)
		h ^= candidateMix64(candidateVertexHash(key.to))
	}
	return candidateMix64(h)
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserve(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserve(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeAlternatives(
	amt lnwire.MilliSatoshi) []candidateRouteChoice {

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	choices := make([]candidateRouteChoice, 0, 3)

	for tries := 0; tries < 7 && len(choices) < 3; tries++ {
		rt, logProb, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		sig := candidateRouteSignature(rt)
		if !seen[sig] {
			seen[sig] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				logProb: logProb,
			})
		}

		var weakest candidateEdgeKey
		weakestP := 2.0
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			penalties[key] += 410000

			edge := r.edges[key]
			amtOver, amountOK := candidateRouteAmount(rt, i)
			if edge != nil && amountOK {
				p := r.probability(edge, amtOver)
				if p < weakestP {
					weakestP = p
					weakest = key
				}
			}
		}
		if weakestP <= 1 {
			penalties[weakest] += 520000
		}
	}

	return choices
}

func (r *candidateRouter) routePath(
	rt *route.Route) ([]*candidateEdge, bool) {

	path := make([]*candidateEdge, len(rt.Hops))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return nil, false
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, false
		}
		path[i] = edge
	}
	return path, true
}

func (r *candidateRouter) fixedRouteQuality(path []*candidateEdge,
	amt lnwire.MilliSatoshi) (float64, bool) {

	rt, err := r.buildRoute(path, amt)
	if err != nil {
		return 0, false
	}

	logProb := 0.0
	for i, edge := range path {
		amtOver, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0, false
		}
		p := r.probability(edge, amtOver)
		if p < 0.08 {
			return 0, false
		}
		logProb += math.Log(p)
	}

	return logProb, logProb >= -5.2
}

func (r *candidateRouter) reliableLimit(rt *route.Route,
	max lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	path, ok := r.routePath(rt)
	if !ok || max <= 0 {
		return 0
	}

	hi := max
	for _, edge := range path {
		limit := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}
		if edge.key.from == r.source {
			if balance, ok := r.localBalances[edge.key.chanID]; ok &&
				balance < limit {

				limit = balance
			}
		}
		if failure := r.currentFails[edge.key]; failure.upper > 0 &&
			failure.upper-1 < limit {

			limit = failure.upper - 1
		}
		limit -= r.reserved[edge.key]
		if limit < hi {
			hi = limit
		}
	}
	if hi <= 0 {
		return 0
	}

	var lo lnwire.MilliSatoshi
	for lo < hi {
		mid := lo + (hi-lo+1)/2
		if _, ok := r.fixedRouteQuality(path, mid); ok {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	return lo
}

func candidateAddSize(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		return
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	var sizes []lnwire.MilliSatoshi
	candidateAddSize(&sizes, seen, remaining, remaining)

	if slots <= 1 {
		return sizes
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddSize(&sizes, seen, base/2, remaining)
	candidateAddSize(&sizes, seen, base*3/4, remaining)
	candidateAddSize(&sizes, seen, base, remaining)
	candidateAddSize(&sizes, seen, base*5/4, remaining)
	candidateAddSize(&sizes, seen, base*3/2, remaining)
	candidateAddSize(&sizes, seen, base*2, remaining)

	if r.lastFailedShard > 0 {
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*3/8, remaining,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
	}

	anchors := r.routeAlternatives(base)
	if len(anchors) > 2 {
		anchors = anchors[:2]
	}
	for _, choice := range anchors {
		limit := r.reliableLimit(choice.route, remaining)
		if limit == 0 {
			continue
		}
		candidateAddSize(&sizes, seen, limit*4/5, remaining)
		candidateAddSize(&sizes, seen, limit, remaining)
	}

	sort.Slice(sizes, func(i, j int) bool {
		di := math.Abs(float64(sizes[i] - base))
		dj := math.Abs(float64(sizes[j] - base))
		if di == dj {
			return sizes[i] > sizes[j]
		}
		return di < dj
	})

	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func candidateOverlapPenalty(rt *route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	source route.Vertex) float64 {

	penalty := 0.0
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok || key.from == source {
			continue
		}
		if reservations[key] > 0 {
			penalty += 0.38
		}
	}
	return penalty
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		parts = 1
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	initial := &candidatePlanState{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}
	beam := []*candidatePlanState{initial}
	var best *candidatePlanState

	const beamWidth = 10

	for depth := uint32(0); depth < parts && len(beam) > 0; depth++ {
		var nextBeam []*candidatePlanState

		for _, state := range beam {
			if state.remaining == 0 {
				if best == nil || state.score > best.score {
					best = state
				}
				continue
			}
			if state.slots == 0 {
				continue
			}

			r.reserved = state.reservations
			sizes := r.planSizes(state.remaining, state.slots)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}
				if state.slots == 1 && size != state.remaining {
					continue
				}

				for _, choice := range r.routeAlternatives(size) {
					fees := choice.route.TotalAmount - size
					overlap := candidateOverlapPenalty(
						choice.route, state.reservations,
						r.source,
					)
					score := state.score + choice.logProb -
						float64(fees)/5_000_000 -
						0.045 - overlap

					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserve(reservations, choice.route)

					routes := append(
						[]*route.Route(nil), state.routes...,
					)
					routes = append(routes, choice.route)

					remaining := state.remaining - size
					progress := 1 - float64(remaining)/
						float64(total)

					ns := &candidatePlanState{
						remaining:    remaining,
						slots:        state.slots - 1,
						routes:       routes,
						reservations: reservations,
						score:        score,
						rank:         score + 7.0*progress,
					}

					if remaining == 0 {
						if best == nil || ns.score > best.score {
							best = ns
						}
					} else if ns.slots > 0 {
						nextBeam = append(nextBeam, ns)
					}
				}
			}
		}

		sort.Slice(nextBeam, func(i, j int) bool {
			return nextBeam[i].rank > nextBeam[j].rank
		})
		if len(nextBeam) > beamWidth {
			nextBeam = nextBeam[:beamWidth]
		}
		beam = nextBeam
	}

	if best != nil && len(best.routes) > 0 {
		return best.routes, nil
	}

	r.reserved = savedReservations
	if parts == 1 {
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	sizes := r.planSizes(total, parts)
	var fallback *route.Route
	bestFallback := math.Inf(-1)

	for _, size := range sizes {
		for _, choice := range r.routeAlternatives(size) {
			progress := float64(size) / float64(total)
			score := choice.logProb + 3.5*progress -
				float64(choice.route.TotalAmount-size)/5_000_000
			if score > bestFallback {
				bestFallback = score
				fallback = choice.route
			}
		}
	}

	if fallback == nil {
		return nil, errors.New("no route found")
	}
	return []*route.Route{fallback}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	projected := amt
	if edge := r.edges[key]; edge != nil && edge.capacity > amt {
		if belief.upperFail > amt {
			projected = amt + (belief.upperFail-amt)*2/5
		} else {
			projected = amt + (edge.capacity-amt)*2/3
		}
	}
	if projected > belief.estimate {
		belief.estimate = projected
	}
	if belief.upperFail > belief.lowerOK &&
		belief.estimate >= belief.upperFail {

		belief.estimate = belief.lowerOK +
			(belief.upperFail-belief.lowerOK)/2
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 7 / 20
	if estimate < belief.lowerOK {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid reported route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 4

	default:
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

var _ = fmt.Sprintf

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	attempts     int
	attemptLimit int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 6
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 36 {
		r.attemptLimit = 36
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)

	lowMode := math.Exp(-x / 0.05)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.032))
	p := 0.5*lowMode + 0.5*highMode

	switch {
	case p < 0.004:
		return 0.004
	case p > 0.988:
		return 0.988
	default:
		return p
	}
}

func candidateRetryCeiling(f candidateFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var fraction int64
	switch {
	case f.count <= 1:
		fraction = 68
	case f.count == 2:
		fraction = 54
	default:
		fraction = 42
	}

	ceiling := f.upper * lnwire.MilliSatoshi(fraction) / 100
	if ceiling < 1 {
		ceiling = 1
	}
	return ceiling, true
}

func candidateRetryPenalty(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.72
	case count == 2:
		return 0.55
	default:
		return 0.40
	}
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0
	}

	retryPenalty := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}

		ceiling, exists := candidateRetryCeiling(failure)
		if exists && total > ceiling {
			return 0
		}
		retryPenalty = candidateRetryPenalty(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryPenalty
	}

	prior := candidatePrior(total, edge.capacity)
	belief, known := r.beliefs[edge.key]
	if !known {
		return prior * retryPenalty
	}

	p := prior

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		p = 0.997
	} else if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.004)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		position = math.Max(0, math.Min(1, position))

		evidence := 0.995 - 0.990*position
		p = 0.10*p + 0.90*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.35 {
			scale := 1 - 0.96*(ratio-0.35)/0.65
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.62 * math.Exp(-distance/0.14)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.075 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}

		estimateProbability := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.75*p + 0.25*estimateProbability
	}

	p *= retryPenalty

	switch {
	case p < 0.0005:
		return 0.0005
	case p > 0.998:
		return 0.998
	default:
		return p
	}
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 760_000.0
		hopPenalty = 220.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProbability float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)

		knownScore, ok := bestScore[item.node]
		if !ok || item.score > knownScore+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProbability = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOverEdge := item.required
			probability := r.probability(edge, amountOverEdge)
			if probability <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			sendingAmount := amountOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(probability)) +
				hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 26_000
			edgeScore += float64(r.suspect[edge.key]) * 360_000
			edgeScore += diversity[edge.key]

			if r.reserved[edge.key] > 0 {
				edgeScore += 520_000
			}

			score := item.score + edgeScore
			oldScore, found := bestScore[edge.key.from]
			if found && score >= oldScore {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge

			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sendingAmount,
				logProb:  item.logProb + math.Log(probability),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProbability, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		nextEdge := path[i+1]
		amounts[i] = amounts[i+1] + nextEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(nextEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amountToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amountToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amountToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}

	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}

	hop := rt.Hops[channelIndex]
	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteSignature(rt *route.Route) string {
	if rt == nil {
		return ""
	}

	signature := ""
	for _, hop := range rt.Hops {
		signature += fmt.Sprintf("/%d", hop.ChannelID)
	}
	return signature
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) findDiverseRoutes(amt lnwire.MilliSatoshi,
	count int) []candidateRouteChoice {

	diversity := make(map[candidateEdgeKey]float64)
	seen := make(map[string]bool)
	choices := make([]candidateRouteChoice, 0, count)

	maxSearches := count * 3
	for search := 0; search < maxSearches && len(choices) < count; search++ {
		rt, logProbability, err := r.findRoute(amt, diversity)
		if err != nil {
			break
		}

		signature := candidateRouteSignature(rt)
		if !seen[signature] {
			seen[signature] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				logProb: logProbability,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}

			penalty := 900_000.0
			if key.from == r.source {
				penalty = 580_000
			}
			diversity[key] += penalty
		}
	}

	return choices
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	copyMap := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		copyMap[key] = amount
	}
	return copyMap
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	if rt == nil {
		return
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amount
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}

	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateScale(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}

	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) /
			float64(denominator),
	)
}

func candidateAddSize(sizes *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, amount,
	maximum lnwire.MilliSatoshi) {

	if amount < 1 {
		amount = 1
	}
	if amount > maximum {
		amount = maximum
	}
	if !seen[amount] {
		seen[amount] = true
		*sizes = append(*sizes, amount)
	}
}

func candidatePlanSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddSize(
		&sizes, seen, candidateScale(base, 1, 2), remaining,
	)
	candidateAddSize(
		&sizes, seen, candidateScale(base, 2, 3), remaining,
	)
	candidateAddSize(
		&sizes, seen, candidateScale(base, 4, 5), remaining,
	)
	candidateAddSize(&sizes, seen, base, remaining)
	candidateAddSize(
		&sizes, seen, candidateScale(base, 6, 5), remaining,
	)
	candidateAddSize(
		&sizes, seen, candidateScale(base, 3, 2), remaining,
	)
	candidateAddSize(&sizes, seen, base*2, remaining)

	if slots > 2 {
		candidateAddSize(&sizes, seen, base*3, remaining)
	}

	candidateAddSize(&sizes, seen, remaining, remaining)

	return sizes
}

func (r *candidateRouter) likelyThreshold(
	edge *candidateEdge) lnwire.MilliSatoshi {

	threshold := candidateScale(edge.capacity, 90, 100)

	if edge.maxHTLC > 0 && edge.maxHTLC < threshold {
		threshold = edge.maxHTLC
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok {
			return 0
		}
		if balance < threshold {
			threshold = balance
		}
		return threshold
	}

	if failure, ok := r.currentFails[edge.key]; ok {
		ceiling, exists := candidateRetryCeiling(failure)
		if exists && ceiling < threshold {
			threshold = ceiling
		}
	}

	belief, known := r.beliefs[edge.key]
	if !known {
		return threshold
	}

	if belief.upperFail > 0 {
		likely := candidateScale(belief.upperFail, 62, 100)
		if belief.lowerOK > likely {
			likely = belief.lowerOK
		}
		if likely >= belief.upperFail {
			likely = belief.upperFail - 1
		}
		if likely < threshold {
			threshold = likely
		}
	} else if belief.lowerOK > 0 {
		likely := belief.lowerOK + candidateScale(
			edge.capacity-belief.lowerOK, 48, 100,
		)
		if likely < threshold {
			threshold = likely
		}
	}

	return threshold
}

func (r *candidateRouter) routeLikelyLimit(
	rt *route.Route) lnwire.MilliSatoshi {

	finalAmount := candidateFinalAmount(rt)
	if finalAmount <= 0 {
		return 0
	}

	maxAdditional := lnwire.MilliSatoshi(math.MaxInt64)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}

		edge := r.edges[key]
		if edge == nil {
			return 0
		}

		amountOver, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0
		}

		threshold := r.likelyThreshold(edge)
		available := threshold - r.reserved[key]
		slack := available - amountOver

		if slack < maxAdditional {
			maxAdditional = slack
		}
	}

	if maxAdditional <= 0 {
		return finalAmount
	}

	limit := finalAmount + maxAdditional
	if limit < finalAmount {
		return finalAmount
	}
	return limit
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState

	const (
		beamWidth      = 14
		maxSizes       = 16
		routesPerSize  = 3
		progressWeight = 3.8
	)

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make(
			[]candidatePlanState, 0, beamWidth*maxSizes,
		)

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}

			sizes := candidatePlanSizes(state.remaining, slots)
			seenSizes := make(map[lnwire.MilliSatoshi]bool)
			for _, size := range sizes {
				seenSizes[size] = true
			}

			for index := 0; index < len(sizes) &&
				index < maxSizes; index++ {

				size := sizes[index]
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				choices := r.findDiverseRoutes(
					size, routesPerSize,
				)

				for _, choice := range choices {
					limit := r.routeLikelyLimit(choice.route)
					if limit > size {
						candidateAddSize(
							&sizes, seenSizes,
							candidateScale(limit, 4, 5),
							state.remaining,
						)
						candidateAddSize(
							&sizes, seenSizes, limit,
							state.remaining,
						)
					}

					newReservations :=
						candidateCopyReservations(
							state.reservations,
						)
					r.reserved = newReservations
					r.reserveRoute(choice.route)

					fee := choice.route.TotalAmount - size
					score := state.score +
						choice.logProb -
						float64(fee)/6_000_000 -
						0.025

					remaining := state.remaining - size
					progress := float64(total-remaining) /
						float64(total)
					rank := score +
						progressWeight*progress

					routes := make(
						[]*route.Route,
						len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, choice.route)

					newState := candidatePlanState{
						remaining:    remaining,
						routes:       routes,
						reservations: newReservations,
						score:        score,
						rank:         rank,
					}
					nextStates = append(
						nextStates, newState,
					)

					if remaining == 0 &&
						(bestComplete == nil ||
							score > bestComplete.score) {

						copyState := newState
						bestComplete = &copyState
					}
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			iComplete := nextStates[i].remaining == 0
			jComplete := nextStates[j].remaining == 0

			if iComplete != jComplete {
				return iComplete
			}
			if nextStates[i].rank == nextStates[j].rank {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no complete route set found")
	}

	return bestComplete.routes, nil
}

func (r *candidateRouter) reactiveShard(
	remaining lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts <= 1 {
		choices := r.findDiverseRoutes(remaining, 1)
		if len(choices) == 0 {
			return nil, errors.New("no route found")
		}
		return choices[0].route, nil
	}

	sizes := candidatePlanSizes(remaining, parts)
	seen := make(map[lnwire.MilliSatoshi]bool)
	for _, size := range sizes {
		seen[size] = true
	}

	base := (remaining + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	candidateAddSize(
		&sizes, seen, candidateScale(base, 2, 5), remaining,
	)
	candidateAddSize(
		&sizes, seen, candidateScale(base, 3, 5), remaining,
	)

	var best *route.Route
	bestScore := math.Inf(-1)

	for _, size := range sizes {
		if size <= 0 || size >= remaining {
			continue
		}

		choices := r.findDiverseRoutes(size, 2)
		for _, choice := range choices {
			fee := choice.route.TotalAmount - size
			progress := float64(size) / float64(remaining)

			score := choice.logProb +
				2.4*progress -
				float64(fee)/6_000_000

			if score > bestScore {
				bestScore = score
				best = choice.route
			}
		}
	}

	if best == nil {
		return nil, errors.New("no retry shard found")
	}
	return best, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		choices := r.findDiverseRoutes(total, 1)
		if len(choices) == 0 {
			return nil, errors.New("no route found")
		}
		return []*route.Route{choices[0].route}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	shard, shardErr := r.reactiveShard(total, parts)
	if shardErr != nil {
		return nil, err
	}
	return []*route.Route{shard}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)

		if finalAmount > 0 && finalAmount <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}

		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++

	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amount >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]

	if amount > belief.lowerOK {
		belief.lowerOK = amount
	}
	if belief.upperFail > 0 && amount >= belief.upperFail {
		belief.upperFail = 0
	}

	if belief.estimate == 0 {
		belief.estimate = amount
	} else if amount > belief.estimate {
		belief.estimate = candidateScale(
			belief.estimate, 1, 3,
		) + candidateScale(amount, 2, 3)
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amount lnwire.MilliSatoshi) {

	if amount <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amount < current.upper {
		current.upper = amount
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]

	if belief.upperFail == 0 || amount < belief.upperFail {
		belief.upperFail = amount
	}
	if belief.lowerOK >= amount {
		belief.lowerOK = 0
	}

	estimate := candidateScale(amount, 9, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}

	if belief.estimate == 0 || belief.estimate >= amount {
		belief.estimate = estimate
	} else {
		belief.estimate = candidateScale(
			belief.estimate, 2, 3,
		) + candidateScale(estimate, 1, 3)
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	if rt == nil {
		return
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}

			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}

			r.learnSuccess(key, amount+r.reserved[key])
		}

		r.held = append(r.held, rt)
		return nil
	}

	r.planned = nil

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passedChannels := failureIndex
	if passedChannels > len(rt.Hops) {
		passedChannels = len(rt.Hops)
	}

	for i := 0; i < passedChannels; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}

		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	amountOver, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	totalRequired := amountOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	// Every successful shard either remains held in an atomic MPP or has
	// already consumed directional liquidity in a non-atomic payment.
	// Both therefore remain reservations for the lifetime of this router.
	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	accepted []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 6
	if r.attemptLimit < 14 {
		r.attemptLimit = 14
	}
	if r.attemptLimit > 30 {
		r.attemptLimit = 30
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateRetryScale(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.24
	case count == 2:
		return 0.08
	default:
		return 0.025
	}
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var numerator int64
	switch {
	case f.count <= 1:
		numerator = 72
	case f.count == 2:
		numerator = 54
	default:
		numerator = 38
	}

	ceiling := f.upper * lnwire.MilliSatoshi(numerator) / 100
	if ceiling <= 0 {
		ceiling = 1
	}
	return ceiling, true
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, ok := candidateRetryCeiling(failure); ok &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryScale(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.005)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence := 0.994 - 0.989*pos
		p = 0.13*p + 0.87*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.35 {
			scale := 1 - 0.96*(ratio-0.35)/0.65
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.58 * math.Exp(-distance/0.15)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.09 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.70*p + 0.30*q
	}

	p *= retryScale
	if p < 0.0005 {
		return 0.0005
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 620_000.0
		hopPenalty = 140.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 18_000
			edgeScore += float64(r.suspect[edge.key]) * 310_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 260_000
			}
			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteSignature(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(candidateVertexHash(rt.SourcePubKey))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(
			key.chanID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		h ^= candidateMix64(candidateVertexHash(key.to))
		h = candidateMix64(h)
	}
	return h
}

type candidateRouteChoice struct {
	rt      *route.Route
	logProb float64
	quality float64
}

func (r *candidateRouter) findRouteVariants(amt lnwire.MilliSatoshi,
	limit int) []candidateRouteChoice {

	if limit < 1 {
		limit = 1
	}

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	choices := make([]candidateRouteChoice, 0, limit)

	maxSearches := limit * 3
	for search := 0; search < maxSearches &&
		len(choices) < limit; search++ {

		rt, logProb, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		signature := candidateRouteSignature(rt)
		if !seen[signature] {
			seen[signature] = true
			fees := rt.TotalAmount - amt
			choices = append(choices, candidateRouteChoice{
				rt:      rt,
				logProb: logProb,
				quality: logProb - float64(fees)/3_500_000,
			})
		}

		last := len(rt.Hops) - 1
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}

			add := 720_000.0
			if i == last {
				add = 1_350_000
			} else if i == 0 {
				add = 900_000
			}
			penalties[key] += add
		}
	}

	sort.Slice(choices, func(i, j int) bool {
		return choices[i].quality > choices[j].quality
	})
	return choices
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations() {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)
	for _, rt := range r.accepted {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidateScaledAmount(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func candidatePlanSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 4),
		remaining,
	)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 5, 4),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 2),
		remaining,
	)
	candidateAddAmount(&values, seen, base*2, remaining)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(remaining, 1, 2),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(remaining, 3, 4),
		remaining,
	)
	candidateAddAmount(&values, seen, remaining, remaining)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 1, 2),
		remaining,
	)

	return values
}

func (r *candidateRouter) routeLimit(rt *route.Route) lnwire.MilliSatoshi {
	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 {
		return 0
	}

	limit := lnwire.MilliSatoshi(math.MaxInt64)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}
		edge := r.edges[key]
		if edge == nil {
			return 0
		}

		used, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0
		}

		totalCeiling := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < totalCeiling {
			totalCeiling = edge.maxHTLC
		}

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok {
				return 0
			}
			if balance < totalCeiling {
				totalCeiling = balance
			}
		} else {
			if failure, ok := r.currentFails[key]; ok {
				if ceiling, ok := candidateRetryCeiling(failure); ok &&
					ceiling < totalCeiling {

					totalCeiling = ceiling
				}
			}

			if belief, ok := r.beliefs[key]; ok {
				var likely lnwire.MilliSatoshi
				switch {
				case belief.upperFail > 0:
					likely = candidateScaledAmount(
						belief.upperFail, 68, 100,
					)
					if belief.lowerOK > likely {
						likely = belief.lowerOK
					}
					if likely >= belief.upperFail {
						likely = belief.upperFail - 1
					}

				case belief.lowerOK > 0:
					likely = belief.lowerOK +
						candidateScaledAmount(
							edge.capacity-belief.lowerOK,
							42, 100,
						)
				}
				if likely > 0 && likely < totalCeiling {
					totalCeiling = likely
				}
			} else {
				likely := candidateScaledAmount(
					edge.capacity, 90, 100,
				)
				if likely < totalCeiling {
					totalCeiling = likely
				}
			}
		}

		availableForRoute := totalCeiling - r.reserved[key]
		headroom := availableForRoute - used
		edgeFinalLimit := finalAmt + headroom
		if edgeFinalLimit < limit {
			limit = edgeFinalLimit
		}
	}

	if limit < 1 {
		return 0
	}
	return limit
}

func candidateRouteOverlap(rt *route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	var overlap float64
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok || reservations[key] <= 0 {
			continue
		}
		overlap++
	}
	return overlap
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState
	const beamWidth = 20

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make([]candidatePlanState, 0, beamWidth*12)

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}

			r.reserved = candidateCopyReservations(
				state.reservations,
			)

			sizes := candidatePlanSizes(state.remaining, slots)
			seenSizes := make(map[lnwire.MilliSatoshi]bool)
			for _, size := range sizes {
				seenSizes[size] = true
			}

			if r.lastFailedShard > 0 {
				candidateAddAmount(
					&sizes, seenSizes,
					candidateScaledAmount(
						r.lastFailedShard, 3, 5,
					),
					state.remaining,
				)
				candidateAddAmount(
					&sizes, seenSizes,
					candidateScaledAmount(
						r.lastFailedShard, 2, 5,
					),
					state.remaining,
				)
			}

			for i := 0; i < len(sizes) && i < 14; i++ {
				size := sizes[i]
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				choices := r.findRouteVariants(size, 3)
				for _, choice := range choices {
					r.reserved = candidateCopyReservations(
						state.reservations,
					)

					limit := r.routeLimit(choice.rt)
					if limit > 0 {
						candidateAddAmount(
							&sizes, seenSizes,
							candidateScaledAmount(
								limit, 4, 5,
							),
							state.remaining,
						)
						candidateAddAmount(
							&sizes, seenSizes, limit,
							state.remaining,
						)
					}

					overlap := candidateRouteOverlap(
						choice.rt, state.reservations,
					)

					newReservations :=
						candidateCopyReservations(
							state.reservations,
						)
					r.reserved = newReservations
					r.reserveRoute(choice.rt)

					fees := choice.rt.TotalAmount - size
					score := state.score + choice.logProb -
						float64(fees)/3_500_000 -
						0.025 - 0.09*overlap

					remaining := state.remaining - size
					progress := float64(total-remaining) /
						float64(total)
					rank := score + 4.4*progress

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, choice.rt)

					nextStates = append(
						nextStates, candidatePlanState{
							remaining:    remaining,
							routes:       routes,
							reservations: newReservations,
							score:        score,
							rank:         rank,
						},
					)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			iComplete := nextStates[i].remaining == 0
			jComplete := nextStates[j].remaining == 0
			if iComplete != jComplete {
				return iComplete
			}
			if iComplete {
				return nextStates[i].score > nextStates[j].score
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	for _, state := range states {
		if state.remaining != 0 {
			continue
		}
		if bestComplete == nil || state.score > bestComplete.score {
			copyState := state
			bestComplete = &copyState
		}
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no route set found")
	}

	return bestComplete.routes, nil
}

func (r *candidateRouter) fallbackShard(remaining lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(remaining, nil)
		return rt, err
	}

	sizes := candidatePlanSizes(remaining, parts)
	seen := make(map[lnwire.MilliSatoshi]bool)
	for _, size := range sizes {
		seen[size] = true
	}

	candidateAddAmount(
		&sizes, seen, candidateScaledAmount(remaining, 2, 5),
		remaining,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaledAmount(remaining, 1, 3),
		remaining,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaledAmount(remaining, 1, 4),
		remaining,
	)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen,
			candidateScaledAmount(r.lastFailedShard, 3, 5),
			remaining,
		)
		candidateAddAmount(
			&sizes, seen,
			candidateScaledAmount(r.lastFailedShard, 2, 5),
			remaining,
		)
		candidateAddAmount(
			&sizes, seen,
			candidateScaledAmount(r.lastFailedShard, 1, 4),
			remaining,
		)
	}

	minUseful := (remaining + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var best *candidateRouteChoice
	bestUtility := math.Inf(-1)

	choose := func(requireUseful bool) {
		for _, size := range sizes {
			if size <= 0 || size > remaining {
				continue
			}
			if requireUseful && size < minUseful {
				continue
			}

			choices := r.findRouteVariants(size, 3)
			for _, choice := range choices {
				progress := float64(size) / float64(remaining)
				fees := choice.rt.TotalAmount - size
				utility := choice.logProb + 3.3*progress -
					float64(fees)/3_500_000

				if utility > bestUtility {
					copyChoice := choice
					best = &copyChoice
					bestUtility = utility
				}
			}
		}
	}

	choose(true)
	if best == nil {
		choose(false)
	}
	if best == nil {
		return nil, errors.New("no fallback shard found")
	}
	return best.rt, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	rt, fallbackErr := r.fallbackShard(total, parts)
	if fallbackErr != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations()

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaledAmount(amt, 9, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.accepted = append(r.accepted, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 6
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 48 {
		r.attemptLimit = 48
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	reserved := r.reserved[edge.key]
	total := amt + reserved
	if total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ceiling := failure.upper * 3 / 4
		if ceiling == 0 {
			ceiling = 1
		}
		if total > ceiling {
			return 0
		}

		retryScale = 0.62 / (1 + 0.12*float64(failure.count))
		if retryScale < 0.28 {
			retryScale = 0.28
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	prior := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return prior * retryScale
	}

	p := prior

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.995

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = 0.008

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		evidence := 0.99 - 0.98*position
		p = 0.15*prior + 0.85*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.93*(ratio-0.45)/0.55
			if scale < 0.07 {
				scale = 0.07
			}
			p *= scale
		}

	case belief.lowerOK > 0 && total > belief.lowerOK:
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.55 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateProb := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.72*p + 0.28*estimateProb
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 480_000.0
		hopPenalty = 350.0
	)

	bestScore := make(map[route.Vertex]float64)
	nextEdge := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOverEdge := item.required
			probability := r.probability(edge, amtOverEdge)
			if probability <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOverEdge)
			}
			required := amtOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(probability)) +
				hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 12_000
			edgeScore += float64(r.suspect[edge.key]) * 230_000

			if reserved := r.reserved[edge.key]; reserved > 0 {
				fraction := float64(reserved) /
					float64(edge.capacity)
				edgeScore += 100_000 + 320_000*fraction
			}

			score := item.score + edgeScore
			oldScore, found := bestScore[edge.key.from]
			if found && score >= oldScore {
				continue
			}

			bestScore[edge.key.from] = score
			nextEdge[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: required,
				logProb:  item.logProb + math.Log(probability),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, nextEdge)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	nextEdge map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := nextEdge[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1

	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		outgoing := path[i+1]
		amounts[i] = amounts[i+1] + outgoing.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(outgoing.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	copyMap := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		copyMap[key] = amount
	}
	return copyMap
}

func candidateReserveRoute(reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveRoute(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	maximum lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > maximum {
		value = maximum
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) planningSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	divisor := lnwire.MilliSatoshi(slots)
	base := (remaining + divisor - 1) / divisor
	seen := make(map[lnwire.MilliSatoshi]bool)
	var sizes []lnwire.MilliSatoshi

	candidateAddAmount(&sizes, seen, base/3, remaining)
	candidateAddAmount(&sizes, seen, base/2, remaining)
	candidateAddAmount(&sizes, seen, base*3/4, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, base*3, remaining)

	candidateAddAmount(&sizes, seen, remaining/8, remaining)
	candidateAddAmount(&sizes, seen, remaining/6, remaining)
	candidateAddAmount(&sizes, seen, remaining/4, remaining)
	candidateAddAmount(&sizes, seen, remaining/3, remaining)
	candidateAddAmount(&sizes, seen, remaining/2, remaining)
	candidateAddAmount(&sizes, seen, remaining*2/3, remaining)
	candidateAddAmount(&sizes, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/4, remaining,
		)
	}

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] < sizes[j]
	})
	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if total <= 0 {
		return nil, errors.New("invalid plan amount")
	}
	if parts == 0 {
		return nil, errors.New("no payment parts available")
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	const beamWidth = 20

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		var nextStates []candidatePlanState

		for _, state := range states {
			sizes := r.planningSizes(state.remaining, state.slots)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				rt, logProbability, err := r.findRoute(size)
				if err != nil {
					continue
				}

				reservations := candidateCopyReservations(r.reserved)
				candidateReserveRoute(reservations, rt)

				fees := rt.TotalAmount - size
				score := state.score + logProbability -
					float64(fees)/3_500_000 - 0.025

				routes := make([]*route.Route, len(state.routes)+1)
				copy(routes, state.routes)
				routes[len(state.routes)] = rt

				remaining := state.remaining - size
				if remaining == 0 {
					if bestPlan == nil || score > bestScore {
						bestPlan = routes
						bestScore = score
					}
					continue
				}

				if state.slots <= 1 {
					continue
				}

				servedFraction := float64(total-remaining) /
					float64(total)

				nextStates = append(nextStates, candidatePlanState{
					remaining:    remaining,
					slots:        state.slots - 1,
					routes:       routes,
					reservations: reservations,
					score:        score,
					rank: score +
						2.8*servedFraction,
				})
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			return nextStates[i].rank > nextStates[j].rank
		})
		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if bestPlan == nil {
		return nil, errors.New("no route-set plan found")
	}
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if belief.estimate == 0 || amt > belief.estimate {
		belief.estimate = amt
	} else {
		belief.estimate = (3*belief.estimate + amt) / 4
	}
	belief.successes++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else {
		belief.estimate = (belief.estimate + estimate) / 2
	}
	belief.failures++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil {
		return errors.New("attempt reported without route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amount+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	passedEdges := failureIndex
	if passedEdges > len(rt.Hops) {
		passedEdges = len(rt.Hops)
	}
	for i := 0; i < passedEdges; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amount, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amount + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	attempts     int
	attemptLimit int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*3 + 8
	if r.attemptLimit < 16 {
		r.attemptLimit = 16
	}
	if r.attemptLimit > 56 {
		r.attemptLimit = 56
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.052)
	highMode := 1 / (1 + math.Exp((x-0.935)/0.032))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.987 {
		return 0.987
	}
	return p
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var numerator int64
	switch {
	case f.count <= 1:
		numerator = 70
	case f.count == 2:
		numerator = 53
	default:
		numerator = 39
	}

	ceiling := f.upper * lnwire.MilliSatoshi(numerator) / 100
	if ceiling < 1 {
		ceiling = 1
	}
	return ceiling, true
}

func candidateRetryScale(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.62
	case count == 2:
		return 0.43
	default:
		return 0.29
	}
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity ||
		r.policyBlocked[edge.key] {

		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, ok := candidateRetryCeiling(failure); ok &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryScale(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.997

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = math.Min(p, 0.003)

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.996 - 0.992*pos
		p = 0.10*p + 0.90*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.35 {
			scale := 1 - 0.97*(ratio-0.35)/0.65
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}

	case belief.lowerOK > 0:
		remaining := float64(edge.capacity - belief.lowerOK)
		scale := 0.08 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		distance := float64(total - belief.lowerOK)
		if distance < 0 {
			distance = 0
		}
		boost := 0.72 * math.Exp(-distance/(remaining+scale))
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.075 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.76*p + 0.24*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}
	return r.liquidityProbability(edge, amt+r.reserved[edge.key])
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 540_000.0
		hopPenalty = 190.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += extraPenalty[edge.key]
			edgeScore += float64(r.edgeUses[edge.key]) * 12_000
			edgeScore += float64(r.suspect[edge.key]) * 175_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 120_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	logProb, err := r.routeLogProbability(rt)
	if err != nil {
		return nil, 0, err
	}
	return rt, logProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	return candidateBuildPath(r.source, amt, path)
}

func candidateBuildPath(source route.Vertex, amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 || len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func (r *candidateRouter) routeEdges(rt *route.Route) (
	[]*candidateEdge, error) {

	if rt == nil || len(rt.Hops) == 0 {
		return nil, errors.New("invalid route")
	}

	path := make([]*candidateEdge, len(rt.Hops))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return nil, errors.New("invalid route edge")
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, errors.New("route edge not found")
		}
		path[i] = edge
	}
	return path, nil
}

func (r *candidateRouter) routeLogProbability(rt *route.Route) (
	float64, error) {

	var logProb float64
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0, errors.New("invalid route edge")
		}
		edge := r.edges[key]
		if edge == nil {
			return 0, errors.New("unknown route edge")
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0, errors.New("invalid route amount")
		}
		p := r.probability(edge, amt)
		if p <= 0 {
			return 0, errors.New("route is no longer feasible")
		}
		logProb += math.Log(p)
	}
	return logProb, nil
}

func candidateScaled(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value < 1 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) likelyTotal(edge *candidateEdge) (
	lnwire.MilliSatoshi, bool) {

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		return balance, ok
	}

	belief, ok := r.beliefs[edge.key]
	if !ok {
		return candidateScaled(edge.capacity, 86, 100), true
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		limit := belief.lowerOK + candidateScaled(
			belief.upperFail-belief.lowerOK, 11, 20,
		)
		if limit >= belief.upperFail {
			limit = belief.upperFail - 1
		}
		return limit, true
	}

	if belief.upperFail > 0 {
		limit := candidateScaled(belief.upperFail, 58, 100)
		if belief.lowerOK > limit {
			limit = belief.lowerOK
		}
		if limit >= belief.upperFail {
			limit = belief.upperFail - 1
		}
		return limit, true
	}

	if belief.lowerOK > 0 {
		limit := candidateScaled(edge.capacity, 92, 100)
		if belief.lowerOK > limit {
			limit = belief.lowerOK
		}
		return limit, true
	}

	return candidateScaled(edge.capacity, 86, 100), true
}

func (r *candidateRouter) pathCheck(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi, likely bool) (*route.Route, bool, bool) {

	rt, err := candidateBuildPath(r.source, finalAmt, path)
	if err != nil {
		return nil, false, false
	}

	tooSmall := false
	tooLarge := false

	for i, edge := range path {
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return nil, false, false
		}

		if amt < edge.minHTLC {
			tooSmall = true
			continue
		}
		if amt > edge.capacity ||
			(edge.maxHTLC > 0 && amt > edge.maxHTLC) {

			tooLarge = true
			continue
		}
		if r.policyBlocked[edge.key] {
			tooLarge = true
			continue
		}

		total := amt + r.reserved[edge.key]
		if total > edge.capacity {
			tooLarge = true
			continue
		}

		if edge.key.from == r.source {
			balance, ok := r.localBalances[edge.key.chanID]
			if !ok || total > balance {
				tooLarge = true
			}
		}

		if failure, ok := r.currentFails[edge.key]; ok {
			if failure.upper > 0 && total >= failure.upper {
				tooLarge = true
			}
			if ceiling, ok := candidateRetryCeiling(failure); ok &&
				total > ceiling {

				tooLarge = true
			}
		}

		if likely {
			limit, ok := r.likelyTotal(edge)
			if !ok || total > limit {
				tooLarge = true
			}
		}
	}

	if tooLarge {
		return nil, false, false
	}
	if tooSmall {
		return nil, false, true
	}
	return rt, true, false
}

func (r *candidateRouter) pathLimit(path []*candidateEdge,
	max lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if max <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(1)
	high := max
	best := lnwire.MilliSatoshi(0)

	for low <= high {
		mid := low + (high-low)/2
		_, fits, tooSmall := r.pathCheck(path, mid, true)

		switch {
		case fits:
			best = mid
			low = mid + 1
		case tooSmall:
			low = mid + 1
		default:
			high = mid - 1
		}
	}

	return best
}

type candidateRouteChoice struct {
	route   *route.Route
	path    []*candidateEdge
	logProb float64
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}
	h := uint64(1469598103934665603)
	for i, hop := range rt.Hops {
		h ^= candidateMix64(hop.ChannelID + uint64(i+1))
		h *= 1099511628211
	}
	return h
}

func (r *candidateRouter) routeVariants(amt lnwire.MilliSatoshi,
	count int) []candidateRouteChoice {

	penalty := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	var choices []candidateRouteChoice

	for pass := 0; pass < count*3 && len(choices) < count; pass++ {
		rt, logProb, err := r.findRoute(amt, penalty)
		if err != nil {
			break
		}

		path, err := r.routeEdges(rt)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				path:    path,
				logProb: logProb,
			})
		}

		last := len(path) - 1
		for i, edge := range path {
			add := 390_000.0
			if i == 0 {
				add = 650_000
			}
			if i == last {
				add = 1_100_000
			}
			penalty[edge.key] += add
		}
	}

	return choices
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func candidateSeedSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	var sizes []lnwire.MilliSatoshi

	candidateAddAmount(&sizes, seen, remaining, remaining)
	if slots <= 1 {
		return sizes
	}

	equal := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddAmount(&sizes, seen, equal, remaining)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 2, 3), remaining,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 3, 2), remaining,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaled(remaining, 1, 2), remaining,
	)

	return sizes
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState
	const beamWidth = 26

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		var nextStates []candidatePlanState

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}

			r.reserved = candidateCopyReservations(
				state.reservations,
			)

			equal := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			choiceSeen := make(map[uint64]bool)
			for _, seed := range candidateSeedSizes(
				state.remaining, slots,
			) {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				variants := r.routeVariants(seed, 4)
				for _, variant := range variants {
					limit := r.pathLimit(
						variant.path, state.remaining,
					)

					amountSeen := make(
						map[lnwire.MilliSatoshi]bool,
					)
					var amounts []lnwire.MilliSatoshi

					candidateAddAmount(
						&amounts, amountSeen, seed,
						state.remaining,
					)
					if limit > 0 {
						candidateAddAmount(
							&amounts, amountSeen, limit,
							state.remaining,
						)
						candidateAddAmount(
							&amounts, amountSeen,
							candidateScaled(limit, 4, 5),
							state.remaining,
						)
						if equal < limit {
							candidateAddAmount(
								&amounts, amountSeen, equal,
								state.remaining,
							)
						}
					}

					for _, shard := range amounts {
						r.reserved = candidateCopyReservations(
							state.reservations,
						)

						rt, fits, _ := r.pathCheck(
							variant.path, shard, false,
						)
						if !fits {
							continue
						}

						choiceKey := candidateRouteHash(rt) ^
							candidateMix64(uint64(shard))
						if choiceSeen[choiceKey] {
							continue
						}
						choiceSeen[choiceKey] = true

						logProb, err := r.routeLogProbability(rt)
						if err != nil {
							continue
						}

						newReservations :=
							candidateCopyReservations(
								state.reservations,
							)
						r.reserved = newReservations
						r.reserveRoute(rt)

						fees := rt.TotalAmount - shard
						score := state.score + logProb -
							float64(fees)/5_000_000 - 0.025

						remaining := state.remaining - shard
						progress := float64(total-remaining) /
							float64(total)
						rank := score + 4.2*progress

						routes := make(
							[]*route.Route, len(state.routes),
							len(state.routes)+1,
						)
						copy(routes, state.routes)
						routes = append(routes, rt)

						nextStates = append(
							nextStates, candidatePlanState{
								remaining: remaining,
								routes: routes,
								reservations: newReservations,
								score: score,
								rank: rank,
							},
						)
					}
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			iComplete := nextStates[i].remaining == 0
			jComplete := nextStates[j].remaining == 0
			if iComplete != jComplete {
				return iComplete
			}
			if nextStates[i].rank == nextStates[j].rank {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	for _, state := range states {
		if state.remaining != 0 {
			continue
		}
		if bestComplete == nil || state.score > bestComplete.score {
			copyState := state
			bestComplete = &copyState
		}
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no route set found")
	}

	plan := append([]*route.Route(nil), bestComplete.routes...)
	sort.SliceStable(plan, func(i, j int) bool {
		return candidateFinalAmount(plan[i]) >
			candidateFinalAmount(plan[j])
	})

	return plan, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	rt, _, singleErr := r.findRoute(total, nil)
	if singleErr != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) plannedRouteValid(rt *route.Route,
	remaining lnwire.MilliSatoshi) bool {

	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 || finalAmt > remaining {
		return false
	}

	path, err := r.routeEdges(rt)
	if err != nil {
		return false
	}
	_, fits, _ := r.pathCheck(path, finalAmt, false)
	return fits
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		if r.plannedRouteValid(rt, amt) {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	targetEstimate := candidateScaled(
		r.edges[key].capacity, 90, 100,
	)
	if targetEstimate < amt {
		targetEstimate = amt
	}
	if targetEstimate > belief.estimate {
		belief.estimate = targetEstimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaled(amt, 9, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.suspect[key]++
	}

	return nil
}

package main

import (
