const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 8
	if r.attemptLimit < 18 {
		r.attemptLimit = 18
	}
	if r.attemptLimit > 36 {
		r.attemptLimit = 36
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}
	if amt <= 0 {
		return 0.985
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probabilityTotal(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total < 0 || total > edge.capacity || r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio <= 0.42:
			retryScale = 0.90
		case ratio <= 0.60:
			retryScale = 0.66
		case ratio <= 0.75:
			retryScale = 0.34
		default:
			retryScale = 0.12
		}
		if failure.count > 2 {
			retryScale *= 0.78
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		return 0.004 * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		evidence := 0.994 - 0.988*position
		p = 0.10*p + 0.90*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.35 {
			scale := 1 - 0.95*(ratio-0.35)/0.65
			if scale < 0.03 {
				scale = 0.03
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.68 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.08 * float64(edge.capacity)
		if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
			scale = 0.16 * float64(
				belief.upperFail - belief.lowerOK,
			)
		}
		if scale < 1 {
			scale = 1
		}

		estimateProb := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.67*p + 0.33*estimateProb
	}

	if belief.successes > belief.failures+1 {
		p += 0.06 * (1 - p)
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	shardAmt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(shardAmt) {
		return 0
	}

	total := shardAmt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0
	}

	return r.probabilityTotal(edge, total)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	last := len(old) - 1
	item := old[last]
	*q = old[:last]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 475_000.0
		hopPenalty = 230.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amountOverEdge := item.required
			p := r.probability(edge, amountOverEdge)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			sending := amountOverEdge + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 14_000
			edgeScore += float64(r.suspect[edge.key]) * 190_000
			edgeScore += extraPenalty[edge.key]

			if reserved := r.reserved[edge.key]; reserved > 0 {
				reuse := 260_000.0
				if edge.key.to == r.spec.Target {
					reuse = 620_000
				}
				reuse += 220_000 * float64(reserved) /
					math.Max(1, float64(edge.capacity))
				edgeScore += reuse
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))

	last := len(path) - 1
	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmount := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			forwardAmount = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmount,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteSignature(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := uint64(0)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(key.chanID + uint64(i+1)<<48)
		h ^= candidateMix64(candidateVertexHash(key.to))
	}
	return candidateMix64(h)
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	copyMap := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		copyMap[key] = amount
	}
	return copyMap
}

func candidateReserve(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amount
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserve(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

type candidateRouteChoice struct {
	route *route.Route
}

func (r *candidateRouter) routeAlternatives(
	amt lnwire.MilliSatoshi) []candidateRouteChoice {

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	choices := make([]candidateRouteChoice, 0, 4)

	for tries := 0; tries < 7 && len(choices) < 4; tries++ {
		rt, _, err := r.findRoute(amt, penalties)
		if err != nil {
			break
		}

		signature := candidateRouteSignature(rt)
		if !seen[signature] {
			seen[signature] = true
			choices = append(choices, candidateRouteChoice{
				route: rt,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}

			penalty := 790_000.0
			if key.to == r.spec.Target {
				penalty = 1_180_000
			}
			penalties[key] += penalty
		}
	}

	return choices
}

func candidateAddSize(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	maximum lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > maximum {
		value = maximum
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) shardSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	var sizes []lnwire.MilliSatoshi

	candidateAddSize(&sizes, seen, remaining, remaining)
	if slots <= 1 {
		return sizes
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddSize(&sizes, seen, base*2/3, remaining)
	candidateAddSize(&sizes, seen, base*4/5, remaining)
	candidateAddSize(&sizes, seen, base, remaining)
	candidateAddSize(&sizes, seen, base*6/5, remaining)
	candidateAddSize(&sizes, seen, base*3/2, remaining)
	candidateAddSize(&sizes, seen, base*2, remaining)

	if r.lastFailedShard > 0 {
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*2/5, remaining,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*3/5, remaining,
		)
		candidateAddSize(
			&sizes, seen, r.lastFailedShard*2/3, remaining,
		)
	}

	return sizes
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planScore(routes []*route.Route,
	reservations,
	baseReservations map[candidateEdgeKey]lnwire.MilliSatoshi) float64 {

	score := 0.0

	for key, total := range reservations {
		base := baseReservations[key]
		if total <= base {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		newProbability := r.probabilityTotal(edge, total)
		if newProbability <= 0 {
			return math.Inf(-1)
		}

		if base > 0 {
			oldProbability := r.probabilityTotal(edge, base)
			if oldProbability <= 0 {
				oldProbability = 0.995
			}

			incremental := newProbability / oldProbability
			if incremental > 0.999 {
				incremental = 0.999
			}
			if incremental < 0.001 {
				incremental = 0.001
			}
			score += math.Log(incremental)
		} else {
			score += math.Log(newProbability)
		}
	}

	for _, rt := range routes {
		finalAmount := candidateFinalAmount(rt)
		fees := rt.TotalAmount - finalAmount
		score -= float64(fees) / 4_500_000
		score -= 0.022
	}

	return score
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		parts = 1
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	initial := &candidatePlanState{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}

	beam := []*candidatePlanState{initial}
	var best *candidatePlanState

	const beamWidth = 12
	initialAverage := float64(total) / float64(parts)
	if initialAverage < 1 {
		initialAverage = 1
	}

	for depth := uint32(0); depth < parts && len(beam) > 0; depth++ {
		var nextBeam []*candidatePlanState

		for _, state := range beam {
			if state.remaining == 0 {
				if best == nil || state.score > best.score {
					best = state
				}
				continue
			}
			if state.slots == 0 {
				continue
			}

			r.reserved = state.reservations
			sizes := r.shardSizes(state.remaining, state.slots)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				for _, choice := range r.routeAlternatives(size) {
					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserve(reservations, choice.route)

					routes := append(
						[]*route.Route(nil), state.routes...,
					)
					routes = append(routes, choice.route)

					remaining := state.remaining - size
					slots := state.slots - 1
					score := r.planScore(
						routes, reservations,
						savedReservations,
					)
					if math.IsInf(score, -1) {
						continue
					}

					progress := 1 - float64(remaining)/
						float64(total)
					rank := score + 9.0*progress

					if remaining > 0 && slots > 0 {
						futureAverage := float64(remaining) /
							float64(slots)
						pressure := futureAverage /
							initialAverage
						if pressure > 1 {
							excess := pressure - 1
							rank -= 5.5 * excess * excess
						}
					}

					next := &candidatePlanState{
						remaining:    remaining,
						slots:        slots,
						routes:       routes,
						reservations: reservations,
						score:        score,
						rank:         rank,
					}

					if remaining == 0 {
						if best == nil || next.score > best.score {
							best = next
						}
					} else if slots > 0 {
						nextBeam = append(nextBeam, next)
					}
				}
			}
		}

		sort.Slice(nextBeam, func(i, j int) bool {
			return nextBeam[i].rank > nextBeam[j].rank
		})
		if len(nextBeam) > beamWidth {
			nextBeam = nextBeam[:beamWidth]
		}
		beam = nextBeam
	}

	if best == nil || len(best.routes) == 0 {
		r.reserved = savedReservations
		rt, _, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	return best.routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) routeStillUsable(rt *route.Route,
	remaining lnwire.MilliSatoshi) bool {

	if rt == nil {
		return false
	}

	finalAmount := candidateFinalAmount(rt)
	if finalAmount <= 0 || finalAmount > remaining {
		return false
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil {
			return false
		}
		amount, ok := candidateRouteAmount(rt, i)
		if !ok || r.probability(edge, amount) <= 0 {
			return false
		}
	}

	return true
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		if r.routeStillUsable(rt, amt) {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++

	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	projected := amt
	if edge := r.edges[key]; edge != nil && edge.capacity > amt {
		if belief.upperFail > amt {
			projected = amt + (belief.upperFail-amt)*2/5
		} else {
			projected = amt + (edge.capacity-amt)*2/3
		}
	}
	if projected > belief.estimate {
		belief.estimate = projected
	}
	if belief.upperFail > belief.lowerOK &&
		belief.estimate >= belief.upperFail {

		belief.estimate = belief.lowerOK +
			(belief.upperFail-belief.lowerOK)/2
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 7 / 20
	if estimate < belief.lowerOK {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt ||
		estimate < belief.estimate {

		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid reported route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amount+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteSuspect(rt, 2)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failureIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	amountOverEdge, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amountOverEdge + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.suspect[key] += 2
		r.lastFailedShard = candidateFinalAmount(rt)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts) + 14
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 36 {
		r.attemptLimit = 36
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateClampProbability(p float64) float64 {
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) absoluteProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.9995
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 && total >= failure.upper {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if ok {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.995

		case belief.upperFail > 0 && total >= belief.upperFail:
			p = 0.004

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK:

			width := float64(
				belief.upperFail - belief.lowerOK,
			)
			pos := float64(total-belief.lowerOK) / width
			if pos < 0 {
				pos = 0
			}
			if pos > 1 {
				pos = 1
			}
			evidence := 0.993 - 0.986*pos
			p = 0.1*p + 0.9*evidence

		case belief.upperFail > 0:
			ratio := float64(total) /
				float64(belief.upperFail)
			if ratio > 0.4 {
				scale := 1 - 0.95*(ratio-0.4)/0.6
				if scale < 0.05 {
					scale = 0.05
				}
				p *= scale
			}

		case belief.lowerOK > 0 && total > belief.lowerOK:
			distance := float64(total-belief.lowerOK) /
				float64(edge.capacity)
			boost := 0.6 * math.Exp(-distance/0.15)
			p += boost * (1 - p)
		}

		if belief.estimate > 0 {
			scale := 0.08 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			q := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate)) /
					scale,
			))
			n := belief.successes + belief.failures
			weight := 0.18 + 0.02*float64(n)
			if weight > 0.34 {
				weight = 0.34
			}
			p = (1-weight)*p + weight*q
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.85:
			p *= 0.22
		case ratio > 0.65:
			p *= 0.52
		case ratio > 0.45:
			p *= 0.78
		}
	}

	return candidateClampProbability(p)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if reserved > edge.capacity || amt > edge.capacity-reserved {
		return 0
	}

	total := reserved + amt
	pTotal := r.absoluteProbability(edge, total)
	if pTotal <= 0 {
		return 0
	}
	if reserved == 0 {
		return pTotal
	}

	pReserved := r.absoluteProbability(edge, reserved)
	if pReserved <= 0 {
		return pTotal
	}

	conditional := pTotal / pReserved
	if conditional > 0.999 {
		conditional = 0.999
	}
	if conditional < 0.002 {
		conditional = 0.002
	}
	return conditional
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	excluded map[candidateEdgeKey]bool) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 700_000.0
		hopPenalty = 250.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if excluded != nil && excluded[edge.key] {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee
			if sending < amtOver {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 22_000
			edgeScore += float64(r.suspect[edge.key]) * 270_000

			if reserved := r.reserved[edge.key]; reserved > 0 &&
				edge.key.from != r.source {

				ratio := float64(reserved) /
					float64(edge.capacity)
				edgeScore += 70_000 + 210_000*ratio
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteID(rt *route.Route) uint64 {
	h := uint64(1469598103934665603)
	for i, hop := range rt.Hops {
		h ^= candidateMix64(hop.ChannelID + uint64(i+1))
		h *= 1099511628211
	}
	return candidateMix64(h ^ uint64(candidateFinalAmount(rt)))
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveInto(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveInto(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		return
	}
	if value > max {
		value = max
	}
	if value > 0 && !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) plannerSizes(
	remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)
	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	candidateAddAmount(&values, seen, base*5/8, remaining)
	candidateAddAmount(&values, seen, base*3/4, remaining)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(&values, seen, base*5/4, remaining)
	candidateAddAmount(&values, seen, base*3/2, remaining)
	candidateAddAmount(&values, seen, base*2, remaining)
	candidateAddAmount(&values, seen, remaining/2, remaining)
	candidateAddAmount(&values, seen, remaining*2/3, remaining)
	candidateAddAmount(&values, seen, remaining, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&values, seen, r.lastFailedShard/3, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&values, seen, r.lastFailedShard*2/3, remaining,
		)
	}

	for _, edge := range r.incomingEdges[r.spec.Target] {
		limit := edge.capacity
		if edge.maxHTLC > 0 && edge.maxHTLC < limit {
			limit = edge.maxHTLC
		}

		reserved := r.reserved[edge.key]
		if reserved >= limit {
			continue
		}
		limit -= reserved

		candidateAddAmount(&values, seen, limit/3, remaining)
		candidateAddAmount(&values, seen, limit/2, remaining)
		candidateAddAmount(&values, seen, limit*4/5, remaining)

		if belief, ok := r.beliefs[edge.key]; ok {
			if belief.lowerOK > reserved {
				safe := belief.lowerOK - reserved
				candidateAddAmount(
					&values, seen, safe*4/5, remaining,
				)
				candidateAddAmount(
					&values, seen, safe, remaining,
				)
			}
			if belief.estimate > reserved {
				estimate := belief.estimate - reserved
				candidateAddAmount(
					&values, seen, estimate*3/4,
					remaining,
				)
			}
			if belief.upperFail > reserved {
				ceiling := belief.upperFail - reserved
				candidateAddAmount(
					&values, seen, ceiling/2, remaining,
				)
				candidateAddAmount(
					&values, seen, ceiling*2/3,
					remaining,
				)
			}
		}

		if failure, ok := r.currentFails[edge.key]; ok &&
			failure.upper > reserved {

			ceiling := failure.upper - reserved
			candidateAddAmount(
				&values, seen, ceiling/3, remaining,
			)
			candidateAddAmount(
				&values, seen, ceiling/2, remaining,
			)
			candidateAddAmount(
				&values, seen, ceiling*2/3, remaining,
			)
		}
	}

	sort.SliceStable(values, func(i, j int) bool {
		di := math.Abs(math.Log(
			float64(values[i]) / float64(base),
		))
		dj := math.Abs(math.Log(
			float64(values[j]) / float64(base),
		))
		return di < dj
	})

	const maxSizes = 18
	if len(values) > maxSizes {
		selected := append(
			[]lnwire.MilliSatoshi(nil), values[:maxSizes]...,
		)
		if !seenInAmounts(selected, remaining) {
			selected[len(selected)-1] = remaining
		}
		values = selected
	}

	return values
}

func seenInAmounts(values []lnwire.MilliSatoshi,
	value lnwire.MilliSatoshi) bool {

	for _, current := range values {
		if current == value {
			return true
		}
	}
	return false
}

type candidateRouteOption struct {
	rt      *route.Route
	logProb float64
	score   float64
}

func candidatePlanContribution(rt *route.Route,
	finalAmt lnwire.MilliSatoshi, logProb float64) float64 {

	fees := rt.TotalAmount - finalAmt
	return logProb - float64(fees)/3_000_000 - 0.02
}

func (r *candidateRouter) routeOptions(
	amt lnwire.MilliSatoshi, limit int) []candidateRouteOption {

	first, firstLogProb, err := r.findRoute(amt, nil)
	if err != nil {
		return nil
	}

	options := []candidateRouteOption{{
		rt:      first,
		logProb: firstLogProb,
		score: candidatePlanContribution(
			first, amt, firstLogProb,
		),
	}}
	seen := map[uint64]bool{candidateRouteID(first): true}

	for i := len(first.Hops) - 1; i >= 0 && len(options) < limit; i-- {
		key, ok := candidateRouteEdgeKey(first, i)
		if !ok {
			continue
		}

		excluded := map[candidateEdgeKey]bool{key: true}
		alt, logProb, err := r.findRoute(amt, excluded)
		if err != nil {
			continue
		}

		id := candidateRouteID(alt)
		if seen[id] {
			continue
		}
		seen[id] = true
		options = append(options, candidateRouteOption{
			rt:      alt,
			logProb: logProb,
			score: candidatePlanContribution(
				alt, amt, logProb,
			),
		})
	}

	sort.Slice(options, func(i, j int) bool {
		return options[i].score > options[j].score
	})
	if len(options) > limit {
		options = options[:limit]
	}
	return options
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	routes       []*route.Route
	score        float64
	rank         float64
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if total <= 0 || parts == 0 {
		return nil, errors.New("invalid payment plan request")
	}

	savedReservations := r.reserved
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestPlan []*route.Route
	bestScore := math.Inf(-1)

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		var nextStates []candidatePlanState

		for _, state := range states {
			slotsLeft := parts - uint32(len(state.routes))
			if slotsLeft == 0 || state.remaining <= 0 {
				continue
			}

			r.reserved = state.reservations
			sizes := r.plannerSizes(state.remaining, slotsLeft)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				nextRemaining := state.remaining - size
				if nextRemaining > 0 && slotsLeft <= 1 {
					continue
				}

				optionLimit := 2
				if len(state.routes) > 2 {
					optionLimit = 1
				}
				options := r.routeOptions(size, optionLimit)
				for _, option := range options {
					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserveInto(
						reservations, option.rt,
					)

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, option.rt)

					score := state.score + option.score
					if nextRemaining == 0 {
						if bestPlan == nil || score > bestScore {
							bestScore = score
							bestPlan = routes
						}
						continue
					}

					progress := float64(total-nextRemaining) /
						float64(total)
					nextStates = append(
						nextStates, candidatePlanState{
							remaining: nextRemaining,
							reservations: reservations,
							routes:       routes,
							score:        score,
							rank: score +
								1.8*progress,
						},
					)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			return nextStates[i].rank > nextStates[j].rank
		})

		const beamWidth = 14
		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if bestPlan == nil {
		return nil, errors.New("no payment plan found")
	}
	return bestPlan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := amt
	if edge := r.edges[key]; edge != nil &&
		amt > edge.capacity/14 {

		highEstimate := edge.capacity * 9 / 10
		if highEstimate > estimate {
			estimate = highEstimate
		}
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 2 / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	} else if estimate < belief.estimate {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return nil
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateFailure
	uncertain     map[candidateEdgeKey]candidateFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
	relaxations     int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) +
		0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat) +
		uint64(e.feeRatePPM)<<17)
	x ^= candidateMix64(uint64(e.timeLockDelta) +
		uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateFailure),
		uncertain:      make(map[candidateEdgeKey]candidateFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 10
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 48 {
		r.attemptLimit = 48
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio > 0.78:
			retryScale *= 0.10
		case ratio > 0.62:
			retryScale *= 0.28
		default:
			retryScale *= 0.65
		}
	}

	if failure, ok := r.uncertain[edge.key]; ok &&
		failure.upper > 0 {

		ratio := float64(total) / float64(failure.upper)
		switch {
		case ratio >= 1:
			retryScale *= 0.10
		case ratio > 0.60:
			retryScale *= 0.38
		default:
			retryScale *= 0.72
		}
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		p *= retryScale
		if p < 0.002 {
			return 0.002
		}
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		p *= retryScale
		if p < 0.001 {
			return 0.001
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.99 - 0.98*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.94*(ratio-0.45)/0.55
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.52 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.68*p + 0.32*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 520_000.0
		hopPenalty = 260.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 48_000
			edgeScore += float64(r.suspect[edge.key]) * 340_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 300_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	for i, edge := range path {
		if !edge.policyAllows(amtOver[i]) {
			return nil, errors.New("constructed route violates policy")
		}
		if amtOver[i]+r.reserved[edge.key] > edge.capacity {
			return nil, errors.New("constructed route exceeds capacity")
		}
		if edge.key.from == r.source {
			balance, ok := r.localBalances[edge.key.chanID]
			if !ok || amtOver[i]+r.reserved[edge.key] > balance {
				return nil, errors.New("constructed route exceeds balance")
			}
		}
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planSizes(remaining lnwire.MilliSatoshi,
	slots uint32) []lnwire.MilliSatoshi {

	if slots == 0 {
		return nil
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, remaining, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base/2, remaining)
	candidateAddAmount(&sizes, seen, base*3/4, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, base*3, remaining)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8, remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/4, remaining,
		)
	}

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] > sizes[j]
	})
	return sizes
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if total <= 0 || parts == 0 {
		return nil, errors.New("invalid payment plan")
	}

	const beamWidth = 18

	savedReservations := r.reserved
	defer func() {
		r.reserved = savedReservations
	}()

	initialReservations := candidateCopyReservations(savedReservations)
	beam := []candidatePlanState{{
		remaining:    total,
		reservations: initialReservations,
	}}

	var best *candidatePlanState

	for depth := uint32(0); depth < parts && len(beam) > 0; depth++ {
		slots := parts - depth
		nextBeam := make([]candidatePlanState, 0, len(beam)*6)

		for _, state := range beam {
			if state.remaining == 0 {
				copyState := state
				if best == nil || copyState.score > best.score {
					best = &copyState
				}
				continue
			}

			for _, size := range r.planSizes(state.remaining, slots) {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				rt, logProb, err := r.findRoute(size)
				if err != nil {
					continue
				}

				fees := rt.TotalAmount - size
				routeScore := logProb -
					float64(fees)/8_000_000 - 0.018

				newReservations := candidateCopyReservations(
					state.reservations,
				)
				r.reserved = newReservations
				r.reserveRoute(rt)

				routes := make([]*route.Route, len(state.routes)+1)
				copy(routes, state.routes)
				routes[len(state.routes)] = rt

				remaining := state.remaining - size
				score := state.score + routeScore
				delivered := total - remaining
				progress := float64(delivered) / float64(total)

				newState := candidatePlanState{
					remaining:    remaining,
					routes:       routes,
					reservations: newReservations,
					score:        score,
					rank:         score + 1.15*progress,
				}

				if remaining == 0 {
					copyState := newState
					if best == nil ||
						copyState.score > best.score {

						best = &copyState
					}
					continue
				}

				if depth+1 < parts {
					nextBeam = append(nextBeam, newState)
				}
			}
		}

		sort.Slice(nextBeam, func(i, j int) bool {
			return nextBeam[i].rank > nextBeam[j].rank
		})
		if len(nextBeam) > beamWidth {
			nextBeam = nextBeam[:beamWidth]
		}
		beam = nextBeam
	}

	if best == nil || len(best.routes) == 0 {
		return nil, errors.New("no complete route set found")
	}
	return best.routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil && r.relaxations == 0 {
		r.relaxations++
		r.currentFails = make(map[candidateEdgeKey]candidateFailure)
		r.uncertain = make(map[candidateEdgeKey]candidateFailure)
		plan, err = r.makePlan(amt, partsLeft)
	}
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}
	if failure, ok := r.uncertain[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.uncertain, key)
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markUnknownFailure(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}

		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			continue
		}
		total := amt + r.reserved[key]

		failure := r.uncertain[key]
		if failure.upper == 0 || total < failure.upper {
			failure.upper = total
		}
		failure.count++
		r.uncertain[key] = failure
		r.suspect[key] += 3
	}
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markUnknownFailure(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markUnknownFailure(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markUnknownFailure(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 3
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)

	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.925)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	total := amt + reserved

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}
	if r.policyBlocked[edge.key] {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}

		ratio := float64(total) / float64(failure.upper)
		retryScale = 0.78 - 0.48*ratio
		if retryScale < 0.22 {
			retryScale = 0.22
		}

		if failure.count > 1 {
			retryScale *= math.Pow(
				0.82, float64(failure.count-1),
			)
			if retryScale < 0.12 {
				retryScale = 0.12
			}
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p *= 0.015
		if p < 0.002 {
			p = 0.002
		}
		return p * retryScale
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence := 0.99 - 0.975*pos
		p = 0.15*p + 0.85*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.45 {
			scale := 1 - 0.92*(ratio-0.45)/0.55
			if scale < 0.08 {
				scale = 0.08
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.5 * math.Exp(-distance/0.16)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.1 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.68*p + 0.32*q
	}

	p *= retryScale
	if p < 0.002 {
		return 0.002
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 390_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 16_000
			edgeScore += float64(r.suspect[edge.key]) * 210_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 210_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}
	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}

	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if max <= 0 {
		return
	}
	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidateProjectedAmount(finalAmt, available,
	amountOver, maximum lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if finalAmt <= 0 || available <= 0 || amountOver <= 0 {
		return 0
	}

	projected := float64(finalAmt) * float64(available) /
		float64(amountOver)

	if projected < 1 {
		return 1
	}
	if projected >= float64(maximum) {
		return maximum
	}
	return lnwire.MilliSatoshi(projected)
}

func (r *candidateRouter) routeLimits(rt *route.Route,
	maximum lnwire.MilliSatoshi) (lnwire.MilliSatoshi,
	lnwire.MilliSatoshi) {

	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 {
		return 0, 0
	}

	hardLimit := maximum
	evidenceLimit := maximum
	hasEvidence := false

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		edge := r.edges[key]
		if edge == nil {
			continue
		}

		amountOver, ok := candidateRouteAmount(rt, i)
		if !ok || amountOver <= 0 {
			continue
		}

		reserved := r.reserved[key]
		available := edge.capacity - reserved
		if available <= 0 {
			return 0, 0
		}

		if edge.maxHTLC > 0 && edge.maxHTLC < available {
			available = edge.maxHTLC
		}

		if key.from == r.source {
			balance, exists := r.localBalances[key.chanID]
			if !exists || balance <= reserved {
				return 0, 0
			}
			if balance-reserved < available {
				available = balance - reserved
			}
		}

		if failure, exists := r.currentFails[key]; exists &&
			failure.upper > 0 {

			if failure.upper <= reserved+1 {
				return 0, 0
			}
			bound := failure.upper - reserved - 1
			if bound < available {
				available = bound
			}
		}

		belief, exists := r.beliefs[key]
		if exists && belief.upperFail > 0 {
			if belief.upperFail <= reserved+1 {
				return 0, 0
			}
			bound := belief.upperFail - reserved - 1
			if bound < available {
				available = bound
			}
		}

		projected := candidateProjectedAmount(
			finalAmt, available, amountOver, maximum,
		)
		if projected < hardLimit {
			hardLimit = projected
		}

		var evidence lnwire.MilliSatoshi
		switch {
		case exists && belief.lowerOK > reserved:
			evidence = belief.lowerOK - reserved
		case exists && belief.estimate > reserved:
			evidence = belief.estimate - reserved
		}

		if evidence > 0 {
			projected = candidateProjectedAmount(
				finalAmt, evidence, amountOver, maximum,
			)
			if projected < evidenceLimit {
				evidenceLimit = projected
			}
			hasEvidence = true
		}
	}

	if !hasEvidence {
		evidenceLimit = 0
	}
	return hardLimit, evidenceLimit
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
}

func (r *candidateRouter) planSizes(state candidatePlanState) (
	[]lnwire.MilliSatoshi, error) {

	if state.remaining <= 0 || state.slots == 0 {
		return nil, errors.New("invalid planning state")
	}

	if state.slots == 1 {
		return []lnwire.MilliSatoshi{state.remaining}, nil
	}

	base := (state.remaining + lnwire.MilliSatoshi(state.slots) - 1) /
		lnwire.MilliSatoshi(state.slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, base/2, state.remaining)
	candidateAddAmount(&sizes, seen, base*3/4, state.remaining)
	candidateAddAmount(&sizes, seen, base, state.remaining)
	candidateAddAmount(&sizes, seen, base*5/4, state.remaining)
	candidateAddAmount(&sizes, seen, base*3/2, state.remaining)
	candidateAddAmount(&sizes, seen, base*2, state.remaining)
	candidateAddAmount(&sizes, seen, base*3, state.remaining)
	candidateAddAmount(
		&sizes, seen, state.remaining, state.remaining,
	)

	if r.lastFailedShard > 0 {
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard/2, state.remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*5/8,
			state.remaining,
		)
		candidateAddAmount(
			&sizes, seen, r.lastFailedShard*3/4,
			state.remaining,
		)
	}

	r.reserved = candidateCopyReservations(state.reservations)
	probe, _, err := r.findRoute(base)
	if err == nil {
		hard, evidence := r.routeLimits(probe, state.remaining)

		candidateAddAmount(
			&sizes, seen, hard*7/8, state.remaining,
		)
		candidateAddAmount(
			&sizes, seen, hard, state.remaining,
		)

		if evidence > 0 {
			candidateAddAmount(
				&sizes, seen, evidence*7/8,
				state.remaining,
			)
			candidateAddAmount(
				&sizes, seen, evidence, state.remaining,
			)
		}
	}

	return sizes, nil
}

func candidatePlanRank(state candidatePlanState,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 {
		return state.score
	}

	progress := float64(total-state.remaining) / float64(total)
	return state.score + 1.35*progress
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if total <= 0 || parts == 0 {
		return nil, errors.New("invalid route plan request")
	}
	if parts == 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var completed []candidatePlanState

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		var nextStates []candidatePlanState

		for _, state := range states {
			if state.remaining == 0 {
				completed = append(completed, state)
				continue
			}
			if state.slots == 0 {
				continue
			}

			sizes, err := r.planSizes(state)
			if err != nil {
				continue
			}

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				rt, logProb, err := r.findRoute(size)
				if err != nil {
					continue
				}

				fee := rt.TotalAmount - size
				nextScore := state.score + logProb -
					float64(fee)/4_000_000 - 0.035

				r.reserveRoute(rt)
				nextReservations := candidateCopyReservations(
					r.reserved,
				)

				nextRoutes := make(
					[]*route.Route, len(state.routes), len(state.routes)+1,
				)
				copy(nextRoutes, state.routes)
				nextRoutes = append(nextRoutes, rt)

				next := candidatePlanState{
					remaining: state.remaining - size,
					slots:     state.slots - 1,
					routes:    nextRoutes,
					reservations: nextReservations,
					score:        nextScore,
				}

				if next.remaining == 0 {
					completed = append(completed, next)
				} else if next.slots > 0 {
					nextStates = append(nextStates, next)
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			return candidatePlanRank(nextStates[i], total) >
				candidatePlanRank(nextStates[j], total)
		})

		const beamWidth = 12
		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if len(completed) == 0 {
		return nil, errors.New("no complete route set found")
	}

	sort.Slice(completed, func(i, j int) bool {
		if completed[i].score == completed[j].score {
			return len(completed[i].routes) <
				len(completed[j].routes)
		}
		return completed[i].score > completed[j].score
	})

	return completed[0].routes, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)

		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}

		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid reported route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	attempts     int
	attemptLimit int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 10
	if r.attemptLimit < 14 {
		r.attemptLimit = 14
	}
	if r.attemptLimit > 40 {
		r.attemptLimit = 40
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		if _, ok := r.edges[key]; ok {
			r.beliefs[key] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.050)
	highMode := 1 / (1 + math.Exp((x-0.942)/0.030))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.987 {
		return 0.987
	}
	return p
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var numerator int64
	switch {
	case f.count <= 1:
		numerator = 52
	case f.count == 2:
		numerator = 27
	default:
		numerator = 14
	}

	ceiling := f.upper * lnwire.MilliSatoshi(numerator) / 100
	if ceiling < 1 {
		ceiling = 1
	}
	return ceiling, true
}

func candidateRetryScale(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.70
	case count == 2:
		return 0.49
	default:
		return 0.32
	}
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity ||
		r.policyBlocked[edge.key] {

		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, ok := candidateRetryCeiling(failure); ok &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryScale(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.997

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = math.Min(p, 0.003)

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.997 - 0.994*pos
		p = 0.08*p + 0.92*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.25 {
			scale := 1 - 0.985*(ratio-0.25)/0.75
			if scale < 0.015 {
				scale = 0.015
			}
			p *= scale
		}

	case belief.lowerOK > 0:
		remaining := float64(edge.capacity - belief.lowerOK)
		scale := 0.06 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		distance := float64(total - belief.lowerOK)
		if distance < 0 {
			distance = 0
		}
		boost := 0.78 * math.Exp(-distance/(remaining+scale))
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.065 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.78*p + 0.22*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}
	return r.liquidityProbability(edge, amt+r.reserved[edge.key])
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source equals target")
	}

	const (
		riskWeight = 500_000.0
		hopPenalty = 170.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += extraPenalty[edge.key]
			edgeScore += float64(r.edgeUses[edge.key]) * 4_000
			edgeScore += float64(r.suspect[edge.key]) * 210_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 20_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	return candidateBuildPath(r.source, amt, path)
}

func candidateBuildPath(source route.Vertex, amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 || len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func (r *candidateRouter) routeEdges(rt *route.Route) (
	[]*candidateEdge, error) {

	if rt == nil || len(rt.Hops) == 0 {
		return nil, errors.New("invalid route")
	}

	path := make([]*candidateEdge, len(rt.Hops))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return nil, errors.New("invalid route edge")
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, errors.New("route edge not found")
		}
		path[i] = edge
	}
	return path, nil
}

func candidateScaled(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if max <= 0 {
		return
	}
	if value < 1 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) likelyTotal(edge *candidateEdge) (
	lnwire.MilliSatoshi, bool) {

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		return balance, ok
	}

	belief, ok := r.beliefs[edge.key]
	if !ok {
		return candidateScaled(edge.capacity, 92, 100), true
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		limit := belief.lowerOK + candidateScaled(
			belief.upperFail-belief.lowerOK, 13, 20,
		)
		if limit >= belief.upperFail {
			limit = belief.upperFail - 1
		}
		return limit, true
	}

	if belief.upperFail > 0 {
		limit := candidateScaled(belief.upperFail, 48, 100)
		if belief.lowerOK > limit {
			limit = belief.lowerOK
		}
		if limit >= belief.upperFail {
			limit = belief.upperFail - 1
		}
		return limit, true
	}

	if belief.lowerOK > 0 {
		limit := candidateScaled(edge.capacity, 94, 100)
		if belief.lowerOK > limit {
			limit = belief.lowerOK
		}
		return limit, true
	}

	return candidateScaled(edge.capacity, 92, 100), true
}

func (r *candidateRouter) pathCheck(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi, likely bool) (*route.Route, bool, bool) {

	rt, err := candidateBuildPath(r.source, finalAmt, path)
	if err != nil {
		return nil, false, false
	}

	tooSmall := false
	tooLarge := false

	for i, edge := range path {
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return nil, false, false
		}

		if amt < edge.minHTLC {
			tooSmall = true
			continue
		}
		if amt > edge.capacity ||
			(edge.maxHTLC > 0 && amt > edge.maxHTLC) {

			tooLarge = true
			continue
		}
		if r.policyBlocked[edge.key] {
			tooLarge = true
			continue
		}

		total := amt + r.reserved[edge.key]
		if total > edge.capacity {
			tooLarge = true
			continue
		}

		if edge.key.from == r.source {
			balance, ok := r.localBalances[edge.key.chanID]
			if !ok || total > balance {
				tooLarge = true
			}
		}

		if failure, ok := r.currentFails[edge.key]; ok {
			if failure.upper > 0 && total >= failure.upper {
				tooLarge = true
			}
			if ceiling, ok := candidateRetryCeiling(failure); ok &&
				total > ceiling {

				tooLarge = true
			}
		}

		if likely {
			limit, ok := r.likelyTotal(edge)
			if !ok || total > limit {
				tooLarge = true
			}
		}
	}

	if tooLarge {
		return nil, false, false
	}
	if tooSmall {
		return nil, false, true
	}
	return rt, true, false
}

func (r *candidateRouter) pathLimit(path []*candidateEdge,
	max lnwire.MilliSatoshi, likely bool) lnwire.MilliSatoshi {

	if max <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(1)
	high := max
	best := lnwire.MilliSatoshi(0)

	for low <= high {
		mid := low + (high-low)/2
		_, fits, tooSmall := r.pathCheck(path, mid, likely)

		switch {
		case fits:
			best = mid
			low = mid + 1
		case tooSmall:
			low = mid + 1
		default:
			high = mid - 1
		}
	}

	return best
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}
	h := uint64(1469598103934665603)
	for i, hop := range rt.Hops {
		h ^= candidateMix64(hop.ChannelID + uint64(i+1))
		h *= 1099511628211
	}
	return h
}

type candidatePathChoice struct {
	path []*candidateEdge
	hash uint64
}

func (r *candidateRouter) routeVariants(amt lnwire.MilliSatoshi,
	count int) []*route.Route {

	penalty := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	var routes []*route.Route

	for pass := 0; pass < count*4 && len(routes) < count; pass++ {
		rt, err := r.findRoute(amt, penalty)
		if err != nil {
			break
		}

		path, err := r.routeEdges(rt)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			routes = append(routes, rt)
		}

		last := len(path) - 1
		for i, edge := range path {
			add := 300_000.0
			if i == 0 {
				add = 520_000
			}
			if i == last {
				add = 900_000
			}
			penalty[edge.key] += add
		}
	}

	return routes
}

func candidateDiscoverySizes(total lnwire.MilliSatoshi,
	parts uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	var sizes []lnwire.MilliSatoshi

	if parts == 0 {
		parts = 1
	}
	equal := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	candidateAddAmount(&sizes, seen, total, total)
	candidateAddAmount(&sizes, seen, candidateScaled(total, 1, 2), total)
	candidateAddAmount(&sizes, seen, equal, total)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 3, 4), total,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 1, 2), total,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 1, 3), total,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 1, 6), total,
	)

	return sizes
}

func (r *candidateRouter) discoverPaths(total lnwire.MilliSatoshi,
	parts uint32) []candidatePathChoice {

	seen := make(map[uint64]bool)
	var paths []candidatePathChoice

	for _, size := range candidateDiscoverySizes(total, parts) {
		for _, rt := range r.routeVariants(size, 8) {
			hash := candidateRouteHash(rt)
			if seen[hash] {
				continue
			}
			path, err := r.routeEdges(rt)
			if err != nil {
				continue
			}
			seen[hash] = true
			paths = append(paths, candidatePathChoice{
				path: path,
				hash: hash,
			})
		}
	}

	return paths
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planScore(
	base, reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	routes []*route.Route) float64 {

	var score float64
	for key, total := range reservations {
		if total <= base[key] {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}
		p := r.liquidityProbability(edge, total)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	for _, rt := range routes {
		finalAmt := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmt {
			fees += rt.TotalAmount - finalAmt
		}
	}

	score -= float64(fees) / 5_000_000
	score -= 0.018 * float64(len(routes))
	return score
}

func candidatePlanAmounts(remaining, hard, soft,
	equal lnwire.MilliSatoshi, slots uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	var amounts []lnwire.MilliSatoshi

	if slots <= 1 {
		if remaining <= hard {
			candidateAddAmount(
				&amounts, seen, remaining, remaining,
			)
		}
		return amounts
	}

	if remaining <= hard {
		candidateAddAmount(&amounts, seen, remaining, remaining)
	}
	if equal <= hard {
		candidateAddAmount(&amounts, seen, equal, remaining)
	}

	if soft > 0 {
		candidateAddAmount(&amounts, seen, soft, remaining)
		candidateAddAmount(
			&amounts, seen, candidateScaled(soft, 4, 5),
			remaining,
		)
		candidateAddAmount(
			&amounts, seen, candidateScaled(soft, 3, 5),
			remaining,
		)
	}

	if hard > 0 {
		candidateAddAmount(&amounts, seen, hard, remaining)
		candidateAddAmount(
			&amounts, seen, candidateScaled(hard, 4, 5),
			remaining,
		)
	}

	return amounts
}

func (r *candidateRouter) planRoutes(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no parts available")
	}

	base := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = base
	}()

	paths := r.discoverPaths(total, parts)
	if len(paths) == 0 {
		return nil, errors.New("no candidate paths")
	}

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(base),
	}}
	var best *candidatePlanState

	const beamWidth = 42

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		var next []candidatePlanState

		for _, state := range states {
			if state.remaining <= 0 {
				continue
			}

			equal := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			for _, choice := range paths {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				hard := r.pathLimit(
					choice.path, state.remaining, false,
				)
				if hard <= 0 {
					continue
				}
				soft := r.pathLimit(
					choice.path, state.remaining, true,
				)

				for _, shard := range candidatePlanAmounts(
					state.remaining, hard, soft, equal, slots,
				) {
					r.reserved = candidateCopyReservations(
						state.reservations,
					)
					rt, fits, _ := r.pathCheck(
						choice.path, shard, false,
					)
					if !fits {
						continue
					}

					newReservations :=
						candidateCopyReservations(
							state.reservations,
						)
					r.reserved = newReservations
					r.reserveRoute(rt)

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, rt)

					remaining := state.remaining - shard
					score := r.planScore(
						base, newReservations, routes,
					)
					if math.IsInf(score, -1) {
						continue
					}

					progress := float64(total-remaining) /
						float64(total)
					rank := score + 8.5*progress

					nextState := candidatePlanState{
						remaining:    remaining,
						routes:       routes,
						reservations: newReservations,
						score:        score,
						rank:         rank,
					}
					if remaining == 0 {
						if best == nil ||
							score > best.score {

							copyState := nextState
							best = &copyState
						}
						continue
					}

					next = append(next, nextState)
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			if next[i].rank == next[j].rank {
				return next[i].remaining <
					next[j].remaining
			}
			return next[i].rank > next[j].rank
		})
		if len(next) > beamWidth {
			next = next[:beamWidth]
		}
		states = next
	}

	if best == nil || len(best.routes) == 0 {
		return nil, errors.New("no route set found")
	}

	plan := append([]*route.Route(nil), best.routes...)
	sort.SliceStable(plan, func(i, j int) bool {
		ai := candidateFinalAmount(plan[i])
		aj := candidateFinalAmount(plan[j])
		if ai == aj {
			return len(plan[i].Hops) < len(plan[j].Hops)
		}
		return ai > aj
	})

	return plan, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, err := r.planRoutes(total, parts)
	if err == nil {
		return plan, nil
	}

	rt, singleErr := r.findRoute(total, nil)
	if singleErr == nil {
		return []*route.Route{rt}, nil
	}
	return nil, err
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) plannedRouteValid(rt *route.Route,
	remaining lnwire.MilliSatoshi) bool {

	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 || finalAmt > remaining {
		return false
	}

	path, err := r.routeEdges(rt)
	if err != nil {
		return false
	}
	_, fits, _ := r.pathCheck(path, finalAmt, false)
	return fits
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	for len(r.planned) > 0 {
		rt := r.planned[0]
		r.planned = r.planned[1:]
		if !r.plannedRouteValid(rt, amt) {
			continue
		}

		r.recordRouteUse(rt)
		r.attempts++
		return rt, nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	r.planned = append([]*route.Route(nil), plan[1:]...)

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	targetEstimate := candidateScaled(edge.capacity, 92, 100)
	if targetEstimate < amt {
		targetEstimate = amt
	}
	if targetEstimate > belief.estimate {
		belief.estimate = targetEstimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaled(amt, 7, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func candidateRouteContains(rt *route.Route,
	failed candidateEdgeKey) bool {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok && key == failed {
			return true
		}
	}
	return false
}

func (r *candidateRouter) discardPlannedUsing(
	failed candidateEdgeKey) {

	kept := r.planned[:0]
	for _, rt := range r.planned {
		if !candidateRouteContains(rt, failed) {
			kept = append(kept, rt)
		}
	}
	r.planned = kept
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		return nil
	}

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.planned = nil
		r.markRouteSuspect(rt, 1)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.planned = nil
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.planned = nil
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.discardPlannedUsing(key)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2
		r.discardPlannedUsing(key)

	default:
		r.suspect[key]++
		r.discardPlannedUsing(key)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 10
	if r.attemptLimit < 22 {
		r.attemptLimit = 22
	}
	if r.attemptLimit > 50 {
		r.attemptLimit = 50
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 {
		return 1
	}
	if total > edge.capacity || r.policyBlocked[edge.key] {
		return 0
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 {

		if total >= failure.upper {
			return 0
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if ok {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.995

		case belief.upperFail > 0 && total >= belief.upperFail:
			if p > 0.006 {
				p = 0.006
			}

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK &&
			total > belief.lowerOK:

			width := float64(
				belief.upperFail - belief.lowerOK,
			)
			pos := float64(total-belief.lowerOK) / width
			evidence := 0.99 - 0.98*pos
			p = 0.12*p + 0.88*evidence

		case belief.upperFail > 0:
			ratio := float64(total) /
				float64(belief.upperFail)
			if ratio > 0.25 {
				scale := 1.15 - 1.4*ratio
				if scale < 0.06 {
					scale = 0.06
				}
				if scale > 1 {
					scale = 1
				}
				p *= scale
			}

		case belief.lowerOK > 0 && total > belief.lowerOK:
			distance := float64(total-belief.lowerOK) /
				float64(edge.capacity)
			boost := 0.5 * math.Exp(-distance/0.16)
			p += boost * (1 - p)
		}

		if belief.estimate > 0 &&
			!(belief.lowerOK > 0 && total <= belief.lowerOK) {

			scale := 0.10 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			q := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate)) /
					scale,
			))
			p = 0.72*p + 0.28*q
		}
	}

	if failure, ok := r.currentFails[edge.key]; ok &&
		failure.upper > 0 && total < failure.upper {

		ratio := float64(total) / float64(failure.upper)
		if ratio > 0.25 {
			scale := 1.15 - 1.4*ratio
			if scale < 0.05 {
				scale = 0.05
			}
			if scale > 1 {
				scale = 1
			}
			p *= scale
		}
	}

	if p < 0.001 {
		return 0.001
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

func (r *candidateRouter) conditionalProbability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	oldTotal := r.reserved[edge.key]
	newTotal := oldTotal + amt

	newProbability := r.liquidityProbability(edge, newTotal)
	if newProbability <= 0 {
		return 0
	}
	if oldTotal == 0 {
		return newProbability
	}

	oldProbability := r.liquidityProbability(edge, oldTotal)
	if oldProbability <= 0 {
		return newProbability
	}

	conditional := newProbability / oldProbability
	if conditional > 0.999 {
		return 0.999
	}
	if conditional < 0.001 {
		return 0.001
	}
	return conditional
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	return r.findRouteWithPenalty(amt, nil)
}

func (r *candidateRouter) findRouteWithPenalty(
	amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 380_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.conditionalProbability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			edgeScore += float64(r.edgeUses[edge.key]) * 18_000
			edgeScore += float64(r.suspect[edge.key]) * 95_000
			edgeScore += extraPenalty[edge.key]

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return nil, 0, err
	}

	return rt, sourceLogProb, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)

		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}

	hop := rt.Hops[channelIndex]
	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func candidateReserveRoute(
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	rt *route.Route) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	candidateReserveRoute(r.reserved, rt)
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidatePlanSizes(remaining lnwire.MilliSatoshi, slots uint32,
	lastFailed lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var sizes []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&sizes, seen, remaining, remaining)
	candidateAddAmount(&sizes, seen, base*3, remaining)
	candidateAddAmount(&sizes, seen, base*2, remaining)
	candidateAddAmount(&sizes, seen, base*3/2, remaining)
	candidateAddAmount(&sizes, seen, base*5/4, remaining)
	candidateAddAmount(&sizes, seen, base, remaining)
	candidateAddAmount(&sizes, seen, base*3/4, remaining)

	if lastFailed > 0 {
		candidateAddAmount(
			&sizes, seen, lastFailed*2/3, remaining,
		)
		candidateAddAmount(
			&sizes, seen, lastFailed/2, remaining,
		)
	}

	sort.Slice(sizes, func(i, j int) bool {
		return sizes[i] > sizes[j]
	})

	return sizes
}

func candidateRouteHash(rt *route.Route) uint64 {
	h := candidateMix64(uint64(candidateFinalAmount(rt)))
	for i, hop := range rt.Hops {
		h ^= candidateMix64(
			hop.ChannelID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
	}
	return candidateMix64(h)
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) routeVariants(
	amt lnwire.MilliSatoshi) []candidateRouteChoice {

	const alternativePenalty = 310_000.0

	penalties := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	var choices []candidateRouteChoice

	for variant := 0; variant < 2; variant++ {
		rt, logProb, err := r.findRouteWithPenalty(amt, penalties)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			choices = append(choices, candidateRouteChoice{
				route:   rt,
				logProb: logProb,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if ok {
				penalties[key] += alternativePenalty
			}
		}
	}

	return choices
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	slots        uint32
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	const beamWidth = 16

	originalReservations := r.reserved
	defer func() {
		r.reserved = originalReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		slots:        parts,
		reservations: candidateCopyReservations(originalReservations),
	}}

	var completed []candidatePlanState

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		var next []candidatePlanState

		for _, state := range states {
			r.reserved = state.reservations
			sizes := candidatePlanSizes(
				state.remaining, state.slots,
				r.lastFailedShard,
			)

			for _, size := range sizes {
				if size <= 0 || size > state.remaining {
					continue
				}

				for _, choice := range r.routeVariants(size) {
					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserveRoute(
						reservations, choice.route,
					)

					remaining := state.remaining - size
					fees := choice.route.TotalAmount - size
					score := state.score + choice.logProb -
						float64(fees)/6_000_000 - 0.018

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, choice.route)

					nextState := candidatePlanState{
						remaining:    remaining,
						slots:        state.slots - 1,
						routes:       routes,
						reservations: reservations,
						score:        score,
					}

					if remaining == 0 {
						completed = append(
							completed, nextState,
						)
						continue
					}
					if nextState.slots == 0 {
						continue
					}

					progress := float64(total-remaining) /
						float64(total)
					nextState.rank = score + 0.65*progress
					next = append(next, nextState)
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			return next[i].rank > next[j].rank
		})
		if len(next) > beamWidth {
			next = next[:beamWidth]
		}
		states = next
	}

	r.reserved = originalReservations

	if len(completed) == 0 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	sort.Slice(completed, func(i, j int) bool {
		return completed[i].score > completed[j].score
	})
	plan := completed[0].routes

	sort.SliceStable(plan, func(i, j int) bool {
		return candidateFinalAmount(plan[i]) >
			candidateFinalAmount(plan[j])
	})

	return plan, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++

	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok &&
		failure.upper > 0 && amt >= failure.upper {

		delete(r.currentFails, key)
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 3 / 5
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	attempts     int
	attemptLimit int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*2 + 10
	if r.attemptLimit < 14 {
		r.attemptLimit = 14
	}
	if r.attemptLimit > 40 {
		r.attemptLimit = 40
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		if _, ok := r.edges[key]; ok {
			r.beliefs[key] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.050)
	highMode := 1 / (1 + math.Exp((x-0.942)/0.030))
	p := 0.48*lowMode + 0.52*highMode

	if p < 0.004 {
		return 0.004
	}
	if p > 0.987 {
		return 0.987
	}
	return p
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var numerator int64
	switch {
	case f.count <= 1:
		numerator = 55
	case f.count == 2:
		numerator = 32
	default:
		numerator = 18
	}

	ceiling := f.upper * lnwire.MilliSatoshi(numerator) / 100
	if ceiling < 1 {
		ceiling = 1
	}
	return ceiling, true
}

func candidateRetryScale(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.72
	case count == 2:
		return 0.48
	default:
		return 0.30
	}
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity ||
		r.policyBlocked[edge.key] {

		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, ok := candidateRetryCeiling(failure); ok &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryScale(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	switch {
	case belief.lowerOK > 0 && total <= belief.lowerOK:
		p = 0.997

	case belief.upperFail > 0 && total >= belief.upperFail:
		p = math.Min(p, 0.003)

	case belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK:

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}
		evidence := 0.997 - 0.994*pos
		p = 0.08*p + 0.92*evidence

	case belief.upperFail > 0:
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.22 {
			scale := 1 - 0.985*(ratio-0.22)/0.78
			if scale < 0.015 {
				scale = 0.015
			}
			p *= scale
		}

	case belief.lowerOK > 0:
		remaining := float64(edge.capacity - belief.lowerOK)
		scale := 0.06 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		distance := float64(total - belief.lowerOK)
		if distance < 0 {
			distance = 0
		}
		boost := 0.80 * math.Exp(-distance/(remaining+scale))
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.065 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.76*p + 0.24*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) {
		return 0
	}
	return r.liquidityProbability(edge, amt+r.reserved[edge.key])
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi,
	extraPenalty map[candidateEdgeKey]float64) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, errors.New("source equals target")
	}

	const (
		riskWeight = 700_000.0
		hopPenalty = 160.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}
		if item.node == r.source {
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += extraPenalty[edge.key]
			edgeScore += float64(r.edgeUses[edge.key]) * 1_500
			edgeScore += float64(r.suspect[edge.key]) * 240_000

			if r.reserved[edge.key] > 0 {
				edgeScore += 30_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, errors.New("no route found")
	}

	return r.buildRoute(amt, next)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	return candidateBuildPath(r.source, amt, path)
}

func candidateBuildPath(source route.Vertex, amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 || len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func (r *candidateRouter) routeEdges(rt *route.Route) (
	[]*candidateEdge, error) {

	if rt == nil || len(rt.Hops) == 0 {
		return nil, errors.New("invalid route")
	}

	path := make([]*candidateEdge, len(rt.Hops))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return nil, errors.New("invalid route edge")
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, errors.New("route edge not found")
		}
		path[i] = edge
	}
	return path, nil
}

func candidateScaled(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if max <= 0 {
		return
	}
	if value < 1 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func (r *candidateRouter) likelyTotal(edge *candidateEdge) (
	lnwire.MilliSatoshi, bool) {

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		return balance, ok
	}

	belief, ok := r.beliefs[edge.key]
	if !ok {
		return candidateScaled(edge.capacity, 88, 100), true
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		limit := belief.lowerOK + candidateScaled(
			belief.upperFail-belief.lowerOK, 11, 20,
		)
		if limit >= belief.upperFail {
			limit = belief.upperFail - 1
		}
		return limit, true
	}

	if belief.upperFail > 0 {
		limit := candidateScaled(belief.upperFail, 48, 100)
		if belief.lowerOK > limit {
			limit = belief.lowerOK
		}
		if limit >= belief.upperFail {
			limit = belief.upperFail - 1
		}
		return limit, true
	}

	if belief.lowerOK > 0 {
		limit := candidateScaled(edge.capacity, 93, 100)
		if belief.lowerOK > limit {
			limit = belief.lowerOK
		}
		return limit, true
	}

	return candidateScaled(edge.capacity, 88, 100), true
}

func (r *candidateRouter) pathCheck(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi, likely bool) (*route.Route, bool, bool) {

	rt, err := candidateBuildPath(r.source, finalAmt, path)
	if err != nil {
		return nil, false, false
	}

	tooSmall := false
	tooLarge := false

	for i, edge := range path {
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return nil, false, false
		}

		if amt < edge.minHTLC {
			tooSmall = true
			continue
		}
		if amt > edge.capacity ||
			(edge.maxHTLC > 0 && amt > edge.maxHTLC) {

			tooLarge = true
			continue
		}
		if r.policyBlocked[edge.key] {
			tooLarge = true
			continue
		}

		total := amt + r.reserved[edge.key]
		if total > edge.capacity {
			tooLarge = true
			continue
		}

		if edge.key.from == r.source {
			balance, ok := r.localBalances[edge.key.chanID]
			if !ok || total > balance {
				tooLarge = true
			}
		}

		if failure, ok := r.currentFails[edge.key]; ok {
			if failure.upper > 0 && total >= failure.upper {
				tooLarge = true
			}
			if ceiling, ok := candidateRetryCeiling(failure); ok &&
				total > ceiling {

				tooLarge = true
			}
		}

		if likely {
			limit, ok := r.likelyTotal(edge)
			if !ok || total > limit {
				tooLarge = true
			}
		}
	}

	if tooLarge {
		return nil, false, false
	}
	if tooSmall {
		return nil, false, true
	}
	return rt, true, false
}

func (r *candidateRouter) pathLimit(path []*candidateEdge,
	max lnwire.MilliSatoshi, likely bool) lnwire.MilliSatoshi {

	if max <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(1)
	high := max
	best := lnwire.MilliSatoshi(0)

	for low <= high {
		mid := low + (high-low)/2
		_, fits, tooSmall := r.pathCheck(path, mid, likely)

		switch {
		case fits:
			best = mid
			low = mid + 1
		case tooSmall:
			low = mid + 1
		default:
			high = mid - 1
		}
	}

	return best
}

func candidateRouteHash(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := uint64(1469598103934665603)
	h ^= candidateVertexHash(rt.SourcePubKey)
	for i, hop := range rt.Hops {
		h ^= candidateMix64(hop.ChannelID + uint64(i+1))
		h *= 1099511628211
		h ^= candidateVertexHash(hop.PubKeyBytes)
		h *= 1099511628211
	}
	return h
}

type candidatePathChoice struct {
	path []*candidateEdge
	hash uint64
}

func (r *candidateRouter) routeVariants(amt lnwire.MilliSatoshi,
	count int) []*route.Route {

	penalty := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	var routes []*route.Route

	for pass := 0; pass < count*3 && len(routes) < count; pass++ {
		rt, err := r.findRoute(amt, penalty)
		if err != nil {
			break
		}

		path, err := r.routeEdges(rt)
		if err != nil {
			break
		}

		hash := candidateRouteHash(rt)
		if !seen[hash] {
			seen[hash] = true
			routes = append(routes, rt)
		}

		last := len(path) - 1
		for i, edge := range path {
			add := 390_000.0
			if i == 0 {
				add = 650_000
			}
			if i == last {
				add = 1_000_000
			}
			penalty[edge.key] += add
		}
	}

	return routes
}

func candidateDiscoverySizes(total lnwire.MilliSatoshi,
	parts uint32) []lnwire.MilliSatoshi {

	if parts == 0 {
		parts = 1
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	var sizes []lnwire.MilliSatoshi
	equal := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	candidateAddAmount(&sizes, seen, total, total)
	candidateAddAmount(&sizes, seen, candidateScaled(total, 3, 4), total)
	candidateAddAmount(&sizes, seen, candidateScaled(total, 1, 2), total)
	candidateAddAmount(&sizes, seen, equal, total)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 3, 4), total,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 1, 2), total,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 1, 3), total,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 1, 6), total,
	)
	candidateAddAmount(
		&sizes, seen, candidateScaled(equal, 1, 10), total,
	)

	return sizes
}

func (r *candidateRouter) discoverPaths(total lnwire.MilliSatoshi,
	parts uint32) []candidatePathChoice {

	seen := make(map[uint64]bool)
	var paths []candidatePathChoice

	for _, size := range candidateDiscoverySizes(total, parts) {
		for _, rt := range r.routeVariants(size, 7) {
			hash := candidateRouteHash(rt)
			if seen[hash] {
				continue
			}

			path, err := r.routeEdges(rt)
			if err != nil {
				continue
			}

			seen[hash] = true
			paths = append(paths, candidatePathChoice{
				path: path,
				hash: hash,
			})
			if len(paths) >= 32 {
				return paths
			}
		}
	}

	return paths
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planScore(
	base, reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	routes []*route.Route) float64 {

	var score float64
	for key, total := range reservations {
		if total <= base[key] {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}
		p := r.liquidityProbability(edge, total)
		if p <= 0 {
			return math.Inf(-1)
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	for _, rt := range routes {
		finalAmt := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmt {
			fees += rt.TotalAmount - finalAmt
		}
	}

	score -= float64(fees) / 5_000_000
	score -= 0.014 * float64(len(routes))
	return score
}

func (r *candidateRouter) optimisticCover(paths []candidatePathChoice,
	remaining lnwire.MilliSatoshi, slots uint32) lnwire.MilliSatoshi {

	if remaining <= 0 || slots == 0 {
		return 0
	}

	limits := make([]lnwire.MilliSatoshi, 0, len(paths))
	for _, choice := range paths {
		limit := r.pathLimit(choice.path, remaining, false)
		if limit > 0 {
			limits = append(limits, limit)
		}
	}

	sort.Slice(limits, func(i, j int) bool {
		return limits[i] > limits[j]
	})

	var total lnwire.MilliSatoshi
	for i := 0; i < len(limits) && i < int(slots); i++ {
		if limits[i] >= remaining-total {
			return remaining
		}
		total += limits[i]
	}

	return total
}

func candidatePlanAmounts(remaining, hard, soft, equal,
	minNeeded lnwire.MilliSatoshi, slots uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	var amounts []lnwire.MilliSatoshi

	if slots <= 1 {
		if remaining <= hard {
			candidateAddAmount(
				&amounts, seen, remaining, remaining,
			)
		}
		return amounts
	}

	if remaining <= hard {
		candidateAddAmount(&amounts, seen, remaining, remaining)
	}
	if minNeeded > 0 && minNeeded <= hard {
		candidateAddAmount(&amounts, seen, minNeeded, remaining)
		candidateAddAmount(
			&amounts, seen,
			minNeeded+(hard-minNeeded)/2, remaining,
		)
	}
	if equal <= hard {
		candidateAddAmount(&amounts, seen, equal, remaining)
	}

	if soft > 0 {
		candidateAddAmount(&amounts, seen, soft, remaining)
		candidateAddAmount(
			&amounts, seen, candidateScaled(soft, 4, 5),
			remaining,
		)
		candidateAddAmount(
			&amounts, seen, candidateScaled(soft, 3, 5),
			remaining,
		)
	}

	if hard > 0 {
		candidateAddAmount(&amounts, seen, hard, remaining)
		candidateAddAmount(
			&amounts, seen, candidateScaled(hard, 4, 5),
			remaining,
		)
		candidateAddAmount(
			&amounts, seen, candidateScaled(hard, 3, 5),
			remaining,
		)
	}

	sort.Slice(amounts, func(i, j int) bool {
		return amounts[i] > amounts[j]
	})
	return amounts
}

func (r *candidateRouter) planRoutes(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts == 0 {
		return nil, errors.New("no parts available")
	}

	base := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = base
	}()

	paths := r.discoverPaths(total, parts)
	if len(paths) == 0 {
		return nil, errors.New("no candidate paths")
	}

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(base),
	}}
	var best *candidatePlanState

	const beamWidth = 64

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		var next []candidatePlanState

		for _, state := range states {
			if state.remaining <= 0 {
				continue
			}

			r.reserved = candidateCopyReservations(
				state.reservations,
			)

			futureCover := r.optimisticCover(
				paths, state.remaining, slots-1,
			)
			minNeeded := state.remaining - futureCover
			if minNeeded < 1 {
				minNeeded = 1
			}

			equal := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			for _, choice := range paths {
				r.reserved = candidateCopyReservations(
					state.reservations,
				)

				hard := r.pathLimit(
					choice.path, state.remaining, false,
				)
				if hard <= 0 {
					continue
				}
				soft := r.pathLimit(
					choice.path, state.remaining, true,
				)

				for _, shard := range candidatePlanAmounts(
					state.remaining, hard, soft, equal,
					minNeeded, slots,
				) {
					r.reserved = candidateCopyReservations(
						state.reservations,
					)
					rt, fits, _ := r.pathCheck(
						choice.path, shard, false,
					)
					if !fits {
						continue
					}

					newReservations :=
						candidateCopyReservations(
							state.reservations,
						)
					r.reserved = newReservations
					r.reserveRoute(rt)

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, rt)

					remaining := state.remaining - shard
					score := r.planScore(
						base, newReservations, routes,
					)
					if math.IsInf(score, -1) {
						continue
					}

					progress := float64(total-remaining) /
						float64(total)
					rank := score + 6.0*progress

					nextState := candidatePlanState{
						remaining:    remaining,
						routes:       routes,
						reservations: newReservations,
						score:        score,
						rank:         rank,
					}

					if remaining == 0 {
						if best == nil ||
							score > best.score {

							copyState := nextState
							best = &copyState
						}
						continue
					}

					if slots <= 1 {
						continue
					}

					next = append(next, nextState)
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			if next[i].rank == next[j].rank {
				return next[i].remaining <
					next[j].remaining
			}
			return next[i].rank > next[j].rank
		})
		if len(next) > beamWidth {
			next = next[:beamWidth]
		}
		states = next
	}

	if best == nil || len(best.routes) == 0 {
		return nil, errors.New("no route set found")
	}

	plan := append([]*route.Route(nil), best.routes...)
	sort.SliceStable(plan, func(i, j int) bool {
		pi := r.routeReliability(plan[i])
		pj := r.routeReliability(plan[j])
		if pi == pj {
			return candidateFinalAmount(plan[i]) >
				candidateFinalAmount(plan[j])
		}
		return pi < pj
	})

	return plan, nil
}

func (r *candidateRouter) routeReliability(rt *route.Route) float64 {
	if rt == nil {
		return 0
	}

	p := 1.0
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}
		edge := r.edges[key]
		if edge == nil {
			return 0
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0
		}
		edgeP := r.probability(edge, amt)
		if edgeP <= 0 {
			return 0
		}
		p *= edgeP
	}
	return p
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts <= 1 {
		return r.findRoute(total, nil)
	}

	paths := r.discoverPaths(total, parts)
	if len(paths) == 0 {
		return nil, errors.New("no route found")
	}

	target := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	bestScore := math.Inf(-1)
	var best *route.Route

	for _, choice := range paths {
		hard := r.pathLimit(choice.path, total, false)
		if hard <= 0 {
			continue
		}
		soft := r.pathLimit(choice.path, total, true)

		seen := make(map[lnwire.MilliSatoshi]bool)
		var amounts []lnwire.MilliSatoshi

		if target <= hard {
			candidateAddAmount(&amounts, seen, target, total)
		}
		if soft > 0 {
			candidateAddAmount(&amounts, seen, soft, total)
			candidateAddAmount(
				&amounts, seen,
				candidateScaled(soft, 4, 5), total,
			)
		}
		candidateAddAmount(&amounts, seen, hard, total)
		candidateAddAmount(
			&amounts, seen, candidateScaled(hard, 3, 4), total,
		)
		candidateAddAmount(
			&amounts, seen, candidateScaled(target, 1, 2), total,
		)
		candidateAddAmount(
			&amounts, seen, candidateScaled(target, 1, 4), total,
		)

		for _, shard := range amounts {
			rt, fits, _ := r.pathCheck(
				choice.path, shard, false,
			)
			if !fits {
				continue
			}

			score := 0.0
			for i, edge := range choice.path {
				amt, ok := candidateRouteAmount(rt, i)
				if !ok {
					score = math.Inf(-1)
					break
				}
				p := r.probability(edge, amt)
				if p <= 0 {
					score = math.Inf(-1)
					break
				}
				score += math.Log(p)
			}
			if math.IsInf(score, -1) {
				continue
			}

			finalAmt := candidateFinalAmount(rt)
			if rt.TotalAmount > finalAmt {
				score -= float64(rt.TotalAmount-finalAmt) /
					5_000_000
			}

			progress := float64(shard) / float64(target)
			if progress > 1 {
				progress = 1 + 0.12*(progress-1)
			}
			score += 5.0 * progress

			if score > bestScore {
				bestScore = score
				best = rt
			}
		}
	}

	if best == nil {
		return nil, errors.New("no feasible shard")
	}
	return best, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, err := r.findRoute(total, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, err := r.planRoutes(total, parts)
	if err == nil {
		return plan, nil
	}

	rt, fallbackErr := r.fallbackShard(total, parts)
	if fallbackErr != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) plannedRouteValid(rt *route.Route,
	remaining lnwire.MilliSatoshi) bool {

	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 || finalAmt > remaining {
		return false
	}

	path, err := r.routeEdges(rt)
	if err != nil {
		return false
	}
	_, fits, _ := r.pathCheck(path, finalAmt, false)
	return fits
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	for len(r.planned) > 0 {
		rt := r.planned[0]
		r.planned = r.planned[1:]
		if !r.plannedRouteValid(rt, amt) {
			continue
		}

		r.recordRouteUse(rt)
		r.attempts++
		return rt, nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	r.planned = append([]*route.Route(nil), plan[1:]...)

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	targetEstimate := candidateScaled(edge.capacity, 92, 100)
	if targetEstimate < amt {
		targetEstimate = amt
	}
	if targetEstimate > belief.estimate {
		belief.estimate = targetEstimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaled(amt, 7, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func candidateRouteContains(rt *route.Route,
	failed candidateEdgeKey) bool {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok && key == failed {
			return true
		}
	}
	return false
}

func candidateRoutesOverlap(a, b *route.Route) bool {
	if a == nil || b == nil {
		return false
	}

	edges := make(map[candidateEdgeKey]bool, len(a.Hops))
	for i := range a.Hops {
		key, ok := candidateRouteEdgeKey(a, i)
		if ok {
			edges[key] = true
		}
	}
	for i := range b.Hops {
		key, ok := candidateRouteEdgeKey(b, i)
		if ok && edges[key] {
			return true
		}
	}
	return false
}

func (r *candidateRouter) discardPlannedUsing(
	failed candidateEdgeKey) {

	kept := r.planned[:0]
	for _, rt := range r.planned {
		if !candidateRouteContains(rt, failed) {
			kept = append(kept, rt)
		}
	}
	r.planned = kept
}

func (r *candidateRouter) discardPlannedOverlapping(
	failedRoute *route.Route) {

	kept := r.planned[:0]
	for _, rt := range r.planned {
		if !candidateRoutesOverlap(rt, failedRoute) {
			kept = append(kept, rt)
		}
	}
	r.planned = kept
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		return nil
	}

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 1)
		r.discardPlannedOverlapping(rt)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		r.discardPlannedOverlapping(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.discardPlannedOverlapping(rt)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 1)
		r.discardPlannedOverlapping(rt)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.discardPlannedUsing(key)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2
		r.discardPlannedUsing(key)

	default:
		r.suspect[key]++
		r.discardPlannedUsing(key)
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key           candidateEdgeKey
	capacity      lnwire.MilliSatoshi
	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs  map[candidateEdgeKey]candidateBelief
	lastSeen int64
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	view   routing.SimNetworkView
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	edgeUses      map[candidateEdgeKey]uint32
	suspect       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		view:           view,
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		suspect:        make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 56 {
		r.attemptLimit = 56
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	now := view.Now().UnixNano()

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil || (mem.lastSeen != 0 && now <= mem.lastSeen) {
		mem = &candidateNetworkMemory{
			beliefs:  make(map[candidateEdgeKey]candidateBelief),
			lastSeen: now,
		}
		candidateMemory.networks[r.networkKey] = mem
	} else {
		for key, belief := range mem.beliefs {
			r.beliefs[key] = belief
		}
		mem.lastSeen = now
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateRetryFactor(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.62
	case count == 2:
		return 0.40
	default:
		return 0.24
	}
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var numerator int64
	switch {
	case f.count <= 1:
		numerator = 64
	case f.count == 2:
		numerator = 46
	default:
		numerator = 32
	}

	ceiling := f.upper * lnwire.MilliSatoshi(numerator) / 100
	if ceiling <= 0 {
		ceiling = 1
	}
	return ceiling, true
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	if !edge.policyAllows(amt) || r.policyBlocked[edge.key] {
		return 0
	}

	total := amt + r.reserved[edge.key]
	if total > edge.capacity {
		return 0
	}

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, ok := candidateRetryCeiling(failure); ok &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryFactor(failure.count)
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999 * retryScale
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p * retryScale
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997 * retryScale
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		p = math.Min(p, 0.004)
	} else if belief.lowerOK > 0 &&
		belief.upperFail > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		if pos < 0 {
			pos = 0
		}
		if pos > 1 {
			pos = 1
		}

		evidence := 0.994 - 0.990*pos
		p = 0.12*p + 0.88*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.35 {
			scale := 1 - 0.97*(ratio-0.35)/0.65
			if scale < 0.025 {
				scale = 0.025
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		if distance > 0 {
			boost := 0.64 * math.Exp(-distance/0.19)
			p += boost * (1 - p)
		}
	}

	if belief.estimate > 0 {
		scale := 0.09 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.76*p + 0.24*q
	}

	p *= retryScale
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

type candidateSearchItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	path     []*candidateEdge
	index    int
}

type candidateSearchQueue []*candidateSearchItem

func (q candidateSearchQueue) Len() int {
	return len(q)
}

func (q candidateSearchQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateSearchQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateSearchQueue) Push(x any) {
	item := x.(*candidateSearchItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateSearchQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidatePathContains(path []*candidateEdge, v route.Vertex) bool {
	for _, edge := range path {
		if edge.key.from == v || edge.key.to == v {
			return true
		}
	}
	return false
}

func (r *candidateRouter) findRouteWithPenalty(
	amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]float64) (*route.Route, float64, error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 500_000.0
		hopPenalty = 150.0
	)

	pq := &candidateSearchQueue{}
	heap.Push(pq, &candidateSearchItem{
		node:     r.spec.Target,
		required: amt,
	})

	expanded := make(map[route.Vertex]int)

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateSearchItem)

		if item.node == r.source {
			rt, err := r.buildRoute(amt, item.path)
			return rt, item.logProb, err
		}

		if expanded[item.node] >= 6 {
			continue
		}
		expanded[item.node]++

		for _, edge := range r.incomingEdges[item.node] {
			if candidatePathContains(item.path, edge.key.from) {
				continue
			}

			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			edgeScore += float64(r.edgeUses[edge.key]) * 30_000
			edgeScore += float64(r.suspect[edge.key]) * 260_000
			edgeScore += diversity[edge.key]

			if r.reserved[edge.key] > 0 {
				edgeScore += 240_000
			}

			path := make([]*candidateEdge, len(item.path)+1)
			path[0] = edge
			copy(path[1:], item.path)

			heap.Push(pq, &candidateSearchItem{
				node:     edge.key.from,
				score:    item.score + edgeScore,
				required: amtOver + fee,
				logProb:  item.logProb + math.Log(p),
				path:     path,
			})
		}
	}

	return nil, 0, errors.New("no route found")
}

func (r *candidateRouter) findRoute(amt lnwire.MilliSatoshi) (
	*route.Route, float64, error) {

	return r.findRouteWithPenalty(
		amt, make(map[candidateEdgeKey]float64),
	)
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	node := r.source
	visited := make(map[route.Vertex]bool)

	for _, edge := range path {
		if visited[node] || edge.key.from != node {
			return nil, errors.New("invalid route path")
		}
		visited[node] = true
		node = edge.key.to
	}
	if node != r.spec.Target {
		return nil, fmt.Errorf("path does not reach target")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if rt == nil || channelIndex < 0 ||
		channelIndex >= len(rt.Hops) {

		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteSignature(rt *route.Route) uint64 {
	if rt == nil {
		return 0
	}

	h := candidateMix64(uint64(candidateFinalAmount(rt)))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(key.chanID + uint64(i+1)*0x9e3779b97f4a7c15)
		h = candidateMix64(h)
	}
	return h
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, amt := range src {
		dst[key] = amt
	}
	return dst
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	max lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > max {
		value = max
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidateScaledAmount(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) / float64(denominator),
	)
}

func (r *candidateRouter) routeLimit(rt *route.Route) lnwire.MilliSatoshi {
	limit := lnwire.MilliSatoshi(math.MaxInt64)

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0
		}
		edge := r.edges[key]
		if edge == nil {
			return 0
		}

		reserved := r.reserved[key]
		available := edge.capacity - reserved
		if edge.maxHTLC > 0 && edge.maxHTLC-reserved < available {
			available = edge.maxHTLC - reserved
		}
		if available < limit {
			limit = available
		}

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok {
				return 0
			}
			localAvailable := balance - reserved
			if localAvailable < limit {
				limit = localAvailable
			}
			continue
		}

		if failure, ok := r.currentFails[key]; ok {
			if ceiling, ok := candidateRetryCeiling(failure); ok {
				likely := ceiling - reserved
				if likely < limit {
					limit = likely
				}
			}
		}

		belief, ok := r.beliefs[key]
		if !ok {
			likely := candidateScaledAmount(
				edge.capacity, 90, 100,
			) - reserved
			if likely < limit {
				limit = likely
			}
			continue
		}

		if belief.upperFail > 0 {
			likelyTotal := candidateScaledAmount(
				belief.upperFail, 60, 100,
			)
			if belief.lowerOK > likelyTotal {
				likelyTotal = belief.lowerOK
			}
			if likelyTotal >= belief.upperFail {
				likelyTotal = belief.upperFail - 1
			}
			if likelyTotal-reserved < limit {
				limit = likelyTotal - reserved
			}
		} else if belief.lowerOK > 0 {
			likelyTotal := belief.lowerOK +
				candidateScaledAmount(
					edge.capacity-belief.lowerOK, 60, 100,
				)
			if likelyTotal-reserved < limit {
				limit = likelyTotal - reserved
			}
		}
	}

	if limit < 1 {
		return 0
	}
	return limit
}

func candidatePlanSizes(remaining lnwire.MilliSatoshi, slots uint32,
	failed lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if slots <= 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 4), remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 5, 4), remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 2), remaining,
	)
	candidateAddAmount(&values, seen, base*2, remaining)

	if failed > 0 {
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(failed, 3, 5), remaining,
		)
		candidateAddAmount(
			&values, seen,
			candidateScaledAmount(failed, 2, 5), remaining,
		)
	}

	candidateAddAmount(&values, seen, remaining, remaining)
	return values
}

type candidateRouteChoice struct {
	rt      *route.Route
	logProb float64
}

func (r *candidateRouter) routeChoices(amt lnwire.MilliSatoshi,
	count int) []candidateRouteChoice {

	diversity := make(map[candidateEdgeKey]float64)
	seen := make(map[uint64]bool)
	choices := make([]candidateRouteChoice, 0, count)

	for tries := 0; tries < count*3 && len(choices) < count; tries++ {
		rt, logProb, err := r.findRouteWithPenalty(amt, diversity)
		if err != nil {
			break
		}

		signature := candidateRouteSignature(rt)
		if !seen[signature] {
			seen[signature] = true
			choices = append(choices, candidateRouteChoice{
				rt:      rt,
				logProb: logProb,
			})
		}

		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			if key.from == r.source {
				diversity[key] += 360_000
			} else {
				diversity[key] += 620_000
			}
		}
	}

	return choices
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState
	const beamWidth = 24

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make([]candidatePlanState, 0, beamWidth*12)

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}

			sizes := candidatePlanSizes(
				state.remaining, slots, r.lastFailedShard,
			)
			seenSizes := make(map[lnwire.MilliSatoshi]bool)
			for _, size := range sizes {
				seenSizes[size] = true
			}

			for i := 0; i < len(sizes) && i < 18; i++ {
				size := sizes[i]
				if size <= 0 || size > state.remaining {
					continue
				}

				r.reserved = candidateCopyReservations(
					state.reservations,
				)
				choices := r.routeChoices(size, 3)

				for _, choice := range choices {
					r.reserved = candidateCopyReservations(
						state.reservations,
					)

					limit := r.routeLimit(choice.rt)
					if limit > size {
						candidateAddAmount(
							&sizes, seenSizes,
							candidateScaledAmount(limit, 4, 5),
							state.remaining,
						)
						candidateAddAmount(
							&sizes, seenSizes, limit,
							state.remaining,
						)
					}

					newReservations := candidateCopyReservations(
						state.reservations,
					)
					r.reserved = newReservations
					r.reserveRoute(choice.rt)

					fees := choice.rt.TotalAmount - size
					score := state.score + choice.logProb -
						float64(fees)/4_000_000 - 0.012

					remaining := state.remaining - size
					progress := float64(total-remaining) /
						float64(total)
					rank := score + 3.2*progress

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, choice.rt)

					nextStates = append(nextStates, candidatePlanState{
						remaining:    remaining,
						routes:       routes,
						reservations: newReservations,
						score:        score,
						rank:         rank,
					})
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			iComplete := nextStates[i].remaining == 0
			jComplete := nextStates[j].remaining == 0
			if iComplete != jComplete {
				return iComplete
			}
			if nextStates[i].rank == nextStates[j].rank {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	for _, state := range states {
		if state.remaining != 0 {
			continue
		}
		if bestComplete == nil || state.score > bestComplete.score {
			copyState := state
			bestComplete = &copyState
		}
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no route set found")
	}

	routes := append([]*route.Route(nil), bestComplete.routes...)
	sort.SliceStable(routes, func(i, j int) bool {
		return candidateFinalAmount(routes[i]) >
			candidateFinalAmount(routes[j])
	})

	return routes, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, _, err := r.findRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	rt, _, singleErr := r.findRoute(total)
	if singleErr != nil {
		return nil, err
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) routeUsable(rt *route.Route) bool {
	if rt == nil || len(rt.Hops) == 0 {
		return false
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil {
			return false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok || r.probability(edge, amt) <= 0 {
			return false
		}
	}
	return true
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmt := candidateFinalAmount(rt)
		if finalAmt > 0 && finalAmt <= amt && r.routeUsable(rt) {
			r.planned = r.planned[1:]
			r.recordRouteUse(rt)
			r.attempts++
			return rt, nil
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief
	now := r.view.Now().UnixNano()

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	mem.lastSeen = now
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaledAmount(amt, 9, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			r.suspect[key] += weight / 2
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.learnSuccess(key, amt+r.reserved[key])
			}
		}

		r.held = append(r.held, rt)
		return nil
	}

	r.planned = nil
	r.lastFailedShard = candidateFinalAmount(rt)

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	if failIdx < 0 {
		r.markRouteSuspect(rt, 3)
		return nil
	}

	passed := failIdx
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx >= len(rt.Hops) {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}
	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.markRouteSuspect(rt, 2)
		return nil
	}

	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 3

	default:
		r.policyBlocked[key] = true
		r.suspect[key] += 2
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const candidateFinalCLTV = 40

type candidateEdgeKey struct {
	chanID uint64
	from   route.Vertex
	to     route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi
	baseFee  lnwire.MilliSatoshi
	feeRate  lnwire.MilliSatoshi
	cltv     uint16
	minHTLC  lnwire.MilliSatoshi
	maxHTLC  lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFee + amt*e.feeRate/1_000_000
}

func (e *candidateEdge) allows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incoming map[route.Vertex][]*candidateEdge
	edges    map[candidateEdgeKey]*candidateEdge
	local    map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief
	failures   map[candidateEdgeKey]candidateFailure
	blocked    map[candidateEdgeKey]bool
	suspect    map[candidateEdgeKey]uint32
	uses       map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	attempts     int
	attemptLimit int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFee) + uint64(e.feeRate)<<17)
	x ^= candidateMix64(uint64(e.cltv) + uint64(e.minHTLC)<<16)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:   source,
		spec:     spec,
		incoming: make(map[route.Vertex][]*candidateEdge),
		edges:    make(map[candidateEdgeKey]*candidateEdge),
		local:    localBalances,
		beliefs:  make(map[candidateEdgeKey]candidateBelief),
		failures: make(map[candidateEdgeKey]candidateFailure),
		blocked:  make(map[candidateEdgeKey]bool),
		suspect:  make(map[candidateEdgeKey]uint32),
		uses:     make(map[candidateEdgeKey]uint32),
		reserved: make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = 12 + int(maxParts)*3
	if r.attemptLimit < 16 {
		r.attemptLimit = 16
	}
	if r.attemptLimit > 44 {
		r.attemptLimit = 44
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFee: policy.FeeBaseMSat,
					feeRate: policy.FeeProportionalMillionths,
					cltv:    policy.TimeLockDelta,
					minHTLC: policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incoming[node] = append(r.incoming[node], edge)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)
				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		if _, ok := r.edges[key]; ok {
			r.beliefs[key] = belief
		}
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if amt <= 0 || capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	low := math.Exp(-x / 0.048)
	high := 1 / (1 + math.Exp((x-0.948)/0.028))
	p := 0.47*low + 0.53*high

	if p < 0.004 {
		return 0.004
	}
	if p > 0.987 {
		return 0.987
	}
	return p
}

func candidateScale(v lnwire.MilliSatoshi, n, d int64) lnwire.MilliSatoshi {
	if v <= 0 || n <= 0 || d <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(float64(v) * float64(n) / float64(d))
}

func (r *candidateRouter) retryCeiling(edge *candidateEdge,
	floor lnwire.MilliSatoshi) (lnwire.MilliSatoshi, bool) {

	failure, ok := r.failures[edge.key]
	if !ok || failure.upper <= 0 {
		return 0, false
	}

	if edge.key.from != r.source {
		if lower := r.beliefs[edge.key].lowerOK; lower > floor {
			floor = lower
		}
	}
	if floor >= failure.upper {
		return failure.upper - 1, true
	}

	var fraction int64
	switch {
	case failure.count <= 1:
		fraction = 60
	case failure.count == 2:
		fraction = 52
	default:
		fraction = 44
	}

	ceiling := floor + candidateScale(
		failure.upper-floor, fraction, 100,
	)
	if ceiling >= failure.upper {
		ceiling = failure.upper - 1
	}
	return ceiling, true
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total, provenFloor lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity || r.blocked[edge.key] {
		return 0
	}

	if failure, ok := r.failures[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, ok := r.retryCeiling(edge, provenFloor); ok &&
			total > ceiling {

			return 0
		}
	}

	if edge.key.from == r.source {
		balance, ok := r.local[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if ok {
		switch {
		case belief.lowerOK > 0 && total <= belief.lowerOK:
			p = 0.996

		case belief.upperFail > 0 && total >= belief.upperFail:
			p = math.Min(p, 0.003)

		case belief.lowerOK > 0 &&
			belief.upperFail > belief.lowerOK:

			width := float64(belief.upperFail - belief.lowerOK)
			pos := float64(total-belief.lowerOK) / width
			if pos < 0 {
				pos = 0
			}
			if pos > 1 {
				pos = 1
			}
			evidence := 0.996 - 0.993*pos
			p = 0.06*p + 0.94*evidence

		case belief.upperFail > 0:
			ratio := float64(total) / float64(belief.upperFail)
			if ratio > 0.18 {
				scale := 1 - 0.98*(ratio-0.18)/0.82
				if scale < 0.02 {
					scale = 0.02
				}
				p *= scale
			}

		case belief.lowerOK > 0:
			remaining := float64(edge.capacity - belief.lowerOK)
			scale := 0.05 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			distance := float64(total - belief.lowerOK)
			if distance < 0 {
				distance = 0
			}
			boost := 0.82 * math.Exp(
				-distance / (remaining + scale),
			)
			p += boost * (1 - p)
		}

		if belief.estimate > 0 {
			scale := 0.055 * float64(edge.capacity)
			if scale < 1 {
				scale = 1
			}
			q := 1 / (1 + math.Exp(
				(float64(total)-float64(belief.estimate))/scale,
			))
			p = 0.74*p + 0.26*q
		}
	}

	if failure, ok := r.failures[edge.key]; ok {
		switch {
		case failure.count == 1:
			p *= 0.82
		case failure.count == 2:
			p *= 0.68
		default:
			p *= 0.54
		}
	}

	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

type candidateLabel struct {
	node  route.Vertex
	req   lnwire.MilliSatoshi
	score float64
	path  []*candidateEdge
	index int
}

type candidateLabelQueue []*candidateLabel

func (q candidateLabelQueue) Len() int {
	return len(q)
}

func (q candidateLabelQueue) Less(i, j int) bool {
	if q[i].score == q[j].score {
		return q[i].req < q[j].req
	}
	return q[i].score < q[j].score
}

func (q candidateLabelQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateLabelQueue) Push(x any) {
	item := x.(*candidateLabel)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateLabelQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func candidatePathContainsVertex(path []*candidateEdge,
	vertex route.Vertex) bool {

	for _, edge := range path {
		if edge.key.from == vertex || edge.key.to == vertex {
			return true
		}
	}
	return false
}

func candidatePathHash(path []*candidateEdge) uint64 {
	h := uint64(1469598103934665603)
	for i, edge := range path {
		h ^= candidateMix64(
			edge.key.chanID + uint64(i+1)*0x9e3779b97f4a7c15,
		)
		h ^= candidateMix64(candidateVertexHash(edge.key.to))
		h *= 1099511628211
	}
	return h
}

func (r *candidateRouter) searchPaths(amt lnwire.MilliSatoshi,
	penalty map[candidateEdgeKey]float64,
	want int) [][]*candidateEdge {

	if amt <= 0 || want <= 0 || r.source == r.spec.Target {
		return nil
	}

	const (
		riskWeight = 390_000.0
		hopPenalty = 130.0
		labelLimit = 18
		maxExpanded = 30000
	)

	pq := &candidateLabelQueue{}
	heap.Push(pq, &candidateLabel{
		node: r.spec.Target,
		req:  amt,
	})

	expandedAt := make(map[route.Vertex]int)
	seenPaths := make(map[uint64]bool)
	var paths [][]*candidateEdge
	expanded := 0

	for pq.Len() > 0 && len(paths) < want && expanded < maxExpanded {
		label := heap.Pop(pq).(*candidateLabel)

		if label.node == r.source {
			hash := candidatePathHash(label.path)
			if !seenPaths[hash] {
				seenPaths[hash] = true
				paths = append(paths, label.path)
			}
			continue
		}

		if expandedAt[label.node] >= labelLimit {
			continue
		}
		expandedAt[label.node]++
		expanded++

		for _, edge := range r.incoming[label.node] {
			if candidatePathContainsVertex(label.path, edge.key.from) {
				continue
			}

			amtOver := label.req
			if !edge.allows(amtOver) {
				continue
			}

			total := r.reserved[edge.key] + amtOver
			p := r.liquidityProbability(
				edge, total, r.reserved[edge.key],
			)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}

			score := label.score + float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty
			score += penalty[edge.key]
			score += float64(r.suspect[edge.key]) * 75_000
			score += float64(r.uses[edge.key]) * 6_000
			if r.reserved[edge.key] > 0 {
				score += 4_000
			}

			path := make([]*candidateEdge, len(label.path)+1)
			path[0] = edge
			copy(path[1:], label.path)

			heap.Push(pq, &candidateLabel{
				node:  edge.key.from,
				req:   amtOver + fee,
				score: score,
				path:  path,
			})
		}
	}

	return paths
}

func candidateBuildRoute(source route.Vertex,
	amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 || len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1

	amounts[last] = amt
	expiries[last] = candidateFinalCLTV

	for i := last - 1; i >= 0; i-- {
		next := path[i+1]
		amounts[i] = amounts[i+1] + next.fee(amounts[i+1])
		expiries[i] = expiries[i+1] + uint32(next.cltv)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forward := amt
		expiry := uint32(candidateFinalCLTV)
		if i < last {
			forward = amounts[i+1]
			expiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forward,
			OutgoingTimeLock: expiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, index int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return 0, false
	}
	if index == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[index-1].AmtToForward, true
}

func candidateRouteKey(rt *route.Route, index int) (
	candidateEdgeKey, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}
	hop := rt.Hops[index]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateCopyReservations(
	src map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	dst := make(map[candidateEdgeKey]lnwire.MilliSatoshi, len(src))
	for key, value := range src {
		dst[key] = value
	}
	return dst
}

func candidateReserve(rt *route.Route,
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi) {

	for i := range rt.Hops {
		key, ok := candidateRouteKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			reservations[key] += amt
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		candidateReserve(rt, r.reserved)
	}
}

func (r *candidateRouter) routePath(rt *route.Route) (
	[]*candidateEdge, error) {

	if rt == nil || len(rt.Hops) == 0 {
		return nil, errors.New("invalid route")
	}

	path := make([]*candidateEdge, len(rt.Hops))
	for i := range rt.Hops {
		key, ok := candidateRouteKey(rt, i)
		if !ok {
			return nil, errors.New("invalid edge")
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, errors.New("unknown route edge")
		}
		path[i] = edge
	}
	return path, nil
}

func (r *candidateRouter) likelyTotal(edge *candidateEdge,
	floor lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if edge.key.from == r.source {
		return r.local[edge.key.chanID]
	}

	belief, ok := r.beliefs[edge.key]
	if !ok {
		return candidateScale(edge.capacity, 91, 100)
	}

	if belief.lowerOK > floor {
		floor = belief.lowerOK
	}

	switch {
	case belief.upperFail > floor:
		limit := floor + candidateScale(
			belief.upperFail-floor, 11, 20,
		)
		if limit >= belief.upperFail {
			limit = belief.upperFail - 1
		}
		return limit

	case belief.upperFail > 0:
		return candidateScale(belief.upperFail, 47, 100)

	case belief.lowerOK > 0:
		limit := candidateScale(edge.capacity, 93, 100)
		if belief.lowerOK > limit {
			limit = belief.lowerOK
		}
		return limit

	default:
		return candidateScale(edge.capacity, 91, 100)
	}
}

func (r *candidateRouter) pathCheck(path []*candidateEdge,
	finalAmt lnwire.MilliSatoshi,
	reservations, proven map[candidateEdgeKey]lnwire.MilliSatoshi,
	likely bool) (*route.Route, int) {

	rt, err := candidateBuildRoute(r.source, finalAmt, path)
	if err != nil {
		return nil, 1
	}

	tooSmall := false
	tooLarge := false

	for i, edge := range path {
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return nil, 1
		}

		if amt < edge.minHTLC {
			tooSmall = true
			continue
		}
		if amt > edge.capacity ||
			(edge.maxHTLC > 0 && amt > edge.maxHTLC) ||
			r.blocked[edge.key] {

			tooLarge = true
			continue
		}

		total := reservations[edge.key] + amt
		if total > edge.capacity {
			tooLarge = true
			continue
		}

		if edge.key.from == r.source {
			balance, ok := r.local[edge.key.chanID]
			if !ok || total > balance {
				tooLarge = true
				continue
			}
		}

		if failure, ok := r.failures[edge.key]; ok {
			if failure.upper > 0 && total >= failure.upper {
				tooLarge = true
				continue
			}
			if ceiling, ok := r.retryCeiling(
				edge, proven[edge.key],
			); ok && total > ceiling {

				tooLarge = true
				continue
			}
		}

		if likely &&
			total > r.likelyTotal(edge, proven[edge.key]) {

			tooLarge = true
		}
	}

	if tooLarge {
		return nil, 1
	}
	if tooSmall {
		return nil, -1
	}
	return rt, 0
}

func (r *candidateRouter) pathLimit(path []*candidateEdge,
	max lnwire.MilliSatoshi,
	reservations, proven map[candidateEdgeKey]lnwire.MilliSatoshi,
	likely bool) lnwire.MilliSatoshi {

	if max <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(1)
	high := max
	best := lnwire.MilliSatoshi(0)

	for low <= high {
		mid := low + (high-low)/2
		_, status := r.pathCheck(
			path, mid, reservations, proven, likely,
		)

		switch status {
		case 0:
			best = mid
			low = mid + 1
		case -1:
			low = mid + 1
		default:
			high = mid - 1
		}
	}

	return best
}

type candidatePathChoice struct {
	path []*candidateEdge
	hash uint64
}

func candidateAddAmount(dst *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool,
	value, maximum lnwire.MilliSatoshi) {

	if maximum <= 0 {
		return
	}
	if value < 1 {
		value = 1
	}
	if value > maximum {
		value = maximum
	}
	if !seen[value] {
		seen[value] = true
		*dst = append(*dst, value)
	}
}

func candidateDiscoveryAmounts(total lnwire.MilliSatoshi,
	parts uint32) []lnwire.MilliSatoshi {

	if parts == 0 {
		parts = 1
	}

	seen := make(map[lnwire.MilliSatoshi]bool)
	var amounts []lnwire.MilliSatoshi
	equal := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	candidateAddAmount(&amounts, seen, total, total)
	candidateAddAmount(&amounts, seen, equal, total)
	candidateAddAmount(&amounts, seen, candidateScale(total, 1, 2), total)
	candidateAddAmount(&amounts, seen, candidateScale(equal, 3, 4), total)
	candidateAddAmount(&amounts, seen, candidateScale(equal, 1, 2), total)
	candidateAddAmount(&amounts, seen, candidateScale(equal, 1, 3), total)
	candidateAddAmount(&amounts, seen, candidateScale(equal, 1, 5), total)
	candidateAddAmount(&amounts, seen, candidateScale(equal, 1, 8), total)
	candidateAddAmount(&amounts, seen, candidateScale(total, 1, 24), total)
	candidateAddAmount(&amounts, seen, candidateScale(total, 1, 40), total)

	return amounts
}

func (r *candidateRouter) discoverPaths(total lnwire.MilliSatoshi,
	parts uint32) []candidatePathChoice {

	seen := make(map[uint64]bool)
	var choices []candidatePathChoice

	addPaths := func(paths [][]*candidateEdge) {
		for _, path := range paths {
			hash := candidatePathHash(path)
			if seen[hash] {
				continue
			}
			seen[hash] = true
			choices = append(choices, candidatePathChoice{
				path: path,
				hash: hash,
			})
		}
	}

	for _, amt := range candidateDiscoveryAmounts(total, parts) {
		first := r.searchPaths(amt, nil, 14)
		addPaths(first)

		penalty := make(map[candidateEdgeKey]float64)
		for _, path := range first {
			for i, edge := range path {
				value := 170_000.0
				if i == 0 {
					value = 260_000
				}
				if i == len(path)-1 {
					value = 390_000
				}
				penalty[edge.key] += value
			}
		}
		addPaths(r.searchPaths(amt, penalty, 10))

		if len(choices) >= 56 {
			break
		}
	}

	if len(choices) > 56 {
		choices = choices[:56]
	}
	return choices
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planScore(
	base, reservations map[candidateEdgeKey]lnwire.MilliSatoshi,
	routes []*route.Route) float64 {

	var score float64

	for key, total := range reservations {
		floor := base[key]
		if total <= floor {
			continue
		}

		edge := r.edges[key]
		if edge == nil {
			return math.Inf(-1)
		}

		p := r.liquidityProbability(edge, total, floor)
		if p <= 0 {
			return math.Inf(-1)
		}

		if floor > 0 {
			baseP := r.liquidityProbability(edge, floor, floor)
			if baseP > 0 {
				p /= baseP
			}
		}
		if p > 0.999 {
			p = 0.999
		}
		if p < 0.001 {
			p = 0.001
		}
		score += math.Log(p)
	}

	var fees lnwire.MilliSatoshi
	for _, rt := range routes {
		finalAmt := candidateFinalAmount(rt)
		if rt.TotalAmount > finalAmt {
			fees += rt.TotalAmount - finalAmt
		}
	}

	score -= float64(fees) / 3_800_000
	score -= 0.022 * float64(len(routes))
	return score
}

func candidatePlanAmounts(remaining, hard, soft, equal,
	minNeeded lnwire.MilliSatoshi, slots uint32) []lnwire.MilliSatoshi {

	seen := make(map[lnwire.MilliSatoshi]bool)
	var amounts []lnwire.MilliSatoshi

	add := func(value lnwire.MilliSatoshi) {
		if value <= 0 || value > hard || value > remaining {
			return
		}
		if slots > 1 && minNeeded > 0 &&
			remaining-value < minNeeded {

			return
		}
		candidateAddAmount(&amounts, seen, value, remaining)
	}

	if slots <= 1 {
		if remaining <= hard {
			add(remaining)
		}
		return amounts
	}

	add(remaining)
	add(equal)
	add(soft)
	add(candidateScale(soft, 4, 5))
	add(candidateScale(soft, 3, 5))
	add(hard)
	add(candidateScale(hard, 9, 10))
	add(candidateScale(hard, 3, 4))
	add(candidateScale(hard, 3, 5))
	add(candidateScale(hard, 1, 2))
	add(candidateScale(hard, 2, 5))
	add(candidateScale(hard, 3, 10))
	add(candidateScale(hard, 1, 5))

	sort.Slice(amounts, func(i, j int) bool {
		di := amounts[i] - equal
		if di < 0 {
			di = -di
		}
		dj := amounts[j] - equal
		if dj < 0 {
			dj = -dj
		}
		if di == dj {
			return amounts[i] > amounts[j]
		}
		return di < dj
	})

	return amounts
}

func (r *candidateRouter) planRoutes(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if total <= 0 || parts == 0 {
		return nil, errors.New("invalid route plan")
	}

	paths := r.discoverPaths(total, parts)
	if len(paths) == 0 {
		return nil, errors.New("no candidate paths")
	}

	base := candidateCopyReservations(r.reserved)
	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(base),
	}}
	var best *candidatePlanState

	const beamWidth = 64

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		var next []candidatePlanState

		for _, state := range states {
			if state.remaining <= 0 {
				continue
			}

			equal := (state.remaining +
				lnwire.MilliSatoshi(slots) - 1) /
				lnwire.MilliSatoshi(slots)

			minNeeded := lnwire.MilliSatoshi(0)
			if slots > 1 {
				minNeeded = lnwire.MilliSatoshi(slots - 1)
			}

			for _, choice := range paths {
				hard := r.pathLimit(
					choice.path, state.remaining,
					state.reservations, base, false,
				)
				if hard <= 0 {
					continue
				}
				soft := r.pathLimit(
					choice.path, state.remaining,
					state.reservations, base, true,
				)

				amounts := candidatePlanAmounts(
					state.remaining, hard, soft, equal,
					minNeeded, slots,
				)
				for _, shard := range amounts {
					rt, status := r.pathCheck(
						choice.path, shard,
						state.reservations, base, false,
					)
					if status != 0 {
						continue
					}

					reservations := candidateCopyReservations(
						state.reservations,
					)
					candidateReserve(rt, reservations)

					routes := make(
						[]*route.Route, len(state.routes),
						len(state.routes)+1,
					)
					copy(routes, state.routes)
					routes = append(routes, rt)

					remaining := state.remaining - shard
					score := r.planScore(
						base, reservations, routes,
					)
					if math.IsInf(score, -1) {
						continue
					}

					progress := float64(total-remaining) /
						float64(total)
					rank := score + 24*progress

					nextState := candidatePlanState{
						remaining:    remaining,
						routes:       routes,
						reservations: reservations,
						score:        score,
						rank:         rank,
					}

					if remaining == 0 {
						if best == nil || score > best.score {
							copyState := nextState
							best = &copyState
						}
						continue
					}

					next = append(next, nextState)
				}
			}
		}

		sort.Slice(next, func(i, j int) bool {
			if next[i].rank == next[j].rank {
				return next[i].remaining < next[j].remaining
			}
			return next[i].rank > next[j].rank
		})

		dedup := make(map[uint64]bool)
		filtered := next[:0]
		for _, state := range next {
			h := candidateMix64(uint64(state.remaining))
			for key, value := range state.reservations {
				h ^= candidateMix64(
					key.chanID ^ uint64(value) ^
						candidateVertexHash(key.to),
				)
			}
			if dedup[h] {
				continue
			}
			dedup[h] = true
			filtered = append(filtered, state)
			if len(filtered) >= beamWidth {
				break
			}
		}
		states = filtered
	}

	if best == nil || len(best.routes) == 0 {
		return nil, errors.New("no route set found")
	}

	plan := append([]*route.Route(nil), best.routes...)
	sort.SliceStable(plan, func(i, j int) bool {
		ai := candidateFinalAmount(plan[i])
		aj := candidateFinalAmount(plan[j])
		if ai == aj {
			return len(plan[i].Hops) < len(plan[j].Hops)
		}
		return ai > aj
	})
	return plan, nil
}

func (r *candidateRouter) bestSingleRoute(
	amt lnwire.MilliSatoshi) (*route.Route, error) {

	paths := r.searchPaths(amt, nil, 1)
	if len(paths) == 0 {
		return nil, errors.New("no route found")
	}
	return candidateBuildRoute(r.source, amt, paths[0])
}

func (r *candidateRouter) fallbackShard(total lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts <= 1 {
		return nil, errors.New("no complete route found")
	}

	paths := r.discoverPaths(total, parts)
	if len(paths) == 0 {
		return nil, errors.New("no fallback path")
	}

	base := candidateCopyReservations(r.reserved)
	equal := (total + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	var best *route.Route
	bestScore := math.Inf(-1)

	for _, choice := range paths {
		hard := r.pathLimit(
			choice.path, total, base, base, false,
		)
		if hard <= 0 {
			continue
		}
		soft := r.pathLimit(
			choice.path, total, base, base, true,
		)

		var shard lnwire.MilliSatoshi
		switch {
		case soft >= equal:
			shard = equal
		case soft > 0:
			shard = soft
		case hard >= equal:
			shard = equal
		default:
			shard = hard
		}
		if shard <= 0 || shard >= total {
			continue
		}

		rt, status := r.pathCheck(
			choice.path, shard, base, base, false,
		)
		if status != 0 {
			continue
		}

		reservations := candidateCopyReservations(base)
		candidateReserve(rt, reservations)
		score := r.planScore(base, reservations, []*route.Route{rt})
		score += 2.5 * float64(shard) / float64(total)

		if best == nil || score > bestScore {
			best = rt
			bestScore = score
		}
	}

	if best == nil {
		return nil, errors.New("no fallback shard")
	}
	return best, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		rt, err := r.bestSingleRoute(total)
		if err != nil {
			return nil, err
		}
		return []*route.Route{rt}, nil
	}

	plan, planErr := r.planRoutes(total, parts)
	if planErr == nil {
		return plan, nil
	}

	if rt, err := r.bestSingleRoute(total); err == nil {
		return []*route.Route{rt}, nil
	}

	rt, err := r.fallbackShard(total, parts)
	if err != nil {
		return nil, planErr
	}
	return []*route.Route{rt}, nil
}

func (r *candidateRouter) recordUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteKey(rt, i)
		if ok {
			r.uses[key]++
		}
	}
}

func (r *candidateRouter) plannedValid(rt *route.Route,
	remaining lnwire.MilliSatoshi) bool {

	finalAmt := candidateFinalAmount(rt)
	if finalAmt <= 0 || finalAmt > remaining {
		return false
	}

	path, err := r.routePath(rt)
	if err != nil {
		return false
	}
	_, status := r.pathCheck(
		path, finalAmt, r.reserved, r.reserved, false,
	)
	return status == 0
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	for len(r.planned) > 0 {
		rt := r.planned[0]
		r.planned = r.planned[1:]
		if !r.plannedValid(rt, amt) {
			r.planned = nil
			break
		}

		r.recordUse(rt)
		r.attempts++
		return rt, nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	r.planned = append([]*route.Route(nil), plan[1:]...)
	r.recordUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.failures[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.failures, key)
		} else if failure.count > 1 {
			failure.count--
			r.failures[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	edge := r.edges[key]
	if edge == nil {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}

	estimate := candidateScale(edge.capacity, 93, 100)
	if estimate < amt {
		estimate = amt
	}
	if estimate > belief.estimate {
		belief.estimate = estimate
	}

	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	failure := r.failures[key]
	if failure.upper == 0 || amt < failure.upper {
		failure.upper = amt
	}
	failure.count++
	r.failures[key] = failure

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScale(amt, 7, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}

	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markSuspect(rt *route.Route, weight uint32) {
	for i := range rt.Hops {
		key, ok := candidateRouteKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(attemptID uint64,
	rt *route.Route, result routing.SimHtlcResult) error {

	_ = attemptID

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.learnSuccess(key, amt+r.reserved[key])
			}
		}
		r.held = append(r.held, rt)
		return nil
	}

	r.planned = nil

	failIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIndex = i + 1
				break
			}
		}
	}

	if failIndex < 0 {
		r.markSuspect(rt, 1)
		return nil
	}

	passed := failIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIndex >= len(rt.Hops) {
		return nil
	}

	key, ok := candidateRouteKey(rt, failIndex)
	if !ok {
		r.markSuspect(rt, 1)
		return nil
	}
	amt, ok := candidateRouteAmount(rt, failIndex)
	if !ok {
		r.markSuspect(rt, 1)
		return nil
	}
	total := amt + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, total)
		r.suspect[key]++

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.blocked[key] = true
		r.suspect[key] += 2

	default:
		r.suspect[key]++
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edgesByKey    map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]lnwire.MilliSatoshi
	policyBlocked map[candidateEdgeKey]bool
	blockedRoutes map[uint64]bool

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	plan     []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(uint64(e.baseFeeMsat))
	x ^= candidateMix64(uint64(e.feeRatePPM))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edgesByKey:     make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]lnwire.MilliSatoshi),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		blockedRoutes:  make(map[uint64]bool),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	r.attemptLimit = int(spec.MaxParts)*3 + 10
	if r.attemptLimit < 28 {
		r.attemptLimit = 28
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				pol := ch.InPolicy
				if pol == nil || pol.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   pol.FeeBaseMSat,
					feeRatePPM:    pol.FeeProportionalMillionths,
					timeLockDelta: pol.TimeLockDelta,
					minHTLC:       pol.MinHTLC,
				}
				if pol.HasMaxHTLC {
					edge.maxHTLC = pol.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edgesByKey[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	for key, belief := range mem.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func (r *candidateRouter) probability(edge *candidateEdge,
	amt lnwire.MilliSatoshi) float64 {

	reserved := r.reserved[edge.key]
	total := amt + reserved

	if !edge.policyAllows(amt) || total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	if r.policyBlocked[edge.key] {
		return 0
	}

	if bound := r.currentFails[edge.key]; bound > 0 &&
		total >= bound {

		return 0
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.995
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		if p > 0.012 {
			p = 0.012
		}
		return p
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK &&
		total > belief.lowerOK {

		width := float64(belief.upperFail - belief.lowerOK)
		pos := float64(total-belief.lowerOK) / width
		evidence := 0.985 - 0.97*pos
		p = 0.18*p + 0.82*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.50 {
			scale := 1 - 0.94*(ratio-0.50)/0.50
			if scale < 0.06 {
				scale = 0.06
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.55 * math.Exp(-distance/0.20)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.10 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		q := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.68*p + 0.32*q
	}

	if p < 0.005 {
		return 0.005
	}
	if p > 0.995 {
		return 0.995
	}
	return p
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	idx      int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].idx = i
	q[j].idx = j
}

func (q *candidateDijkstraQueue) Push(x any) {
	item := x.(*candidateDijkstraItem)
	item.idx = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

func (r *candidateRouter) findPath(amt lnwire.MilliSatoshi,
	diversity map[candidateEdgeKey]int) ([]*candidateEdge, float64,
	error) {

	if amt <= 0 {
		return nil, 0, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return nil, 0, errors.New("source equals target")
	}

	const (
		riskWeight = 320_000.0
		hopPenalty = 220.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)

	bestScore[r.spec.Target] = 0
	pq := &candidateDijkstraQueue{}
	heap.Push(pq, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProb float64

	for pq.Len() > 0 {
		item := heap.Pop(pq).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProb = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			amtOver := item.required
			p := r.probability(edge, amtOver)
			if p <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amtOver)
			}
			sending := amtOver + fee

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(p)) + hopPenalty

			if r.reserved[edge.key] > 0 {
				edgeScore += 550_000
			}
			if diversity != nil {
				edgeScore += float64(diversity[edge.key]) * 480_000
			}

			score := item.score + edgeScore
			old, found := bestScore[edge.key.from]
			if found && score >= old {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(pq, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sending,
				logProb:  item.logProb + math.Log(p),
			})
		}
	}

	if _, ok := bestScore[r.source]; !ok {
		return nil, 0, errors.New("no route found")
	}

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)
	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, 0, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, 0, fmt.Errorf("broken path at %v", node)
		}
		path = append(path, edge)
		node = edge.key.to
	}

	if len(path) == 0 {
		return nil, 0, errors.New("empty route")
	}

	return path, sourceLogProb, nil
}

func (r *candidateRouter) buildPathRoute(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if amt <= 0 || len(path) == 0 {
		return nil, errors.New("invalid route")
	}

	amtOver := make([]lnwire.MilliSatoshi, len(path))
	expiryOver := make([]uint32, len(path))

	last := len(path) - 1
	amtOver[last] = amt
	expiryOver[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amtOver[i] = amtOver[i+1] +
			forwardingEdge.fee(amtOver[i+1])
		expiryOver[i] = expiryOver[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		if !edge.policyAllows(amtOver[i]) {
			return nil, errors.New("route violates channel policy")
		}

		amtToForward := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			amtToForward = amtOver[i+1]
			outgoingExpiry = expiryOver[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     amtToForward,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiryOver[0],
		TotalAmount:   amtOver[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, channelIndex int) (
	lnwire.MilliSatoshi, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return 0, false
	}
	if channelIndex == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[channelIndex-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route,
	channelIndex int) (candidateEdgeKey, bool) {

	if channelIndex < 0 || channelIndex >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if channelIndex > 0 {
		from = rt.Hops[channelIndex-1].PubKeyBytes
	}
	hop := rt.Hops[channelIndex]

	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateRouteHash(rt *route.Route) uint64 {
	h := uint64(0x243f6a8885a308d3)
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		h ^= candidateMix64(key.chanID + uint64(i+1))
		h ^= candidateMix64(candidateVertexHash(key.from))
		h ^= candidateMix64(candidateVertexHash(key.to))
		h = candidateMix64(h)
	}
	return h
}

func candidatePathHash(path []*candidateEdge) uint64 {
	h := uint64(0x243f6a8885a308d3)
	for i, edge := range path {
		h ^= candidateMix64(edge.key.chanID + uint64(i+1))
		h ^= candidateMix64(candidateVertexHash(edge.key.from))
		h ^= candidateMix64(candidateVertexHash(edge.key.to))
		h = candidateMix64(h)
	}
	return h
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count

	for _, rt := range r.held[start:] {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if ok {
				r.reserved[key] += amt
			}
		}
	}
}

func (r *candidateRouter) routeUsable(rt *route.Route) bool {
	if rt == nil || r.blockedRoutes[candidateRouteHash(rt)] {
		return false
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edgesByKey[key]
		if edge == nil {
			return false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok || r.probability(edge, amt) <= 0 {
			return false
		}
	}

	return true
}

func (r *candidateRouter) pathStats(path []*candidateEdge,
	amt lnwire.MilliSatoshi, safe bool) (float64, bool) {

	rt, err := r.buildPathRoute(amt, path)
	if err != nil {
		return 0, false
	}

	logProb := 0.0
	for i, edge := range path {
		amtOver, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0, false
		}

		p := r.probability(edge, amtOver)
		if p <= 0 {
			return 0, false
		}

		if safe && edge.key.from != r.source {
			total := amtOver + r.reserved[edge.key]
			belief := r.beliefs[edge.key]

			if bound := r.currentFails[edge.key]; bound > 0 {
				retry := bound * 5 / 8
				if retry <= 0 {
					retry = 1
				}
				if total > retry {
					return 0, false
				}
			}

			if belief.upperFail > 0 {
				retry := belief.upperFail * 5 / 8
				if belief.lowerOK > 0 {
					retry = belief.lowerOK +
						(belief.upperFail-belief.lowerOK)/5
				}
				if retry <= 0 {
					retry = 1
				}
				if total > retry {
					return 0, false
				}
			} else if belief.lowerOK == 0 {
				limit := edge.capacity * 9 / 10
				if total > limit {
					return 0, false
				}
			} else {
				limit := edge.capacity * 94 / 100
				if total > limit && total > belief.lowerOK {
					return 0, false
				}
			}
		}

		logProb += math.Log(p)
	}

	return logProb, true
}

func (r *candidateRouter) pathLimit(path []*candidateEdge,
	max lnwire.MilliSatoshi, safe bool) lnwire.MilliSatoshi {

	if max <= 0 {
		return 0
	}

	lo := lnwire.MilliSatoshi(0)
	hi := max

	for lo < hi {
		mid := lo + (hi-lo+1)/2
		if _, ok := r.pathStats(path, mid, safe); ok {
			lo = mid
		} else {
			hi = mid - 1
		}
	}

	return lo
}

type candidatePlanPath struct {
	path    []*candidateEdge
	safe    lnwire.MilliSatoshi
	hard    lnwire.MilliSatoshi
	quality float64
	hash    uint64
}

func (r *candidateRouter) collectPaths(amt lnwire.MilliSatoshi,
	parts uint32) []candidatePlanPath {

	if parts == 0 {
		parts = 1
	}

	base := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	probes := []lnwire.MilliSatoshi{
		base,
		base * 3 / 4,
		base / 2,
		base * 3 / 2,
		base * 2,
		amt,
	}
	if r.lastFailedShard > 0 {
		probes = append(
			[]lnwire.MilliSatoshi{
				r.lastFailedShard * 5 / 8,
				r.lastFailedShard / 2,
			},
			probes...,
		)
	}

	diversity := make(map[candidateEdgeKey]int)
	seen := make(map[uint64]bool)
	maxPaths := int(parts)*4 + 4
	var paths []candidatePlanPath

	for _, probe := range probes {
		if probe <= 0 {
			probe = 1
		}
		if probe > amt {
			probe = amt
		}

		for repeat := 0; repeat < 3 && len(paths) < maxPaths; repeat++ {
			path, logProb, err := r.findPath(probe, diversity)
			if err != nil {
				break
			}

			hash := candidatePathHash(path)
			for _, edge := range path {
				diversity[edge.key]++
			}

			if seen[hash] {
				continue
			}
			seen[hash] = true

			rt, err := r.buildPathRoute(probe, path)
			if err != nil || r.blockedRoutes[candidateRouteHash(rt)] {
				continue
			}

			hard := r.pathLimit(path, amt, false)
			if hard <= 0 {
				continue
			}
			safe := r.pathLimit(path, hard, true)

			qualityAmt := safe
			if qualityAmt <= 0 {
				qualityAmt = hard
			}
			if qualityAmt > base {
				qualityAmt = base
			}
			if qualityAmt <= 0 {
				qualityAmt = 1
			}
			if q, ok := r.pathStats(path, qualityAmt, false); ok {
				logProb = q
			}

			paths = append(paths, candidatePlanPath{
				path:    path,
				safe:    safe,
				hard:    hard,
				quality: logProb,
				hash:    hash,
			})
		}
	}

	return paths
}

func candidatePathOverlap(path []*candidateEdge,
	used map[candidateEdgeKey]int) int {

	overlap := 0
	for _, edge := range path {
		overlap += used[edge.key]
	}
	return overlap
}

func (r *candidateRouter) choosePlanPaths(paths []candidatePlanPath,
	amt lnwire.MilliSatoshi, parts uint32) []candidatePlanPath {

	var selected []candidatePlanPath
	usedPath := make(map[uint64]bool)
	usedEdges := make(map[candidateEdgeKey]int)

	var hardSum, safeSum lnwire.MilliSatoshi

	for len(selected) < int(parts) {
		best := -1
		bestScore := math.Inf(-1)

		for i := range paths {
			p := paths[i]
			if usedPath[p.hash] || p.hard <= 0 {
				continue
			}

			safe := p.safe
			if safe <= 0 {
				safe = p.hard / 8
			}
			if safe <= 0 {
				safe = 1
			}

			overlap := candidatePathOverlap(p.path, usedEdges)
			score := math.Log(float64(p.hard)+1) +
				0.45*math.Log(float64(safe)+1) +
				0.55*p.quality -
				3.2*float64(overlap)

			if score > bestScore {
				bestScore = score
				best = i
			}
		}

		if best < 0 {
			break
		}

		p := paths[best]
		selected = append(selected, p)
		usedPath[p.hash] = true
		hardSum += p.hard
		safeSum += p.safe
		for _, edge := range p.path {
			usedEdges[edge.key]++
		}

		if hardSum >= amt && safeSum >= amt {
			break
		}
	}

	if hardSum < amt {
		return nil
	}

	return selected
}

func candidateAllocate(selected []candidatePlanPath,
	amt lnwire.MilliSatoshi) ([]lnwire.MilliSatoshi, bool) {

	if len(selected) == 0 || amt <= 0 {
		return nil, false
	}

	weights := make([]lnwire.MilliSatoshi, len(selected))
	var weightSum lnwire.MilliSatoshi
	for i := range selected {
		weights[i] = selected[i].safe
		if weights[i] <= 0 {
			weights[i] = selected[i].hard / 4
		}
		if weights[i] <= 0 {
			weights[i] = 1
		}
		weightSum += weights[i]
	}

	alloc := make([]lnwire.MilliSatoshi, len(selected))
	remaining := amt

	for i := range selected {
		if i == len(selected)-1 {
			if remaining <= 0 || remaining > selected[i].hard {
				return nil, false
			}
			alloc[i] = remaining
			break
		}

		var restHard lnwire.MilliSatoshi
		for j := i + 1; j < len(selected); j++ {
			restHard += selected[j].hard
		}

		minimum := remaining - restHard
		if minimum < 1 {
			minimum = 1
		}

		restParts := lnwire.MilliSatoshi(len(selected) - i - 1)
		maximum := selected[i].hard
		if remaining-restParts < maximum {
			maximum = remaining - restParts
		}
		if maximum < minimum {
			return nil, false
		}

		desired := minimum
		if weightSum > 0 {
			desired = lnwire.MilliSatoshi(
				float64(remaining) *
					float64(weights[i]) /
					float64(weightSum),
			)
		}
		if desired < minimum {
			desired = minimum
		}
		if desired > maximum {
			desired = maximum
		}

		alloc[i] = desired
		remaining -= desired
		weightSum -= weights[i]
	}

	return alloc, true
}

func (r *candidateRouter) makePlan(amt lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	paths := r.collectPaths(amt, parts)
	if len(paths) == 0 {
		return nil, errors.New("no route found")
	}

	selected := r.choosePlanPaths(paths, amt, parts)
	if len(selected) == 0 {
		return nil, errors.New("insufficient route-set capacity")
	}

	alloc, ok := candidateAllocate(selected, amt)
	if !ok {
		return nil, errors.New("unable to allocate route set")
	}

	var plan []*route.Route
	for i := range selected {
		rt, err := r.buildPathRoute(alloc[i], selected[i].path)
		if err != nil || !r.routeUsable(rt) {
			return nil, errors.New("planned route is no longer usable")
		}
		plan = append(plan, rt)
	}

	sort.Slice(plan, func(i, j int) bool {
		return candidateFinalAmount(plan[i]) >
			candidateFinalAmount(plan[j])
	})

	return plan, nil
}

func (r *candidateRouter) fallbackRoute(amt lnwire.MilliSatoshi,
	parts uint32) (*route.Route, error) {

	if parts == 0 {
		parts = 1
	}

	base := (amt + lnwire.MilliSatoshi(parts) - 1) /
		lnwire.MilliSatoshi(parts)

	sizes := []lnwire.MilliSatoshi{
		base,
		base * 3 / 4,
		base / 2,
	}
	if r.lastFailedShard > 0 {
		sizes = append(
			[]lnwire.MilliSatoshi{
				r.lastFailedShard * 5 / 8,
				r.lastFailedShard / 2,
			},
			sizes...,
		)
	}
	if parts == 1 {
		sizes = []lnwire.MilliSatoshi{amt}
	}

	var best *route.Route
	bestUtility := math.Inf(-1)
	seen := make(map[lnwire.MilliSatoshi]bool)

	for _, size := range sizes {
		if size <= 0 {
			size = 1
		}
		if size > amt {
			size = amt
		}
		if seen[size] {
			continue
		}
		seen[size] = true

		path, logProb, err := r.findPath(size, nil)
		if err != nil {
			continue
		}
		rt, err := r.buildPathRoute(size, path)
		if err != nil || !r.routeUsable(rt) {
			continue
		}

		fees := rt.TotalAmount - size
		utility := logProb +
			0.30*math.Log(float64(size)/float64(base)) -
			float64(fees)/5_000_000

		if best == nil || utility > bestUtility {
			best = rt
			bestUtility = utility
		}
	}

	if best == nil {
		return nil, errors.New("no route found")
	}
	return best, nil
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	for len(r.plan) > 0 {
		rt := r.plan[0]
		r.plan = r.plan[1:]

		if candidateFinalAmount(rt) > amt || !r.routeUsable(rt) {
			r.plan = nil
			break
		}

		r.attempts++
		return rt, nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err == nil && len(plan) > 0 {
		r.plan = plan[1:]
		r.attempts++
		return plan[0], nil
	}

	rt, err := r.fallbackRoute(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	mem := candidateMemory.networks[r.networkKey]
	if mem == nil {
		mem = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = mem
	}
	mem.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 || key.from == r.source {
		return
	}

	if old := r.currentFails[key]; old == 0 || amt < old {
		r.currentFails[key] = amt
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := amt * 5 / 8
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++

	r.storeBelief(key, belief)
}

func (r *candidateRouter) ReportAttempt(attemptID uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	_ = attemptID

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amt, ok := candidateRouteAmount(rt, i)
			if !ok {
				continue
			}
			r.learnSuccess(key, amt+r.reserved[key])
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.plan = nil

	failIdx := -1
	if result.FailureSource == rt.SourcePubKey {
		failIdx = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failIdx = i + 1
				break
			}
		}
	}

	passed := failIdx
	if passed < 0 {
		passed = 0
	}
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}

	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amt, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amt+r.reserved[key])
		}
	}

	if failIdx < 0 || failIdx >= len(rt.Hops) {
		r.blockedRoutes[candidateRouteHash(rt)] = true
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failIdx)
	if !ok {
		r.blockedRoutes[candidateRouteHash(rt)] = true
		return nil
	}

	amtOver, ok := candidateRouteAmount(rt, failIdx)
	if !ok {
		r.blockedRoutes[candidateRouteHash(rt)] = true
		return nil
	}
	totalRequired := amtOver + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true

	default:
		r.policyBlocked[key] = true
		r.blockedRoutes[candidateRouteHash(rt)] = true
	}

	return nil
}

package main

import (
	"container/heap"
	"context"
	"errors"
	"fmt"
	"math"
	"sort"
	"sync"

	graphdb "github.com/lightningnetwork/lnd/graph/db"
	"github.com/lightningnetwork/lnd/lnwire"
	"github.com/lightningnetwork/lnd/routing"
	"github.com/lightningnetwork/lnd/routing/route"
)

const finalCltvDelta = 40

type candidateEdgeKey struct {
	chanID   uint64
	from, to route.Vertex
}

type candidateEdge struct {
	key      candidateEdgeKey
	capacity lnwire.MilliSatoshi

	baseFeeMsat   lnwire.MilliSatoshi
	feeRatePPM    lnwire.MilliSatoshi
	timeLockDelta uint16
	minHTLC       lnwire.MilliSatoshi
	maxHTLC       lnwire.MilliSatoshi
}

func (e *candidateEdge) fee(amt lnwire.MilliSatoshi) lnwire.MilliSatoshi {
	return e.baseFeeMsat + amt*e.feeRatePPM/1_000_000
}

func (e *candidateEdge) policyAllows(amt lnwire.MilliSatoshi) bool {
	if amt < e.minHTLC || amt > e.capacity {
		return false
	}
	return e.maxHTLC == 0 || amt <= e.maxHTLC
}

type candidateBelief struct {
	lowerOK   lnwire.MilliSatoshi
	upperFail lnwire.MilliSatoshi
	estimate  lnwire.MilliSatoshi
	successes uint32
	failures  uint32
}

type candidateCurrentFailure struct {
	upper lnwire.MilliSatoshi
	count uint32
}

type candidateNetworkKey struct {
	source      route.Vertex
	fingerprint uint64
}

type candidateNetworkMemory struct {
	beliefs map[candidateEdgeKey]candidateBelief
}

var candidateMemory = struct {
	sync.Mutex
	networks map[candidateNetworkKey]*candidateNetworkMemory
}{
	networks: make(map[candidateNetworkKey]*candidateNetworkMemory),
}

type candidateRouter struct {
	source route.Vertex
	spec   *routing.SimPaymentSpec

	incomingEdges map[route.Vertex][]*candidateEdge
	edges         map[candidateEdgeKey]*candidateEdge
	localBalances map[uint64]lnwire.MilliSatoshi

	networkKey candidateNetworkKey
	beliefs    map[candidateEdgeKey]candidateBelief

	currentFails  map[candidateEdgeKey]candidateCurrentFailure
	policyBlocked map[candidateEdgeKey]bool
	suspect       map[candidateEdgeKey]uint32
	edgeUses      map[candidateEdgeKey]uint32

	reserved map[candidateEdgeKey]lnwire.MilliSatoshi
	held     []*route.Route
	planned  []*route.Route

	lastFailedShard lnwire.MilliSatoshi
	attempts        int
	attemptLimit    int
}

func candidateMix64(x uint64) uint64 {
	x ^= x >> 30
	x *= 0xbf58476d1ce4e5b9
	x ^= x >> 27
	x *= 0x94d049bb133111eb
	return x ^ (x >> 31)
}

func candidateVertexHash(v route.Vertex) uint64 {
	h := uint64(1469598103934665603)
	for i, b := range v {
		h ^= uint64(b) + uint64(i+1)<<8
		h *= 1099511628211
	}
	return h
}

func candidateEdgeHash(e *candidateEdge) uint64 {
	x := candidateMix64(e.key.chanID)
	x ^= candidateMix64(candidateVertexHash(e.key.from))
	x ^= candidateMix64(
		candidateVertexHash(e.key.to) + 0x9e3779b97f4a7c15,
	)
	x ^= candidateMix64(uint64(e.capacity))
	x ^= candidateMix64(
		uint64(e.baseFeeMsat) + uint64(e.feeRatePPM)<<17,
	)
	x ^= candidateMix64(
		uint64(e.timeLockDelta) + uint64(e.minHTLC)<<16,
	)
	x ^= candidateMix64(uint64(e.maxHTLC))
	return candidateMix64(x)
}

func newCandidateRouter(view routing.SimNetworkView, source route.Vertex,
	localBalances map[uint64]lnwire.MilliSatoshi,
	spec *routing.SimPaymentSpec) (routing.SimRouter, error) {

	r := &candidateRouter{
		source:         source,
		spec:           spec,
		incomingEdges:  make(map[route.Vertex][]*candidateEdge),
		edges:          make(map[candidateEdgeKey]*candidateEdge),
		localBalances:  localBalances,
		beliefs:        make(map[candidateEdgeKey]candidateBelief),
		currentFails:   make(map[candidateEdgeKey]candidateCurrentFailure),
		policyBlocked:  make(map[candidateEdgeKey]bool),
		suspect:        make(map[candidateEdgeKey]uint32),
		edgeUses:       make(map[candidateEdgeKey]uint32),
		reserved:       make(map[candidateEdgeKey]lnwire.MilliSatoshi),
	}

	maxParts := spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	r.attemptLimit = int(maxParts)*4 + 8
	if r.attemptLimit < 20 {
		r.attemptLimit = 20
	}
	if r.attemptLimit > 64 {
		r.attemptLimit = 64
	}

	ctx := context.Background()
	seen := map[route.Vertex]bool{source: true}
	queue := []route.Vertex{source}
	var fingerprint uint64

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		err := view.ForEachNodeDirectedChannel(
			ctx, node, func(ch *graphdb.DirectedChannel) error {
				if !seen[ch.OtherNode] {
					seen[ch.OtherNode] = true
					queue = append(queue, ch.OtherNode)
				}

				policy := ch.InPolicy
				if policy == nil || policy.IsDisabled {
					return nil
				}

				edge := &candidateEdge{
					key: candidateEdgeKey{
						chanID: ch.ChannelID,
						from:   ch.OtherNode,
						to:     node,
					},
					capacity: lnwire.NewMSatFromSatoshis(
						ch.Capacity,
					),
					baseFeeMsat:   policy.FeeBaseMSat,
					feeRatePPM:    policy.FeeProportionalMillionths,
					timeLockDelta: policy.TimeLockDelta,
					minHTLC:       policy.MinHTLC,
				}
				if policy.HasMaxHTLC {
					edge.maxHTLC = policy.MaxHTLC
				}

				r.incomingEdges[node] = append(
					r.incomingEdges[node], edge,
				)
				r.edges[edge.key] = edge
				fingerprint ^= candidateEdgeHash(edge)

				return nil
			}, func() {},
		)
		if err != nil {
			return nil, err
		}
	}

	r.networkKey = candidateNetworkKey{
		source:      source,
		fingerprint: fingerprint,
	}

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	for key, belief := range memory.beliefs {
		r.beliefs[key] = belief
	}
	candidateMemory.Unlock()

	return r, nil
}

func candidatePrior(amt, capacity lnwire.MilliSatoshi) float64 {
	if capacity <= 0 || amt <= 0 || amt > capacity {
		return 0
	}

	x := float64(amt) / float64(capacity)
	lowMode := math.Exp(-x / 0.055)
	highMode := 1 / (1 + math.Exp((x-0.93)/0.035))
	p := 0.5*lowMode + 0.5*highMode

	if p < 0.005 {
		return 0.005
	}
	if p > 0.985 {
		return 0.985
	}
	return p
}

func candidateRetryFactor(count uint32) float64 {
	switch {
	case count == 0:
		return 1
	case count == 1:
		return 0.62
	case count == 2:
		return 0.46
	default:
		return 0.34
	}
}

func candidateRetryCeiling(f candidateCurrentFailure) (
	lnwire.MilliSatoshi, bool) {

	if f.upper <= 0 {
		return 0, false
	}

	var percent lnwire.MilliSatoshi
	switch {
	case f.count <= 1:
		percent = 72
	case f.count == 2:
		percent = 56
	default:
		percent = 44
	}

	ceiling := f.upper * percent / 100
	if ceiling < 1 {
		ceiling = 1
	}
	return ceiling, true
}

func candidateClampProbability(p float64) float64 {
	if p < 0.001 {
		return 0.001
	}
	if p > 0.997 {
		return 0.997
	}
	return p
}

func (r *candidateRouter) liquidityProbability(edge *candidateEdge,
	total lnwire.MilliSatoshi) float64 {

	if total <= 0 || total > edge.capacity {
		return 0
	}

	if edge.key.from == r.source {
		balance, ok := r.localBalances[edge.key.chanID]
		if !ok || total > balance {
			return 0
		}
		return 0.999
	}

	p := candidatePrior(total, edge.capacity)
	belief, ok := r.beliefs[edge.key]
	if !ok {
		return p
	}

	if belief.lowerOK > 0 && total <= belief.lowerOK {
		return 0.997
	}

	if belief.upperFail > 0 && total >= belief.upperFail {
		return math.Min(p, 0.005)
	}

	if belief.lowerOK > 0 && belief.upperFail > belief.lowerOK {
		width := float64(belief.upperFail - belief.lowerOK)
		position := float64(total-belief.lowerOK) / width
		if position < 0 {
			position = 0
		}
		if position > 1 {
			position = 1
		}

		evidence := 0.994 - 0.989*position
		p = 0.12*p + 0.88*evidence
	} else if belief.upperFail > 0 {
		ratio := float64(total) / float64(belief.upperFail)
		if ratio > 0.40 {
			scale := 1 - 0.95*(ratio-0.40)/0.60
			if scale < 0.035 {
				scale = 0.035
			}
			p *= scale
		}
	} else if belief.lowerOK > 0 && total > belief.lowerOK {
		distance := float64(total-belief.lowerOK) /
			float64(edge.capacity)
		boost := 0.62 * math.Exp(-distance/0.18)
		p += boost * (1 - p)
	}

	if belief.estimate > 0 {
		scale := 0.09 * float64(edge.capacity)
		if scale < 1 {
			scale = 1
		}
		estimateProb := 1 / (1 + math.Exp(
			(float64(total)-float64(belief.estimate))/scale,
		))
		p = 0.75*p + 0.25*estimateProb
	}

	return candidateClampProbability(p)
}

func (r *candidateRouter) probability(edge *candidateEdge,
	shardAmt lnwire.MilliSatoshi) float64 {

	if r.policyBlocked[edge.key] || !edge.policyAllows(shardAmt) {
		return 0
	}

	reserved := r.reserved[edge.key]
	if shardAmt > edge.capacity-reserved {
		return 0
	}
	total := shardAmt + reserved

	retryScale := 1.0
	if failure, ok := r.currentFails[edge.key]; ok {
		if failure.upper > 0 && total >= failure.upper {
			return 0
		}
		if ceiling, valid := candidateRetryCeiling(failure); valid &&
			total > ceiling {

			return 0
		}
		retryScale = candidateRetryFactor(failure.count)
	}

	newProbability := r.liquidityProbability(edge, total)
	if newProbability <= 0 {
		return 0
	}

	// An already-held shard proves that the channel carried the reserved
	// amount. Charge only the incremental risk of increasing that total.
	if reserved > 0 {
		oldProbability := r.liquidityProbability(edge, reserved)
		if oldProbability > 0 {
			newProbability /= oldProbability
		}
		if newProbability > 0.999 {
			newProbability = 0.999
		}
	}

	return candidateClampProbability(newProbability * retryScale)
}

type candidateDijkstraItem struct {
	node     route.Vertex
	score    float64
	required lnwire.MilliSatoshi
	logProb  float64
	index    int
}

type candidateDijkstraQueue []*candidateDijkstraItem

func (q candidateDijkstraQueue) Len() int {
	return len(q)
}

func (q candidateDijkstraQueue) Less(i, j int) bool {
	return q[i].score < q[j].score
}

func (q candidateDijkstraQueue) Swap(i, j int) {
	q[i], q[j] = q[j], q[i]
	q[i].index = i
	q[j].index = j
}

func (q *candidateDijkstraQueue) Push(value any) {
	item := value.(*candidateDijkstraItem)
	item.index = len(*q)
	*q = append(*q, item)
}

func (q *candidateDijkstraQueue) Pop() any {
	old := *q
	n := len(old)
	item := old[n-1]
	*q = old[:n-1]
	return item
}

type candidateFoundRoute struct {
	route   *route.Route
	score   float64
	logProb float64
}

func (r *candidateRouter) searchRoute(amt lnwire.MilliSatoshi,
	banned map[candidateEdgeKey]bool,
	extraPenalty map[candidateEdgeKey]float64) (
	candidateFoundRoute, error) {

	if amt <= 0 {
		return candidateFoundRoute{}, errors.New("invalid route amount")
	}
	if r.source == r.spec.Target {
		return candidateFoundRoute{}, errors.New("source equals target")
	}

	const (
		riskWeight = 650_000.0
		hopPenalty = 180.0
	)

	bestScore := make(map[route.Vertex]float64)
	next := make(map[route.Vertex]*candidateEdge)
	bestScore[r.spec.Target] = 0

	queue := &candidateDijkstraQueue{}
	heap.Push(queue, &candidateDijkstraItem{
		node:     r.spec.Target,
		required: amt,
	})

	var sourceLogProbability float64

	for queue.Len() > 0 {
		item := heap.Pop(queue).(*candidateDijkstraItem)
		known, ok := bestScore[item.node]
		if !ok || item.score > known+0.0001 {
			continue
		}

		if item.node == r.source {
			sourceLogProbability = item.logProb
			break
		}

		for _, edge := range r.incomingEdges[item.node] {
			if banned != nil && banned[edge.key] {
				continue
			}

			amountOverEdge := item.required
			probability := r.probability(edge, amountOverEdge)
			if probability <= 0 {
				continue
			}

			fee := lnwire.MilliSatoshi(0)
			if edge.key.from != r.source {
				fee = edge.fee(amountOverEdge)
			}
			sendingAmount := amountOverEdge + fee
			if sendingAmount < amountOverEdge {
				continue
			}

			edgeScore := float64(fee) +
				riskWeight*(-math.Log(probability)) +
				hopPenalty

			edgeScore += float64(r.suspect[edge.key]) * 170_000
			edgeScore += float64(r.edgeUses[edge.key]) * 5_000
			if r.reserved[edge.key] > 0 {
				edgeScore += 85_000
			}
			if extraPenalty != nil {
				edgeScore += extraPenalty[edge.key]
			}

			score := item.score + edgeScore
			oldScore, found := bestScore[edge.key.from]
			if found && score >= oldScore {
				continue
			}

			bestScore[edge.key.from] = score
			next[edge.key.from] = edge
			heap.Push(queue, &candidateDijkstraItem{
				node:     edge.key.from,
				score:    score,
				required: sendingAmount,
				logProb: item.logProb +
					math.Log(probability),
			})
		}
	}

	score, found := bestScore[r.source]
	if !found {
		return candidateFoundRoute{}, errors.New("no route found")
	}

	rt, err := r.buildRoute(amt, next)
	if err != nil {
		return candidateFoundRoute{}, err
	}

	return candidateFoundRoute{
		route:   rt,
		score:   score,
		logProb: sourceLogProbability,
	}, nil
}

func (r *candidateRouter) buildRoute(amt lnwire.MilliSatoshi,
	next map[route.Vertex]*candidateEdge) (*route.Route, error) {

	var path []*candidateEdge
	visited := make(map[route.Vertex]bool)

	for node := r.source; node != r.spec.Target; {
		if visited[node] {
			return nil, errors.New("route contains cycle")
		}
		visited[node] = true

		edge, ok := next[node]
		if !ok {
			return nil, fmt.Errorf("broken path at %v", node)
		}

		path = append(path, edge)
		node = edge.key.to
	}

	return r.buildPath(amt, path)
}

func (r *candidateRouter) buildPath(amt lnwire.MilliSatoshi,
	path []*candidateEdge) (*route.Route, error) {

	if len(path) == 0 {
		return nil, errors.New("empty route")
	}

	amounts := make([]lnwire.MilliSatoshi, len(path))
	expiries := make([]uint32, len(path))
	last := len(path) - 1

	amounts[last] = amt
	expiries[last] = finalCltvDelta

	for i := last - 1; i >= 0; i-- {
		forwardingEdge := path[i+1]
		amounts[i] = amounts[i+1] +
			forwardingEdge.fee(amounts[i+1])
		if amounts[i] < amounts[i+1] {
			return nil, errors.New("route amount overflow")
		}
		expiries[i] = expiries[i+1] +
			uint32(forwardingEdge.timeLockDelta)
	}

	for i, edge := range path {
		if !edge.policyAllows(amounts[i]) {
			return nil, errors.New("fixed path violates policy")
		}
	}

	hops := make([]*route.Hop, len(path))
	for i, edge := range path {
		forwardAmount := amt
		outgoingExpiry := uint32(finalCltvDelta)
		if i < last {
			forwardAmount = amounts[i+1]
			outgoingExpiry = expiries[i+1]
		}

		hops[i] = &route.Hop{
			PubKeyBytes:      edge.key.to,
			ChannelID:        edge.key.chanID,
			AmtToForward:     forwardAmount,
			OutgoingTimeLock: outgoingExpiry,
		}
	}

	return &route.Route{
		TotalTimeLock: expiries[0],
		TotalAmount:   amounts[0],
		SourcePubKey:  r.source,
		Hops:          hops,
	}, nil
}

func candidateRouteAmount(rt *route.Route, index int) (
	lnwire.MilliSatoshi, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return 0, false
	}
	if index == 0 {
		return rt.TotalAmount, true
	}
	return rt.Hops[index-1].AmtToForward, true
}

func candidateRouteEdgeKey(rt *route.Route, index int) (
	candidateEdgeKey, bool) {

	if rt == nil || index < 0 || index >= len(rt.Hops) {
		return candidateEdgeKey{}, false
	}

	from := rt.SourcePubKey
	if index > 0 {
		from = rt.Hops[index-1].PubKeyBytes
	}

	hop := rt.Hops[index]
	return candidateEdgeKey{
		chanID: hop.ChannelID,
		from:   from,
		to:     hop.PubKeyBytes,
	}, true
}

func candidateFinalAmount(rt *route.Route) lnwire.MilliSatoshi {
	if rt == nil || len(rt.Hops) == 0 {
		return 0
	}
	return rt.Hops[len(rt.Hops)-1].AmtToForward
}

func candidateRouteHash(rt *route.Route) uint64 {
	h := uint64(1469598103934665603)
	for i, hop := range rt.Hops {
		h ^= candidateMix64(hop.ChannelID + uint64(i+1))
		h *= 1099511628211
	}
	h ^= candidateMix64(uint64(candidateFinalAmount(rt)))
	return candidateMix64(h)
}

func (r *candidateRouter) routePath(rt *route.Route) (
	[]*candidateEdge, bool) {

	path := make([]*candidateEdge, 0, len(rt.Hops))
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return nil, false
		}
		edge := r.edges[key]
		if edge == nil {
			return nil, false
		}
		path = append(path, edge)
	}
	return path, true
}

func (r *candidateRouter) routeLogProbability(rt *route.Route) (
	float64, bool) {

	logProbability := 0.0
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return 0, false
		}
		edge := r.edges[key]
		if edge == nil {
			return 0, false
		}
		amt, ok := candidateRouteAmount(rt, i)
		if !ok {
			return 0, false
		}
		p := r.probability(edge, amt)
		if p <= 0 {
			return 0, false
		}
		logProbability += math.Log(p)
	}
	return logProbability, true
}

func (r *candidateRouter) findAlternatives(
	amt lnwire.MilliSatoshi, limit int) []candidateFoundRoute {

	if limit < 1 {
		return nil
	}

	first, err := r.searchRoute(amt, nil, nil)
	if err != nil {
		return nil
	}

	results := []candidateFoundRoute{first}
	seen := map[uint64]bool{
		candidateRouteHash(first.route): true,
	}

	for cursor := 0; cursor < len(results) &&
		len(results) < limit*3; cursor++ {

		base := results[cursor]
		for i := range base.route.Hops {
			key, ok := candidateRouteEdgeKey(base.route, i)
			if !ok {
				continue
			}

			found, err := r.searchRoute(
				amt, map[candidateEdgeKey]bool{key: true}, nil,
			)
			if err != nil {
				continue
			}

			hash := candidateRouteHash(found.route)
			if seen[hash] {
				continue
			}
			seen[hash] = true
			results = append(results, found)

			if len(results) >= limit*3 {
				break
			}
		}
	}

	diversityPenalty := make(map[candidateEdgeKey]float64)
	for _, found := range results {
		for i := range found.route.Hops {
			key, ok := candidateRouteEdgeKey(found.route, i)
			if ok {
				diversityPenalty[key] += 125_000
			}
		}
	}
	for len(results) < limit*3 {
		found, err := r.searchRoute(amt, nil, diversityPenalty)
		if err != nil {
			break
		}

		hash := candidateRouteHash(found.route)
		if seen[hash] {
			break
		}
		seen[hash] = true
		results = append(results, found)

		for i := range found.route.Hops {
			key, ok := candidateRouteEdgeKey(found.route, i)
			if ok {
				diversityPenalty[key] += 125_000
			}
		}
	}

	sort.Slice(results, func(i, j int) bool {
		return results[i].score < results[j].score
	})
	if len(results) > limit {
		results = results[:limit]
	}

	return results
}

func candidateCopyReservations(
	source map[candidateEdgeKey]lnwire.MilliSatoshi,
) map[candidateEdgeKey]lnwire.MilliSatoshi {

	result := make(
		map[candidateEdgeKey]lnwire.MilliSatoshi, len(source),
	)
	for key, amount := range source {
		result[key] = amount
	}
	return result
}

func (r *candidateRouter) reserveRoute(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.reserved[key] += amount
		}
	}
}

func (r *candidateRouter) syncReservations(inFlight uint32) {
	r.reserved = make(map[candidateEdgeKey]lnwire.MilliSatoshi)

	if inFlight == 0 {
		r.held = nil
		return
	}

	count := int(inFlight)
	if count > len(r.held) {
		count = len(r.held)
	}
	start := len(r.held) - count
	for _, rt := range r.held[start:] {
		r.reserveRoute(rt)
	}
}

func candidateScaledAmount(value lnwire.MilliSatoshi,
	numerator, denominator int64) lnwire.MilliSatoshi {

	if value <= 0 || numerator <= 0 || denominator <= 0 {
		return 0
	}
	return lnwire.MilliSatoshi(
		float64(value) * float64(numerator) /
			float64(denominator),
	)
}

func candidateAddAmount(values *[]lnwire.MilliSatoshi,
	seen map[lnwire.MilliSatoshi]bool, value,
	maximum lnwire.MilliSatoshi) {

	if value <= 0 {
		value = 1
	}
	if value > maximum {
		value = maximum
	}
	if !seen[value] {
		seen[value] = true
		*values = append(*values, value)
	}
}

func candidatePlanSeeds(remaining lnwire.MilliSatoshi,
	slots uint32, failed lnwire.MilliSatoshi) []lnwire.MilliSatoshi {

	if slots == 0 {
		return nil
	}
	if slots == 1 {
		return []lnwire.MilliSatoshi{remaining}
	}

	base := (remaining + lnwire.MilliSatoshi(slots) - 1) /
		lnwire.MilliSatoshi(slots)

	var values []lnwire.MilliSatoshi
	seen := make(map[lnwire.MilliSatoshi]bool)

	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 1, 2),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 2, 3),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 4, 5),
		remaining,
	)
	candidateAddAmount(&values, seen, base, remaining)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 5, 4),
		remaining,
	)
	candidateAddAmount(
		&values, seen, candidateScaledAmount(base, 3, 2),
		remaining,
	)
	candidateAddAmount(&values, seen, base*2, remaining)
	candidateAddAmount(&values, seen, remaining, remaining)

	if failed > 0 {
		candidateAddAmount(
			&values, seen, candidateScaledAmount(failed, 11, 20),
			remaining,
		)
		candidateAddAmount(
			&values, seen, candidateScaledAmount(failed, 7, 10),
			remaining,
		)
	}

	return values
}

func (r *candidateRouter) pathLikelyAllows(path []*candidateEdge,
	finalAmount lnwire.MilliSatoshi) bool {

	rt, err := r.buildPath(finalAmount, path)
	if err != nil {
		return false
	}

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			return false
		}
		edge := r.edges[key]
		if edge == nil {
			return false
		}

		shardAmount, ok := candidateRouteAmount(rt, i)
		if !ok {
			return false
		}
		reserved := r.reserved[key]
		if shardAmount > edge.capacity-reserved {
			return false
		}
		total := shardAmount + reserved

		if key.from == r.source {
			balance, ok := r.localBalances[key.chanID]
			if !ok || total > balance {
				return false
			}
			continue
		}

		if failure, ok := r.currentFails[key]; ok {
			ceiling, valid := candidateRetryCeiling(failure)
			if valid && total > ceiling {
				return false
			}
		}

		belief, known := r.beliefs[key]
		var likelyTotal lnwire.MilliSatoshi
		switch {
		case known && belief.upperFail > 0:
			likelyTotal = candidateScaledAmount(
				belief.upperFail, 7, 10,
			)
			if belief.lowerOK > likelyTotal {
				likelyTotal = belief.lowerOK
			}
			if likelyTotal >= belief.upperFail {
				likelyTotal = belief.upperFail - 1
			}

		case known && belief.lowerOK > 0:
			likelyTotal = belief.lowerOK +
				candidateScaledAmount(
					edge.capacity-belief.lowerOK, 7, 10,
				)

		default:
			likelyTotal = candidateScaledAmount(
				edge.capacity, 9, 10,
			)
		}

		if total > likelyTotal {
			return false
		}
	}

	return true
}

func (r *candidateRouter) pathLikelyLimit(path []*candidateEdge,
	maximum lnwire.MilliSatoshi) lnwire.MilliSatoshi {

	if maximum <= 0 {
		return 0
	}

	low := lnwire.MilliSatoshi(0)
	high := maximum

	for low < high {
		mid := low + (high-low+1)/2
		if r.pathLikelyAllows(path, mid) {
			low = mid
		} else {
			high = mid - 1
		}
	}

	return low
}

type candidateRouteChoice struct {
	route   *route.Route
	logProb float64
}

func (r *candidateRouter) planChoices(
	remaining lnwire.MilliSatoshi, slots uint32,
) []candidateRouteChoice {

	seeds := candidatePlanSeeds(
		remaining, slots, r.lastFailedShard,
	)
	choices := make([]candidateRouteChoice, 0, len(seeds)*4)
	seen := make(map[uint64]bool)

	addRoute := func(rt *route.Route) {
		if rt == nil {
			return
		}
		finalAmount := candidateFinalAmount(rt)
		if finalAmount <= 0 || finalAmount > remaining {
			return
		}

		hash := candidateRouteHash(rt)
		if seen[hash] {
			return
		}

		logProbability, ok := r.routeLogProbability(rt)
		if !ok {
			return
		}

		seen[hash] = true
		choices = append(choices, candidateRouteChoice{
			route:   rt,
			logProb: logProbability,
		})
	}

	for _, seed := range seeds {
		alternatives := r.findAlternatives(seed, 5)
		for _, found := range alternatives {
			addRoute(found.route)

			path, ok := r.routePath(found.route)
			if !ok {
				continue
			}

			limit := r.pathLikelyLimit(path, remaining)
			if limit <= 0 {
				continue
			}

			suggested := []lnwire.MilliSatoshi{
				candidateScaledAmount(limit, 4, 5),
				candidateScaledAmount(limit, 9, 10),
				limit,
			}
			for _, amount := range suggested {
				if amount <= 0 || amount > remaining {
					continue
				}
				rt, err := r.buildPath(amount, path)
				if err == nil {
					addRoute(rt)
				}
			}
		}
	}

	sort.Slice(choices, func(i, j int) bool {
		leftAmount := candidateFinalAmount(choices[i].route)
		rightAmount := candidateFinalAmount(choices[j].route)

		left := choices[i].logProb +
			2.2*float64(leftAmount)/float64(remaining)
		right := choices[j].logProb +
			2.2*float64(rightAmount)/float64(remaining)
		return left > right
	})

	if len(choices) > 32 {
		choices = choices[:32]
	}
	return choices
}

type candidatePlanState struct {
	remaining    lnwire.MilliSatoshi
	routes       []*route.Route
	reservations map[candidateEdgeKey]lnwire.MilliSatoshi
	score        float64
	rank         float64
}

func (r *candidateRouter) planBeam(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	savedReservations := candidateCopyReservations(r.reserved)
	defer func() {
		r.reserved = savedReservations
	}()

	states := []candidatePlanState{{
		remaining:    total,
		reservations: candidateCopyReservations(savedReservations),
	}}

	var bestComplete *candidatePlanState
	const beamWidth = 24

	for depth := uint32(0); depth < parts && len(states) > 0; depth++ {
		slots := parts - depth
		nextStates := make([]candidatePlanState, 0, beamWidth*12)

		for _, state := range states {
			if state.remaining == 0 {
				if bestComplete == nil ||
					state.score > bestComplete.score {

					copyState := state
					bestComplete = &copyState
				}
				continue
			}

			r.reserved = candidateCopyReservations(
				state.reservations,
			)
			choices := r.planChoices(state.remaining, slots)

			for _, choice := range choices {
				shardAmount := candidateFinalAmount(choice.route)
				if shardAmount <= 0 ||
					shardAmount > state.remaining {

					continue
				}

				newReservations := candidateCopyReservations(
					state.reservations,
				)
				r.reserved = newReservations
				r.reserveRoute(choice.route)

				remaining := state.remaining - shardAmount
				fees := choice.route.TotalAmount - shardAmount
				score := state.score + choice.logProb -
					float64(fees)/4_000_000 - 0.02

				progress := float64(total-remaining) /
					float64(total)
				rank := score + 3.8*progress

				routes := make(
					[]*route.Route, len(state.routes),
					len(state.routes)+1,
				)
				copy(routes, state.routes)
				routes = append(routes, choice.route)

				nextState := candidatePlanState{
					remaining:    remaining,
					routes:       routes,
					reservations: newReservations,
					score:        score,
					rank:         rank,
				}
				nextStates = append(nextStates, nextState)

				if remaining == 0 &&
					(bestComplete == nil ||
						score > bestComplete.score) {

					copyState := nextState
					bestComplete = &copyState
				}
			}
		}

		sort.Slice(nextStates, func(i, j int) bool {
			iComplete := nextStates[i].remaining == 0
			jComplete := nextStates[j].remaining == 0
			if iComplete != jComplete {
				return iComplete
			}
			if nextStates[i].rank == nextStates[j].rank {
				return nextStates[i].remaining <
					nextStates[j].remaining
			}
			return nextStates[i].rank > nextStates[j].rank
		})

		if len(nextStates) > beamWidth {
			nextStates = nextStates[:beamWidth]
		}
		states = nextStates
	}

	if bestComplete == nil || len(bestComplete.routes) == 0 {
		return nil, errors.New("no route set found")
	}
	return bestComplete.routes, nil
}

func (r *candidateRouter) makePlan(total lnwire.MilliSatoshi,
	parts uint32) ([]*route.Route, error) {

	if parts <= 1 {
		found, err := r.searchRoute(total, nil, nil)
		if err != nil {
			return nil, err
		}
		return []*route.Route{found.route}, nil
	}

	plan, err := r.planBeam(total, parts)
	if err == nil {
		return plan, nil
	}

	found, singleErr := r.searchRoute(total, nil, nil)
	if singleErr == nil {
		return []*route.Route{found.route}, nil
	}

	return nil, err
}

func (r *candidateRouter) recordRouteUse(rt *route.Route) {
	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if ok {
			r.edgeUses[key]++
		}
	}
}

func (r *candidateRouter) RequestRoute(amt lnwire.MilliSatoshi,
	inFlightHtlcs uint32) (*route.Route, error) {

	if amt <= 0 {
		return nil, errors.New("payment amount exhausted")
	}
	if r.attempts >= r.attemptLimit {
		return nil, errors.New("routing attempt budget exhausted")
	}

	r.syncReservations(inFlightHtlcs)

	maxParts := r.spec.MaxParts
	if maxParts == 0 {
		maxParts = 1
	}
	if inFlightHtlcs >= maxParts {
		return nil, errors.New("maximum number of parts in flight")
	}
	partsLeft := maxParts - inFlightHtlcs

	if len(r.planned) > 0 {
		rt := r.planned[0]
		finalAmount := candidateFinalAmount(rt)
		if finalAmount > 0 && finalAmount <= amt {
			if _, valid := r.routeLogProbability(rt); valid {
				r.planned = r.planned[1:]
				r.recordRouteUse(rt)
				r.attempts++
				return rt, nil
			}
		}
		r.planned = nil
	}

	plan, err := r.makePlan(amt, partsLeft)
	if err != nil {
		return nil, err
	}

	rt := plan[0]
	if len(plan) > 1 {
		r.planned = append([]*route.Route(nil), plan[1:]...)
	} else {
		r.planned = nil
	}

	r.recordRouteUse(rt)
	r.attempts++
	return rt, nil
}

func (r *candidateRouter) storeBelief(key candidateEdgeKey,
	belief candidateBelief) {

	r.beliefs[key] = belief

	candidateMemory.Lock()
	memory := candidateMemory.networks[r.networkKey]
	if memory == nil {
		memory = &candidateNetworkMemory{
			beliefs: make(map[candidateEdgeKey]candidateBelief),
		}
		candidateMemory.networks[r.networkKey] = memory
	}
	memory.beliefs[key] = belief
	candidateMemory.Unlock()
}

func (r *candidateRouter) learnSuccess(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	if failure, ok := r.currentFails[key]; ok {
		if failure.upper == 0 || amt >= failure.upper {
			delete(r.currentFails, key)
		} else if failure.count > 1 {
			failure.count--
			r.currentFails[key] = failure
		}
	}

	if r.suspect[key] > 0 {
		r.suspect[key]--
	}

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if amt > belief.lowerOK {
		belief.lowerOK = amt
	}
	if belief.upperFail > 0 && amt >= belief.upperFail {
		belief.upperFail = 0
	}
	if amt > belief.estimate {
		belief.estimate = amt
	}
	belief.successes++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) learnFailure(key candidateEdgeKey,
	amt lnwire.MilliSatoshi) {

	if amt <= 0 {
		return
	}

	current := r.currentFails[key]
	if current.upper == 0 || amt < current.upper {
		current.upper = amt
	}
	current.count++
	r.currentFails[key] = current

	if key.from == r.source {
		return
	}

	belief := r.beliefs[key]
	if belief.upperFail == 0 || amt < belief.upperFail {
		belief.upperFail = amt
	}
	if belief.lowerOK >= amt {
		belief.lowerOK = 0
	}

	estimate := candidateScaledAmount(amt, 11, 20)
	if belief.lowerOK > estimate {
		estimate = belief.lowerOK
	}
	if belief.estimate == 0 || belief.estimate >= amt {
		belief.estimate = estimate
	}
	belief.failures++
	r.storeBelief(key, belief)
}

func (r *candidateRouter) markRouteSuspect(rt *route.Route,
	weight uint32) {

	for i := range rt.Hops {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		if key.from == r.source && len(rt.Hops) > 1 {
			continue
		}
		r.suspect[key] += weight
	}
}

func (r *candidateRouter) ReportAttempt(_ uint64, rt *route.Route,
	result routing.SimHtlcResult) error {

	if rt == nil || len(rt.Hops) == 0 {
		return errors.New("invalid attempted route")
	}

	if result.Failure == nil {
		for i := range rt.Hops {
			key, ok := candidateRouteEdgeKey(rt, i)
			if !ok {
				continue
			}
			amount, ok := candidateRouteAmount(rt, i)
			if ok {
				r.learnSuccess(key, amount+r.reserved[key])
			}
		}

		r.held = append(r.held, rt)
		r.lastFailedShard = 0
		return nil
	}

	r.planned = nil

	failureIndex := -1
	if result.FailureSource == rt.SourcePubKey {
		failureIndex = 0
	} else {
		for i, hop := range rt.Hops {
			if hop.PubKeyBytes == result.FailureSource {
				failureIndex = i + 1
				break
			}
		}
	}

	if failureIndex < 0 {
		r.markRouteSuspect(rt, 1)
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	passed := failureIndex
	if passed > len(rt.Hops) {
		passed = len(rt.Hops)
	}
	for i := 0; i < passed; i++ {
		key, ok := candidateRouteEdgeKey(rt, i)
		if !ok {
			continue
		}
		amount, ok := candidateRouteAmount(rt, i)
		if ok {
			r.learnSuccess(key, amount+r.reserved[key])
		}
	}

	if failureIndex >= len(rt.Hops) {
		r.lastFailedShard = candidateFinalAmount(rt)
		return nil
	}

	key, ok := candidateRouteEdgeKey(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}
	amountOverEdge, ok := candidateRouteAmount(rt, failureIndex)
	if !ok {
		r.markRouteSuspect(rt, 1)
		return nil
	}

	totalRequired := amountOverEdge + r.reserved[key]

	switch result.Failure.Code() {
	case lnwire.CodeTemporaryChannelFailure:
		r.learnFailure(key, totalRequired)
		r.suspect[key]++
		r.lastFailedShard = candidateFinalAmount(rt)

	case lnwire.CodeFeeInsufficient,
		lnwire.CodeIncorrectCltvExpiry:

		r.policyBlocked[key] = true
		r.suspect[key] += 2

	default:
		r.policyBlocked[key] = true
		r.suspect[key]++
	}

	return nil
}
